import math
import platform
from pathlib import Path
import re
import shlex
import shutil
import subprocess
import sys
import tempfile


def run(command, **options):
    result = subprocess.run(command, capture_output=True, text=True, **options)
    if result.returncode:
        raise AssertionError(
            f"Command failed with status {result.returncode}: "
            f"{shlex.join(map(str, command))}\n"
            f"{result.stdout}{result.stderr}"
        )
    return result.stdout


def link_freebasic_standalone_interfaces(source_directory, destination):
    destination.mkdir(parents=True, exist_ok=True)
    for interface in source_directory.glob("*.bi"):
        # Implementation fragments are compiled through their owning .bas unit.
        if interface.stem.endswith("_body"):
            continue
        # FTS5's generated catalogs repeat core SQLite ABI records and belong
        # in source-specific contexts, not the combined core test catalog.
        if interface.name.startswith("sqlite3_fts5_") and \
           interface.name.endswith("_types.bi"):
            continue
        (destination / interface.name).symlink_to(interface)


def copy_freebasic_interface_closure(source_directory, destination, interfaces):
    pending = list(interfaces)
    copied = set()
    while pending:
        interface_name = pending.pop()
        if interface_name in copied:
            continue
        source = source_directory / interface_name
        if not source.is_file():
            continue
        copied.add(interface_name)
        target = destination / interface_name
        if target.exists():
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
        pending.extend(re.findall(
            r'^\s*#include(?:\s+once)?\s+"([^"]+)"',
            source.read_text(encoding="utf-8"), re.M))


def procedure_names(text):
    return set(re.findall(r"^(?:Private )?(?:Function|Sub) (c2fb\w+)", text, re.M))


def check_api_routines_regeneration(converter, work):
    # The owner includes the checked-in table, while profile generation writes
    # to a separate directory. The checked-in declarations must not suppress
    # the forward declarations needed by the generated profile table.
    source = work / "api-routines-source.i"
    source.write_text(
        "struct sqlite3_api_routines {\n"
        "    void (*sqlite3_test_api)(void);\n"
        "    void *(*sqlite3_deserialize)(void);\n"
        "    void *(*sqlite3_serialize)(void);\n"
        "};\n"
        "static const sqlite3_api_routines sqlite3Apis = {\n"
        "    sqlite3_test_api, sqlite3_deserialize, sqlite3_serialize\n"
        "};\n"
    )
    ledger = work / "api-routines-functions.csv"
    with ledger.open("w", encoding="utf-8", newline="") as csv_file:
        writer = csv.writer(csv_file, lineterminator="\n")
        writer.writerow([
            "Upstream source", "Function", "Start line", "End line", "Lines",
            "Size class", "Port status", "Notes",
        ])
        writer.writerows([
            ["src/main.c", "sqlite3_test_api", 1, 1, 1, "small", "FB body present", ""],
            ["src/memdb.c", "sqlite3_deserialize", 1, 1, 1, "small", "FB body present", ""],
            ["src/memdb.c", "sqlite3_serialize", 1, 1, 1, "small", "FB body present", ""],
        ])
    source_table = work / "sqlite3_extension_api_table.bi"
    generated_directory = work / "generated-api-table"
    generated_directory.mkdir()
    output = generated_directory / "sqlite3_extension_api_table.bi"
    owner = work / "api-routines-owner.bas"
    generated_body = work / "api-routines-generated-body.bas"
    owner.write_text('#include once "sqlite3_extension_api_table.bi"\n')
    source_table.write_text(
        'Declare Function sqlite3_test_api CDecl Alias "sqlite3_test_api" '
        '() As Any Ptr\n'
    )
    generated_body.write_text(
        'Function sqlite3_test_api CDecl Alias "sqlite3_test_api" () As Any Ptr\n'
        '    Return 0\n'
        'End Function\n'
    )
    command = [
        converter, "api-routines", str(source), str(ledger), str(owner), str(output)
    ]
    for _ in range(2):
        run(command)
        generated = output.read_text()
        assert generated.count('Declare Function sqlite3_test_api ') == 1, generated
        assert "ProcPtr(sqlite3_test_api)" in generated, generated
        assert generated.count("#ifndef SQLITE_OMIT_DESERIALIZE") == 2, generated
        assert re.search(
            r"#ifndef SQLITE_OMIT_DESERIALIZE\s+"
            r"sqlite3Apis\(1\) = CPtr\(Any Ptr, ProcPtr\(sqlite3_deserialize\)\)\s+"
            r"#endif",
            generated,
        ), generated
        assert re.search(
            r"#ifndef SQLITE_OMIT_DESERIALIZE\s+"
            r"sqlite3Apis\(2\) = CPtr\(Any Ptr, ProcPtr\(sqlite3_serialize\)\)\s+"
            r"#endif",
            generated,
        ), generated


def freebasic_ulong_arrays(source):
    arrays = {}
    pattern = re.compile(
        r"Dim Shared As Const ULong\s+([A-Za-z_][A-Za-z_0-9]*)"
        r"\(0 To (\d+)\)\s*=\s*\{([^}]*)\}",
        re.I | re.S,
    )
    for name, upper_bound, values_text in pattern.findall(source):
        values = [int(value) for value in re.findall(r"\d+", values_text)]
        assert len(values) == int(upper_bound) + 1, (name, upper_bound, values)
        arrays[name] = values
    return arrays


def check_sqlite_auxiliary_modes(converter, fbc, work, repository, fb_directory):
    constants = work / "sqlite3_api_constants.bi"
    run([
        converter, "defines", "../src/sqlite.h.in", str(constants),
    ], cwd=fb_directory)
    assert constants.read_bytes() == (
        fb_directory / "sqlite3_api_constants.bi").read_bytes()

    fp_tables = work / "sqlite3_fp10_tables.bi"
    run([
        converter, "fp-tables", "../src/util.c", str(fp_tables),
    ], cwd=fb_directory)
    generated_arrays = freebasic_ulong_arrays(fp_tables.read_text())
    checked_in_arrays = freebasic_ulong_arrays(
        (fb_directory / "sqlite3_fp10_tables.bi").read_text())
    assert generated_arrays == checked_in_arrays
    assert len(generated_arrays) == 5, generated_arrays.keys()

    wrapper = work / "sqlite3_auxiliary_modes.bas"
    wrapper.write_text(
        f'#include once "{constants.as_posix()}"\n'
        f'#include once "{fp_tables.as_posix()}"\n'
        "If SQLITE_OK <> 0 Then End 1\n"
        "If SQLITE_DONE <> 101 Then End 2\n" +
        "".join(
            f"Print {name}({index})\n"
            for name, values in generated_arrays.items()
            for index in sorted({0, len(values) // 2, len(values) - 1})
        )
    )
    executable = work / "sqlite3_auxiliary_modes"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)], cwd=work)
    actual_values = [int(value) for value in run([str(executable)], cwd=work).split()]
    expected_values = [
        values[index]
        for values in generated_arrays.values()
        for index in sorted({0, len(values) // 2, len(values) - 1})
    ]
    assert actual_values == expected_values, (actual_values, expected_values)

    source_directory = work / "function-index-source"
    source_directory.mkdir()
    (source_directory / "a.c").write_text(
        "int c2fbModeFirst(void) { if (1) { return 1; } return 0; }\n"
        "static int c2fbModeDuplicate(void) { return 2; }\n"
    )
    (source_directory / "b.c").write_text(
        "static int c2fbModeDuplicate(void) { return 3; }\n"
        "int c2fbModeSecond(void) { return 4; }\n"
    )
    (source_directory / "api.h").write_text(
        "static inline int c2fbModeHeader(void) { return 5; }\n"
        "static inline int c2fbModeDuplicate(void) { return 6; }\n"
    )
    functions = work / "function-index.csv"
    run([converter, "functions", str(source_directory), str(functions)])
    with functions.open(encoding="utf-8", newline="") as csv_file:
        indexed_rows = list(csv.DictReader(csv_file))
    indexed_names = [row["Function"] for row in indexed_rows]
    assert indexed_names == [
        "c2fbModeFirst", "c2fbModeDuplicate",
        "c2fbModeDuplicate", "c2fbModeSecond",
    ], indexed_names
    assert set(indexed_names) == {
        "c2fbModeFirst", "c2fbModeDuplicate", "c2fbModeSecond",
    }, indexed_names
    assert indexed_names.count("c2fbModeDuplicate") == 2, indexed_names
    repeated_functions = work / "function-index-repeat.csv"
    run([converter, "functions", str(source_directory), str(repeated_functions)])
    assert repeated_functions.read_bytes() == functions.read_bytes()

    header_functions = work / "function-index-with-headers.csv"
    run([
        converter, "functions", str(source_directory),
        str(header_functions), "--include-headers",
    ])
    with header_functions.open(encoding="utf-8", newline="") as csv_file:
        header_rows = list(csv.DictReader(csv_file))
    header_names = [row["Function"] for row in header_rows]
    assert set(header_names) == set(indexed_names) | {"c2fbModeHeader"}, header_names
    assert header_names.count("c2fbModeDuplicate") == 2, header_names

    fixture_fb_directory = work / "function-index-freebasic"
    fixture_fb_directory.mkdir()
    (fixture_fb_directory / "implementation.bas").write_text(
        "Private Function c2fbModeFirst() As Long\n"
        "    Return 1\n"
        "End Function\n"
        'Function fbModeSecond Alias "c2fbModeSecond" () As Long\n'
        "    Return 2\n"
        "End Function\n"
    )
    (fixture_fb_directory / "declarations.bi").write_text(
        'Declare Function fbModeDuplicate Alias "c2fbModeDuplicate" () As Long\n'
    )
    run([
        converter, "reconcile-functions", str(functions),
        str(fixture_fb_directory),
    ])
    with functions.open(encoding="utf-8", newline="") as csv_file:
        reconciled_rows = {
            row["Function"]: row["Port status"]
            for row in csv.DictReader(csv_file)
        }
    assert reconciled_rows == {
        "c2fbModeFirst": "FB body present",
        "c2fbModeDuplicate": "Needs mapping",
        "c2fbModeSecond": "FB body present",
    }, reconciled_rows

    sqlite_functions = work / "sqlite3-functions.csv"
    run([
        converter, "functions", str(repository / "src"),
        str(sqlite_functions),
    ])
    run([
        converter, "reconcile-functions", str(sqlite_functions),
        str(fb_directory),
    ])
    with sqlite_functions.open(encoding="utf-8", newline="") as csv_file:
        actual_rows = list(csv.DictReader(csv_file))
    with (fb_directory / "PORTING_FUNCTIONS.csv").open(
        encoding="utf-8", newline=""
    ) as csv_file:
        expected_rows = list(csv.DictReader(csv_file))
    compared_fields = (
        "Upstream source", "Function", "Start line", "End line", "Lines",
        "Size class", "Port status",
    )
    actual_projection = sorted(
        tuple(row[field] for field in compared_fields) for row in actual_rows)
    expected_projection = sorted(
        tuple(row[field] for field in compared_fields) for row in expected_rows)
    assert actual_projection == expected_projection


def check_body_candidate_growth(converter, body_catalog, work):
    source = work / "body-candidate-growth.c"
    source.write_text("".join(
        f"int c2fbCapacity{index}(int value) {{ return value; }}\n"
        for index in range(300)
    ))
    output = work / "body-candidate-growth.bas"
    run([converter, "translate-simple", str(source), str(output), str(body_catalog)])
    expected = {f"c2fbCapacity{index}" for index in range(300)}
    actual = procedure_names(output.read_text())
    assert actual == expected, (
        f"Candidate storage growth lost functions: {expected - actual}; "
        f"unexpected: {actual - expected}"
    )


def check_body_candidate_skip_summary(converter, work):
    # Bulk runs must distinguish unsupported bodies from duplicate definitions.
    source = work / "body-candidate-skip-summary.c"
    source.write_text(
        "int c2fbSummaryAccepted(int value) { return value; }\n"
        "int c2fbSummaryUnsupported(int value) {\n"
        '    __asm__("nop");\n'
        "    return value;\n"
        "}\n"
        "int c2fbSummaryDuplicate(int value) { return value; }\n"
        "int c2fbSummaryDuplicate(int value) { return value + 1; }\n"
    )
    candidate = work / "body-candidate-skip-summary.bas"
    command = [
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc",
    ]
    summary = run(command)
    assert "translated 1 simple functions; skipped 2" in summary, summary
    assert (
        "c2fb candidate skips: unsupported=1, duplicates=1, dependencies=0, "
        "already-ported=0, other=0"
    ) in summary, summary
    generated = candidate.read_text()
    assert "Function c2fbSummaryAccepted" in generated, generated
    assert "c2fb skipped c2fbSummaryUnsupported:" in generated, generated
    assert "c2fb skipped c2fbSummaryDuplicate: multiple source definitions" \
        in generated, generated


def check_generic_body_long_boolean_chains(converter, fbc, work):
    # Long C boolean chains must stay shallow enough for the target compiler.
    source = work / "long-boolean-chains.c"
    or_terms = [f"value == {index}" for index in range(128)]
    and_terms = ["value >= 0", "value <= 127"] + [
        f"value != {1000 + index}" for index in range(126)
    ]
    source.write_text(
        "int c2fbLongOrChain(int value) {\n"
        "    return " + " || ".join(or_terms) + ";\n"
        "}\n"
        "int c2fbLongAndChain(int value) {\n"
        "    return " + " && ".join(and_terms) + ";\n"
        "}\n"
    )
    candidate = work / "long-boolean-chains.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc",
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert 'crt/longdouble.bi' not in generated, generated
    logical_lines = [
        line for line in generated.splitlines()
        if "OrElse" in line or "AndAlso" in line
    ]
    assert logical_lines and max(map(len, logical_lines)) < 12000, generated

    wrapper = work / "check-long-boolean-chains.bas"
    wrapper.write_text(
        '#include once "long-boolean-chains.bas"\n'
        "If c2fbLongOrChain(0) <> 1 Then End 1\n"
        "If c2fbLongOrChain(127) <> 1 Then End 2\n"
        "If c2fbLongOrChain(128) <> 0 Then End 3\n"
        "If c2fbLongAndChain(64) <> 1 Then End 4\n"
        "If c2fbLongAndChain(1017) <> 0 Then End 5\n"
        "If c2fbLongAndChain(-1) <> 0 Then End 6\n"
    )
    executable = work / "check-long-boolean-chains"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)], cwd=work)
    run([str(executable)], cwd=work)


def check_generic_body_gnu_memory_clobber(converter, fbc, cc, work):
    # GNU's empty asm with a memory clobber must remain a compiler barrier.
    source_directory = work / "generic-body-gnu-memory-clobber"
    source_directory.mkdir()
    source = source_directory / "memory_clobber.c"
    source.write_text(
        "#include <stddef.h>\n"
        "#include <string.h>\n"
        "void *c2fbMemoryClobber(void *target, int value, size_t length) {\n"
        "    memset(target, value, length);\n"
        '    __asm__ __volatile__("" ::: "memory");\n'
        "    return target;\n"
        "}\n"
    )
    candidate = source_directory / "memory_clobber_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc", "--type-map=size_t=CULong",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert re.search(r"Asm\s+nop\s+End Asm", generated), generated

    reference_path = source_directory / "memory_clobber_reference.so"
    run(cc + ["-std=gnu11", "-O2", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbMemoryClobber.argtypes = [ctypes.c_void_p, ctypes.c_int,
                                             ctypes.c_size_t]
    reference.c2fbMemoryClobber.restype = ctypes.c_void_p

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"]),
                           ("llvm", ["-gen", "llvm"])):
        converted_path = source_directory / f"memory_clobber_{backend}.so"
        run(fbc + ["-O", "2", "-R", "-w", "all", *flags, "-dll",
                   str(candidate), "-x", str(converted_path)],
            cwd=source_directory)
        if backend == "gcc":
            intermediate = candidate.with_suffix(".c").read_text()
            assert re.search(
                r'__asm__ __volatile__\(.*?"nop".*?"memory"',
                intermediate, re.S,
            ), intermediate
        elif backend == "llvm":
            intermediate = candidate.with_suffix(".ll").read_text()
            assert "asm sideeffect" in intermediate, intermediate
            assert '"nop"' in intermediate and "~{memory}" in intermediate, intermediate

        converted = ctypes.CDLL(str(converted_path))
        converted.c2fbMemoryClobber.argtypes = [ctypes.c_void_p, ctypes.c_int,
                                                 ctypes.c_size_t]
        converted.c2fbMemoryClobber.restype = ctypes.c_void_p
        for value in (-1, 0x12, 0x112):
            for length in (0, 1, 7, 8, 64, 511):
                initial = b"\xa5" * 512
                reference_buffer = ctypes.create_string_buffer(initial, 512)
                converted_buffer = ctypes.create_string_buffer(initial, 512)
                reference_address = ctypes.addressof(reference_buffer)
                converted_address = ctypes.addressof(converted_buffer)
                assert reference.c2fbMemoryClobber(
                    reference_address, value, length
                ) == reference_address
                assert converted.c2fbMemoryClobber(
                    converted_address, value, length
                ) == converted_address
                expected = bytes([value & 0xff]) * length + initial[length:]
                assert ctypes.string_at(reference_address, 512) == expected
                assert ctypes.string_at(converted_address, 512) == expected


def check_generic_body_error_nonzero_status_terminates(
    converter, fbc, cc, work
):
    # GNU error() exits only for nonzero status and returns for zero.
    source_directory = work / "generic-body-error-status-termination"
    source_directory.mkdir()
    source = source_directory / "error_status.c"
    source.write_text(
        "#include <error.h>\n"
        "int c2fbErrorStatusZero(void) {\n"
        "    error(0, 0, \"nonfatal\");\n"
        "    return 7;\n"
        "}\n"
        "int c2fbErrorStatusNonzero(void) {\n"
        "    error(1, 0, \"fatal\");\n"
        "    return 9;\n"
        "}\n"
    )
    candidate = source_directory / "error_status_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), cc[0],
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary

    reference_source = source_directory / "reference_main.c"
    reference_source.write_text(
        "#include <string.h>\n"
        "int c2fbErrorStatusZero(void);\n"
        "int c2fbErrorStatusNonzero(void);\n"
        "int main(int argc, char **argv) {\n"
        "    if (argc > 1 && strcmp(argv[1], \"zero\") == 0)\n"
        "        return c2fbErrorStatusZero();\n"
        "    return c2fbErrorStatusNonzero();\n"
        "}\n"
    )
    reference = source_directory / "reference"
    run(cc + ["-std=c99", "-O2", str(source), str(reference_source),
              "-o", str(reference)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "error_status_candidates.bas"\n'
        'If Command(1) = "zero" Then\n'
        "    End c2fbErrorStatusZero()\n"
        "Else\n"
        "    End c2fbErrorStatusNonzero()\n"
        "End If\n"
    )
    converted = source_directory / "converted"
    run(fbc + ["-w", "all", "-i", str(source_directory), str(wrapper),
               "-x", str(converted)], cwd=source_directory)
    for case in ("zero", "nonzero"):
        c_result = subprocess.run(
            [str(reference), case], capture_output=True)
        fb_result = subprocess.run(
            [str(converted), case], capture_output=True)
        assert c_result.returncode == fb_result.returncode, (
            case, c_result.returncode, fb_result.returncode
        )


def check_generic_body_longdouble(converter, fbc, cc, work):
    # C long-double literals must retain their decimal precision and C integer
    # conversions must not pass through Double in generated FreeBASIC bodies.
    source = work / "generic-body-longdouble.c"
    source.write_text(
        "int c2fbLongDoubleLiteralPrecision(void) {\n"
        "    long double value = 1.0L + 1.0000000000000001e-18L;\n"
        "    return value > 1.0L;\n"
        "}\n"
        "int c2fbLongDoubleArgument(long double value) {\n"
        "    long double adjusted = value + 1.0000000000000001e-18L;\n"
        "    return adjusted > value;\n"
        "}\n"
        "int c2fbLongDoubleIntegerPrecision(void) {\n"
        "    long long value = 9007199254740993LL;\n"
        "    long double converted = (long double)value;\n"
        "    return converted > 9007199254740992.0L;\n"
        "}\n"
        "int c2fbLongDoubleUnsignedPrecision(void) {\n"
        "    unsigned long long value = 18446744073709551615ULL;\n"
        "    long double converted = (long double)value;\n"
        "    return converted > 18446744073709551614.0L;\n"
        "}\n"
        "int c2fbLongDoubleIntegerInitializer(void) {\n"
        "    long double value = 1;\n"
        "    return value == 1.0L;\n"
        "}\n"
        "int c2fbLongDoubleTruncate(void) {\n"
        "    return (int)-1.75L == -1;\n"
        "}\n"
        "int c2fbLongDoubleCompound(long double value) {\n"
        "    value += 1.0000000000000001e-18L;\n"
        "    return value > 1.0L;\n"
        "}\n"
        "int c2fbHexFloatDouble(void) {\n"
        "    double value = 0X1.0000000000001P0;\n"
        "    return value > 1.0;\n"
        "}\n"
        "int c2fbHexFloatSingle(void) {\n"
        "    float value = 0x.800002p+1f;\n"
        "    return value > 1.0f;\n"
        "}\n"
        "int c2fbHexFloatLongDouble(void) {\n"
        "    long double value = 0x1.0000000000000008p0L;\n"
        "    return value > 1.0L;\n"
        "}\n"
        "int c2fbHexFloatIntegerCast(void) {\n"
        "    return (int)(0x1.8p+1 + 0x1p0);\n"
        "}\n"
        "int c2fbLongDoubleDivision(long double value) {\n"
        "    return (value / 3.0L) > (value / 4.0L);\n"
        "}\n"
        "long double c2fbLongDoubleReturn(long double value) {\n"
        "    return value + 0.5L;\n"
        "}\n"
        "long double c2fbLongDoubleExternal(long double value);\n"
        "int c2fbLongDoubleExternalResult(long double value) {\n"
        "    return c2fbLongDoubleExternal(value) > value;\n"
        "}\n"
        "long double c2fbLongDoubleExternalArgument(long double value) {\n"
        "    return c2fbLongDoubleExternal(value + 0.5L);\n"
        "}\n"
    )
    support_source = work / "generic-body-longdouble-support.c"
    support_source.write_text(
        "long double c2fbLongDoubleExternal(long double value) {\n"
        "    return value + 0.5L;\n"
        "}\n"
        "extern long double c2fbLongDoubleReturn(long double value);\n"
        "int c2fbLongDoubleReturnPrecisionCheck(void) {\n"
        "    return c2fbLongDoubleReturn(1.0L) > 1.0L;\n"
        "}\n"
    )
    support_object = work / "generic-body-longdouble-support.o"
    run(cc + ["-std=c99", "-O2", "-fPIC", "-c", str(support_source),
              "-o", str(support_object)])
    candidate = work / "generic-body-longdouble.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), *cc,
    ])
    assert "translated 15 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert '#include once "crt/longdouble.bi"' in generated, generated
    assert "CLongDoubleFromStringValue" in generated, generated
    assert 'As CLongDouble' in generated, generated
    assert 'Alias "c2fbLongDoubleExternal"' in generated, generated

    mapped_source = work / "generic-body-longdouble-type-map.c"
    mapped_source.write_text(
        "c2fb_test_long_double c2fbLongDoubleTypeMapped("
        "c2fb_test_long_double value) { return value; }\n"
    )
    mapped_candidate = work / "generic-body-longdouble-type-map.bas"
    run([
        converter, "translate-simple-generic-c", str(mapped_source),
        str(mapped_candidate), *cc,
        "--type-map=c2fb_test_long_double=CLongDouble",
    ])
    assert 'crt/longdouble.bi' in mapped_candidate.read_text()

    literal_source = work / "generic-body-longdouble-literal-only.c"
    literal_source.write_text(
        "double c2fbLongDoubleLiteralOnly(void) { "
        "return 1.0000000000000001L; }\n"
    )
    literal_candidate = work / "generic-body-longdouble-literal-only.bas"
    run([
        converter, "translate-simple-generic-c", str(literal_source),
        str(literal_candidate), *cc,
    ])
    literal_generated = literal_candidate.read_text()
    assert 'crt/longdouble.bi' in literal_generated, literal_generated
    assert "CLongDoubleFromStringValue" in literal_generated, literal_generated

    discarded_source = work / "generic-body-longdouble-discarded-call.c"
    discarded_source.write_text(
        "long double c2fbLongDoubleDiscardedResult(void);\n"
        "void c2fbLongDoubleDiscardedCall(void) { "
        "c2fbLongDoubleDiscardedResult(); }\n"
    )
    discarded_candidate = work / "generic-body-longdouble-discarded-call.bas"
    run([
        converter, "translate-simple-generic-c", str(discarded_source),
        str(discarded_candidate), *cc,
    ])
    discarded_generated = discarded_candidate.read_text()
    assert 'crt/longdouble.bi' in discarded_generated, discarded_generated
    assert 'As CLongDouble' in discarded_generated, discarded_generated

    reference_path = work / "generic-body-longdouble-reference.so"
    run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(source),
              str(support_source),
              "-lm", "-o", str(reference_path)])
    reference = ctypes.CDLL(str(reference_path))
    for backend, flags in (
        ("native", []), ("gcc", ["-gen", "gcc"]),
        ("llvm", ["-gen", "llvm"]),
    ):
        converted_path = work / f"generic-body-longdouble-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate),
                           str(support_object),
                           "-x", str(converted_path)])
        converted = ctypes.CDLL(str(converted_path))
        for name in (
            "c2fbLongDoubleLiteralPrecision",
            "c2fbHexFloatDouble",
            "c2fbHexFloatSingle",
            "c2fbHexFloatLongDouble",
            "c2fbHexFloatIntegerCast",
            "c2fbLongDoubleIntegerPrecision",
            "c2fbLongDoubleUnsignedPrecision",
            "c2fbLongDoubleIntegerInitializer",
            "c2fbLongDoubleTruncate",
            "c2fbLongDoubleReturnPrecisionCheck",
        ):
            c_function = getattr(reference, name)
            fb_function = getattr(converted, name)
            c_function.restype = fb_function.restype = ctypes.c_int32
            expected = c_function()
            actual = fb_function()
            assert actual == expected, f"{name}: C={expected}, FreeBASIC={actual}"
        for name in (
            "c2fbLongDoubleArgument", "c2fbLongDoubleCompound",
            "c2fbLongDoubleDivision",
        ):
            c_function = getattr(reference, name)
            fb_function = getattr(converted, name)
            for function in (c_function, fb_function):
                function.argtypes = [ctypes.c_longdouble]
                function.restype = ctypes.c_int32
            for number in (-1.0, 0.0, 1.0, 1e16):
                expected = c_function(ctypes.c_longdouble(number))
                actual = fb_function(ctypes.c_longdouble(number))
                assert actual == expected, (
                    f"{name}({number}): C={expected}, FreeBASIC={actual}"
                )
        for name in (
            "c2fbLongDoubleReturn", "c2fbLongDoubleExternalArgument",
        ):
            c_function = getattr(reference, name)
            fb_function = getattr(converted, name)
            for function in (c_function, fb_function):
                function.argtypes = [ctypes.c_longdouble]
                function.restype = ctypes.c_longdouble
            for number in (-1.0, 0.0, 1.0, 1e16):
                expected = c_function(ctypes.c_longdouble(number))
                actual = fb_function(ctypes.c_longdouble(number))
                assert actual == expected, (
                    f"{name}({number}): C={expected}, FreeBASIC={actual}"
                )
        c_function = reference.c2fbLongDoubleExternalResult
        fb_function = converted.c2fbLongDoubleExternalResult
        for function in (c_function, fb_function):
            function.argtypes = [ctypes.c_longdouble]
            function.restype = ctypes.c_int32
        for number in (-1.0, 0.0, 1.0, 1e16):
            expected = c_function(ctypes.c_longdouble(number))
            actual = fb_function(ctypes.c_longdouble(number))
            assert actual == expected, (
                f"c2fbLongDoubleExternalResult({number}): "
                f"C={expected}, FreeBASIC={actual}"
            )


def check_generic_body_tree_catalog_field_growth(converter, work):
    # The project-wide layout catalog spans declaration-sized source batches.
    source_directory = work / "generic-body-tree-catalog-field-growth-source"
    source_directory.mkdir()
    output_directory = work / "generic-body-tree-catalog-field-growth-output"
    field_count = 6600
    units = tuple(f"unit{index}" for index in range(5))
    for unit in units:
        fields = "".join(
            f"    int field{index:04d};\n" for index in range(field_count)
        )
        (source_directory / f"{unit}.c").write_text(
            f"struct C2fbCatalogRecord_{unit} {{\n{fields}}};\n"
            f"int c2fbCatalogUnit_{unit}(void) {{ return 1; }}\n"
        )

    summary = run([
        converter, "translate-simple-generic-tree-c", str(source_directory),
        str(output_directory), "cc",
    ])
    assert "processed 5 preprocessed C source files" in summary, summary
    for unit in units:
        candidate = output_directory / f"{unit}_candidates.bas"
        assert candidate.is_file(), f"Missing tree candidate: {candidate}"
        assert f"Function c2fbCatalogUnit_{unit}" in candidate.read_text()


def check_generic_header_case_insensitive_record_fields(converter, fbc, work):
    header = work / "case-insensitive-record-fields.h"
    output = work / "case-insensitive-record-fields.bi"
    header.write_text(
        "struct c2fb_case_field_names {\n"
        "    int field;\n"
        "    int FIELD;\n"
        "    int field_;\n"
        "};\n"
    )
    run([converter, "generic-header", str(header), str(output), "cc"])
    generated = output.read_text()
    record_match = re.search(
        r"(?ms)^Type _c2fb_record_c2fb_c2fb_case_field_names"
        r"(?: Field = \d+)?\s*\n(.*?)^End Type$", generated)
    if record_match is None:
        record_match = re.search(
            r"(?ms)^Union _c2fb_record_c2fb_c2fb_case_field_names\s*\n"
            r"\s+Type\s*\n(.*?)^\s+End Type$", generated)
    assert record_match is not None, generated
    field_names = re.findall(r"^\s*(\w+)\s+As\s+", record_match.group(1), re.M)
    assert field_names == ["field", "FIELD_", "field__"], field_names

    wrapper = work / "check-case-insensitive-record-fields.bas"
    wrapper.write_text(
        f'#include once "{output.name}"\n'
        "Dim As c2fb_c2fb_case_field_names value\n"
        "value.field = 1\n"
        "value.FIELD_ = 2\n"
        "value.field__ = 3\n"
        "If value.field <> 1 OrElse value.FIELD_ <> 2 OrElse _\n"
        "   value.field__ <> 3 Then End 1\n"
    )
    executable = work / "check-case-insensitive-record-fields"
    run(fbc + ["-w", "all", "-i", str(work), str(wrapper), "-x", str(executable)],
        cwd=work)
    run([str(executable)], cwd=work)


