def check_generic_body_line_marker_space_before_offsetof(
    converter, fbc, cc, repository, work
):
    # System offsetof macros place source markers between builtin arguments.
    source_directory = work / "generic-body-line-marker-offsetof"
    source_directory.mkdir()
    source = source_directory / "matchinfo_size.c"
    source.write_text(
        "#include <stddef.h>\n"
        "typedef struct MatchinfoBuffer {\n"
        "    unsigned char aRef[3];\n"
        "    int nElem;\n"
        "    int bGlobal;\n"
        "    char *zMatchinfo;\n"
        "    unsigned int aMI[0];\n"
        "} MatchinfoBuffer;\n"
        "unsigned long long c2fbMatchinfoBufferBytes(int nElem) {\n"
        "    return sizeof(unsigned int) * (2*(long long)nElem+1)\n"
        "        + offsetof(MatchinfoBuffer, aMI)\n"
        "        + (((1)+1)/2)*sizeof(unsigned long long);\n"
        "}\n"
    )
    candidate = source_directory / "matchinfo_size_candidates.bas"
    snippet_profile = Path(__file__).resolve().parents[1] / "profiles/sqlite-fts3-snippet-body.rsp"
    type_binding = source_directory / "matchinfo_types.bi"
    type_binding.write_text(
        "Type Fts3MatchinfoBuffer\n"
        "    aRef(0 To 2) As UByte\n"
        "    nElem As Long\n"
        "    bGlobal As Long\n"
        "    zMatchinfo As ZString Ptr\n"
        "    aMI(0 To 0) As ULong\n"
        "End Type\n"
    )
    fb_source_directory = source_directory
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        "@" + str(snippet_profile), *cc,
        f"--fb-source-directory={fb_source_directory}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "OffsetOf(Fts3MatchinfoBuffer, aMI(0))" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "matchinfo_types.bi"\n'
        f'#include once "{candidate.name}"\n'
    )

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference_function = reference.c2fbMatchinfoBufferBytes
    reference_function.argtypes = [ctypes.c_int]
    reference_function.restype = ctypes.c_ulonglong

    for backend_flags in ([], ["-gen", "gcc"]):
        converted_path = source_directory / (
            "converted_native.so" if not backend_flags else "converted_gcc.so"
        )
        run(fbc + ["-w", "all", *backend_flags, "-i",
                   str(fb_source_directory), "-dll", str(wrapper), "-x",
                   str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        converted_function = converted.c2fbMatchinfoBufferBytes
        converted_function.argtypes = [ctypes.c_int]
        converted_function.restype = ctypes.c_ulonglong
        for element_count in (0, 1, 2, 7, 64):
            reference_value = reference_function(element_count)
            converted_value = converted_function(element_count)
            assert reference_value == converted_value, (
                f"backend={backend_flags!r}, nElem={element_count}, "
                f"C={reference_value}, FreeBASIC={converted_value}\n{generated}"
            )


def check_generic_body_offsetof_array_element_zero(converter, fbc, cc, work):
    # offsetof(record, array[0]) resolves to the array member's start.
    source_directory = work / "generic-body-offsetof-array-element-zero"
    source_directory.mkdir()
    source = source_directory / "offsetof_array_element.c"
    source.write_text(
        "unsigned long long c2fbDirentNameOffset(void) {\n"
        "    struct C2fbDirent { char d_type; char d_name[1]; };\n"
        "    return __builtin_offsetof(struct C2fbDirent, d_name[0]);\n"
        "}\n"
        "void *c2fbDirentFromFileName(char *name) {\n"
        "    struct C2fbDirent { char d_type; char d_name[1]; };\n"
        "    return (void *) ((char *) name -\n"
        "        __builtin_offsetof(struct C2fbDirent, d_name[0]));\n"
        "}\n"
    )
    candidate = source_directory / "offsetof_array_element_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        *cc,
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert re.search(r"OffsetOf\(\w+, d_name\(0\)\)", generated), generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbDirentNameOffset.restype = ctypes.c_size_t
    reference.c2fbDirentFromFileName.argtypes = [ctypes.c_void_p]
    reference.c2fbDirentFromFileName.restype = ctypes.c_void_p

    for backend_flags in ([], ["-gen", "gcc"]):
        converted_path = source_directory / (
            "converted_native.so" if not backend_flags else "converted_gcc.so"
        )
        run(fbc + ["-w", "all", *backend_flags, "-dll", str(candidate), "-x",
                   str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        converted.c2fbDirentNameOffset.restype = ctypes.c_size_t
        converted.c2fbDirentFromFileName.argtypes = [ctypes.c_void_p]
        converted.c2fbDirentFromFileName.restype = ctypes.c_void_p

        buffer = ctypes.create_string_buffer(32)
        name_address = ctypes.addressof(buffer) + 1
        assert reference.c2fbDirentNameOffset() == 1
        assert converted.c2fbDirentNameOffset() == \
            reference.c2fbDirentNameOffset()
        for library in (reference, converted):
            entry_address = library.c2fbDirentFromFileName(name_address)
            assert entry_address == name_address - 1
            ctypes.c_ubyte.from_address(entry_address).value = 8
            assert buffer.raw[0] == 8
            buffer[0] = 0


def check_generic_body_null_pointer_arguments(converter, fbc, cc, work):
    # C integer zero must become a null pointer of each declared parameter type.
    source_directory = work / "generic-body-null-pointer-arguments"
    source_directory.mkdir()
    source = source_directory / "null_pointer_arguments.c"
    source.write_text(
        "static int c2fbNullPointerHelper(\n"
        "    int *pInteger, const unsigned char *pByte\n"
        ") {\n"
        "    return pInteger == 0 && pByte == 0;\n"
        "}\n"
        "int c2fbNullPointerCall(void) {\n"
        "    return c2fbNullPointerHelper(0, 0);\n"
        "}\n"
    )
    candidate = source_directory / "null_pointer_arguments_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        *cc,
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "CPtr(c2fb_c_int Ptr, 0)" in generated, generated
    assert "CPtr(Const UByte Ptr, 0)" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbNullPointerCall.restype = ctypes.c_int
    assert reference.c2fbNullPointerCall() == 1

    for backend_flags in ([], ["-gen", "gcc"]):
        converted_path = source_directory / (
            "converted_native.so" if not backend_flags else "converted_gcc.so"
        )
        run(fbc + ["-w", "all", *backend_flags, "-dll", str(candidate),
                   "-x", str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        converted.c2fbNullPointerCall.restype = ctypes.c_int
        assert converted.c2fbNullPointerCall() == 1


def check_generic_body_c23_nullptr(converter, fbc, cc, work):
    source_directory = work / "generic-body-c23-nullptr"
    source_directory.mkdir()
    source = source_directory / "c23_nullptr.c"
    source.write_text(
        "typedef int (*c2fbNullptrCallback)(int);\n"
        "void *c2fbNullptrReturn(void) { return nullptr; }\n"
        "int c2fbNullptrCompare(void *p) { return p == nullptr; }\n"
        "int c2fbNullptrCall(void) { return c2fbNullptrCompare(nullptr); }\n"
        "int c2fbNullptrCallbackCompare(c2fbNullptrCallback p) {\n"
        "    return p == nullptr;\n"
        "}\n"
    )
    candidate = source_directory / "c23_nullptr_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        *cc, "-std=gnu23",
    ])
    assert "translated 4 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "CPtr(Any Ptr, 0)" in generated, generated

    reference_path = source_directory / "c23_reference.so"
    run(cc + ["-std=gnu23", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbNullptrReturn.restype = ctypes.c_void_p
    reference.c2fbNullptrCompare.argtypes = [ctypes.c_void_p]
    reference.c2fbNullptrCompare.restype = ctypes.c_int
    reference.c2fbNullptrCall.restype = ctypes.c_int
    callback_type = ctypes.CFUNCTYPE(ctypes.c_int, ctypes.c_int)
    reference.c2fbNullptrCallbackCompare.argtypes = [callback_type]
    reference.c2fbNullptrCallbackCompare.restype = ctypes.c_int
    null_callback = ctypes.cast(None, callback_type)

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"]),
                           ("llvm", ["-gen", "llvm"])):
        converted_path = source_directory / f"c23_converted_{backend}.so"
        run(fbc + ["-w", "all", *flags, "-dll", str(candidate),
                   "-x", str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        converted.c2fbNullptrReturn.restype = ctypes.c_void_p
        converted.c2fbNullptrCompare.argtypes = [ctypes.c_void_p]
        converted.c2fbNullptrCompare.restype = ctypes.c_int
        converted.c2fbNullptrCall.restype = ctypes.c_int
        converted.c2fbNullptrCallbackCompare.argtypes = [callback_type]
        converted.c2fbNullptrCallbackCompare.restype = ctypes.c_int
        assert converted.c2fbNullptrReturn() == reference.c2fbNullptrReturn()
        assert converted.c2fbNullptrCompare(None) == reference.c2fbNullptrCompare(None) == 1
        assert converted.c2fbNullptrCompare(ctypes.c_void_p(1)) == \
            reference.c2fbNullptrCompare(ctypes.c_void_p(1)) == 0
        assert converted.c2fbNullptrCall() == reference.c2fbNullptrCall() == 1
        assert converted.c2fbNullptrCallbackCompare(null_callback) == \
            reference.c2fbNullptrCallbackCompare(null_callback) == 1
        callback = callback_type(lambda value: value + 1)
        assert converted.c2fbNullptrCallbackCompare(callback) == \
            reference.c2fbNullptrCallbackCompare(callback) == 0

    legacy_source = source_directory / "c17_nullptr_identifier.c"
    legacy_source.write_text(
        "int c2fbLegacyNullptrParameter(int nullptr) { return nullptr; }\n"
    )
    legacy_candidate = source_directory / "c17_nullptr_candidates.bas"
    legacy_summary = run([
        converter, "translate-simple-generic-c", str(legacy_source),
        str(legacy_candidate), *cc, "-std=gnu17",
    ])
    assert "translated 1 simple functions; skipped 0" in legacy_summary, legacy_summary
    assert "CPtr(Any Ptr, 0)" not in legacy_candidate.read_text()


