def check_generic_body_local_may_alias_typedef(converter, fbc, cc, work):
    # The C alias is safe to lower because FreeBASIC backends permit pointer
    # aliasing; the regression keeps the typedef and its wide load intact.
    source_directory = work / "generic-body-local-may-alias-typedef"
    source_directory.mkdir()
    source = source_directory / "local_may_alias.c"
    source.write_text(
        "unsigned long c2fbLocalMayAliasLoad(const double *value) {\n"
        "    typedef unsigned long int longword "
        "__attribute__((__may_alias__));\n"
        "    const longword *word = (const longword *) value;\n"
        "    return *word;\n"
        "}\n"
    )
    candidate = source_directory / "local_may_alias_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        *cc,
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "c2fb_c_ulong" in generated, generated
    assert "__may_alias__" not in generated, generated

    reference_source = source_directory / "local_may_alias_reference.c"
    reference_source.write_text(
        source.read_text().replace(
            "c2fbLocalMayAliasLoad", "c2fbReferenceLocalMayAliasLoad"
        )
    )
    reference_path = source_directory / "local_may_alias_reference.so"
    run(cc + ["-std=gnu11", "-O2", "-fstrict-aliasing", "-shared", "-fPIC",
              str(reference_source), "-o", str(reference_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference_function = reference.c2fbReferenceLocalMayAliasLoad
    reference_function.argtypes = [ctypes.POINTER(ctypes.c_double)]
    reference_function.restype = ctypes.c_ulong

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"]),
                           ("llvm", ["-gen", "llvm"])):
        converted_path = source_directory / f"local_may_alias_{backend}.so"
        run(fbc + ["-w", "all", *flags, "-dll", str(candidate), "-x",
                   str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        converted_function = converted.c2fbLocalMayAliasLoad
        converted_function.argtypes = [ctypes.POINTER(ctypes.c_double)]
        converted_function.restype = ctypes.c_ulong
        for value in (0.0, 1.0, -0.0, 1.5, 3.14159, float("inf"), float("nan")):
            argument = ctypes.c_double(value)
            assert converted_function(ctypes.byref(argument)) == \
                reference_function(ctypes.byref(argument)), (
                    f"backend={backend}, value={value}"
                )


