def check_generic_body_source_unit_local_types(converter, fbc, cc, work):
    source_directory = work / "generic-body-source-unit-local-types"
    source_directory.mkdir()
    source = source_directory / "private_types.c"
    source.write_text(
        "typedef struct PrivateNode { int value; } PrivateNode;\n"
        "typedef struct PrivateLink { const PrivateNode *node; } PrivateLink;\n"
        "static const int private_values[] = { 3, 7, 11 };\n"
        "int c2fbReadPrivateNode(const PrivateLink *link) {\n"
        "    if (!link || !link->node) return -1;\n"
        "    return link->node->value + private_values[1];\n"
        "}\n"
    )
    candidate = source_directory / "private_types_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    type_context = source_directory / "private_types_candidates_types.bi"
    assert type_context.is_file(), "Source-unit converter omitted the private type context"
    assert "Type c2fb_PrivateNode" in type_context.read_text()
    assert "Private Dim Shared c2fb_private_values(0 To 2) As Const Long = " \
        "{3, 7, 11}" in type_context.read_text()
    assert "' c2fb static-object: private_values=c2fb_private_values" \
        in type_context.read_text()
    generated = candidate.read_text()
    assert '#include once "private_types_candidates_types.bi"' in generated
    assert "c2fb_private_values(" in generated
    assert "c2fb_global_private_values" not in generated, \
        "Body translator duplicated storage already present in the local context"
    assert "translated 1 simple functions; skipped 0" in summary, summary

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "private_types_candidates.bas"\n'
        "Dim node As c2fb_PrivateNode\n"
        "Dim link As c2fb_PrivateLink\n"
        "node.value = 37\n"
        "link.node = @node\n"
        "If c2fbReadPrivateNode(@link) <> 44 Then End 1\n"
    )
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check.o")], cwd=source_directory)


def check_generic_body_source_unit_callback_typedef_alias_initializer(
    converter, fbc, cc, work
):
    # Inline header callbacks must match body aliases after ABI typedef resolution.
    source_directory = work / "generic-body-source-unit-callback-typedef-alias"
    source_directory.mkdir()
    header = source_directory / "callback_table.h"
    header.write_text(
        "typedef unsigned long size_t;\n"
        "typedef int C2fbStatus;\n"
        "typedef struct C2fbConfig { int value; } C2fbConfig;\n"
        "typedef struct C2fbVtable {\n"
        "    C2fbStatus (*probe)(void **context, const C2fbConfig *config);\n"
        "    C2fbStatus (*load)(void *context, const char *name, void *destination, size_t size);\n"
        "} C2fbVtable;\n"
        "C2fbStatus c2fbProbe(void **context, const C2fbConfig *config);\n"
        "C2fbStatus c2fbLoad(void *context, const char *name, void *destination, size_t size);\n"
    )
    source = source_directory / "callback_table.c"
    source.write_text(
        '#include "callback_table.h"\n'
        "C2fbStatus c2fbProbe(void **context, const C2fbConfig *config) { "
        "return (context != 0) + (config != 0); }\n"
        "C2fbStatus c2fbLoad(void *context, const char *name, "
        "void *destination, size_t size) { "
        "return context != 0 && name != 0 && destination != 0 && size != 0; }\n"
        "static const C2fbVtable c2fbVtable = { c2fbProbe, c2fbLoad };\n"
        "const C2fbVtable *c2fbGetVtable(void) { return &c2fbVtable; }\n"
    )
