def check_generic_body_source_unit_binding_closure(converter, fbc, cc, work):
    # A filtered source index must retain transitive includes and the BAS owner
    # of an included interface without exposing unrelated binding modules.
    root = work / "generic-body-source-unit-binding-closure"
    source_directory = root / "c-source"
    bindings = root / "fb-source"
    (bindings / "helpers").mkdir(parents=True)
    source = source_directory / "caller.c"
    source_directory.mkdir()
    (bindings / "api.bi").write_text(
        '#include once "helpers/helper.bi"\n'
        '#include once "detached.bi"\n'
    )
    (bindings / "helpers/helper.bi").write_text(
        'Declare Function moduleHelper CDecl Alias "moduleHelper" '
        "(ByVal value As Integer) As Integer\n"
    )
    (bindings / "helpers/helper.bas").write_text(
        '#include once "helper.bi"\n'
        'Function moduleHelper CDecl Alias "moduleHelper" '
        "(ByVal value As Integer) As Integer\n"
        "    Return value + 1\n"
        "End Function\n"
    )
    (bindings / "detached.bi").write_text(
        'Declare Function detachedHelper CDecl Alias "detachedHelper" '
        "(ByVal value As Integer) As Integer\n"
    )
    (bindings / "detached.bas").write_text(
        'Function detachedHelper CDecl Alias "detachedHelper" '
        "(ByVal value As Integer) As Integer\n"
        "    Return value + 2\n"
        "End Function\n"
    )
    (bindings / "unused.bas").write_text(
        "Private Sub unrelatedBinding()\nEnd Sub\n"
    )
    source.write_text(
        "int moduleHelper(int value);\n"
        "int c2fbSourceUnitCall(int value) { return moduleHelper(value); }\n"
    )

    candidate = root / "caller_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--fb-source-directory", str(bindings),
        "--fb-source-pattern=api.bi", "--fb-source-include-closure",
    ])
    assert "indexed 1 selected and 3 included FreeBASIC source files" in summary, summary
    generated = candidate.read_text()
    assert "Function c2fbSourceUnitCall" in generated, generated
    assert '#include once "caller_candidates_types.bi"' in generated, generated

    wrapper = root / "check.bas"
    wrapper.write_text(
        '#include once "helpers/helper.bas"\n'
        '#include once "caller_candidates.bas"\n'
        "If c2fbSourceUnitCall(41) <> 42 Then End 1\n"
    )
    executable = root / "check"
    runtime_include = Path(fbc[0]).resolve().parent.parent / "inc"
    include_options = ["-i", str(runtime_include)] if runtime_include.is_dir() else []
    run(fbc + ["-w", "all", *include_options, "-i", str(bindings),
               str(wrapper), "-x", str(executable)], cwd=root)
    run([str(executable)], cwd=root)

    for index, invalid_glob in enumerate(("../*", "C:/outside.bi")):
        invalid_pattern = subprocess.run([
            sys.executable, str(source_unit_tool), str(source),
            str(root / f"invalid_candidates_{index}.bas"), "--converter", converter,
            "--fb-source-directory", str(bindings),
            "--fb-source-pattern=" + invalid_glob,
        ], capture_output=True, text=True)
        assert invalid_pattern.returncode == 2, invalid_pattern.stderr
        assert "must be a non-empty path relative" in invalid_pattern.stderr, \
            invalid_pattern.stderr

    invalid_body_option = subprocess.run([
        sys.executable, str(source_unit_tool), str(source),
        str(root / "invalid_body_option.bas"), "--converter", converter,
        "--fb-source-directory", str(bindings),
        "--body-option=--fb-source-include-closure",
    ], capture_output=True, text=True)
    assert invalid_body_option.returncode == 2, invalid_body_option.stderr
    assert "is managed by c2fb_source_unit.py" in invalid_body_option.stderr, \
        invalid_body_option.stderr

    source_unit_spec = importlib.util.spec_from_file_location(
        "c2fb_source_unit_limit_test", source_unit_tool
    )
    source_unit_module = importlib.util.module_from_spec(source_unit_spec)
    source_unit_spec.loader.exec_module(source_unit_module)
    source_unit_module.MAX_INDEXED_BODY_SOURCE_FILES = 3
    try:
        source_unit_module.collect_binding_sources(
            bindings, True, ("api.bi",), include_closure=True
        )
    except ValueError as error:
        assert "source limit" in str(error), error
    else:
        raise AssertionError("FreeBASIC include closure exceeded its source limit")


def check_generic_body_source_unit_nonsibling_procedure_owner(
    converter, fbc, cc, work
):
    # A selected interface can be implemented by a differently named module.
    root = work / "generic-body-source-unit-nonsibling-procedure-owner"
    source_directory = root / "c-source"
    bindings = root / "fb-source"
    bindings.mkdir(parents=True)
    source = source_directory / "caller.c"
    source_directory.mkdir()
    (bindings / "api.bi").write_text(
        '#include once "nested.bi"\n'
        'Declare Function c2fbRootValue CDecl Alias "c2fbRootValue" '
        "(ByVal value As Long) As Long\n"
    )
    (bindings / "nested.bi").write_text(
        'Declare Function c2fbNestedExisting CDecl Alias "c2fbNestedExisting" '
        "(ByVal value As Long) As Long\n"
    )
    (bindings / "api.bas").write_text(
        '#include once "api.bi"\n'
        'Function c2fbRootValue CDecl Alias "c2fbRootValue" '
        "(ByVal value As Long) As Long\n"
        "    Return value + 1\n"
        "End Function\n"
    )
    (bindings / "nested_owner.bas").write_text(
        '#include once "nested.bi"\n'
        'Function c2fbNestedExisting CDecl Alias "c2fbNestedExisting" '
        "(ByVal value As Long) As Long\n"
        "    Return value + 2\n"
        "End Function\n"
    )
    (bindings / "unrelated.bas").write_text(
        "Private Sub c2fbUnrelatedSourceModule()\nEnd Sub\n"
    )
    source.write_text(
        "int c2fbRootValue(int value);\n"
        "int c2fbNestedExisting(int value);\n"
        "int c2fbNestedExisting(int value) { return value + 2; }\n"
        "int c2fbCaller(int value) {\n"
        "    return c2fbRootValue(value) + c2fbNestedExisting(value);\n"
        "}\n"
    )

    candidate = root / "caller_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--fb-source-directory", str(bindings),
        "--fb-source-pattern=api.bi", "--fb-source-include-closure",
    ])
    assert "indexed 1 selected and 3 included FreeBASIC source files" in summary, summary
    assert "already-ported=1" in summary, summary
    generated = candidate.read_text()
    assert "c2fb skipped c2fbNestedExisting: FreeBASIC body already exists" \
        in generated, generated
    assert not any(
        line.startswith("Function c2fbNestedExisting ")
        for line in generated.splitlines()
    ), generated

    wrapper = root / "check.bas"
    wrapper.write_text(
        '#include once "api.bas"\n'
        '#include once "nested_owner.bas"\n'
        '#include once "caller_candidates.bas"\n'
        "If c2fbCaller(40) <> 83 Then End 1\n"
    )
    executable = root / "check"
    run(fbc + ["-w", "all", "-i", str(bindings), "-i", str(root),
               str(wrapper), "-x", str(executable)], cwd=root)
    run([str(executable)], cwd=root)


def check_generic_body_source_unit_preprocessed_goto(converter, fbc, cc, work):
    # Source-unit preprocessing selects a C branch before lowering labels and goto.
    source_directory = work / "generic-body-source-unit-preprocessed-goto"
    source_directory.mkdir()
    source = source_directory / "conditional_goto.c"
    source.write_text(
        "int c2fbConditionalGoto(int value) {\n"
        "    int adjustment;\n"
        "#if C2FB_FEATURE == 1\n"
        "    adjustment = 7;\n"
        "#else\n"
        "    adjustment = 3;\n"
        "#endif\n"
        "    if (value < 0) goto make_positive;\n"
        "    value += adjustment;\n"
        "    goto finished;\n"
        "make_positive:\n"
        "    value = -value + adjustment;\n"
        "finished:\n"
        "    return value;\n"
        "}\n"
    )
    candidate = source_directory / "conditional_goto_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--header-compiler-option=-DC2FB_FEATURE=1",
        "--body-compiler-option=-DC2FB_FEATURE=1",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "Goto c2fb_label_" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", "-DC2FB_FEATURE=1",
              str(source), "-o", str(reference_path)], cwd=source_directory)
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x",
               str(converted_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        function = library.c2fbConditionalGoto
        function.argtypes = [ctypes.c_int]
        function.restype = ctypes.c_int
    for value in (-19, -1, 0, 1, 37):
        assert reference.c2fbConditionalGoto(value) == \
            converted.c2fbConditionalGoto(value)


def check_generic_body_source_unit_flexible_byte_array_access(
    converter, fbc, cc, work
):
    # The generated tail accessor preserves C's omitted flexible-array storage.
    source_directory = work / "generic-body-source-unit-flexible-byte-array"
    source_directory.mkdir()
    source = source_directory / "packet.c"
    source.write_text(
        "#include <stddef.h>\n"
        "typedef struct Packet {\n"
        "    unsigned int length;\n"
        "    unsigned char payload[];\n"
        "} Packet;\n"
        "unsigned char *c2fbGetPacketPayload(Packet *packet) {\n"
        "    return packet->payload;\n"
        "}\n"
        "unsigned int c2fbGetPacketPayloadOffset(void) {\n"
        "    return (unsigned int)offsetof(Packet, payload);\n"
        "}\n"
        "int c2fbWritePacketPayload(Packet *packet, int value) {\n"
        "    packet->payload[1] = (unsigned char)value;\n"
        "    return packet->payload[1];\n"
        "}\n"
    )
    candidate = source_directory / "packet_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    type_context = source_directory / "packet_candidates_types.bi"
    type_text = type_context.read_text()
    generated = candidate.read_text()
    assert "payload_tail_ptr" in type_text, type_text
    assert "c2fb_Packet_payload_tail_ptr(arg0)" in generated, generated
    assert "c2fb_Packet_payload_tail_ptr(Cast(c2fb_Packet Ptr, 0))" \
        in generated, generated
    assert "translated 3 simple functions; skipped 0" in summary, summary

    reference = source_directory / "packet_layout_reference.c"
    reference.write_text(
        "#include <stddef.h>\n"
        "typedef struct Packet {\n"
        "    unsigned int length;\n"
        "    unsigned char payload[];\n"
        "} Packet;\n"
        "unsigned int c2fbReferencePacketPayloadOffset(void) {\n"
        "    return (unsigned int)offsetof(Packet, payload);\n"
        "}\n"
    )
    reference_object = source_directory / "packet-layout-reference.o"
    run(cc + ["-std=c99", "-Wall", "-Wextra", "-Werror", "-c",
              str(reference), "-o", str(reference_object)], cwd=source_directory)
    candidate_object = source_directory / "packet-candidate.o"
    run(fbc + ["-w", "all", "-c", str(candidate), "-o",
               str(candidate_object)], cwd=source_directory)

    wrapper = source_directory / "check_packet_payload.bas"
    wrapper.write_text(
        '#include once "packet_candidates_types.bi"\n'
        'Declare Function c2fbGetPacketPayload CDecl '
        'Alias "c2fbGetPacketPayload" '
        '(ByVal packet As c2fb_Packet Ptr) As UByte Ptr\n'
        'Declare Function c2fbWritePacketPayload CDecl '
        'Alias "c2fbWritePacketPayload" '
        '(ByVal packet As c2fb_Packet Ptr, ByVal value As Long) As Long\n'
        'Declare Function c2fbGetPacketPayloadOffset CDecl '
        'Alias "c2fbGetPacketPayloadOffset" () As ULong\n'
        'Declare Function c2fbReferencePacketPayloadOffset CDecl '
        'Alias "c2fbReferencePacketPayloadOffset" () As ULong\n'
        "Dim packet As c2fb_Packet\n"
        "Dim payload As UByte Ptr = c2fbGetPacketPayload(@packet)\n"
        "Dim cOffset As ULong = c2fbReferencePacketPayloadOffset()\n"
        "If cOffset <> SizeOf(packet) Then End 1\n"
        "If c2fbGetPacketPayloadOffset() <> cOffset Then End 2\n"
        "If payload <> Cast(UByte Ptr, @packet) + cOffset Then End 3\n"
        "If c2fbWritePacketPayload(@packet, &H5A) <> &H5A Then End 4\n"
        "If payload[1] <> &H5A Then End 5\n"
    )
    executable = source_directory / "check_packet_payload"
    run(fbc + ["-w", "all", str(wrapper), str(candidate_object),
               str(reference_object), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_body_source_unit_nonbyte_flexible_record_array(
    converter, fbc, cc, work
):
    # The hidden tail placeholder preserves member alignment, while sizeof stays rejected.
    source_directory = work / "generic-body-source-unit-nonbyte-flexible-record-array"
    source_directory.mkdir()
    header = source_directory / "flex.h"
    header.write_text(
        "#include <stdint.h>\n"
        "typedef struct Item { uint32_t value; } Item;\n"
        "typedef struct Flex { uint32_t count; Item items[]; } Flex;\n"
    )
    source = source_directory / "flex.c"
    source.write_text(
        "#include <stddef.h>\n"
        '#include "flex.h"\n'
        "size_t c2fbFlexOffset(void) { return offsetof(Flex, items); }\n"
        "uint32_t c2fbFlexGet(Flex *value, uint32_t index) {\n"
        "    if ((value == NULL) || (index >= value->count)) return 0;\n"
        "    return value->items[index].value;\n"
        "}\n"
        "size_t c2fbFlexSize(void) { return sizeof(Flex); }\n"
    )
    candidate = source_directory / "flex_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--include-header-types",
        f"--header-compiler-option=-I{source_directory}",
        f"--body-compiler-option=-I{source_directory}",
    ])
    assert "translated 2 simple functions; skipped 1" in summary, summary
    type_context = candidate.with_name(candidate.stem + "_types.bi").read_text()
    assert "_c2fb_items_flex_storage As c2fb_Item" in type_context, type_context
    assert "synthetic flexible-array element preserves tail alignment" \
        in type_context, type_context
    generated = candidate.read_text()
    assert "c2fb_Flex_items_tail_ptr" in generated, generated
    assert "Cast(c2fb_size_t, c2fb_Flex_items_tail_ptr(" in generated, generated
    assert "c2fb skipped c2fbFlexSize" in generated, generated

    support = source_directory / "support.c"
    support.write_text(
        "#include <stddef.h>\n"
        "#include <stdlib.h>\n"
        '#include "flex.h"\n'
        "Flex *c2fbMakeFlex(uint32_t count) {\n"
        "    Flex *value = malloc(offsetof(Flex, items) + count * sizeof(Item));\n"
        "    if (value == NULL) return NULL;\n"
        "    value->count = count;\n"
        "    for (uint32_t index = 0; index < count; ++index)\n"
        "        value->items[index].value = 23u + index * 17u;\n"
        "    return value;\n"
        "}\n"
        "void c2fbFreeFlex(Flex *value) { free(value); }\n"
    )
    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c11", "-shared", "-fPIC", str(source), str(support),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "flex_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x",
               str(converted_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    reference.c2fbMakeFlex.argtypes = [ctypes.c_uint32]
    reference.c2fbMakeFlex.restype = ctypes.c_void_p
    reference.c2fbFreeFlex.argtypes = [ctypes.c_void_p]
    for library in (reference, converted):
        library.c2fbFlexOffset.restype = ctypes.c_size_t
        library.c2fbFlexGet.argtypes = [ctypes.c_void_p, ctypes.c_uint32]
        library.c2fbFlexGet.restype = ctypes.c_uint32
    assert converted.c2fbFlexOffset() == reference.c2fbFlexOffset()

    value = reference.c2fbMakeFlex(5)
    assert value, "C flexible-array fixture allocation failed"
    try:
        for index in range(6):
            assert converted.c2fbFlexGet(value, index) == \
                reference.c2fbFlexGet(value, index)
    finally:
        reference.c2fbFreeFlex(value)


def check_generic_body_source_unit_qualified_flexible_record_array(
    converter, fbc, cc, work
):
    # A qualified size hint gives one record a typed tail slot without changing
    # another record that happens to use the same member name.
    source_directory = work / "generic-body-source-unit-qualified-flexible-record-array"
    source_directory.mkdir()
    source = source_directory / "packet.c"
    source.write_text(
        "#include <stddef.h>\n"
        "typedef struct Point { int x; int y; } Point;\n"
        "typedef struct RecordPacket { unsigned char marker; Point point[]; } RecordPacket;\n"
        "typedef struct BytePacket { unsigned char marker; unsigned char point[]; } BytePacket;\n"
        "unsigned int c2fbRecordPacketPointOffset(void) {\n"
        "    return (unsigned int)offsetof(RecordPacket, point);\n"
        "}\n"
        "int c2fbReadRecordPacketPoint(const RecordPacket *packet) {\n"
        "    return packet->point[0].x;\n"
        "}\n"
    )
