def check_generic_body_anonymous_record_pointer_typedef_cast(
    converter, fbc, cc, work
):
    # Xlib exposes Display opaquely, then uses an anonymous record-pointer
    # typedef inside ScreenOfDisplay. C keeps Display and display distinct.
    source_directory = work / "generic-body-anonymous-record-pointer-typedef"
    source_directory.mkdir()
    source = source_directory / "xlib_display.c"
    source.write_text(
        "#include <stdlib.h>\n"
        "typedef struct _XDisplay Display;\n"
        "typedef struct XScreen { void *default_gc; } XScreen;\n"
        "typedef struct { XScreen *screens; } *_XPrivDisplay;\n"
        "#define ScreenOfDisplay(dpy, scrn) \\\n"
        "    (&((_XPrivDisplay)(dpy))->screens[(scrn)])\n"
        "void *c2fbDefaultGC(Display *display, int screen) {\n"
        "    return ScreenOfDisplay(display, screen)->default_gc;\n"
        "}\n"
        "#ifndef C2FB_CONVERTER\n"
        "void *c2fbMakeTestDisplay(XScreen *screens) {\n"
        "    _XPrivDisplay display = malloc(sizeof(*display));\n"
        "    if (!display) return 0;\n"
        "    display->screens = screens;\n"
        "    return display;\n"
        "}\n"
        "void c2fbFreeTestDisplay(void *display) { free(display); }\n"
        "#endif\n"
    )
    candidate = source_directory / "xlib_display_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--header-compiler-option=-DC2FB_CONVERTER",
        "--body-compiler-option=-DC2FB_CONVERTER",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary

    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x",
               str(converted_path)], cwd=source_directory)
    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)

    class XScreen(ctypes.Structure):
        _fields_ = [("default_gc", ctypes.c_void_p)]

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbDefaultGC.argtypes = [ctypes.c_void_p, ctypes.c_int]
        library.c2fbDefaultGC.restype = ctypes.c_void_p
    reference.c2fbMakeTestDisplay.argtypes = [ctypes.POINTER(XScreen)]
    reference.c2fbMakeTestDisplay.restype = ctypes.c_void_p
    reference.c2fbFreeTestDisplay.argtypes = [ctypes.c_void_p]

    marker = 0x12345678
    screens = (XScreen * 1)(XScreen(marker))
    display = reference.c2fbMakeTestDisplay(screens)
    assert display, "C fixture could not allocate its Xlib-style display"
    try:
        expected = reference.c2fbDefaultGC(display, 0)
        actual = converted.c2fbDefaultGC(display, 0)
        assert expected == marker and actual == expected, (expected, actual)
    finally:
        reference.c2fbFreeTestDisplay(display)


def check_generic_body_source_unit_included_typedef_dependencies(
    converter, fbc, cc, work
):
    # Included scalar typedefs used by a source-private record must travel with
    # that record even when the type-only pass filters the included header.
    source_directory = work / "generic-body-source-unit-included-typedef-dependencies"
    source_directory.mkdir()
    (source_directory / "value_type.h").write_text(
        "typedef unsigned long C2fbBaseWord;\n"
        "typedef C2fbBaseWord C2fbWord;\n"
    )
    source = source_directory / "record.c"
    source.write_text(
        '#include "value_type.h"\n'
        "struct PrivateRecord { C2fbWord value; };\n"
        "static C2fbWord scalar = 19;\n"
        "static struct PrivateRecord record = { 37 };\n"
        "int c2fbReadRecord(void) { return (int)record.value; }\n"
        "int c2fbReadScalar(void) { return (int)scalar; }\n"
    )
    candidate = source_directory / "record_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        f"--header-compiler-option=-I{source_directory}",
        f"--body-compiler-option=-I{source_directory}",
    ])
    type_context = candidate.with_name(candidate.stem + "_types.bi")
    generated_types = type_context.read_text()
    assert "Type c2fb_C2fbBaseWord As CULong" in generated_types, generated_types
    assert "Type c2fb_C2fbWord As c2fb_C2fbBaseWord" in generated_types, generated_types
    assert "value As c2fb_C2fbWord" in generated_types, generated_types
    assert "Private Dim Shared c2fb_scalar As c2fb_C2fbWord = 19" in generated_types, \
        generated_types
    assert "translated 2 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "record_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x",
               str(converted_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    assert reference.c2fbReadRecord() == converted.c2fbReadRecord() == 37
    assert reference.c2fbReadScalar() == converted.c2fbReadScalar() == 19


def check_generic_body_source_unit_included_header_types(
    converter, fbc, cc, work
):
    # Header-defined records need an explicit source filter expansion because
    # their layouts are not private to the root C file.
    source_directory = work / "generic-body-source-unit-included-header-types"
    source_directory.mkdir()
    (source_directory / "record.h").write_text(
        "typedef struct C2fbIncludedRecord {\n"
        "    int value;\n"
        "    int count;\n"
        "} C2fbIncludedRecord;\n"
        "int c2fbUpdateIncludedRecord(C2fbIncludedRecord *record, int delta);\n"
    )
    source = source_directory / "record.c"
    source.write_text(
        '#include "record.h"\n'
        "int c2fbUpdateIncludedRecord(C2fbIncludedRecord *record, int delta) {\n"
        "    if (record == 0) return -1;\n"
        "    record->value += delta;\n"
        "    record->count++;\n"
        "    return record->value + record->count;\n"
        "}\n"
    )
    candidate = source_directory / "record_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--include-header-types",
        f"--header-compiler-option=-I{source_directory}",
        f"--body-compiler-option=-I{source_directory}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated_types = candidate.with_name(candidate.stem + "_types.bi").read_text()
    assert "value As Long" in generated_types, generated_types
    assert "count As Long" in generated_types, generated_types
    assert "Declare Function c2fbUpdateIncludedRecord" not in generated_types, \
        generated_types

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "record_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x",
               str(converted_path)], cwd=source_directory)

    class IncludedRecord(ctypes.Structure):
        _fields_ = [("value", ctypes.c_int), ("count", ctypes.c_int)]

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        function = library.c2fbUpdateIncludedRecord
        function.argtypes = [ctypes.POINTER(IncludedRecord), ctypes.c_int]
        function.restype = ctypes.c_int

    for initial_value, initial_count, delta in ((3, 1, 7), (0, 0, -5)):
        expected_record = IncludedRecord(initial_value, initial_count)
        actual_record = IncludedRecord(initial_value, initial_count)
        expected = reference.c2fbUpdateIncludedRecord(
            ctypes.byref(expected_record), delta
        )
        actual = converted.c2fbUpdateIncludedRecord(
            ctypes.byref(actual_record), delta
        )
        assert actual == expected
        assert (actual_record.value, actual_record.count) == (
            expected_record.value, expected_record.count
        )


def check_generic_body_source_unit_external_header_enum_call(
    converter, fbc, cc, work
):
    # An included C prototype with a tagged enum parameter remains callable.
    source_directory = work / "generic-body-source-unit-external-header-enum-call"
    source_directory.mkdir()
    (source_directory / "helper.h").write_text(
        "#ifndef C2FB_EXTERNAL_ENUM_HELPER_H\n"
        "#define C2FB_EXTERNAL_ENUM_HELPER_H\n"
        "enum helper_mode { HELPER_DISABLED, HELPER_ENABLED };\n"
        "int helper(int, char const *, enum helper_mode);\n"
        "#endif\n"
    )
    source = source_directory / "root.c"
    source.write_text(
        '#include "helper.h"\n'
        "int c2fbHeaderEnumCall(int descriptor, char const *name,\n"
        "                       enum helper_mode mode) {\n"
        "    return helper(descriptor, name, mode);\n"
        "}\n"
    )
    helper = source_directory / "helper.c"
    helper.write_text(
        '#include "helper.h"\n'
        "int helper(int descriptor, char const *name, enum helper_mode mode) {\n"
        "    return descriptor == 17 && name != 0 && name[0] == 'c'\n"
        "           && mode == HELPER_ENABLED ? 42 : 0;\n"
        "}\n"
    )
    candidate = source_directory / "root_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--include-header-types",
        f"--header-compiler-option=-I{source_directory}",
        f"--body-compiler-option=-I{source_directory}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert 'Declare Function c2fb_external_helper CDecl Alias "helper"' \
        in generated, generated
    generated_types = candidate.with_name(candidate.stem + "_types.bi").read_text()
    assert "c2fb_helper_mode" in generated_types, generated_types

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=gnu11", "-shared", "-fPIC", str(source), str(helper),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbHeaderEnumCall.argtypes = [
        ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
    ]
    reference.c2fbHeaderEnumCall.restype = ctypes.c_int
    assert reference.c2fbHeaderEnumCall(17, b"copy", 1) == 42
    assert reference.c2fbHeaderEnumCall(16, b"copy", 1) == 0

    helper_object = source_directory / "helper.o"
    run(cc + ["-std=gnu11", "-fPIC", f"-I{source_directory}", "-c",
              str(helper), "-o", str(helper_object)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        "/'\n"
        "    Project: C2FB source-unit regression\n"
        "    File: check.bas\n"
        "    Purpose: Exercise an imported C call with a tagged enum parameter.\n"
        "    This file intentionally does NOT contain: the helper implementation.\n"
        "'/\n"
        '#include once "root_candidates.bas"\n'
        "Sub Main()\n"
        "    If c2fbHeaderEnumCall(17, StrPtr(\"copy\"), _\n"
        "        Cast(c2fb_helper_mode, 1)) <> 42 Then End 1\n"
        "    If c2fbHeaderEnumCall(16, StrPtr(\"copy\"), _\n"
        "        Cast(c2fb_helper_mode, 1)) <> 0 Then End 2\n"
        "    End 0\n"
        "End Sub\n"
        "/' end of check.bas '/\n"
    )

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"]),
                           ("llvm", ["-gen", "llvm"])):
        if backend == "llvm" and shutil.which("llc") is None:
            continue
        object_path = source_directory / f"root-{backend}.o"
        run(fbc + flags + ["-w", "all", "-c", str(wrapper),
                           "-o", str(object_path)], cwd=source_directory)

    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(helper_object),
               "-x", str(executable)], cwd=source_directory)
    run([str(executable)], cwd=source_directory)


