def check_generic_body_source_unit_anonymous_header_static_record(
    converter, fbc, cc, work
):
    # Generated header tables can exceed the cap used for small local lists.
    source_directory = work / "generic-body-anonymous-header-static-record"
    source_directory.mkdir()
    values = [11 + index for index in range(600)]
    (source_directory / "table.h").write_text(
        "static const struct {\n"
        "    unsigned int header[1];\n"
        "    unsigned int values[600];\n"
        "} c2fbTable = {{600}, {" + ", ".join(map(str, values)) + "}};\n"
    )
    source = source_directory / "root.c"
    source.write_text(
        '#include "table.h"\n'
        "int c2fbReadHeaderTable(unsigned int index) {\n"
        "    if (c2fbTable.header[0] != 600 || index >= 600) return -1;\n"
        "    return c2fbTable.values[index];\n"
        "}\n"
    )
    candidate = source_directory / "root_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        f"--header-compiler-option=-I{source_directory}",
        f"--body-compiler-option=-I{source_directory}",
        "--body-option=--include-global-definitions",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "c2fbTable" in generated, generated
    assert "c2fb_static_record_0" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC",
              f"-I{source_directory}", str(source), "-o", str(reference_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbReadHeaderTable.argtypes = [ctypes.c_uint]
    reference.c2fbReadHeaderTable.restype = ctypes.c_int

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        wrapper = source_directory / f"check-{backend}.bas"
        wrapper.write_text('#include once "root_candidates.bas"\n')
        run(fbc + flags + ["-w", "all", "-dll", str(wrapper),
                           "-x", str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        converted.c2fbReadHeaderTable.argtypes = [ctypes.c_uint]
        converted.c2fbReadHeaderTable.restype = ctypes.c_int
        for index in (0, 511, 512, 599, 600):
            expected = values[index] if index < len(values) else -1
            assert reference.c2fbReadHeaderTable(index) == \
                converted.c2fbReadHeaderTable(index) == expected


def check_generic_body_source_unit_transitive_header_declaration(
    converter, fbc, cc, work
):
    # Declarations in nested FreeBASIC includes must suppress duplicate C prototypes.
    source_directory = work / "generic-body-source-unit-transitive-header-declaration"
    source_directory.mkdir()
    context = source_directory / "context"
    context.mkdir()
    (context / "inner.bi").write_text(
        'Declare Function c2fbNestedBody CDecl Alias "c2fbNestedBody" '
        "(ByVal value As Any Ptr) As Long\n"
    )
    (context / "root.bi").write_text(
        '#include once "inner.bi"\n'
        'Declare Function c2fbRootCallable CDecl Alias "c2fbRootCallable" '
        "(ByVal value As Any Ptr) As Long\n"
    )
    (context / "root.bas").write_text(
        '#include once "root.bi"\n'
        'Function c2fbRootCallable CDecl Alias "c2fbRootCallable" '
        "(ByVal value As Any Ptr) As Long\n"
        "    Return 40\n"
        "End Function\n"
    )
    source = source_directory / "root.c"
    source.write_text(
        "int c2fbRootCallable(void *value);\n"
        "int c2fbNestedBody(void *value);\n"
        "int c2fbNestedBody(void *value) { return value != 0; }\n"
        "int c2fbCaller(void *value) { return c2fbRootCallable(value); }\n"
    )
    candidate = source_directory / "root_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--fb-source-directory", str(context),
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert '#include once "root.bi"' in generated, generated
    assert "Declare Function c2fbNestedBody" not in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "root.bas"\n'
        '#include once "root_candidates.bas"\n'
        "If c2fbCaller(0) <> 40 Then End 1\n"
        "If c2fbNestedBody(0) <> 0 Then End 2\n"
        "If c2fbNestedBody(Cast(Any Ptr, 1)) <> 1 Then End 3\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", "-i", str(context), "-i",
               str(source_directory), str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_body_source_unit_incomplete_external_object(
    converter, fbc, cc, work
):
    # An incomplete extern object can still be passed by address in a body.
    source_directory = work / "generic-body-source-unit-incomplete-extern-object"
    source_directory.mkdir()
    (source_directory / "opaque.h").write_text(
        "struct C2fbOpaque;\n"
        "extern struct C2fbOpaque c2fb_opaque_object;\n"
        "int c2fb_opaque_check(struct C2fbOpaque *value);\n"
    )
    source = source_directory / "body.c"
    source.write_text(
        '#include "opaque.h"\n'
        "int c2fbPassOpaqueAddress(void) {\n"
        "    return c2fb_opaque_check(&c2fb_opaque_object);\n"
        "}\n"
    )
    support = source_directory / "support.c"
    support.write_text(
        '#include "opaque.h"\n'
        "struct C2fbOpaque { int marker; };\n"
        "struct C2fbOpaque c2fb_opaque_object = { 42 };\n"
        "int c2fb_opaque_check(struct C2fbOpaque *value) {\n"
        "    return value == &c2fb_opaque_object && value->marker == 42;\n"
        "}\n"
    )

    candidate = source_directory / "body_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        f"--header-compiler-option=-I{source_directory}",
        f"--body-compiler-option=-I{source_directory}",
    ])
    generated = candidate.read_text()
    generated_types = candidate.with_name("body_candidates_types.bi").read_text()
    assert "Type c2fb_C2fbOpaque As _c2fb_record_c2fb_C2fbOpaque" \
        in generated_types, generated_types
    assert "Extern c2fb_global_c2fb_opaque_object Alias " \
        '"c2fb_opaque_object" As c2fb_C2fbOpaque' in generated, generated
    assert "@(c2fb_global_c2fb_opaque_object)" in generated, generated
    assert "translated 1 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", f"-I{source_directory}",
              str(source), str(support), "-o", str(reference_path)],
        cwd=source_directory)
    support_object = source_directory / "support.o"
    run(cc + ["-std=c99", "-Wall", "-Wextra", "-Werror", "-fPIC",
              "-I" + str(source_directory), "-c", str(support), "-o",
              str(support_object)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "body_candidates.bas"\n'
        "If c2fbPassOpaqueAddress() <> 1 Then End 1\n"
    )
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), str(support_object),
               "-x", str(converted_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    reference.c2fbPassOpaqueAddress.restype = ctypes.c_int
    converted.c2fbPassOpaqueAddress.restype = ctypes.c_int
    assert reference.c2fbPassOpaqueAddress() == \
        converted.c2fbPassOpaqueAddress() == 1


def check_generic_body_source_unit_local_record_array_enum_bound(
    converter, fbc, cc, work
):
    # A supported enum bound should keep a local record array fixed-size.
    source_directory = work / "generic-body-source-unit-local-record-array-enum-bound"
    source_directory.mkdir()
    source = source_directory / "record_array.c"
    source.write_text(
        "typedef struct C2fbLocalEntry {\n"
        "    int prefix;\n"
        "    unsigned char value;\n"
        "} C2fbLocalEntry;\n"
        "enum { C2fbLocalEntryCount = 1u << 2 };\n"
        "int c2fbLocalRecordArrayEnumBound(int base) {\n"
        "    C2fbLocalEntry table[C2fbLocalEntryCount];\n"
        "    for (int index = 0; index < C2fbLocalEntryCount; ++index) {\n"
        "        table[index].prefix = base + index;\n"
        "        table[index].value = (unsigned char)(index * 3);\n"
        "    }\n"
        "    return table[C2fbLocalEntryCount - 1].prefix * 16 + "
        "table[C2fbLocalEntryCount - 1].value + (int)sizeof(table);\n"
        "}\n"
    )
    candidate = source_directory / "record_array_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "record_array_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x",
               str(converted_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    reference_function = reference.c2fbLocalRecordArrayEnumBound
    converted_function = converted.c2fbLocalRecordArrayEnumBound
    for function in (reference_function, converted_function):
        function.argtypes = [ctypes.c_int]
        function.restype = ctypes.c_int
    for base in (-17, 0, 31):
        assert converted_function(base) == reference_function(base)


def check_generic_body_source_unit_local_union_header_sizeof_bound(
    converter, fbc, cc, work
):
    # A header record's target size can appear in a local union's storage bound.
    source_directory = work / "generic-body-source-unit-local-union-header-sizeof"
    source_directory.mkdir()
    header = source_directory / "file-name-info.h"
    header.write_text(
        "typedef struct _FILE_NAME_INFO {\n"
        "    unsigned long FileNameLength;\n"
        "    unsigned short FileName[1];\n"
        "} FILE_NAME_INFO;\n"
    )
    source = source_directory / "local_union.c"
    source.write_text(
        '#include "file-name-info.h"\n'
        "int c2fbLocalUnionHeaderSizeofBound(int input) {\n"
        "    union {\n"
        "        FILE_NAME_INFO info;\n"
        "        char storage[sizeof(FILE_NAME_INFO) +\n"
        "                     32 * sizeof(unsigned short)];\n"
        "    } value;\n"
        "    value.info.FileNameLength = (unsigned long) input;\n"
        "    value.info.FileName[0] = (unsigned short) (input + 1);\n"
        "    return (int) sizeof(value) + (int) value.info.FileNameLength +\n"
        "        value.info.FileName[0];\n"
        "}\n"
    )
    candidate = source_directory / "local_union_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0], "--include-header-types",
        f"--header-compiler-option=-I{source_directory}",
        f"--body-compiler-option=-I{source_directory}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", f"-I{source_directory}",
              str(source), "-o", str(reference_path)], cwd=source_directory)
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x",
               str(converted_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbLocalUnionHeaderSizeofBound.argtypes = [ctypes.c_int]
        library.c2fbLocalUnionHeaderSizeofBound.restype = ctypes.c_int
    for value in (-17, 0, 31):
        assert converted.c2fbLocalUnionHeaderSizeofBound(value) == \
            reference.c2fbLocalUnionHeaderSizeofBound(value)


def check_generic_body_source_unit_record_typedef_alias_fields(
    converter, fbc, cc, work
):
    # A field that uses a typedef alias still resolves to the underlying C tag.
    source_directory = work / "generic-body-source-unit-record-typedef-alias-fields"
    source_directory.mkdir()
    source = source_directory / "record_alias_fields.c"
    source.write_text(
        "typedef struct InnerTag { int value; } Inner;\n"
        "typedef struct OuterTag { Inner inner; } Outer;\n"
        "int c2fbWriteNestedAlias(Outer *object, int value) {\n"
        "    object->inner.value = value;\n"
        "    return object->inner.value;\n"
        "}\n"
    )
    candidate = source_directory / "record_alias_fields_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    assert 'Function c2fbWriteNestedAlias CDecl Alias "c2fbWriteNestedAlias"' \
        in candidate.read_text()

    class InnerValue(ctypes.Structure):
        _fields_ = [("value", ctypes.c_int)]

    class OuterValue(ctypes.Structure):
        _fields_ = [("inner", InnerValue)]

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "record_alias_fields_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x", str(converted_path)],
        cwd=source_directory)
    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source), "-o", str(reference_path)],
        cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbWriteNestedAlias.argtypes = [
            ctypes.POINTER(OuterValue), ctypes.c_int,
        ]
        library.c2fbWriteNestedAlias.restype = ctypes.c_int
    for initial_value, replacement in ((-7, 13), (0, -2), (29, 29)):
        reference_value = OuterValue(InnerValue(initial_value))
        converted_value = OuterValue(InnerValue(initial_value))
        assert reference.c2fbWriteNestedAlias(
            ctypes.byref(reference_value), replacement) == \
            converted.c2fbWriteNestedAlias(
                ctypes.byref(converted_value), replacement)
        assert reference_value.inner.value == converted_value.inner.value == replacement


def check_generic_body_source_unit_type_keyword_field(
    converter, fbc, cc, work
):
    # C field names must survive FreeBASIC keywords and UNICODE defines.
    source_directory = work / "generic-body-source-unit-type-keyword-field"
    source_directory.mkdir()
    source = source_directory / "type_field.c"
    source.write_text(
        "typedef struct TypeField { int type; int new; int new_; int and; int value; int unicode; } TypeField;\n"
        "int c2fbUpdateTypeField(TypeField *field, int type, int new, int new_, int and, int value, int unicode) {\n"
        "    field->type = type;\n"
        "    field->new = new;\n"
        "    field->new_ = new_;\n"
        "    field->and = and;\n"
        "    field->value = value;\n"
        "    field->unicode = unicode;\n"
        "    return field->type + field->new + field->new_ + field->and + field->value + field->unicode;\n"
        "}\n"
    )
    candidate = source_directory / "type_field_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    type_context = candidate.with_name(
        candidate.stem + "_types.bi").read_text()
    for field_name in ("type", "new_", "new__", "and_", "unicode_"):
        assert re.search(
            rf"^[ \t]+{re.escape(field_name)} As Long$", type_context, re.M
        ), type_context
    assert "unicode_" in candidate.read_text()

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "type_field_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-d", "UNICODE=1", "-dll", str(wrapper),
               "-x", str(converted_path)], cwd=source_directory)

    class TypeField(ctypes.Structure):
        _fields_ = [
            ("type", ctypes.c_int), ("new", ctypes.c_int),
            ("new_", ctypes.c_int), ("and", ctypes.c_int),
            ("value", ctypes.c_int), ("unicode", ctypes.c_int),
        ]

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbUpdateTypeField.argtypes = [
            ctypes.POINTER(TypeField), ctypes.c_int, ctypes.c_int,
            ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int,
        ]
        library.c2fbUpdateTypeField.restype = ctypes.c_int
    for values in ((-7, 13, 17, 5, 29, 31), (0, -2, 6, 7, -11, 4),
                   (29, 29, 3, -3, 0, -19)):
        reference_field = TypeField(1, 2, 3, 4, 5, 6)
        converted_field = TypeField(1, 2, 3, 4, 5, 6)
        reference_result = reference.c2fbUpdateTypeField(
            ctypes.byref(reference_field), *values)
        converted_result = converted.c2fbUpdateTypeField(
            ctypes.byref(converted_field), *values)
        assert reference_result == converted_result == sum(values)
        field_names = ("type", "new", "new_", "and", "value", "unicode")
        assert [getattr(reference_field, name) for name in field_names] == \
            [getattr(converted_field, name) for name in field_names] == \
            list(values)


def check_generic_body_source_unit_sizeof_offset_local_array(
    converter, fbc, cc, work
):
    # A fixed local byte buffer may be bounded by a record's mapped size and field offset.
    source_directory = work / "generic-body-source-unit-sizeof-offset-local-array"
    source_directory.mkdir()
    source = source_directory / "tail.c"
    source.write_text(
        "typedef struct TailRecord {\n"
        "    unsigned char prefix[3];\n"
        "    int marker;\n"
        "    unsigned char tail[5];\n"
        "} TailRecord;\n"
        "int c2fbReadTail(TailRecord *record) {\n"
        "    unsigned char saved[sizeof(TailRecord) - "
        "__builtin_offsetof(TailRecord, marker)];\n"
        "    saved[0] = record->tail[0];\n"
        "    saved[sizeof(saved) - 1] = record->tail[4];\n"
        "    return sizeof(saved) + saved[0] + saved[sizeof(saved) - 1];\n"
        "}\n"
    )
    candidate = source_directory / "tail_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    # Known record layouts may fold this offset into the fixed local extent.
    assert "OffsetOf(" in generated or "0 To 11" in generated, generated
    assert "SizeOf(" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x",
               str(converted_path)], cwd=source_directory)

    class TailRecord(ctypes.Structure):
        _fields_ = [
            ("prefix", ctypes.c_uint8 * 3),
            ("marker", ctypes.c_int),
            ("tail", ctypes.c_uint8 * 5),
        ]

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbReadTail.argtypes = [ctypes.POINTER(TailRecord)]
        library.c2fbReadTail.restype = ctypes.c_int
    for first, last in ((1, 2), (0, 255), (19, 41)):
        reference_value = TailRecord((1, 2, 3), 7, (first, 0, 0, 0, last))
        converted_value = TailRecord((1, 2, 3), 7, (first, 0, 0, 0, last))
        assert reference.c2fbReadTail(ctypes.byref(reference_value)) == \
            converted.c2fbReadTail(ctypes.byref(converted_value))


def check_generic_body_source_unit_large_array_member_sizeof(
    converter, fbc, cc, work
):
    # sizeof must preserve an array member before the ordinary pointer decay.
    source_directory = work / "generic-body-source-unit-large-array-member-sizeof"
    source_directory.mkdir()
    source = source_directory / "large_array_member.c"
    source.write_text(
        "#include <string.h>\n"
        "typedef struct Capture { short buffer[65536]; } Capture;\n"
        "typedef struct Context { Capture capture; } Context;\n"
        "int c2fbClearCaptureBuffer(Context *context) {\n"
        "    memset(context->capture.buffer, 0, sizeof(context->capture.buffer));\n"
        "    return (int)sizeof(context->capture.buffer);\n"
        "}\n"
        "int c2fbClearCaptureBufferAddress(Context *context) {\n"
        "    memset(&context->capture.buffer, 0, sizeof(context->capture.buffer));\n"
        "    return (int)sizeof(context->capture.buffer);\n"
        "}\n"
    )
    candidate = source_directory / "large_array_member_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "65536ULL * SizeOf(Short)" in generated, generated
    assert "arg0->capture.buffer(0)" in generated, generated
    type_context = candidate.with_name(
        candidate.stem + "_types.bi").read_text()
    assert re.search(r"buffer\(0 To 65535\) As Short", type_context), type_context

    class CaptureValue(ctypes.Structure):
        _fields_ = [("buffer", ctypes.c_short * 65536)]

    class ContextValue(ctypes.Structure):
        _fields_ = [("capture", CaptureValue)]

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    function_names = (
        "c2fbClearCaptureBuffer", "c2fbClearCaptureBufferAddress",
    )
    for function_name in function_names:
        function = getattr(reference, function_name)
        function.argtypes = [ctypes.POINTER(ContextValue)]
        function.restype = ctypes.c_int

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "large_array_member_candidates.bas"\n')
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(wrapper), "-x",
                           str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        expected_size = ctypes.sizeof(CaptureValue)
        assert expected_size == 131072
        for function_name in function_names:
            function = getattr(converted, function_name)
            function.argtypes = [ctypes.POINTER(ContextValue)]
            function.restype = ctypes.c_int
            reference_context = ContextValue()
            converted_context = ContextValue()
            ctypes.memset(ctypes.addressof(reference_context), 0x7F,
                          ctypes.sizeof(reference_context))
            ctypes.memset(ctypes.addressof(converted_context), 0x7F,
                          ctypes.sizeof(converted_context))
            assert getattr(reference, function_name)(
                ctypes.byref(reference_context)) == expected_size
            assert function(ctypes.byref(converted_context)) == expected_size
            assert not any(reference_context.capture.buffer)
            assert not any(converted_context.capture.buffer)

    header_directory = source_directory / "header-array-member-sizeof"
    header_directory.mkdir()
    header = header_directory / "array_fields.h"
    header.write_text(
        "struct C2fbHeaderArrayProbe {\n"
        "    char user[32];\n"
        "    short id[4];\n"
        "};\n"
    )
    header_source = header_directory / "array_fields.c"
    header_source.write_text(
        "#define _GNU_SOURCE 1\n"
        '#include "array_fields.h"\n'
        "#include <string.h>\n"
        "int c2fbHeaderArrayUserSize(void) {\n"
        "    return sizeof (((struct C2fbHeaderArrayProbe *) 0)->user);\n"
        "}\n"
        "int c2fbHeaderArrayIdSize(void) {\n"
        "    return sizeof (((struct C2fbHeaderArrayProbe *) 0)->id);\n"
        "}\n"
        "int c2fbHeaderArrayParameterSize("
        "struct C2fbHeaderArrayProbe *record) {\n"
        "    return sizeof record->user;\n"
        "}\n"
        "int c2fbHeaderArrayBoundedLength(const char *text) {\n"
        "    return strnlen(text, "
        "sizeof (((struct C2fbHeaderArrayProbe *) 0)->user));\n"
        "}\n"
    )
    header_candidate = header_directory / "array_fields_candidates.bas"
    header_summary = run([
        sys.executable, str(source_unit_tool), str(header_source),
        str(header_candidate), "--converter", converter,
        "--compiler", cc[0], "--include-header-types",
    ], cwd=header_directory)
    assert "translated 4 simple functions; skipped 0" in header_summary, header_summary
    header_generated = header_candidate.read_text()
    assert "Return Cast(c2fb_size_t, 32ULL)" in header_generated, header_generated
    assert "Return Cast(c2fb_size_t, 8ULL)" in header_generated, header_generated

    header_reference_path = header_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(header_source),
              "-o", str(header_reference_path)], cwd=header_directory)
    header_reference = ctypes.CDLL(str(header_reference_path))
    header_function_names = (
        "c2fbHeaderArrayUserSize", "c2fbHeaderArrayIdSize",
        "c2fbHeaderArrayParameterSize", "c2fbHeaderArrayBoundedLength",
    )
    expected_sizes = (32, 8, 32, 32)
    for function_name in header_function_names:
        function = getattr(header_reference, function_name)
        if function_name.endswith("ParameterSize"):
            function.argtypes = [ctypes.c_void_p]
        elif function_name.endswith("BoundedLength"):
            function.argtypes = [ctypes.c_char_p]
        else:
            function.argtypes = []
        function.restype = ctypes.c_int

    header_wrapper = header_directory / "check.bas"
    header_wrapper.write_text(
        '#include once "array_fields_candidates.bas"\n'
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = header_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(header_wrapper), "-x",
                           str(converted_path)], cwd=header_directory)
        converted = ctypes.CDLL(str(converted_path))
        for index, function_name in enumerate(header_function_names):
            function = getattr(converted, function_name)
            if function_name.endswith("ParameterSize"):
                function.argtypes = [ctypes.c_void_p]
            elif function_name.endswith("BoundedLength"):
                function.argtypes = [ctypes.c_char_p]
            else:
                function.argtypes = []
            function.restype = ctypes.c_int
            if function_name.endswith("BoundedLength"):
                arguments = (b"abcdefghijklmnopqrstuvwxyz1234567890",)
            elif function.argtypes:
                arguments = (ctypes.c_void_p(),)
            else:
                arguments = ()
            assert getattr(header_reference, function_name)(*arguments) == expected_sizes[index]
            assert function(*arguments) == expected_sizes[index]


def check_generic_body_chained_assignment_expressions(converter, fbc, cc, work):
    # Assignment expressions associate right-to-left and yield their stored value.
    source_directory = work / "generic-body-chained-assignment-expressions"
    source_directory.mkdir()
    source = source_directory / "chained_assignment.c"
    source.write_text(
        "static int c2fb_storage;\n"
        "static int c2fb_allocate_calls;\n"
        "static int *c2fbAllocateOnce(int value) {\n"
        "    c2fb_allocate_calls++;\n"
        "    c2fb_storage = value;\n"
        "    return &c2fb_storage;\n"
        "}\n"
        "int c2fbChainAssign(int *left, int *right, int value) {\n"
        "    return *left = *right = value;\n"
        "}\n"
        "int *c2fbAssignPointerChain(int **output, int value) {\n"
        "    int *local = 0;\n"
        "    int *result = 0;\n"
        "    result = local = c2fbAllocateOnce(value);\n"
        "    *output = result;\n"
        "    return result;\n"
        "}\n"
        "int c2fbAllocationCallCount(void) { return c2fb_allocate_calls; }\n"
        "int c2fbAssignLoopCondition(int *values) {\n"
        "    int index = 0;\n"
        "    while ((values[index] = index + 1) < 4) index++;\n"
        "    return values[2] + values[3] + index;\n"
        "}\n"
    )
    candidate = source_directory / "chained_assignment_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        *cc,
    ])
    assert "translated 5 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "c2fbAllocateOnce" in generated, generated
    assert "c2fbAssignPointerChain" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "chained_assignment_candidates.bas"\n')
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(wrapper), "-x",
                           str(converted_path)], cwd=source_directory)
        reference = ctypes.CDLL(str(reference_path))
        converted = ctypes.CDLL(str(converted_path))
        int_pointer = ctypes.POINTER(ctypes.c_int)
        for library in (reference, converted):
            function = library.c2fbChainAssign
            function.argtypes = [int_pointer, int_pointer, ctypes.c_int]
            function.restype = ctypes.c_int
            function = library.c2fbAssignPointerChain
            function.argtypes = [ctypes.POINTER(int_pointer), ctypes.c_int]
            function.restype = int_pointer
            library.c2fbAllocationCallCount.argtypes = []
            library.c2fbAllocationCallCount.restype = ctypes.c_int
            library.c2fbAssignLoopCondition.argtypes = [int_pointer]
            library.c2fbAssignLoopCondition.restype = ctypes.c_int

        for value in (-19, 0, 37):
            reference_left, reference_right = ctypes.c_int(3), ctypes.c_int(9)
            converted_left, converted_right = ctypes.c_int(3), ctypes.c_int(9)
            expected = reference.c2fbChainAssign(
                ctypes.byref(reference_left), ctypes.byref(reference_right), value
            )
            actual = converted.c2fbChainAssign(
                ctypes.byref(converted_left), ctypes.byref(converted_right), value
            )
            assert actual == expected == value
            assert (converted_left.value, converted_right.value) == (
                reference_left.value, reference_right.value
            ) == (value, value)

            reference_output = int_pointer()
            converted_output = int_pointer()
            expected_calls_before = reference.c2fbAllocationCallCount()
            actual_calls_before = converted.c2fbAllocationCallCount()
            expected_pointer = reference.c2fbAssignPointerChain(
                ctypes.byref(reference_output), value
            )
            actual_pointer = converted.c2fbAssignPointerChain(
                ctypes.byref(converted_output), value
            )
            assert ctypes.cast(expected_pointer, ctypes.c_void_p).value == \
                ctypes.cast(reference_output, ctypes.c_void_p).value
            assert ctypes.cast(actual_pointer, ctypes.c_void_p).value == \
                ctypes.cast(converted_output, ctypes.c_void_p).value
            assert actual_pointer.contents.value == expected_pointer.contents.value == value
            actual_calls = converted.c2fbAllocationCallCount()
            expected_calls = reference.c2fbAllocationCallCount()
            assert (actual_calls - actual_calls_before) == \
                (expected_calls - expected_calls_before) == 1, (
                    f"{backend} pointer assignment calls: "
                    f"C={expected_calls - expected_calls_before}, "
                    f"FreeBASIC={actual_calls - actual_calls_before}"
            )

        reference_values = (ctypes.c_int * 5)()
        converted_values = (ctypes.c_int * 5)()
        assert converted.c2fbAssignLoopCondition(converted_values) == \
            reference.c2fbAssignLoopCondition(reference_values)
        assert list(converted_values) == list(reference_values) == [1, 2, 3, 4, 0]


def check_generic_body_infinite_loop_termination(converter, fbc, cc, work):
    # Constant-true loops have no fallthrough path even without a final return.
    source_directory = work / "generic-body-infinite-loop-termination"
    source_directory.mkdir()
    source = source_directory / "infinite_loops.c"
    source.write_text(
        "int c2fbDoUntilReturn(int value) {\n"
        "    do {\n"
        "        if (value > 0) return value + 3;\n"
        "    } while (1);\n"
        "}\n"
        "int c2fbWhileUntilReturn(int value) {\n"
        "    while (1) {\n"
        "        if (value > 0) return value * 2;\n"
        "    }\n"
        "}\n"
        "int c2fbForUntilReturn(int value) {\n"
        "    for (;;) {\n"
        "        if (value > 0) return value - 1;\n"
        "    }\n"
        "}\n"
        "int c2fbForwardGotoInsideInfiniteLoop(int value) {\n"
        "    for (;;) {\n"
        "        for (int index = 0; index < 1; index++) {\n"
        "            goto selected;\n"
        "        }\n"
        "    selected:\n"
        "        if (value > 0) return value + 9;\n"
        "    }\n"
        "}\n"
        "int c2fbForwardGotoOutsideInfiniteLoop(int value) {\n"
        "    for (;;) {\n"
        "        if (value > 0) goto finished;\n"
        "        return 4;\n"
        "    }\n"
        "finished:\n"
        "    value += 1;\n"
        "}\n"
        "int c2fbInfiniteLoopCanBreak(int value) {\n"
        "    do {\n"
        "        if (value > 0) break;\n"
        "    } while (1);\n"
        "}\n"
    )
    candidate = source_directory / "infinite_loops_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc",
    ])
    assert "translated 4 simple functions; skipped 2" in summary, summary
    generated = candidate.read_text()
    assert "c2fbInfiniteLoopCanBreak" not in procedure_names(generated), generated
    assert "c2fbForwardGotoOutsideInfiniteLoop" not in \
        procedure_names(generated), generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    function_names = (
        "c2fbDoUntilReturn", "c2fbWhileUntilReturn", "c2fbForUntilReturn",
        "c2fbForwardGotoInsideInfiniteLoop",
    )
    for function_name in function_names:
        function = getattr(reference, function_name)
        function.argtypes = [ctypes.c_int]
        function.restype = ctypes.c_int

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "infinite_loops_candidates.bas"\n')
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(wrapper), "-x",
                           str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        for function_name in function_names:
            function = getattr(converted, function_name)
            function.argtypes = [ctypes.c_int]
            function.restype = ctypes.c_int
        for value in (1, 4, 19):
            for function_name in function_names:
                expected = getattr(reference, function_name)(value)
                actual = getattr(converted, function_name)(value)
                assert actual == expected, (
                    f"{backend} {function_name}({value}): "
                    f"C={expected}, FreeBASIC={actual}"
                )


def check_generic_body_source_unit_shift_array_bound(converter, fbc, cc, work):
    # C compile-time shift expressions determine fixed module-array storage.
    source_directory = work / "generic-body-source-unit-shift-array-bound"
    source_directory.mkdir()
    source = source_directory / "shift_array.c"
    source.write_text(
        "#define C2FB_TABLE_COUNT (1 + 2 << 3)\n"
        "static int c2fb_shift_table[C2FB_TABLE_COUNT];\n"
        "int c2fbReadShiftArray(int index) {\n"
        "    if (index < 0 || index >= C2FB_TABLE_COUNT) return -1;\n"
        "    c2fb_shift_table[index] = index + 4;\n"
        "    return c2fb_shift_table[index];\n"
        "}\n"
    )
    candidate = source_directory / "shift_array_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    type_context = candidate.with_name(
        candidate.stem + "_types.bi").read_text()
    assert re.search(
        r"Private Dim Shared c2fb_c2fb_shift_table\(0 To 23\) As Long",
        type_context,
    ), type_context
    assert "' c2fb static-object: c2fb_shift_table=" in type_context

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "shift_array_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x", str(converted_path)],
        cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbReadShiftArray.argtypes = [ctypes.c_int]
        library.c2fbReadShiftArray.restype = ctypes.c_int
    for index, expected in ((-1, -1), (0, 4), (7, 11), (23, 27), (24, -1)):
        assert reference.c2fbReadShiftArray(index) == \
            converted.c2fbReadShiftArray(index) == expected


def check_generic_body_source_unit_unsized_external_arrays(
    converter, fbc, cc, work
):
    # A C extern array with no bound is storage beginning at its linker symbol.
    source_directory = work / "generic-body-source-unit-unsized-external-arrays"
    source_directory.mkdir()
    source = source_directory / "reader.c"
    source.write_text(
        "struct Item { int value; };\n"
        "extern const struct Item *c2fb_external_items[];\n"
        "extern int c2fb_external_values[];\n"
        "int c2fb_external_values[3];\n"
        "int c2fbReadExternalItem(int index) {\n"
        "    if (index < 0 || !c2fb_external_items[index]) return -1;\n"
        "    return c2fb_external_items[index]->value;\n"
        "}\n"
        "int c2fbReadCompletedExternalArray(int index) {\n"
        "    if (index < 0 || index >= 3) return -1;\n"
        "    c2fb_external_values[0]++;\n"
        "    return c2fb_external_values[index];\n"
        "}\n"
    )
    support = source_directory / "nodes.c"
    support.write_text(
        "struct Item { int value; };\n"
        "static const struct Item first_item = { 17 };\n"
        "static const struct Item second_item = { -9 };\n"
        "const struct Item *c2fb_external_items[] = {\n"
        "    &first_item, &second_item, 0\n"
        "};\n"
    )
    candidate = source_directory / "reader_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        f"--header-compiler-option=-I{source_directory}",
        f"--body-compiler-option=-I{source_directory}",
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert 'Alias "c2fb_external_items" As Const c2fb_Item Ptr' in generated
    assert "c2fb_global_c2fb_external_items(arg0)" in generated, generated
    assert 'Alias "c2fb_external_values" As c2fb_c_int' in generated

    support_object = source_directory / "nodes.o"
    run(cc + ["-std=c99", "-c", str(support), "-o", str(support_object)],
        cwd=source_directory)
    values_support = source_directory / "values.c"
    values_support.write_text("int c2fb_external_values[3];\n")
    values_support_object = source_directory / "values.o"
    run(cc + ["-std=c99", "-c", str(values_support), "-o",
              str(values_support_object)], cwd=source_directory)
    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source), str(support),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "reader_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), str(support_object),
               str(values_support_object), "-x", str(converted_path)],
        cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbReadExternalItem.argtypes = [ctypes.c_int]
        library.c2fbReadExternalItem.restype = ctypes.c_int
        library.c2fbReadCompletedExternalArray.argtypes = [ctypes.c_int]
        library.c2fbReadCompletedExternalArray.restype = ctypes.c_int
    for index, expected in ((-1, -1), (0, 17), (1, -9), (2, -1)):
        assert reference.c2fbReadExternalItem(index) == \
            converted.c2fbReadExternalItem(index) == expected
    for index, expected in ((0, 1), (1, 0), (0, 3), (2, 0), (-1, -1)):
        assert reference.c2fbReadCompletedExternalArray(index) == \
            converted.c2fbReadCompletedExternalArray(index) == expected


