def check_generic_body_anonymous_local_records(converter, fbc, cc, work):
    # Anonymous function-local structs and unions receive private FB record types.
    source_directory = work / "generic-body-anonymous-local-records"
    source_directory.mkdir()
    source = source_directory / "anonymous_records.c"
    source.write_text(
        "int c2fbAnonymousStaticArray(int index) {\n"
        "    static const struct {\n"
        "        unsigned char key;\n"
        "        unsigned char nChar;\n"
        "        unsigned char code;\n"
        "    } aKeyword[] = { { 0, 7, 4 }, { 1, 5, 2 } };\n"
        "    if (index < 0 || index > 1) return -1;\n"
        "    return aKeyword[index].key + aKeyword[index].nChar + "
        "aKeyword[index].code;\n"
        "}\n"
        "int c2fbAnonymousAutomaticRecord(int value) {\n"
        "    struct { int left; int right; } pair = { value, value + 2 };\n"
        "    return pair.left * 10 + pair.right;\n"
        "}\n"
        "int c2fbNamedLocalRecord(int value) {\n"
        "    struct LocalRecord { int left; int right; };\n"
        "    struct LocalRecord pair = { value, value + 1 };\n"
        "    return pair.left + pair.right;\n"
        "}\n"
        "int c2fbInlineNamedLocalRecord(int value) {\n"
        "    struct InlineRecord { int value; } record = { value };\n"
        "    return record.value + 1;\n"
        "}\n"
        "int c2fbAnonymousLocalUnion(int value) {\n"
        "    union { int signedValue; unsigned int unsignedValue; } storage;\n"
        "    storage.unsignedValue = (unsigned int)value;\n"
        "    return storage.signedValue;\n"
        "}\n"
        "int c2fbAnonymousLocalRecordMultipleDeclarators(int value) {\n"
        "    struct { int base, len; } best, cur;\n"
        "    best.base = value;\n"
        "    best.len = value + 1;\n"
        "    cur.base = value - 2;\n"
        "    cur.len = value + 3;\n"
        "    return best.base * 1000 + best.len * 10 + cur.base + cur.len;\n"
        "}\n"
    )
    candidate = source_directory / "anonymous_record_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        "cc",
    ])
    assert "translated 6 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "Private Type c2fb_local_record_0" in generated, generated
    assert "Private Type c2fb_local_record_1" in generated, generated
    assert "Private Type c2fb_local_record_2" in generated, generated
    assert "Private Type c2fb_local_record_3" in generated, generated
    assert "Private Union c2fb_local_record_4" in generated, generated
    assert "Private Type c2fb_local_record_5" in generated, generated
    assert "Static local" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)])
    reference = ctypes.CDLL(str(reference_path))
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate),
                           "-x", str(converted_path)])
        converted = ctypes.CDLL(str(converted_path))
        for library in (reference, converted):
            library.c2fbAnonymousStaticArray.argtypes = [ctypes.c_int]
            library.c2fbAnonymousStaticArray.restype = ctypes.c_int
            library.c2fbAnonymousAutomaticRecord.argtypes = [ctypes.c_int]
            library.c2fbAnonymousAutomaticRecord.restype = ctypes.c_int
            library.c2fbNamedLocalRecord.argtypes = [ctypes.c_int]
            library.c2fbNamedLocalRecord.restype = ctypes.c_int
            library.c2fbInlineNamedLocalRecord.argtypes = [ctypes.c_int]
            library.c2fbInlineNamedLocalRecord.restype = ctypes.c_int
            library.c2fbAnonymousLocalUnion.argtypes = [ctypes.c_int]
            library.c2fbAnonymousLocalUnion.restype = ctypes.c_int
            library.c2fbAnonymousLocalRecordMultipleDeclarators.argtypes = [
                ctypes.c_int
            ]
            library.c2fbAnonymousLocalRecordMultipleDeclarators.restype = \
                ctypes.c_int
        for index in (-1, 0, 1, 2):
            assert reference.c2fbAnonymousStaticArray(index) == \
                converted.c2fbAnonymousStaticArray(index)
        for value in (-19, -1, 0, 7, 28):
            assert reference.c2fbAnonymousAutomaticRecord(value) == \
                converted.c2fbAnonymousAutomaticRecord(value)
            assert reference.c2fbNamedLocalRecord(value) == \
                converted.c2fbNamedLocalRecord(value)
            assert reference.c2fbInlineNamedLocalRecord(value) == \
                converted.c2fbInlineNamedLocalRecord(value)
        for value in (0, 1, 7, 28):
            assert reference.c2fbAnonymousLocalUnion(value) == \
                converted.c2fbAnonymousLocalUnion(value) == value
        for value in (-19, -1, 0, 7, 28):
            assert reference.c2fbAnonymousLocalRecordMultipleDeclarators(value) == \
                converted.c2fbAnonymousLocalRecordMultipleDeclarators(value)


def check_generic_body_anonymous_local_record_sizeof_array(
    converter, fbc, cc, work
):
    # Anonymous union arrays may use sizeof the member type as their bound.
    source_directory = work / "generic-body-anonymous-local-record-sizeof-array"
    source_directory.mkdir()
    source = source_directory / "anonymous_union_array.c"
    source.write_text(
        "int c2fbAnonymousUnionArray(int value, int byte_index) {\n"
        "    int result = 0;\n"
        "    if (value != 0) {\n"
        "        union { unsigned int word; unsigned char bytes[sizeof(unsigned int)]; } storage;\n"
        "        storage.word = (unsigned int)value;\n"
        "        result = storage.bytes[byte_index];\n"
        "    }\n"
        "    return result;\n"
        "}\n"
    )
    candidate = source_directory / "anonymous_union_array_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "Private Union c2fb_local_record_0" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)])
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate),
                           "-x", str(converted_path)])
        reference = ctypes.CDLL(str(reference_path))
        converted = ctypes.CDLL(str(converted_path))
        for library in (reference, converted):
            library.c2fbAnonymousUnionArray.argtypes = [ctypes.c_int, ctypes.c_int]
            library.c2fbAnonymousUnionArray.restype = ctypes.c_int
        for value in (0, 1, 0x1234567, 0x7654321):
            for byte_index in range(ctypes.sizeof(ctypes.c_uint)):
                assert reference.c2fbAnonymousUnionArray(value, byte_index) == \
                    converted.c2fbAnonymousUnionArray(value, byte_index)


