def check_generic_body_assert_expansion_in_conditional_comma(
    converter, fbc, cc, work
):
    # The assertion failure path belongs only to the selected ?: branch.
    source_directory = work / "generic-body-assert-expansion-conditional-comma"
    source_directory.mkdir()
    source = source_directory / "assert_comma.c"
    source.write_text(
        "static int c2fbCalls;\n"
        "static int __assert_single_arg(int condition) { return condition; }\n"
        "extern void __assert_fail(const char *, const char *, unsigned int, "
        "const char *) __attribute__((noreturn));\n"
        "int c2fbProbe(void) { c2fbCalls++; return 1; }\n"
        "int c2fbCallCount(void) { return c2fbCalls; }\n"
        "#define affirm(condition) ((void) sizeof (__assert_single_arg "
        "(condition)), __extension__ ({ if (condition) ; else "
        "__assert_fail (#condition, __FILE__, __LINE__, __func__); }))\n"
        "int c2fbAssertCommaConditional(int choose) {\n"
        "    return choose ? (affirm(c2fbProbe()), 7) : 11;\n"
        "}\n"
    )
    candidate = source_directory / "assert_comma_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        cc[0],
    ])
    assert "translated 4 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "If arg0 Then" in generated, generated
    assert "__assert_fail" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=gnu11", "-O2", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)])
    reference = ctypes.CDLL(str(reference_path))
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate),
                           "-x", str(converted_path)])
        converted = ctypes.CDLL(str(converted_path))
        for library in (reference, converted):
            library.c2fbAssertCommaConditional.argtypes = [ctypes.c_int]
            library.c2fbAssertCommaConditional.restype = ctypes.c_int
            library.c2fbCallCount.argtypes = []
            library.c2fbCallCount.restype = ctypes.c_int
        for choose in (0, 1, 2):
            reference_calls_before = reference.c2fbCallCount()
            converted_calls_before = converted.c2fbCallCount()
            expected = reference.c2fbAssertCommaConditional(choose)
            actual = converted.c2fbAssertCommaConditional(choose)
            assert actual == expected
            expected_calls = reference.c2fbCallCount() - reference_calls_before
            actual_calls = converted.c2fbCallCount() - converted_calls_before
            assert actual_calls == expected_calls


def check_generic_body_source_unit_emitted_enum_names(
    converter, fbc, cc, work
):
    # Body expressions retain FreeBASIC names for complex emitted enum values.
    source_directory = work / "generic-body-source-unit-emitted-enum-names"
    source_directory.mkdir()
    source = source_directory / "enum_names.c"
    source.write_text(
        "#include <limits.h>\n"
        "#include <stdint.h>\n"
        "enum size_spec {\n"
        "    NO_SIZE = 0, CHAR,\n"
        "    SHORT = CHAR + (UCHAR_MAX < USHRT_MAX),\n"
        "    INT = SHORT + (USHRT_MAX < UINT_MAX),\n"
        "    LONG = INT + (UINT_MAX < ULONG_MAX),\n"
        "    LONG_LONG = LONG + (ULONG_MAX < ULLONG_MAX),\n"
        "    INTMAX = LONG_LONG + (ULLONG_MAX < UINTMAX_MAX)\n"
        "};\n"
        "const char *c2fbChooseFormat(enum size_spec size_spec,\n"
        "    const char *int_format, const char *long_format,\n"
        "    const char *long_long_format, const char *intmax_format) {\n"
        "    return (LONG < INTMAX && size_spec == INTMAX ? intmax_format\n"
        "        : LONG < LONG_LONG && size_spec == LONG_LONG ? long_long_format\n"
        "        : INT < LONG && size_spec == LONG ? long_format\n"
        "        : int_format);\n"
        "}\n"
    )
    candidate = source_directory / "enum_names_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "LONG_" in generated, generated
    assert "INTMAX" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)])
    reference = ctypes.CDLL(str(reference_path))
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate),
                           "-x", str(converted_path)])
        converted = ctypes.CDLL(str(converted_path))
        for library in (reference, converted):
            library.c2fbChooseFormat.argtypes = [
                ctypes.c_int, ctypes.c_char_p, ctypes.c_char_p,
                ctypes.c_char_p, ctypes.c_char_p,
            ]
            library.c2fbChooseFormat.restype = ctypes.c_char_p
        formats = (b"i", b"l", b"ll", b"j")
        for size_spec in range(0, 10):
            assert reference.c2fbChooseFormat(size_spec, *formats) == \
                converted.c2fbChooseFormat(size_spec, *formats)


