    assert invalid_limit_result.returncode != 0
    assert "max_profiles must be an integer from 1 to 4096" in \
        invalid_limit_result.stderr, invalid_limit_result.stderr
    assert not (source_directory / "invalid-profile-limit-bindings").exists()

    target_script_directory = source_directory / "fbfrog-target-script"
    target_script_directory.mkdir()
    (target_script_directory / "include").mkdir()
    (target_script_directory / "predefines.h").write_text(
        "#define C2FB_FORCED_INCLUDE_VALUE 9\n"
        "extern int preIncludedMarker;\n"
    )
    (target_script_directory / "include" / "target_common.h").write_text(
        "#if C2FB_FORCED_INCLUDE_VALUE == 9\n"
        "extern int includePathMarker;\n"
        "#endif\n"
    )
    (target_script_directory / "common.h").write_text(
        "#include <target_common.h>\n"
        "#if C2FB_SELECTED_TARGET == 1\n"
        "extern int selectedLinux64;\n"
        "#elif C2FB_SELECTED_TARGET == 2\n"
        "extern int selectedWindows32;\n"
        "#endif\n"
        "#ifdef C2FB_TARGET_BOOL\n"
        "extern int targetBooleanOn;\n"
        "#else\n"
        "extern int targetBooleanOff;\n"
        "#endif\n"
    )
