def check_fbfrog_boolean_redeclared_in_exclusive_paths(converter, fbc, work):
    source_directory = work / "fbfrog-branch-boolean-declarations"
    source_directory.mkdir()
    (source_directory / "branch.h").write_text(
        "#if C2FB_API_VERSION == 1\n"
        "#ifdef C2FB_OPTIONAL\n"
        "extern int versionOneOptional;\n"
        "#else\n"
        "extern int versionOneDefault;\n"
        "#endif\n"
        "#else\n"
        "#ifdef C2FB_OPTIONAL\n"
        "extern int versionTwoOptional;\n"
        "#else\n"
        "extern int versionTwoDefault;\n"
        "#endif\n"
        "#endif\n"
    )
    script = source_directory / "branches.fbfrog"
    script.write_text(
        "-declareversions C2FB_API_VERSION 1 2\n"
        "-selectversion\n"
        "-case 1\n"
        "-declarebool C2FB_OPTIONAL\n"
        "-case 2\n"
        "-declarebool C2FB_OPTIONAL\n"
        "-endselect\n"
    )
    manifest = source_directory / "branches.json"
    manifest.write_text(json.dumps({
        "input": "branch.h",
        "output_directory": "bindings",
        "combined_binding": "api.bi",
        "converter": converter,
        "fbfrog_version_script": {
            "path": "branches.fbfrog",
            "name_prefix": "branch-api",
            "compiler": "cc",
            "targets": [],
        },
    }))
    matrix_tool = Path(__file__).resolve().parents[1] / "c2fb_target_matrix.py"
    run([sys.executable, str(matrix_tool), str(manifest)], cwd=source_directory)
    binding_directory = source_directory / "bindings"
    assert len(list(binding_directory.glob("branch-api-*.bi"))) == 4
    expected_profiles = {
        (1, True): "versionOneOptional",
        (1, False): "versionOneDefault",
        (2, True): "versionTwoOptional",
        (2, False): "versionTwoDefault",
    }
    for (version, optional), expected_name in expected_profiles.items():
        suffix = "c2fb_optional-on" if optional else "c2fb_optional-off"
        profile = binding_directory / f"branch-api-{version}-{suffix}.bi"
        generated = profile.read_text()
        assert f"c2fb_{expected_name}" in generated, (profile, generated)
        for other_name in set(expected_profiles.values()) - {expected_name}:
            assert f"c2fb_{other_name}" not in generated, (profile, generated)
        wrapper = source_directory / f"check-{version}-{int(optional)}.bas"
        wrapper.write_text('#include once "bindings/api.bi"\n')
        defines = ["-d", f"C2FB_API_VERSION={version}"]
        if optional:
            defines.extend(["-d", "C2FB_OPTIONAL=1"])
        run(fbc + ["-w", "all", *defines, "-c", str(wrapper), "-o",
                   str(source_directory / f"check-{version}-{int(optional)}.o")],
            cwd=source_directory)


def check_generic_header_module_static_objects(converter, fbc, work):
    # File-scope C statics become module-local shared storage, not C externs.
    source_directory = work / "generic-header-module-static-objects"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    large_values = ", ".join(
        str(3 + index * 2) for index in range(128)
    )
    header.write_text(
        "static int counter;\n"
        "static const int initial = 123;\n"
        "static void *opaque = 0;\n"
        "static int values[3] = {1, 2, 3};\n"
        "static int inferred[] = {4, 5};\n"
        "static int largeValues[128] = {" + large_values + "};\n"
        "typedef struct StaticPoint { int x; int y; } StaticPoint;\n"
        "static StaticPoint points[2] = {{0, 0}, {1, 2}};\n"
        "static StaticPoint partialPoint = {7};\n"
        "typedef struct StaticArray { int coord[2]; } StaticArray;\n"
        "static StaticArray arrays[2] = {{0, 0}, {1, 2}};\n"
        "typedef struct StaticPointerRecord {\n"
        "    int value; const int *pointer; const char *text;\n"
        "} StaticPointerRecord;\n"
        "static StaticPointerRecord pointerRecord = {7, &initial, \"record\"};\n"
        "static StaticPointerRecord zeroPointerRecord = {0};\n"
        "typedef struct StaticCallbackRecord {\n"
        "    const char *name; int (*probe)(void); void (*notify)(void);\n"
        "} StaticCallbackRecord;\n"
        "static const StaticCallbackRecord callbackRecord = {\n"
        "    \"unavailable\", 0, 0\n"
        "};\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "12 module-static objects" in summary, summary
    assert "Dim Shared c2fb_counter As Long" in generated, generated
    assert "Dim Shared c2fb_initial As Const Long = 123" in generated, generated
    assert "Dim Shared c2fb_opaque As Any Ptr = CPtr(Any Ptr, 0)" in generated, generated
    assert "Dim Shared c2fb_values(0 To 2) As Long = {1, 2, 3}" in generated, generated
    assert "Dim Shared c2fb_inferred(0 To 1) As Long = {4, 5}" in generated, generated
    large_array_line = next(
        line for line in generated.splitlines()
        if line.startswith("Dim Shared c2fb_largeValues")
    )
    assert large_array_line.startswith(
        "Dim Shared c2fb_largeValues(0 To 127) As Long = {"
    ), large_array_line
    assert large_array_line.endswith("257}"), large_array_line[-80:]
    assert "Dim Shared c2fb_points(0 To 1) As c2fb_StaticPoint = " \
        "{(0, 0), (1, 2)}" in generated, generated
    assert "Dim Shared c2fb_partialPoint As c2fb_StaticPoint = (7, 0)" \
        in generated, generated
    assert "Dim Shared c2fb_arrays(0 To 1) As c2fb_StaticArray = " \
        "{({0, 0}), ({1, 2})}" in generated, generated
    assert "Dim Shared c2fb_pointerRecord As c2fb_StaticPointerRecord = " \
        "(7, @c2fb_initial, " \
        "CPtr(Const ZString Ptr, StrPtr(!\"record\")))" in generated, generated
    assert "Dim Shared c2fb_zeroPointerRecord As c2fb_StaticPointerRecord\n" \
        in generated, generated
    assert "Dim Shared c2fb_callbackRecord_storage As " \
        "c2fb_StaticCallbackRecord = " \
        '(CPtr(Const ZString Ptr, StrPtr(!"unavailable")), 0, 0)' \
        in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "If c2fb_counter <> 0 Then End 1\n"
        "If c2fb_initial <> 123 Then End 2\n"
        "If c2fb_opaque <> 0 Then End 3\n"
        "If c2fb_values(0) <> 1 OrElse c2fb_values(2) <> 3 Then End 4\n"
        "If c2fb_inferred(1) <> 5 Then End 5\n"
        "If c2fb_largeValues(0) <> 3 OrElse "
        "c2fb_largeValues(73) <> 149 OrElse "
        "c2fb_largeValues(127) <> 257 Then End 9\n"
        "If c2fb_points(1).x <> 1 OrElse c2fb_points(1).y <> 2 Then End 6\n"
        "If c2fb_partialPoint.x <> 7 OrElse c2fb_partialPoint.y <> 0 Then End 7\n"
        "If c2fb_arrays(1).coord(0) <> 1 OrElse "
        "c2fb_arrays(1).coord(1) <> 2 Then End 8\n"
        "If c2fb_pointerRecord.value <> 7 OrElse "
        "c2fb_pointerRecord.pointer <> @c2fb_initial OrElse "
        "c2fb_pointerRecord.text = 0 Then End 10\n"
        "If CPtr(Const Byte Ptr, c2fb_pointerRecord.text)[0] <> Asc(\"r\") Then End 12\n"
        "If c2fb_zeroPointerRecord.value <> 0 OrElse "
        "c2fb_zeroPointerRecord.pointer <> 0 OrElse "
        "c2fb_zeroPointerRecord.text <> 0 Then End 11\n"
        "If c2fb_callbackRecord.probe <> 0 OrElse "
        "c2fb_callbackRecord.notify <> 0 Then End 13\n"
        "If CPtr(Const Byte Ptr, c2fb_callbackRecord.name)[0] <> Asc(\"u\") "
        "Then End 14\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


    callback_header = source_directory / "callback.h"
    callback_header.write_text(
        "extern int callbackTarget(void);\n"
        "static int (*callback)(void) = &callbackTarget;\n"
        "static int (*callbackTable[2])(void) = {&callbackTarget, 0};\n"
    )
    callback_binding = source_directory / "callback.bi"
    run([converter, "generic-header", str(callback_header),
         str(callback_binding), "cc"])
    callback_generated = callback_binding.read_text()
    assert "Dim Shared c2fb_callback As Function CDecl() As Long = " \
        "ProcPtr(c2fb_callbackTarget)" in callback_generated, callback_generated
    assert "Dim Shared c2fb_callbackTable(0 To 1) As Function CDecl() As Long = " \
        "{ProcPtr(c2fb_callbackTarget), CPtr(Function CDecl() As Long, 0)}" \
        in callback_generated, callback_generated
    callback_wrapper = source_directory / "callback-check.bas"
    callback_wrapper.write_text(
        '#include once "callback.bi"\n'
        "Sub checkCallback()\n"
        "    Dim result As Long = c2fb_callback()\n"
        "End Sub\n"
    )
    run(fbc + ["-w", "all", "-c", str(callback_wrapper), "-o",
               str(source_directory / "callback-check.o")],
        cwd=source_directory)


def check_generic_header_static_record_character_array(converter, fbc, cc, work):
    # A string initializer must fill an inline C char-array field in the record layout.
    source_directory = work / "generic-header-static-record-character-array"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "struct C2fbStaticName { int num; const char name[8]; };\n"
        "static struct C2fbStaticName names[2] = {"
        "{1, \"HUP\"}, {2, \"INT\"}};\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
    ], cwd=source_directory)
    assert "1 module-static objects" in summary, summary
    generated = binding.read_text()
    assert "Dim Shared c2fb_names(0 To 1) As c2fb_C2fbStaticName = " \
        "{(1, {72, 85, 80, 0}), (2, {73, 78, 84, 0})}" in generated, generated

    c_source = source_directory / "reference.c"
    c_source.write_text(
        '#include "probe.h"\n'
        "#include <stdio.h>\n"
        "int main(void) {\n"
        '    printf("%d %u %d %u\\n", names[0].num, '
        "(unsigned char) names[0].name[0], names[1].num, "
        "(unsigned char) names[1].name[0]);\n"
        "    return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "reference"
    run(cc + [str(c_source), "-I", str(source_directory), "-o",
              str(c_executable)], cwd=source_directory)
    c_output = run([str(c_executable)], cwd=source_directory)

    fb_source = source_directory / "check.bas"
    fb_source.write_text(
        '#include once "probe.bi"\n'
        'Print c2fb_names(0).num; " "; '
        'CInt(c2fb_names(0).name(0)); " "; '
        'c2fb_names(1).num; " "; CInt(c2fb_names(1).name(0))\n'
    )
    fb_executable = source_directory / "check"
    run(fbc + ["-w", "all", str(fb_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_output = run([str(fb_executable)], cwd=source_directory)
    assert fb_output.split() == c_output.split(), (
        f"C record-array output={c_output!r}, FreeBASIC={fb_output!r}"
    )


def check_generic_header_supports_thread_local_objects(converter, fbc, work):
    source_directory = work / "generic-header-thread-local-objects"
    source_directory.mkdir()
    header = source_directory / "thread-local.h"
    header.write_text(
        "_Thread_local unsigned int standardTlsCounter;\n"
        "_Thread_local unsigned int standardTlsValues[2];\n"
        "static __thread unsigned int compilerTlsCounter;\n"
        "static unsigned int ordinaryCounter;\n"
        "unsigned int thread_local;\n"
    )
    binding = source_directory / "thread-local.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), "cc",
        "--include-static-objects", "--private-static-objects",
    ])
    generated = binding.read_text()
    assert 'Extern "C"' in generated, generated
    assert 'Thread Local Extern c2fb_standardTlsCounter Alias "standardTlsCounter" As ULong' \
        in generated, generated
    assert 'Thread Local Extern c2fb_standardTlsValues(0 To 1) Alias "standardTlsValues" As ULong' \
        in generated, generated
    assert "Private Thread Local Dim Shared c2fb_compilerTlsCounter As ULong" \
        in generated, generated
    assert "c2fb_ordinaryCounter" in generated, generated
    assert "c2fb_thread_local" in generated, generated
    assert "skipped 0 unsupported declarations" in summary, summary
    header_wrapper = source_directory / "thread-local-check.bas"
    header_wrapper.write_text('#include once "thread-local.bi"\n')
    run(fbc + ["-w", "all", "-c", str(header_wrapper), "-o",
               str(source_directory / "thread-local-check.o")], cwd=source_directory)
    c_definition = source_directory / "thread-local-definition.c"
    c_definition.write_text(
        "_Thread_local unsigned int standardTlsCounter = 7;\n"
        "_Thread_local unsigned int standardTlsValues[2] = {3, 4};\n"
    )
    c_object = source_directory / "thread-local-definition.o"
    c_build = subprocess.run(
        shlex.split("cc") + ["-c", str(c_definition), "-o", str(c_object)],
        cwd=source_directory, capture_output=True, text=True,
    )
    assert c_build.returncode == 0, c_build.stdout + c_build.stderr
    external_wrapper = source_directory / "thread-local-external-check.bas"
    external_wrapper.write_text(
        '#include once "thread-local.bi"\n'
        "If c2fb_standardTlsCounter <> 7 Then End 1\n"
        "c2fb_standardTlsCounter = 11\n"
        "If c2fb_standardTlsValues(0) <> 3 OrElse _\n"
        "   c2fb_standardTlsValues(1) <> 4 Then End 2\n"
        "c2fb_standardTlsValues(1) = 12\n"
        'Print "C2FB external thread-local passed"\n'
    )
    external_executable = source_directory / "thread-local-external-check"
    run(fbc + ["-gen", "gas64", "-mt", str(external_wrapper),
               str(c_object), "-x", str(external_executable)], cwd=source_directory)
    external_result = subprocess.run(
        [str(external_executable)], cwd=source_directory,
        capture_output=True, text=True, timeout=30, check=False,
    )
    assert external_result.returncode == 0 and external_result.stdout.strip() == \
        "C2FB external thread-local passed", external_result.stdout + external_result.stderr

    cpp_header = source_directory / "thread-local.hpp"
    cpp_header.write_text(
        "static thread_local unsigned int cppTlsCounter;\n"
        "thread_local unsigned int externalCppTlsCounter;\n"
        "static unsigned int ordinaryCppCounter;\n"
    )
    cpp_binding = source_directory / "thread-local-cpp.bi"
    cpp_summary = run([
        converter, "generic-header", str(cpp_header), str(cpp_binding), "cc",
        "-x", "c++", "--include-static-objects", "--private-static-objects",
    ])
    cpp_generated = cpp_binding.read_text()
    assert "Private Thread Local Dim Shared c2fb_cppTlsCounter As ULong" \
        in cpp_generated, cpp_generated
    assert "c2fb_ordinaryCppCounter" in cpp_generated, cpp_generated
    assert "external C++ thread-local object needs a C++ linker name" \
        in cpp_generated, cpp_generated
    assert "skipped 1 unsupported declaration" in cpp_summary, cpp_summary

    source = source_directory / "source-unit.c"
    source.write_text(
        "static _Thread_local unsigned int sourceUnitTlsCounter = 7;\n"
        "unsigned int c2fbReadSourceUnitTls(void) {\n"
        "    return sourceUnitTlsCounter;\n"
        "}\n"
    )
    candidate = source_directory / "source-unit-candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    result = subprocess.run(
        [
            sys.executable, str(source_unit_tool), str(source), str(candidate),
            "--converter", str(converter), "--compiler", "cc",
        ],
        cwd=source_directory, capture_output=True, text=True,
    )
    assert result.returncode == 0, result.stdout + result.stderr
    assert "unsupported thread-local C objects" not in result.stdout, result.stdout
    type_context = candidate.with_name("source-unit-candidates_types.bi")
    assert "Private Thread Local Dim Shared c2fb_sourceUnitTlsCounter As ULong = 7" \
        in type_context.read_text(), type_context.read_text()
    run(fbc + ["-mt", "-w", "all", "-c", str(candidate), "-o",
               str(source_directory / "source-unit-candidates.o")], cwd=source_directory)
    procedure = re.search(
        r"^Function\s+([A-Za-z_][A-Za-z_0-9]*)\b",
        candidate.read_text(), re.MULTILINE,
    )
    assert procedure is not None, candidate.read_text()
    wrapper = source_directory / "source-unit-thread-local-check.bas"
    wrapper.write_text(
        '#include once "source-unit-candidates.bas"\n'
        f"If {procedure.group(1)}() <> 7 Then End 1\n"
        'Print "C2FB thread-local source unit passed"\n'
    )
    executable = source_directory / "source-unit-thread-local-check"
    run(fbc + ["-gen", "gas64", "-mt", "-w", "all", str(wrapper),
               "-x", str(executable)], cwd=source_directory)
    executed = subprocess.run(
        [str(executable)], cwd=source_directory, capture_output=True,
        text=True, timeout=30, check=False,
    )
    assert executed.returncode == 0 and executed.stdout.strip() == \
        "C2FB thread-local source unit passed", executed.stdout + executed.stderr

    tree_source_directory = source_directory / "tree-source"
    tree_source_directory.mkdir()
    (tree_source_directory / "source-unit.c").write_text(source.read_text())
    tree_candidates = source_directory / "tree-candidates"
    tree_result = subprocess.run(
        [
            sys.executable, str(source_unit_tool), str(tree_source_directory),
            str(tree_candidates), "--tree", "--jobs=2",
            "--converter", str(converter), "--compiler", "cc",
        ],
        cwd=source_directory, capture_output=True, text=True,
    )
    assert tree_result.returncode == 0, tree_result.stdout + tree_result.stderr
    assert "unsupported thread-local C objects" not in tree_result.stdout, tree_result.stdout
    tree_candidate = tree_candidates / "source-unit_candidates.bas"
    assert tree_candidate.is_file()
    run(fbc + ["-mt", "-w", "all", "-c", str(tree_candidate), "-o",
               str(tree_candidates / "source-unit_candidates.o")], cwd=tree_candidates)


def check_generic_header_forward_static_record_initializers(converter, fbc, work):
    # Forward aliases may resolve through the backing UDT name, so static
    # aggregate initializers must find the validated record plan by that name.
    source_directory = work / "generic-header-forward-static-record-initializers"
    source_directory.mkdir()
    header = source_directory / "float_static.h"
    header.write_text(
        "typedef struct FloatPair { unsigned int byte_size; "
        "float first; float second; } FloatPair;\n"
        "static const FloatPair values[2] = "
        "{{sizeof(FloatPair), 1.25f, 0.5f}, "
        "{sizeof(FloatPair), 2.75f, 1.0f}};\n"
    )
    binding = source_directory / "float_static.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding),
        "--exclude=*", "--preserve-type-dependencies",
        "--include-static-objects", "--private-static-objects",
        "--forward-decl=*", "cc",
    ])
    generated = binding.read_text()
    assert "1 module-static objects" in summary, summary
    assert "c2fb_values(0 To 1) As Const c2fb_FloatPair_ = " \
        in generated, generated
    assert "unsupported module-static initializer" not in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "float_static.bi"\n'
        "If c2fb_values(0).byte_size <> SizeOf(c2fb_FloatPair_) Then End 1\n"
        "If c2fb_values(1).byte_size <> SizeOf(c2fb_FloatPair_) Then End 2\n"
        "If c2fb_values(0).first <> 1.25! OrElse "
        "c2fb_values(0).second <> 0.5! Then End 1\n"
        "If c2fb_values(1).first <> 2.75! OrElse "
        "c2fb_values(1).second <> 1.0! Then End 2\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)

    unsupported_directory = work / "generic-header-unsupported-static-record"
    unsupported_directory.mkdir()
    unsupported_header = unsupported_directory / "callback_static.h"
    unsupported_header.write_text(
        "typedef struct CallbackOwner { void (*callback)(void); "
        "int value; } CallbackOwner;\n"
        "static CallbackOwner unsupported = {(void (*)(void))1, 2};\n"
    )
    unsupported_binding = unsupported_directory / "callback_static.bi"
    unsupported_summary = run([
        converter, "generic-header", str(unsupported_header),
        str(unsupported_binding), "--exclude=*", "--preserve-type-dependencies",
        "--include-static-objects", "--private-static-objects",
        "--forward-decl=*", "cc",
    ])
    unsupported_generated = unsupported_binding.read_text()
    assert "skipped 1 unsupported declarations or macro expressions" \
        in unsupported_summary, unsupported_summary
    assert "c2fb skipped unsupported module-static initializer" \
        in unsupported_generated, unsupported_generated
    assert "c2fb_unsupported As" not in unsupported_generated, \
        unsupported_generated
    assert " = (" not in unsupported_generated, unsupported_generated


def check_generic_header_self_referential_static_record_initializer(
        converter, fbc, work):
    # C permits a static object to point to itself from its own initializer.
    source_directory = work / "generic-header-self-referential-static-record"
    source_directory.mkdir()
    header = source_directory / "self_static.h"
    header.write_text(
        "typedef struct SelfNode { struct SelfNode *next; "
        "struct SelfNode *previous; unsigned int value; } SelfNode;\n"
        "static SelfNode anchor = {&anchor, &anchor, 37};\n"
        "typedef struct ConstSelfNode { struct ConstSelfNode *next; "
        "unsigned int value; } ConstSelfNode;\n"
        "static const ConstSelfNode const_anchor = {&const_anchor, 53};\n"
    )
    binding = source_directory / "self_static.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding),
        "--exclude=*", "--preserve-type-dependencies",
        "--include-static-objects", "--private-static-objects",
        "--forward-decl=*", "cc",
    ])
    generated = binding.read_text()
    assert "2 module-static objects" in summary, summary
    assert "c2fb skipped unsupported module-static initializer" not in generated, \
        generated
    assert "Private Dim Shared c2fb_anchor As" in generated, generated
    assert "@c2fb_anchor" in generated, generated
    assert "@c2fb_const_anchor" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "self_static.bi"\n'
        "If c2fb_anchor.next <> @c2fb_anchor Then End 1\n"
        "If c2fb_anchor.previous <> @c2fb_anchor Then End 2\n"
        "If c2fb_anchor.value <> 37 Then End 3\n"
        "If c2fb_const_anchor.next <> @c2fb_const_anchor Then End 4\n"
        "If c2fb_const_anchor.value <> 53 Then End 5\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)

    accessor_directory = work / "generic-header-self-referential-const-accessor"
    accessor_directory.mkdir()
    accessor_header = accessor_directory / "const_accessor.h"
    accessor_header.write_text(
        "typedef struct c2fbConstRecord { struct c2fbConstRecord *next; "
        "unsigned int value; } c2fbConstRecord;\n"
        "static const c2fbConstRecord c2fbStaticConstRecord = "
        "{&c2fbStaticConstRecord, 17};\n"
    )
    accessor_binding = accessor_directory / "const_accessor.bi"
    run([
        converter, "generic-header", str(accessor_header),
        str(accessor_binding), "--include-static-objects",
        "--private-static-objects", "cc",
    ])
    accessor_generated = accessor_binding.read_text()
    assert "c2fb skipped unsupported module-static initializer" not in \
        accessor_generated, accessor_generated
    assert "c2fb_c2fbStaticConstRecord_storage As c2fb_c2fbConstRecord = " \
        in accessor_generated, accessor_generated
    assert "@c2fb_c2fbStaticConstRecord_storage" in accessor_generated, \
        accessor_generated

    accessor_wrapper = accessor_directory / "check.bas"
    accessor_wrapper.write_text(
        '#include once "const_accessor.bi"\n'
        "If c2fb_c2fbStaticConstRecord.next <> "
        "@c2fb_c2fbStaticConstRecord_storage Then End 1\n"
        "If c2fb_c2fbStaticConstRecord.value <> 17 Then End 2\n"
    )
    accessor_executable = accessor_directory / "check"
    run(fbc + ["-w", "all", str(accessor_wrapper), "-x",
               str(accessor_executable)], cwd=accessor_directory)
    run([str(accessor_executable)], cwd=accessor_directory)


def check_generic_header_record_pointer_arrays(converter, fbc, work):
    # Pointers to recursive records retain their pointee type inside arrays.
    source_directory = work / "generic-header-record-pointer-arrays"
    source_directory.mkdir()
    header = source_directory / "recursive_node.h"
    header.write_text(
        "typedef struct RecursiveNode { int value; "
        "struct RecursiveNode *children[2]; } RecursiveNode;\n"
    )
    binding = source_directory / "recursive_node.bi"
    run([
        converter, "generic-header", str(header), str(binding),
        "--exclude=*", "--preserve-type-dependencies",
        "--emit-source=*", "--forward-decl=*", "cc",
    ])
    generated = binding.read_text()
    assert "children(0 To 1) As c2fb_RecursiveNode Ptr" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "recursive_node.bi"\n'
        "Dim parent As c2fb_RecursiveNode\n"
        "Dim child As c2fb_RecursiveNode\n"
        "parent.children(0) = @child\n"
        "child.value = 17\n"
        "If parent.children(0)->value <> 17 Then End 1\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_sqlite_expr_generic_type_context(converter, fbc, cc, repository, work):
    source = repository / "src/expr.c"
    binding = work / "sqlite-expr-types.bi"
    run([
        converter, "generic-header", str(source), str(binding),
        "--exclude=*", "--preserve-type-dependencies",
        "--include-static-objects", "--private-static-objects",
        "--emit-source=*", "--forward-decl=*", *cc,
        f"-I{repository / 'src'}", f"-I{repository}",
        "-DSQLITE_THREADSAFE=1",
    ])
    generated = binding.read_text()
    assert "xCleanup As Sub CDecl(ByVal arg0 As c2fb_sqlite3_ Ptr, " \
        "ByVal arg1 As Any Ptr)" in generated, generated
    assert "Private Dim Shared c2fb_zeroItem_storage As " \
        "c2fb_ExprList_item\n" in generated, generated
    assert "c2fb_zeroItem_storage As c2fb_ExprList_item = {0}" \
        not in generated, generated

    wrapper = work / "sqlite-expr-types-check.bas"
    wrapper.write_text('#include once "sqlite-expr-types.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(work / "sqlite-expr-types-check.o")], cwd=work)


def check_generic_body_prefers_duplicate_layout_headers(converter, fbc, cc, work):
    source_directory = work / "generic-body-layout-header-selection"
    freebasic_directory = source_directory / "freebasic"
    freebasic_directory.mkdir(parents=True)
    type_definition = (
        "Type _c2fb_record_c2fb_sqlite3_vfs\n"
        "    value As Long\n"
        "End Type\n"
        "Type c2fb_sqlite3_vfs As _c2fb_record_c2fb_sqlite3_vfs\n"
    )
    (freebasic_directory / "00_layout_types.bi").write_text(
        type_definition +
        "#ifndef __C2FB_ABI_TYPE_C_INT__\n"
        "#define __C2FB_ABI_TYPE_C_INT__\n"
        "Type c2fb_c_int As Long\n"
        "#endif\n"
        "Declare Function c2fbLayoutReadValue CDecl Alias "
        "\"c2fbLayoutReadValue\" (ByVal value As c2fb_c_int) "
        "As c2fb_c_int\n"
    )
    (freebasic_directory / "99_layout_duplicate_types.bi").write_text(type_definition)
    (freebasic_directory / "layout_body.bi").write_text(
        type_definition +
        "Private Function unrelatedLayoutBody() As Long\n"
        "    Return missingLayoutBodyDependency()\n"
        "End Function\n"
    )
    (freebasic_directory / "abi_alias_body.bi").write_text(
        "#ifndef __C2FB_ABI_TYPE_C_INT__\n"
        "#define __C2FB_ABI_TYPE_C_INT__\n"
        "Type c2fb_c_int As Long\n"
        "#endif\n"
        "Private Function unrelatedAbiAliasBody() As Long\n"
        "    Return missingAbiAliasDependency()\n"
        "End Function\n"
    )
    source = source_directory / "layout.c"
    source.write_text(
        "typedef struct sqlite3_vfs { int value; } sqlite3_vfs;\n"
        "int c2fbLayoutReadValue(int value);\n"
        "int readVfs(sqlite3_vfs *vfs) {\n"
        "    return c2fbLayoutReadValue(vfs->value);\n"
        "}\n"
    )
    candidate = source_directory / "layout_candidates.bas"
    run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        cc[0], f"--fb-source-directory={freebasic_directory}",
    ])
    generated = candidate.read_text()
    assert "#include once \"00_layout_types.bi\"" in generated, generated
    assert "99_layout_duplicate_types.bi" not in generated, generated
    assert "layout_body.bi" not in generated, generated
    assert "abi_alias_body.bi" not in generated, generated
    assert "c2fbLayoutReadValue" in generated, generated
    assert "Function readVfs" in generated, generated

    object_path = source_directory / "layout_candidates.o"
    run(fbc + ["-w", "all", "-i", str(freebasic_directory), "-c",
               str(candidate), "-o", str(object_path)])


def check_sqlite_btree_known_record_sizes(converter, fbc, cc, repository, work):
    # Port-owned records need a validated extent, even when their fields differ.
    if sys.platform != "linux" or platform.machine().lower() not in ("x86_64", "amd64"):
        return

    source_root = work / "sqlite-btree-sizeof-root"
    source_directory = source_root / "src"
    source_directory.mkdir(parents=True)
    (source_root / "tool").symlink_to(repository / "tool")
    (source_directory / "sqlite.h.in").symlink_to(repository / "src/sqlite.h.in")
    source = source_directory / "btree_sizeof.c"
    source.write_text(
        "#include <stddef.h>\n"
        '#include "btreeInt.h"\n'
        "size_t c2fbBtCursorSize(void) { return sizeof(BtCursor); }\n"
        "size_t c2fbBtCursorPointerSize(BtCursor *cursor) { return sizeof(*cursor); }\n"
        "size_t c2fbBtCursorPbtOffset(void) { return offsetof(BtCursor, pBt); }\n"
        "size_t c2fbBtLockSize(void) { return sizeof(BtLock); }\n"
        "size_t c2fbBtLockNextOffset(void) { return offsetof(BtLock, pNext); }\n"
        "size_t c2fbBtreeSize(void) { return sizeof(Btree); }\n"
        "size_t c2fbBtreePbtOffset(void) { return offsetof(Btree, pBt); }\n"
        "size_t c2fbBtreeNextOffset(void) { return offsetof(Btree, pNext); }\n"
        "size_t c2fbBtreeLockOffset(void) { return offsetof(Btree, lock); }\n"
        "size_t c2fbBtSharedSize(void) { return sizeof(BtShared); }\n"
        "size_t c2fbBtSharedLockOffset(void) { return offsetof(BtShared, pLock); }\n"
        "size_t c2fbBtSharedTempOffset(void) { return offsetof(BtShared, pTmpSpace); }\n"
        "size_t c2fbClearBtCursor(BtCursor *cursor) {\n"
        "    memset(cursor, 0, sizeof(*cursor));\n"
        "    return sizeof(*cursor);\n"
        "}\n"
        "size_t c2fbMemPageSize(void) { return sizeof(MemPage); }\n"
    )

    freebasic_types = work / "sqlite-btree-sizeof-types"
    link_freebasic_standalone_interfaces(repository / "fb_src", freebasic_types)
    output_directory = work / "sqlite-btree-sizeof-output"
    summary = run([
        converter, "translate-preprocessed-files", str(source_directory),
        str(repository), str(output_directory), str(freebasic_types), cc[0],
        "1", "0", "", "0", source.name,
        f"-I{repository / 'src'}", f"-I{repository}",
    ])
    assert "preprocessed 1 engine C inputs; skipped 0 preprocessing failures" \
        in summary, summary
    candidate = output_directory / "btree_sizeof_preprocessed_candidates.bas"
    generated = candidate.read_text()
    assert "SizeOf(BtCursor)" in generated, generated
    assert "OffsetOf(BtCursor, pBt)" in generated, generated
    assert "SizeOf(BtLock)" in generated, generated
    assert "SizeOf(Btree)" in generated, generated
    assert "OffsetOf(Btree, pBt)" in generated, generated
    assert "OffsetOf(Btree, pNext)" in generated, generated
    assert "OffsetOf(Btree, lock)" in generated, generated
    assert "SizeOf(BtShared)" in generated, generated
    assert "OffsetOf(BtShared, pLock)" in generated, generated
    assert "OffsetOf(BtShared, pTmpSpace)" in generated, generated
    assert "SizeOf(MemPage)" in generated, generated

    compiler_includes = output_directory / ".c2fb_includes"
    reference_path = output_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", "-DSQLITE_THREADSAFE=1",
              "-I" + str(compiler_includes), "-I" + str(repository / "src"),
              "-I" + str(repository), str(source), "-o", str(reference_path)],
        cwd=source_directory)
    expected_mem_page_size = output_directory / "mem_page_size_expected.bas"
    expected_mem_page_size.write_text(
        '#include once "sqlite3_btree.bi"\n'
        'Public Function c2fbExpectedMemPageSize CDecl Alias "c2fbExpectedMemPageSize" () As ULongInt\n'
        '    Return SizeOf(MemPage)\n'
        'End Function\n'
    )
    converted_path = output_directory / "converted.so"
    run(fbc + ["-d", "SQLITE_THREADSAFE=1", "-w", "all", "-i",
               str(freebasic_types), "-dll", str(candidate),
               str(expected_mem_page_size), "-x",
               str(converted_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    size_names = (
        "c2fbBtCursorSize", "c2fbBtCursorPointerSize", "c2fbBtCursorPbtOffset",
        "c2fbBtLockSize", "c2fbBtLockNextOffset", "c2fbBtreeSize",
        "c2fbBtreePbtOffset", "c2fbBtreeNextOffset", "c2fbBtreeLockOffset",
        "c2fbBtSharedSize", "c2fbBtSharedLockOffset", "c2fbBtSharedTempOffset",
    )
    for function_name in size_names:
        c_function = getattr(reference, function_name)
        fb_function = getattr(converted, function_name)
        c_function.restype = fb_function.restype = ctypes.c_size_t
        if function_name == "c2fbBtCursorPointerSize":
            c_function.argtypes = fb_function.argtypes = [ctypes.c_void_p]
            assert c_function(None) == fb_function(None)
        else:
            assert c_function() == fb_function(), function_name

    reference.c2fbMemPageSize.restype = ctypes.c_size_t
    converted.c2fbMemPageSize.restype = ctypes.c_size_t
    converted.c2fbExpectedMemPageSize.restype = ctypes.c_size_t
    c_mem_page_size = reference.c2fbMemPageSize()
    fb_mem_page_size = converted.c2fbMemPageSize()
    assert fb_mem_page_size == converted.c2fbExpectedMemPageSize()
    assert fb_mem_page_size == c_mem_page_size + 8

    omit_shared_cache_source = source_directory / "btree_sizeof_omit_shared_cache.c"
    omit_shared_cache_source.write_text(
        '#include "btreeInt.h"\n'
        "size_t c2fbBtreeSizeWithoutSharedCache(void) { return sizeof(Btree); }\n"
        "size_t c2fbBtSharedSizeWithoutSharedCache(void) { return sizeof(BtShared); }\n"
    )
    omit_shared_cache_output = work / "sqlite-btree-sizeof-omit-shared-cache"
    omit_shared_cache_summary = run([
        converter, "translate-preprocessed-files", str(source_directory),
        str(repository), str(omit_shared_cache_output), str(freebasic_types),
        cc[0], "1", "0", "SQLITE_OMIT_SHARED_CACHE=1", "0",
        omit_shared_cache_source.name,
        f"-I{repository / 'src'}", f"-I{repository}",
    ])
    assert "preprocessed 1 engine C inputs; skipped 0 preprocessing failures" \
        in omit_shared_cache_summary, omit_shared_cache_summary
    omit_shared_cache_candidate = omit_shared_cache_output / (
        "btree_sizeof_omit_shared_cache_preprocessed_candidates.bas")
    omit_shared_cache_generated = omit_shared_cache_candidate.read_text()
    assert "c2fb skipped c2fbBtreeSizeWithoutSharedCache: outside the supported subset" \
        in omit_shared_cache_generated, omit_shared_cache_generated
    assert "c2fb skipped c2fbBtSharedSizeWithoutSharedCache: outside the supported subset" \
        in omit_shared_cache_generated, omit_shared_cache_generated

    cursor_size = reference.c2fbBtCursorSize()
    c_cursor = ctypes.create_string_buffer(b"\xA5" * cursor_size, cursor_size)
    fb_cursor = ctypes.create_string_buffer(b"\xA5" * cursor_size, cursor_size)
    reference.c2fbClearBtCursor.argtypes = [ctypes.c_void_p]
    converted.c2fbClearBtCursor.argtypes = [ctypes.c_void_p]
    reference.c2fbClearBtCursor.restype = ctypes.c_size_t
    converted.c2fbClearBtCursor.restype = ctypes.c_size_t
    assert reference.c2fbClearBtCursor(c_cursor) == cursor_size
    assert converted.c2fbClearBtCursor(fb_cursor) == cursor_size
    assert c_cursor.raw == fb_cursor.raw == bytes(cursor_size)


def check_generic_header_unsized_module_arrays(converter, fbc, cc, work):
    source_directory = work / "generic-header-unsized-module-arrays"
    source_directory.mkdir()
    header = source_directory / "unsized.h"
    header.write_text(
        "extern int externalValues[];\n"
        "static int staticValues[];\n"
        "static int initializedValues[] = {4, 7};\n"
        "static char staticString[];\n"
        "extern char narrowString[];\n"
        "extern const char constNarrowString[];\n"
    )
    binding = source_directory / "unsized.bi"
    run([converter, "generic-header", str(header), str(binding), *cc])
    generated = binding.read_text()
    for expected in (
        'Extern c2fb_externalValues_storage Alias "externalValues" As Long',
        "Dim Shared c2fb_staticValues_storage As Long",
        "Dim Shared c2fb_staticString_storage As Byte",
        "Dim Shared c2fb_initializedValues(0 To 1) As Long = {4, 7}",
        "#define c2fb_externalValues(c2fb_index)",
        "#define c2fb_staticValues(c2fb_index)",
        "#define c2fb_staticString(c2fb_index)",
        "#define c2fb_narrowString(c2fb_index)",
        "#define c2fb_constNarrowString(c2fb_index)",
    ):
        assert expected in generated, (expected, generated)
    assert "unsupported module-static unsized array" not in generated

    support = source_directory / "support.c"
    support.write_text(
        "int externalValues[3] = {13, 17, 19};\n"
        'char narrowString[] = "narrow";\n'
        'const char constNarrowString[] = "const";\n'
    )
    support_object = source_directory / "support.o"
    run(cc + ["-c", str(support), "-o", str(support_object)])
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "unsized.bi"\n'
        "If c2fb_externalValues(1) <> 17 Then End 1\n"
        "If c2fb_staticValues(0) <> 0 Then End 2\n"
        "c2fb_staticValues(2) = 23\n"
        "If c2fb_staticValues(2) <> 23 Then End 3\n"
        "If c2fb_initializedValues(1) <> 7 Then End 4\n"
        "If c2fb_staticString(0) <> 0 Then End 5\n"
        "If c2fb_narrowString(1) <> 97 Then End 6\n"
        "If c2fb_constNarrowString(2) <> 110 Then End 7\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(support_object), "-x",
               str(executable)])
    run([str(executable)])

    script = source_directory / "fix-unsized.fbfrog"
    script.write_text(
        "-target linux-x86_64\n"
        "-fixunsizedarrays\n"
        "unsized.h\n"
    )
    manifest = source_directory / "fix-unsized.json"
    manifest.write_text(json.dumps({
        "output_directory": "script-bindings",
        "combined_binding": "api.bi",
        "converter": converter,
        "fbfrog_version_script": {
            "path": "fix-unsized.fbfrog",
            "name_prefix": "fix-unsized",
            "targets": [{
                "name": "linux64",
                "fbfrog_target": "linux-x86_64",
                "compiler": "cc",
            }],
        },
    }))
    matrix_tool = Path(__file__).resolve().parents[1] / "c2fb_target_matrix.py"
    run([sys.executable, str(matrix_tool), str(manifest)], cwd=source_directory)
    script_binding = source_directory / "script-bindings/fix-unsized-linux64.bi"
    script_generated = script_binding.read_text()
    assert "Dim Shared c2fb_staticValues_storage As Long" in script_generated
    assert "Dim Shared c2fb_staticString_storage As Byte" in script_generated
    assert "#define c2fb_staticValues(c2fb_index)" in script_generated
    assert "#define c2fb_staticString (*Cptr(ZString Ptr, " \
        "@c2fb_staticString_storage))" in script_generated
    assert "#define c2fb_narrowString (*Cptr(ZString Ptr, " \
        "@c2fb_narrowString_storage))" in script_generated
    assert "#define c2fb_constNarrowString (*Cptr(Const ZString Ptr, " \
        "@c2fb_constNarrowString_storage))" in script_generated
    script_wrapper = source_directory / "check-script-unsized.bas"
    script_wrapper.write_text(
        '#include once "script-bindings/api.bi"\n'
        "If Len(c2fb_staticString) <> 0 Then End 3\n"
        'If c2fb_narrowString <> !"narrow" Then End 1\n'
        'If c2fb_constNarrowString <> !"const" Then End 2\n'
    )
    script_executable = source_directory / "check-script-unsized"
    run(fbc + ["-w", "all", str(script_wrapper), str(support_object), "-x",
               str(script_executable)], cwd=source_directory)
    run([str(script_executable)], cwd=source_directory)


def check_generic_header_static_string_pointer_initializers(converter, fbc, cc, work):
    source_directory = work / "generic-header-static-string-pointers"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "#define stringify1(s) #s\n"
        "#define stringify2(s) stringify1(s)\n"
        "#define mergetest(a, b) prefix a##b\n"
        'static char *message = "prefix " "xy";\n'
        'static const char *embedded = "a\\0b";\n'
        'static char *empty = "";\n'
        'static char *stringified = stringify1(mergetest(x, y));\n'
        'static char *expanded = stringify2(mergetest(x, y));\n'
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding),
        "--include-static-objects", "--private-static-objects",
        "--exclude-define=mergetest", "cc",
    ])
    generated = binding.read_text()
    assert "5 module-static objects" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert 'Private Dim Shared c2fb_message As ZString Ptr = CPtr(ZString Ptr, StrPtr(!"prefix xy"))' \
        in generated, generated
    assert 'Private Dim Shared c2fb_embedded As Const ZString Ptr = CPtr(Const ZString Ptr, StrPtr(!"a\\000b"))' \
        in generated, generated
    assert 'Private Dim Shared c2fb_empty As ZString Ptr = CPtr(ZString Ptr, StrPtr(!""))' \
        in generated, generated
    assert 'Private Dim Shared c2fb_stringified As ZString Ptr = CPtr(ZString Ptr, StrPtr(!"mergetest(x, y)"))' \
        in generated, generated
    assert 'Private Dim Shared c2fb_expanded As ZString Ptr = CPtr(ZString Ptr, StrPtr(!"prefix xy"))' \
        in generated, generated

    c_reference = source_directory / "reference.c"
    c_reference.write_text(
        '#include "probe.h"\n'
        "#include <stdio.h>\n"
        "int main(void) { int i;\n"
        '  for (i = 0; i < 16; ++i) printf("%u\\n", (unsigned char)stringified[i]);\n'
        '  for (i = 0; i < 10; ++i) printf("%u\\n", (unsigned char)expanded[i]);\n'
        '  for (i = 0; i < 10; ++i) printf("%u\\n", (unsigned char)message[i]);\n'
        '  for (i = 0; i < 4; ++i) printf("%u\\n", (unsigned char)embedded[i]);\n'
        '  printf("%u\\n", (unsigned char)empty[0]);\n'
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "reference"
    run(cc + ["-std=c99", str(c_reference), "-o", str(c_executable)],
        cwd=source_directory)
    c_values = run([str(c_executable)], cwd=source_directory).split()

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "For index As Long = 0 To 15: Print Peek(UByte, "
        "CPtr(Any Ptr, c2fb_stringified) + index): Next\n"
        "For index As Long = 0 To 9: Print Peek(UByte, "
        "CPtr(Any Ptr, c2fb_expanded) + index): Next\n"
        "For index As Long = 0 To 9: Print Peek(UByte, "
        "CPtr(Any Ptr, c2fb_message) + index): Next\n"
        "For index As Long = 0 To 3: Print Peek(UByte, "
        "CPtr(Any Ptr, c2fb_embedded) + index): Next\n"
        "Print Peek(UByte, c2fb_empty)\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    fb_values = run([str(executable)], cwd=source_directory).split()
    assert fb_values == c_values, \
        f"Static string pointer bytes differ: C={c_values}, FreeBASIC={fb_values}"


def check_generic_header_static_character_array_initializers(converter, fbc, cc, work):
    source_directory = work / "generic-header-static-character-arrays"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        'static char printable[8] = "A\\x42";\n'
        'static unsigned char high[3] = "\\200\\xFF";\n'
        'static char exact[3] = "abc";\n'
        'static char inferred[] = "xy";\n'
        'static char adjacent[4] = "a" "\\102";\n'
        'static char embedded[4] = "a\\0b";\n'
        'static char mapped[5] = "hey";\n'
        'static signed char signedHigh[2] = "\\xFF";\n'
        'static char escapes[9] = "\\a\\b\\t\\n\\v\\f\\r\\\\";\n'
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "9 module-static objects" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert "Dim Shared c2fb_printable(0 To 7) As Byte = {65, 66, 0}" \
        in generated, generated
    assert "Dim Shared c2fb_high(0 To 2) As UByte = {128, 255, 0}" \
        in generated, generated
    assert "Dim Shared c2fb_exact(0 To 2) As Byte = {97, 98, 99}" \
        in generated, generated
    assert "Dim Shared c2fb_inferred(0 To 2) As Byte = {120, 121, 0}" \
        in generated, generated
    assert "Dim Shared c2fb_embedded(0 To 3) As Byte = {97, 0, 98, 0}" \
        in generated, generated
    assert "Dim Shared c2fb_signedHigh(0 To 1) As Byte = {255, 0}" \
        in generated, generated
    assert "Dim Shared c2fb_escapes(0 To 8) As Byte = " \
        "{7, 8, 9, 10, 11, 12, 13, 92, 0}" in generated, generated

    cases = [
        ("printable", 8), ("high", 3), ("exact", 3), ("inferred", 3),
        ("adjacent", 4), ("embedded", 4), ("mapped", 5), ("signedHigh", 2),
        ("escapes", 9),
    ]
    c_reference = source_directory / "reference.c"
    c_body = '#include "probe.h"\n#include <stdio.h>\nint main(void) { int i;\n'
    for name, count in cases:
        c_body += (
            f"for (i = 0; i < {count}; ++i) "
            f'printf("%u\\n", (unsigned char){name}[i]);\n'
        )
    c_reference.write_text(c_body + "return 0;\n}\n")
    c_executable = source_directory / "reference"
    run(cc + ["-std=c99", "-O2", str(c_reference), "-o", str(c_executable)],
        cwd=source_directory)
    c_values = run([str(c_executable)], cwd=source_directory).split()

    wrapper = source_directory / "check.bas"
    fb_body = '#include once "probe.bi"\n'
    for name, count in cases:
        fb_body += (
            f"For index As Long = 0 To {count - 1}: "
            f"Print Cast(UByte, c2fb_{name}(index)): Next\n"
        )
    wrapper.write_text(fb_body)
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    fb_values = run([str(executable)], cwd=source_directory).split()
    assert fb_values == c_values, \
        f"Static character array bytes differ: C={c_values}, FreeBASIC={fb_values}"

    string_binding = source_directory / "string-binding.bi"
    run([converter, "generic-header", str(header), str(string_binding),
         "--string=mapped", "--string=embedded", "--string=high", "cc"])
    assert 'Dim Shared c2fb_mapped As ZString * 5 = !"hey"' \
        in string_binding.read_text()
    assert 'Dim Shared c2fb_embedded As ZString * 4 = !"a\\000b"' \
        in string_binding.read_text()
    assert 'Dim Shared c2fb_high As ZString * 3 = !"\\128\\255"' \
        in string_binding.read_text()
    string_wrapper = source_directory / "string-check.bas"
    string_wrapper.write_text(
        '#include once "string-binding.bi"\n'
        "If SizeOf(c2fb_mapped) <> 5 Then End 1\n"
        "If Asc(c2fb_mapped) <> 104 Then End 2\n"
        "If Asc(Mid(c2fb_mapped, 2, 1)) <> 101 Then End 3\n"
        "If Peek(UByte, StrPtr(c2fb_mapped) + 3) <> 0 Then End 4\n"
        "If Peek(UByte, StrPtr(c2fb_embedded) + 0) <> 97 Then End 5\n"
        "If Peek(UByte, StrPtr(c2fb_embedded) + 1) <> 0 Then End 6\n"
        "If Peek(UByte, StrPtr(c2fb_embedded) + 2) <> 98 Then End 7\n"
        "If Peek(UByte, StrPtr(c2fb_embedded) + 3) <> 0 Then End 8\n"
        "If Peek(UByte, StrPtr(c2fb_high) + 0) <> 128 Then End 9\n"
        "If Peek(UByte, StrPtr(c2fb_high) + 1) <> 255 Then End 10\n"
        "If Peek(UByte, StrPtr(c2fb_high) + 2) <> 0 Then End 11\n"
    )
    string_executable = source_directory / "string-check"
    run(fbc + ["-w", "all", str(string_wrapper), "-x", str(string_executable)],
        cwd=source_directory)
    run([str(string_executable)], cwd=source_directory)

    invalid_header = source_directory / "invalid.h"
    invalid_header.write_text(
        'static char tooShort[2] = "abc";\n'
        'static char tooWide[4] = "\\x100";\n'
        'static char unsupportedEscape[4] = "\\X41";\n'
    )
    invalid_binding = source_directory / "invalid.bi"
    run([converter, "generic-header", str(invalid_header), str(invalid_binding), "cc"])
    invalid_generated = invalid_binding.read_text()
    assert "unsupported module-static initializer" in invalid_generated
    assert "c2fb_tooShort" not in invalid_generated
    assert "c2fb_tooWide" not in invalid_generated
    assert "c2fb_unsupportedEscape" not in invalid_generated


def check_generic_header_static_character_matrix_initializers(
    converter, fbc, cc, work
):
    # String rows in a C character matrix include their row-local terminators.
    source_directory = work / "generic-header-static-character-matrix"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        'static char const charname[4][4] = { "nul", "soh", "stx", "etx" };\n'
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert "c2fb_charname" in generated, generated
    assert "{110, 117, 108, 0}" in generated, generated
    assert "{115, 111, 104, 0}" in generated, generated

    c_reference = source_directory / "reference.c"
    c_reference.write_text(
        '#include "probe.h"\n'
        "int c2fbMatrixByte(int row, int column) { "
        "return (unsigned char)charname[row][column]; }\n"
    )
    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(c_reference),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        wrapper = source_directory / f"check-{backend}.bas"
        wrapper.write_text(
            '#include once "probe.bi"\n'
            'Function c2fbMatrixByte CDecl Alias "c2fbMatrixByte" '
            '(ByVal row As Long, ByVal column As Long) As Long\n'
            '    Return Cast(UByte, c2fb_charname(row, column))\n'
            'End Function\n'
        )
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(wrapper),
                           "-x", str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        for library in (reference, converted):
            library.c2fbMatrixByte.argtypes = [ctypes.c_int, ctypes.c_int]
            library.c2fbMatrixByte.restype = ctypes.c_int
        for row in range(4):
            for column in range(4):
                assert reference.c2fbMatrixByte(row, column) == \
                    converted.c2fbMatrixByte(row, column)


def check_generic_header_record_string_override_layout(converter, fbc, cc, work):
    # A fixed FreeBASIC string already occupies the full C character-array extent.
    source_directory = work / "generic-header-record-string-override-layout"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "struct UDT1 {\n"
        "    signed char name[10];\n"
        "    signed char forComparison[10];\n"
        "    signed char myPath[10];\n"
        "};\n"
        "struct UDT2 {\n"
        "    signed char name[10];\n"
        "    signed char myFullPath[10];\n"
        "};\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding),
        "--string=UDT1.name", "--string=UDT*.my*Path", *cc,
    ])
    generated = binding.read_text()
    assert "emitted 2 record layouts" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert re.search(
        r"Type _c2fb_record_c2fb_UDT1\s+name As ZString \* 10\s+"
        r"forComparison\(0 To 9\) As Byte\s+myPath As ZString \* 10",
        generated,
    ), generated
    assert re.search(
        r"Type _c2fb_record_c2fb_UDT2\s+name\(0 To 9\) As Byte\s+"
        r"myFullPath As ZString \* 10",
        generated,
    ), generated

    c_source = source_directory / "layout.c"
    c_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '    printf("%zu\\n", sizeof(struct UDT1));\n'
        '    printf("%zu\\n", sizeof(struct UDT2));\n'
        "    return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + ["-std=c11", str(c_source), "-o", str(c_executable)],
        cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory)

    fb_source = source_directory / "layout.bas"
    fb_source.write_text(
        '#include once "probe.bi"\n'
        "Dim firstRecord As c2fb_UDT1\n"
        "Dim secondRecord As c2fb_UDT2\n"
        "Print SizeOf(firstRecord)\n"
        "Print SizeOf(secondRecord)\n"
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory)
    parse_layout = lambda text: [
        tuple(int(value) for value in line.split())
        for line in text.splitlines()
    ]
    assert parse_layout(fb_layout) == parse_layout(c_layout), (
        f"String-overridden record layout differs: C={c_layout!r}, "
        f"FreeBASIC={fb_layout!r}"
    )


def check_generic_header_anonymous_enum_record_field(converter, fbc, cc, work):
    # An inline anonymous enum has C int layout and file-scope enumerators.
    source_directory = work / "generic-header-anonymous-enum-record-field"
    source_directory.mkdir()
    header = source_directory / "record.h"
    header.write_text(
        "typedef _Bool bool;\n"
        "typedef struct C2fbAnonymousEnumRecord C2fbAnonymousEnumRecord;\n"
        "struct C2fbAnonymousEnumRecord {\n"
        "    unsigned char prefix;\n"
        "    enum { C2fbStatusOpen = 3, C2fbStatusHeld, "
        "C2fbStatusClosed = 12, } status;\n"
        "    bool (*print_func)(struct C2fbAnonymousEnumRecord *);\n"
        "    void (*char_func)(char);\n"
        "    unsigned short trailing;\n"
        "};\n"
    )
    binding = source_directory / "record.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
    ])
    generated = binding.read_text()
    assert "emitted 1 record layouts" in summary, summary
    assert "unsupported record declaration/layout: C2fbAnonymousEnumRecord" not in generated, generated
    assert re.search(r"status As (?:c2fb_c_int|Long)", generated), generated
    assert re.search(r"Const c2fb_C2fbStatusOpen As Long = 3", generated), generated
    assert re.search(r"Const c2fb_C2fbStatusHeld As Long = 4", generated), generated
    assert re.search(r"Const c2fb_C2fbStatusClosed As Long = 12", generated), generated

    support = source_directory / "support.c"
    support.write_text(
        "#include <stddef.h>\n"
        '#include "record.h"\n'
        "size_t c2fbAnonymousEnumRecordSize(void) { "
        "return sizeof(C2fbAnonymousEnumRecord); }\n"
        "size_t c2fbAnonymousEnumStatusOffset(void) { "
        "return offsetof(C2fbAnonymousEnumRecord, status); }\n"
        "size_t c2fbAnonymousEnumTrailingOffset(void) { "
        "return offsetof(C2fbAnonymousEnumRecord, trailing); }\n"
        "int c2fbAnonymousEnumReadStatus(C2fbAnonymousEnumRecord *record) { "
        "return record->status; }\n"
    )
    support_object = source_directory / "support.o"
    run(cc + ["-std=c11", "-Wall", "-Wextra", "-Werror", "-c",
              str(support), "-o", str(support_object)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "record.bi"\n'
        "Declare Function c2fbAnonymousEnumRecordSize CDecl Alias "
        '"c2fbAnonymousEnumRecordSize" () As c2fb_size_t\n'
        "Declare Function c2fbAnonymousEnumStatusOffset CDecl Alias "
        '"c2fbAnonymousEnumStatusOffset" () As c2fb_size_t\n'
        "Declare Function c2fbAnonymousEnumTrailingOffset CDecl Alias "
        '"c2fbAnonymousEnumTrailingOffset" () As c2fb_size_t\n'
        "Declare Function c2fbAnonymousEnumReadStatus CDecl Alias "
        '"c2fbAnonymousEnumReadStatus" (ByVal record As Any Ptr) As Long\n'
        "Dim record As c2fb_C2fbAnonymousEnumRecord_\n"
        "If SizeOf(record) <> c2fbAnonymousEnumRecordSize() Then End 1\n"
        "If CULngInt(@record.status) - CULngInt(@record) <> "
        "c2fbAnonymousEnumStatusOffset() Then End 2\n"
        "If CULngInt(@record.trailing) - CULngInt(@record) <> "
        "c2fbAnonymousEnumTrailingOffset() Then End 3\n"
        "record.status = c2fb_C2fbStatusHeld\n"
        "If c2fbAnonymousEnumReadStatus(@record) <> 4 Then End 4\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", "-i", str(source_directory), str(wrapper),
               str(support_object), "-x", str(executable)], cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_body_source_unit_anonymous_enum_record_field(
    converter, fbc, cc, work
):
    # Body member reads and writes use the same inline-enum record field layout.
    source_directory = work / "generic-body-source-unit-anonymous-enum-record-field"
    source_directory.mkdir()
    source = source_directory / "record_field.c"
    source.write_text(
        "typedef struct C2fbEnumRecord {\n"
        "    unsigned char prefix;\n"
        "    enum { C2fbStateOpen = 3, C2fbStateHeld } status;\n"
        "    int count;\n"
        "} C2fbEnumRecord;\n"
        "int c2fbAnonymousEnumRecordMutation(C2fbEnumRecord *record) {\n"
        "    record->status = C2fbStateHeld;\n"
        "    record->count += 1;\n"
        "    return record->status + record->count;\n"
        "}\n"
    )
    candidate = source_directory / "record_field_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "record_field_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x",
               str(converted_path)], cwd=source_directory)

    class EnumRecord(ctypes.Structure):
        _fields_ = [
            ("prefix", ctypes.c_ubyte),
            ("status", ctypes.c_int),
            ("count", ctypes.c_int),
        ]

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    reference_function = reference.c2fbAnonymousEnumRecordMutation
    converted_function = converted.c2fbAnonymousEnumRecordMutation
    for function in (reference_function, converted_function):
        function.argtypes = [ctypes.POINTER(EnumRecord)]
        function.restype = ctypes.c_int
    for prefix, status, count in ((7, 3, 4), (0, 4, -2), (255, -7, 18)):
        reference_record = EnumRecord(prefix, status, count)
        converted_record = EnumRecord(prefix, status, count)
        reference_result = reference_function(ctypes.byref(reference_record))
        converted_result = converted_function(ctypes.byref(converted_record))
        assert converted_result == reference_result
        assert bytes(converted_record) == bytes(reference_record)


def check_generic_header_alignof_and_offsetof_enum_values(
    converter, fbc, cc, work
):
    # Enum constants must use the active C ABI's type alignment and member offsets.
    source_directory = work / "generic-header-alignof-offsetof-enum-values"
    source_directory.mkdir()
    header = source_directory / "alignment.h"
    header.write_text(
        "#include <stddef.h>\n"
        "struct C2fbOffsetRecord { char prefix; long value; char tail[]; };\n"
        "enum {\n"
        "    C2fbAlignLong = __alignof__(long),\n"
        "    C2fbAlignDouble = __alignof__(double),\n"
        "    C2fbAlignLongLong = __alignof__(long long),\n"
        "    C2fbAlignLongDouble = __alignof__(long double),\n"
        "    C2fbAlignPointer = __alignof__(void *),\n"
        "    C2fbOffsetValue = offsetof(struct C2fbOffsetRecord, value),\n"
        "    C2fbOffsetTail = offsetof(struct C2fbOffsetRecord, tail)\n"
        "};\n"
        "enum { C2fbDefaultMxfast = 64 * sizeof(size_t) / 4 };\n"
        "enum { C2fbMinimumOffset = C2fbDefaultMxfast - "
        "offsetof(struct C2fbOffsetRecord, tail) };\n"
    )
    binding = source_directory / "alignment.bi"
    run([converter, "generic-header", str(header), str(binding), *cc],
        cwd=source_directory)
    generated = binding.read_text()
    for name in (
        "C2fbAlignLong", "C2fbAlignDouble", "C2fbAlignLongLong",
        "C2fbAlignLongDouble", "C2fbAlignPointer", "C2fbOffsetValue",
        "C2fbOffsetTail", "C2fbDefaultMxfast", "C2fbMinimumOffset",
    ):
        assert re.search(rf"Const c2fb_{name} As Long = \d+", generated), generated

    c_source = source_directory / "alignment.c"
    c_source.write_text(
        '#include "alignment.h"\n'
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        "int main(void) {\n"
        '    printf("%d %d %d %d %d %d %zu %d\\n", C2fbAlignLong, C2fbAlignDouble,\n'
        "           C2fbAlignLongLong, C2fbAlignLongDouble, C2fbAlignPointer,\n"
        "           C2fbOffsetValue, offsetof(struct C2fbOffsetRecord, tail),\n"
        "           C2fbMinimumOffset);\n"
        "    return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "alignment-c"
    run(cc + ["-std=gnu11", str(c_source), "-I", str(source_directory),
              "-o", str(c_executable)], cwd=source_directory)
    c_output = run([str(c_executable)], cwd=source_directory)

    fb_source = source_directory / "alignment.bas"
    fb_source.write_text(
        '#include once "alignment.bi"\n'
        'Print c2fb_C2fbAlignLong; " "; c2fb_C2fbAlignDouble; " "; '
        'c2fb_C2fbAlignLongLong; " "; c2fb_C2fbAlignLongDouble; " "; '
        'c2fb_C2fbAlignPointer; " "; c2fb_C2fbOffsetValue; " "; '
        'c2fb_C2fbOffsetTail; " "; c2fb_C2fbMinimumOffset\n'
    )
    fb_executable = source_directory / "alignment-fb"
    run(fbc + ["-w", "all", str(fb_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_output = run([str(fb_executable)], cwd=source_directory)
    assert [int(value) for value in fb_output.split()] == \
        [int(value) for value in c_output.split()], (
            f"C alignment constants={c_output!r}, FreeBASIC={fb_output!r}"
        )


def check_generic_header_mingw_i686_scalar_alignments(converter, work):
    # MinGW's 32-bit ABI aligns 64-bit integer and double scalars to eight bytes.
    compiler = shutil.which("i686-w64-mingw32-gcc")
    if compiler is None:
        return

    source_directory = work / "generic-header-mingw-i686-scalar-alignments"
    source_directory.mkdir()
    header = source_directory / "alignment.h"
    header.write_text(
        "enum {\n"
        "    C2fbAlignLongLong = __alignof__(long long),\n"
        "    C2fbAlignULongLong = __alignof__(unsigned long long),\n"
        "    C2fbAlignDouble = __alignof__(double),\n"
        "    C2fbAlignLongDouble = __alignof__(long double)\n"
        "};\n"
    )
    binding = source_directory / "alignment.bi"
    run([converter, "generic-header", str(header), str(binding), compiler],
        cwd=source_directory)
    generated = binding.read_text()

    c_source = source_directory / "alignment.c"
    c_source.write_text(
        "_Static_assert (__alignof__(long long) == 8, \"long long ABI\");\n"
        "_Static_assert (__alignof__(unsigned long long) == 8, \"unsigned long long ABI\");\n"
        "_Static_assert (__alignof__(double) == 8, \"double ABI\");\n"
        "_Static_assert (__alignof__(long double) == 4, \"long double ABI\");\n"
    )
    run([compiler, "-std=gnu11", "-fsyntax-only", str(c_source)],
        cwd=source_directory)

    expected = {
        "C2fbAlignLongLong": 8,
        "C2fbAlignULongLong": 8,
        "C2fbAlignDouble": 8,
        "C2fbAlignLongDouble": 4,
    }
    for name, value in expected.items():
        assert re.search(
            rf"Const c2fb_{name} As Long = {value}(?:\s|$)", generated
        ), f"MinGW i686 C ABI alignment for {name} was not emitted:\n{generated}"


def check_generic_header_type_map_alignment(converter, fbc, cc, work):
    # A mapped C type needs its ABI alignment when its FreeBASIC carrier is external.
    source_directory = work / "generic-header-type-map-alignment"
    source_directory.mkdir()
    header = source_directory / "alignment.h"
    header.write_text(
        "#include <stddef.h>\n"
        "typedef struct { __int128 first; __int128 second; } C2fbMappedAlignment;\n"
        "struct Scratch {\n"
        "    void *data;\n"
        "    size_t length;\n"
        "    union { C2fbMappedAlignment align; char bytes[1024]; } space;\n"
        "};\n"
        "struct Holder { char prefix; struct Scratch value; char suffix; };\n"
    )
    carrier = source_directory / "alignment-carrier.bi"
    carrier.write_text(
        "Type C2fbExternalAlignment\n"
        "    first As Integer<128>\n"
        "    second As Integer<128>\n"
        "End Type\n"
    )
    binding = source_directory / "alignment.bi"
    run(
        [
            converter, "generic-header", str(header), str(binding), *cc,
            "-std=gnu11", "--emit-source=*",
            "--fb-include=alignment-carrier.bi",
            "--type-map=C2fbMappedAlignment=C2fbExternalAlignment",
            "--type-alignment=C2fbMappedAlignment=16",
        ],
        cwd=source_directory,
    )
    generated = binding.read_text()

    c_source = source_directory / "alignment.c"
    c_source.write_text(
        '#include "alignment.h"\n'
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        "int main(void) {\n"
        '    printf("%zu %zu %zu %zu %zu %zu %zu\\n", sizeof(C2fbMappedAlignment), '
        "_Alignof(C2fbMappedAlignment), sizeof(struct Scratch), "
        "offsetof(struct Scratch, space), sizeof(struct Holder), "
        "offsetof(struct Holder, value), offsetof(struct Holder, suffix));\n"
        "    return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "alignment-c"
    run(
        cc + ["-std=gnu11", str(c_source), "-I", str(source_directory),
              "-o", str(c_executable)],
        cwd=source_directory,
    )
    c_output = run([str(c_executable)], cwd=source_directory)

    fb_source = source_directory / "alignment.bas"
    fb_source.write_text(
        '#include once "alignment.bi"\n'
        "Type AlignmentHolder\n"
        "    prefix As Byte\n"
        "    value As C2fbExternalAlignment\n"
        "End Type\n"
        "Dim scratch As c2fb_Scratch\n"
        "Dim alignmentHolder As AlignmentHolder\n"
        "Dim holder As c2fb_Holder\n"
        'Print SizeOf(C2fbExternalAlignment); " "; '
        'CULngInt(@alignmentHolder.value)-CULngInt(@alignmentHolder); " "; '
        'SizeOf(c2fb_Scratch); " "; '
        'CULngInt(@scratch.space)-CULngInt(@scratch); " "; '
        'SizeOf(c2fb_Holder); " "; '
        'CULngInt(@holder.value)-CULngInt(@holder); " "; '
        'CULngInt(@holder.suffix)-CULngInt(@holder)\n'
    )
    fb_executable = source_directory / "alignment-fb"
    run(
        fbc + ["-w", "all", "-i", str(source_directory),
               str(fb_source), "-x", str(fb_executable)],
        cwd=source_directory,
    )
    fb_output = run([str(fb_executable)], cwd=source_directory)
    assert [int(value) for value in fb_output.split()] == \
        [int(value) for value in c_output.split()], (
            f"C mapped-type layout={c_output!r}, FreeBASIC={fb_output!r}"
        )


def check_generic_header_fbfrog_string_defaults(converter, fbc, cc, work):
    source_directory = work / "generic-header-fbfrog-string-defaults"
    source_directory.mkdir()
    header = source_directory / "strings.h"
    header.write_text(
        "#include <stddef.h>\n"
        "typedef char CHAR;\n"
        "typedef const char CCHAR;\n"
        "typedef wchar_t WCHAR;\n"
        "typedef const wchar_t CWCHAR;\n"
        "typedef char Buffer[6];\n"
        "extern CHAR *charAliasPointer;\n"
        "extern CCHAR *constCharPointer;\n"
        "extern const CCHAR *doubleConstPointer;\n"
        "extern const CCHAR constScalar;\n"
        "extern char narrowArray[10];\n"
        "extern char narrowMatrix[3][8];\n"
        "extern Buffer aliasBuffer;\n"
        "extern signed char rawBytes[4];\n"
        "extern wchar_t wideArray[5];\n"
        "extern WCHAR *wideAliasPointer;\n"
        "struct FbfrogText {\n"
        "    char direct[10];\n"
        "    char rows[3][8];\n"
        "    signed char bytes[4];\n"
        "    CHAR aliasText[6];\n"
        "    Buffer aliasField;\n"
        "    wchar_t wide[5];\n"
        "};\n"
    )
    default_binding = source_directory / "default.bi"
    run([converter, "generic-header", str(header), str(default_binding), *cc])
    default_generated = default_binding.read_text()
    assert "Type c2fb_CHAR As Byte" in default_generated, default_generated
    assert "Extern c2fb_narrowArray(0 To 9)" in default_generated, default_generated
    assert "As Byte" in default_generated, default_generated

    binding = source_directory / "strings.bi"
    run([
        converter, "generic-header", str(header), str(binding),
        "--fbfrog-string-defaults", *cc,
    ])
    generated = binding.read_text()
    assert "Type c2fb_CHAR As ZString" in generated, generated
    assert "Type c2fb_CCHAR As Const ZString" in generated, generated
    assert "Const Const" not in generated, generated
    assert 'Extern c2fb_constCharPointer Alias "constCharPointer" ' \
        "As c2fb_CCHAR Ptr" in generated, generated
    assert 'Extern c2fb_charAliasPointer Alias "charAliasPointer" ' \
        "As c2fb_CHAR Ptr" in generated, generated
    assert 'Extern c2fb_narrowArray Alias "narrowArray" As ZString * 10' \
        in generated, generated
    assert 'Extern c2fb_narrowMatrix(0 To 2) Alias "narrowMatrix" ' \
        "As ZString * 8" in generated, generated
    assert 'Extern c2fb_aliasBuffer Alias "aliasBuffer" As ZString * 6' \
        in generated, generated
    assert 'Extern c2fb_rawBytes(0 To 3) Alias "rawBytes" As Byte' \
        in generated, generated
    assert "    direct As ZString * 10" in generated, generated
    assert "    rows(0 To 2) As ZString * 8" in generated, generated
    assert "    bytes(0 To 3) As Byte" in generated, generated
    assert "    aliasText As ZString * 6" in generated, generated
    assert "    aliasField As ZString * 6" in generated, generated

    fbc_width_source = source_directory / "fbc-width.bas"
    fbc_width_source.write_text("Print SizeOf(WString)\n")
    fbc_width_executable = source_directory / "fbc-width"
    run(fbc + [str(fbc_width_source), "-x", str(fbc_width_executable)],
        cwd=source_directory)
    fbc_wchar_size = int(run([str(fbc_width_executable)], cwd=source_directory))

    c_reference = source_directory / "layout.c"
    c_reference.write_text(
        '#include "strings.h"\n'
        "#include <stdio.h>\n"
        "int main(void) {\n"
        '    printf("%zu %zu %zu %zu %zu %zu\\n", '
        "sizeof(struct FbfrogText), offsetof(struct FbfrogText, direct), "
        "offsetof(struct FbfrogText, rows), offsetof(struct FbfrogText, bytes), "
        "offsetof(struct FbfrogText, aliasText), offsetof(struct FbfrogText, wide));\n"
        "    return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + ["-std=c11", str(c_reference), "-o", str(c_executable)],
        cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory).split()

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "strings.bi"\n'
        "Print SizeOf(c2fb_FbfrogText)\n"
        "Print OffsetOf(c2fb_FbfrogText, direct)\n"
        "Print OffsetOf(c2fb_FbfrogText, rows(0))\n"
        "Print OffsetOf(c2fb_FbfrogText, bytes(0))\n"
        "Print OffsetOf(c2fb_FbfrogText, aliasText)\n"
        "Print OffsetOf(c2fb_FbfrogText, wide)\n"
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory).split()
    assert fb_layout == c_layout, (
        f"FBFrog-default character mappings changed ABI: C={c_layout!r}, "
        f"FreeBASIC={fb_layout!r}, WString={fbc_wchar_size} bytes"
    )

    raw_binding = source_directory / "raw-characters.bi"
    run([
        converter, "generic-header", str(header), str(raw_binding),
        "--fbfrog-string-defaults", "--no-string=CHAR",
        "--no-string=narrowArray", *cc,
    ])
    raw_generated = raw_binding.read_text()
    assert "Type c2fb_CHAR As Byte" in raw_generated, raw_generated
    assert 'Extern c2fb_narrowArray(0 To 9) Alias "narrowArray" As Byte' \
        in raw_generated, raw_generated
    assert 'Extern c2fb_narrowMatrix(0 To 2) Alias "narrowMatrix" ' \
        "As ZString * 8" in raw_generated, raw_generated

    mismatch_binding = source_directory / "wchar-mismatch.bi"
    mismatch_width = 2 if fbc_wchar_size != 2 else 4
    run([
        converter, "generic-header", str(header), str(mismatch_binding),
        "--fbfrog-string-defaults", f"--fbfrog-wstring-size={mismatch_width}",
        *cc,
    ])
    mismatch_generated = mismatch_binding.read_text()
    assert "Type c2fb_WCHAR As wchar_t" in mismatch_generated, mismatch_generated
    assert 'Extern c2fb_wideArray(0 To 4) Alias "wideArray" As wchar_t' \
        in mismatch_generated, mismatch_generated


def check_generic_header_string_parameter_positions(converter, fbc, cc, work):
    # FBFrog string rules address unnamed parameters by zero-based position.
    source_directory = work / "generic-header-string-parameter-positions"
    source_directory.mkdir()
    header = source_directory / "parameters.h"
    header.write_text(
        "void f1(unsigned char *param1);\n"
        "void f2(unsigned char *param1);\n"
        "void f3(unsigned char *);\n"
        "void f4(unsigned char *);\n"
        "void f5(unsigned char *, unsigned char *, unsigned char *);\n"
        "typedef void (*PFDoodle)(unsigned char *, unsigned char *);\n"
        "void f6(int, void (*procPtrParam)(unsigned char *, unsigned char *), int);\n"
        "void f7(unsigned char *param);\n"
    )
    binding = source_directory / "parameters.bi"
    run([
        converter, "generic-header", str(header), str(binding),
        "--string=f1.param1", "--string=f3.0", "--string=f5.1",
        "--string=PFDoodle.1", "--string=procPtrParam.1", "--string=f7*",
        *cc,
    ])
    generated = binding.read_text()
    expected_declarations = (
        'Declare Sub c2fb_f1 CDecl Alias "f1" (ByVal arg0 As ZString Ptr)',
        'Declare Sub c2fb_f2 CDecl Alias "f2" (ByVal arg0 As UByte Ptr)',
        'Declare Sub c2fb_f3 CDecl Alias "f3" (ByVal arg0 As ZString Ptr)',
        'Declare Sub c2fb_f4 CDecl Alias "f4" (ByVal arg0 As UByte Ptr)',
        'Declare Sub c2fb_f5 CDecl Alias "f5" (ByVal arg0 As UByte Ptr, '
        'ByVal arg1 As ZString Ptr, ByVal arg2 As UByte Ptr)',
        'Type c2fb_PFDoodle As Sub CDecl(ByVal arg0 As UByte Ptr, '
        'ByVal arg1 As ZString Ptr)',
        'Declare Sub c2fb_f6 CDecl Alias "f6" (ByVal arg0 As Long, '
        'ByVal arg1 As Sub CDecl(ByVal arg0 As UByte Ptr, '
        'ByVal arg1 As ZString Ptr), ByVal arg2 As Long)',
        'Declare Sub c2fb_f7 CDecl Alias "f7" (ByVal arg0 As ZString Ptr)',
    )
    for declaration in expected_declarations:
        assert declaration in generated, (declaration, generated)

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "parameters.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check.o")], cwd=source_directory)


def check_generic_header_large_static_array_initializer(converter, fbc, cc, work):
    # File-scope C tables can exceed both the body-local list bound and the
    # old 32,768-token declaration limit. Compare every byte with C storage.
    source_directory = work / "generic-header-large-static-array-initializer"
    source_directory.mkdir()
    element_count = 20000
    values = [index % 256 for index in range(element_count)]
    source = source_directory / "large_table.h"
    source.write_text(
        f"static const unsigned char largeByteTable[{element_count}] = {{\n    "
        + ", ".join(str(value) for value in values)
        + "\n};\n"
    )
    binding = source_directory / "large_table.bi"
    summary = run([
        converter, "generic-header", str(source), str(binding),
        "--include-static-objects", "--private-static-objects", "cc",
    ])
    generated = binding.read_text()
    assert "1 module-static objects" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" \
        in summary, summary
    assert f"c2fb_largeByteTable(0 To {element_count - 1})" in generated, generated

    reference = source_directory / "reference.c"
    reference.write_text(
        '#include "large_table.h"\n'
        "#include <stdio.h>\n"
        "int main(void) {\n"
        "    int index;\n"
        f"    for (index = 0; index < {element_count}; ++index)\n"
        '        printf("%u\\n", (unsigned int)largeByteTable[index]);\n'
        "    return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "reference"
    run(cc + ["-std=c99", str(reference), "-o", str(c_executable)],
        cwd=source_directory)
    c_values = run([str(c_executable)], cwd=source_directory).split()

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "large_table.bi"\n'
        f"For index As Long = 0 To {element_count - 1}\n"
        "    Print c2fb_largeByteTable(index)\n"
        "Next\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    fb_values = run([str(executable)], cwd=source_directory).split()
    assert fb_values == c_values, \
        f"Static array bytes differ: C={c_values[:8]}, FreeBASIC={fb_values[:8]}"


def check_generic_header_assembler_names(converter, fbc, cc, work):
    # GNU asm labels change the linker name while leaving the C identifier intact.
    source_directory = work / "generic-header-assembler-names"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        'extern int linkedObject asm("linked_object");\n'
        'extern int linkedArray[3] __asm__("linked_array");\n'
        'extern int linkedEscaped __asm__("linked_" "\\x65" "scaped");\n'
        'extern int linkedCalls asm("linked_calls");\n'
        'extern int unsupportedLabel asm("bad\\nname");\n'
        '__attribute__((__stdcall__)) void callStd(void) asm("linked_stdcall");\n'
        '__attribute__((__cdecl__)) void callCDecl(void) __asm__("linked_cdecl");\n'
    )
    binding = source_directory / "probe.bi"
    run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert 'Extern c2fb_linkedObject Alias "linked_object" As Long' \
        in generated, generated
    assert 'Extern c2fb_linkedArray(0 To 2) Alias "linked_array" As Long' \
        in generated, generated
    assert 'Extern c2fb_linkedEscaped Alias "linked_escaped" As Long' \
        in generated, generated
    assert 'Extern c2fb_linkedCalls Alias "linked_calls" As Long' \
        in generated, generated
    assert 'Declare Sub c2fb_callStd StdCall Alias "linked_stdcall" ()' \
        in generated, generated
    assert 'Declare Sub c2fb_callCDecl CDecl Alias "linked_cdecl" ()' \
        in generated, generated
    assert "c2fb skipped unsupported assembler symbol name:" in generated, generated
    assert "c2fb_unsupportedLabel" not in generated, generated

    support = source_directory / "support.c"
    support.write_text(
        "int linked_object = 17;\n"
        "int linked_array[3] = {23, 29, 31};\n"
        "int linked_escaped = 41;\n"
        "int linked_calls = 0;\n"
        "void linked_stdcall(void) { linked_calls++; }\n"
        "void linked_cdecl(void) { linked_calls++; }\n"
    )
    support_object = source_directory / "support.o"
    run(cc + ["-c", str(support), "-o", str(support_object)],
        cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "If c2fb_linkedObject <> 17 Then End 1\n"
        "If c2fb_linkedArray(1) <> 29 Then End 2\n"
        "If c2fb_linkedEscaped <> 41 Then End 3\n"
        "c2fb_callStd()\n"
        "c2fb_callCDecl()\n"
        "If c2fb_linkedCalls <> 2 Then End 4\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(support_object), "-x",
               str(executable)], cwd=source_directory)
    run([str(executable)], cwd=source_directory)

def check_generic_header_type_rename_namespaces(converter, fbc, cc, work):
    # C tags and typedef names can share one spelling but need separate renames.
    source_directory = work / "generic-header-type-rename-namespaces"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "struct A { double d; };\n"
        "typedef int A;\n"
        "extern struct A tagObject;\n"
        "extern A typedefObject;\n"
        "typedef struct Shared { int value; } Shared;\n"
        "extern Shared sharedObject;\n"
    )
    support = source_directory / "support.c"
    support.write_text(
        "struct A { double d; };\n"
        "typedef int A;\n"
        "struct A tagObject = {7.5};\n"
        "A typedefObject = 42;\n"
        "typedef struct Shared { int value; } Shared;\n"
        "Shared sharedObject = {55};\n"
    )
    support_object = source_directory / "support.o"
    run(cc + ["-c", str(support), "-o", str(support_object)],
        cwd=source_directory)

    rename_cases = [
        (
            ["--rename-tag=A=Tag", "--rename-tag=Shared=TaggedShared"],
            [
                "Type Tag As _c2fb_record_Tag",
                "Type c2fb_A As Long",
                "Type TaggedShared As _c2fb_record_TaggedShared",
                "Type c2fb_Shared As TaggedShared",
                'Extern c2fb_tagObject Alias "tagObject" As Tag',
                'Extern c2fb_typedefObject Alias "typedefObject" As c2fb_A',
                'Extern c2fb_sharedObject Alias "sharedObject" As c2fb_Shared',
            ],
        ),
        (
            ["--rename-typedef=A=MyInt", "--rename-typedef=Shared=SharedAlias"],
            [
                "Type c2fb_A As _c2fb_record_c2fb_A",
                "Type MyInt As Long",
                "Type c2fb_Shared As _c2fb_record_c2fb_Shared",
                "Type SharedAlias As c2fb_Shared",
                'Extern c2fb_tagObject Alias "tagObject" As c2fb_A',
                'Extern c2fb_typedefObject Alias "typedefObject" As MyInt',
                'Extern c2fb_sharedObject Alias "sharedObject" As SharedAlias',
            ],
        ),
        (
            ["--rename=A=General", "--rename-tag=A=Tag",
             "--rename-typedef=A=MyInt"],
            [
                "Type Tag As _c2fb_record_Tag",
                "Type MyInt As Long",
                'Extern c2fb_tagObject Alias "tagObject" As Tag',
                'Extern c2fb_typedefObject Alias "typedefObject" As MyInt',
            ],
        ),
    ]
    for caseIndex, (rename_options, expected_lines) in enumerate(rename_cases):
        binding = source_directory / f"probe-{caseIndex}.bi"
        run([converter, "generic-header", str(header), str(binding),
             *rename_options, "cc"])
        generated = binding.read_text()
        for expected_line in expected_lines:
            assert expected_line in generated, generated

        wrapper = source_directory / f"check-{caseIndex}.bas"
        wrapper.write_text(
            f'#include once "{binding.name}"\n'
            "If c2fb_tagObject.d <> 7.5 Then End 1\n"
            "If c2fb_typedefObject <> 42 Then End 2\n"
            "If c2fb_sharedObject.value <> 55 Then End 3\n"
        )
        executable = source_directory / f"check-{caseIndex}"
        run(fbc + ["-w", "all", str(wrapper), str(support_object), "-x",
                   str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_procedure_macro_renames(converter, fbc, cc, work):
    # Procedure, macro, and macro-parameter renames update only their own names.
    source_directory = work / "generic-header-procedure-macro-renames"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "void runProc(void);\n"
        "extern int callCount;\n"
        "extern int x1;\n"
        "extern int X;\n"
        "#define VALUE 7\n"
        "#define CALL_PROC runProc()\n"
        "#define MACRO(x1) x1\n"
        "#define OBJECT_VALUE x1\n"
        "#define C2FB_KEYWORD(type) type\n"
        "#define C2FB_BODY_COLLISION(left) (X + left)\n"
        "#define C2FB_CASE_COLLISION(x, X) ((x) + (X))\n"
    )
    binding = source_directory / "probe.bi"
    run([
        converter, "generic-header", str(header), str(binding), "cc",
        "--rename-proc=runProc=renamedProc",
        "--rename-define=VALUE=renamedValue",
        "--rename-define=CALL_PROC=renamedCallMacro",
        "--rename-define=MACRO=renamedMacro",
        "--rename-macro-param=x1=x2",
        "--rename=X=X",
        "--rename-macro-param=type=type",
        "--rename-macro-param=left=X",
    ])
    generated = binding.read_text()
    assert 'Declare Sub renamedProc CDecl Alias "runProc" ()' \
        in generated, generated
    assert "Const renamedValue = 7" in generated, generated
    assert "#define renamedCallMacro renamedProc()" in generated, generated
    assert "#define renamedMacro(x2) x2" in generated, generated
    assert "#define c2fb_OBJECT_VALUE c2fb_x1" in generated, generated
    assert "#define c2fb_C2FB_KEYWORD(type_) type_" in generated, generated
    assert "#define c2fb_C2FB_BODY_COLLISION(X_) ((X + X_))" in generated, generated
    assert "#define c2fb_C2FB_CASE_COLLISION(c2fb_macro_arg_0, c2fb_macro_arg_1)" \
        in generated, generated
    assert "macro parameter rename matched: x1 -> x2" in generated, generated

    support = source_directory / "support.c"
    support.write_text(
        "int callCount = 0;\n"
        "int x1 = 11;\n"
        "int X = 5;\n"
        "void runProc(void) { callCount++; }\n"
    )
    support_object = source_directory / "support.o"
    run(cc + ["-c", str(support), "-o", str(support_object)],
        cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "If renamedValue <> 7 Then End 1\n"
        "If c2fb_OBJECT_VALUE <> 11 Then End 2\n"
        "If renamedMacro(13) <> 13 Then End 3\n"
        "renamedCallMacro\n"
        "If c2fb_callCount <> 1 Then End 4\n"
        "If c2fb_C2FB_KEYWORD(17) <> 17 Then End 5\n"
        "If c2fb_C2FB_BODY_COLLISION(3) <> 8 Then End 6\n"
        "If c2fb_C2FB_CASE_COLLISION(2, 9) <> 11 Then End 7\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), str(support_object),
                           "-x", str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_cross_phase_move_above(converter, fbc, cc, work):
    # A built-in scalar object can be emitted before a later scalar typedef.
    source_directory = work / "generic-header-cross-phase-move-above"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef int ScalarAlias;\n"
        "extern int earlyObject;\n"
        "extern int earlyFunction(int value);\n"
        "extern int *earlyPointer(int *values);\n"
        "struct OpaqueRecord;\n"
        "extern struct OpaqueRecord opaqueValue;\n"
        "extern struct OpaqueRecord *opaquePointer;\n"
        "extern struct OpaqueRecord *earlyOpaqueFunction(void);\n"
        "extern int opaqueValueMatches(const struct OpaqueRecord *value);\n"
        "typedef struct OpaqueAliasTag OpaqueAlias;\n"
        "extern OpaqueAlias opaqueAliasValue;\n"
        "extern int opaqueAliasMatches(const OpaqueAlias *value);\n"
        "struct UnrequestedRecord;\n"
        "extern struct UnrequestedRecord unrequestedValue;\n"
        "struct Record { int value; };\n"
        "extern struct Record laterRecord;\n"
    )
    binding = source_directory / "probe.bi"
    run([
        converter, "generic-header", str(header), str(binding), *cc,
        "--forward-decl=OpaqueRecord",
        "--forward-decl=OpaqueAlias",
        "-moveabove", "earlyObject", "ScalarAlias",
        "-moveabove", "earlyFunction", "ScalarAlias",
        "-moveabove", "earlyPointer", "ScalarAlias",
        "-moveabove", "opaquePointer", "ScalarAlias",
        "-moveabove", "earlyOpaqueFunction", "ScalarAlias",
        "--move-above=laterRecord=ScalarAlias",
    ])
    generated = binding.read_text()
    assert generated.index('Extern c2fb_earlyObject Alias "earlyObject"') < \
        generated.index("Type c2fb_ScalarAlias As Long"), generated
    assert "c2fb move-above applied: earlyObject -> ScalarAlias" in generated
    assert generated.index("Declare Function c2fb_earlyFunction") < \
        generated.index("Type c2fb_ScalarAlias As Long"), generated
    assert "c2fb move-above applied: earlyFunction -> ScalarAlias" in generated
    assert generated.index("Declare Function c2fb_earlyPointer") < \
        generated.index("Type c2fb_ScalarAlias As Long"), generated
    assert "c2fb move-above applied: earlyPointer -> ScalarAlias" in generated
    assert 'Extern c2fb_opaqueValue Alias "opaqueValue" As c2fb_OpaqueRecord' \
        in generated, generated
    assert 'Extern c2fb_opaqueAliasValue Alias "opaqueAliasValue" ' \
        'As c2fb_OpaqueAlias' in generated, generated
    assert "c2fb skipped unsupported external value type: no mapping for type " \
        "under target profile: extern struct UnrequestedRecord unrequestedValue" \
        in generated, generated
    assert generated.index("Type c2fb_OpaqueRecord As") < \
        generated.index('Extern c2fb_opaquePointer Alias "opaquePointer"'), generated
    assert generated.index('Extern c2fb_opaquePointer Alias "opaquePointer"') < \
        generated.index("Type c2fb_ScalarAlias As Long"), generated
    assert "c2fb move-above applied: opaquePointer -> ScalarAlias" in generated
    assert generated.index("Declare Function c2fb_earlyOpaqueFunction") < \
        generated.index("Type c2fb_ScalarAlias As Long"), generated
    assert "c2fb move-above applied: earlyOpaqueFunction -> ScalarAlias" in generated
    assert "c2fb move-above not applied (names belong to different output phases): " \
        "laterRecord -> ScalarAlias" in generated
    assert generated.index("Type c2fb_ScalarAlias As Long") < \
        generated.index('Extern c2fb_laterRecord Alias "laterRecord"'), generated

    support = source_directory / "support.c"
    support.write_text(
        '#include "probe.h"\n'
        "int earlyObject = 17;\n"
        "int earlyFunction(int value) { return value + 30; }\n"
        "int *earlyPointer(int *values) { return values; }\n"
        "struct OpaqueRecord { int marker; };\n"
        "struct OpaqueRecord opaqueValue = {37};\n"
        "static struct OpaqueRecord opaquePointerTarget = {41};\n"
        "struct OpaqueRecord *opaquePointer = &opaquePointerTarget;\n"
        "struct OpaqueRecord *earlyOpaqueFunction(void) { return opaquePointer; }\n"
        "int opaqueValueMatches(const struct OpaqueRecord *value) {\n"
        "    return value == &opaqueValue && value->marker == 37;\n"
        "}\n"
        "struct OpaqueAliasTag { int marker; };\n"
        "OpaqueAlias opaqueAliasValue = {61};\n"
        "int opaqueAliasMatches(const OpaqueAlias *value) {\n"
        "    return value == &opaqueAliasValue && value->marker == 61;\n"
        "}\n"
        "struct UnrequestedRecord { int value; };\n"
        "struct UnrequestedRecord unrequestedValue = {59};\n"
        "struct Record laterRecord = {23};\n"
    )
    support_object = source_directory / "support.o"
    run(cc + ["-c", str(support), "-o", str(support_object)],
        cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "If c2fb_earlyObject <> 17 Then End 1\n"
        "If c2fb_earlyFunction(1) <> 31 Then End 2\n"
        "Dim values(0 To 0) As Long\n"
        "values(0) = 37\n"
        "Dim result As Long Ptr = c2fb_earlyPointer(@values(0))\n"
        "If *result <> 37 Then End 3\n"
        "If c2fb_opaquePointer = 0 Then End 4\n"
        "If c2fb_earlyOpaqueFunction() <> c2fb_opaquePointer Then End 5\n"
        "If c2fb_laterRecord.value <> 23 Then End 6\n"
        "If c2fb_opaqueValueMatches(@c2fb_opaqueValue) <> 1 Then End 7\n"
        "If c2fb_opaqueAliasMatches(@c2fb_opaqueAliasValue) <> 1 Then End 8\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(support_object), "-x",
               str(executable)], cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_pointer_depth_limits(converter, fbc, work):
    # FreeBASIC supports eight pointer levels; deeper imports must be rejected.
    source_directory = work / "generic-header-pointer-depth-limits"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "extern int ******** depthEight;\n"
        "extern int ********* depthNine;\n"
        "typedef int *Pointer;\n"
        "extern Pointer ******** depthFromAlias;\n"
        "extern int ****(****callback)(void);\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 2 unsupported declarations" in summary, summary
    assert "Extern c2fb_depthEight Alias \"depthEight\" As " + \
        "Long Ptr Ptr Ptr Ptr Ptr Ptr Ptr Ptr" in generated, generated
    assert "Extern c2fb_depthNine Alias" not in generated, generated
    assert "Extern c2fb_depthFromAlias Alias" not in generated, generated
    assert "pointer depth exceeds FreeBASIC's configured limit" in generated, generated
    assert "Type _c2fb_callback_callback As Function CDecl() As " + \
        "Long Ptr Ptr Ptr Ptr" in generated, generated
    assert 'Extern c2fb_callback Alias "callback" As ' + \
        "_c2fb_callback_callback Ptr Ptr Ptr" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "probe.bi"\n')
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)

def check_generic_header_anonymous_same_kind_records(converter, fbc, cc, work):
    # Opposite-kind anonymous wrappers preserve same-kind C aggregate layout.
    source_directory = work / "generic-header-anonymous-same-kind-records"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "struct AnonStruct {\n"
        "    struct { int first; char innerTail; };\n"
        "    char trailing;\n"
        "};\n"
        "union AnonUnion {\n"
        "    union { int value; char byte; };\n"
        "    char overlay;\n"
        "};\n"
        "struct NestedAnon {\n"
        "    struct {\n"
        "        struct { int deep; };\n"
        "        char insideTail;\n"
        "    };\n"
        "    short trailing;\n"
        "};\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
        "-std=c11", "-pedantic-errors",
    ])
    assert "emitted 3 record layouts" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '  printf("%zu %zu %zu %zu\\n", sizeof(struct AnonStruct), '
        "offsetof(struct AnonStruct, first), "
        "offsetof(struct AnonStruct, innerTail), "
        "offsetof(struct AnonStruct, trailing));\n"
        '  printf("%zu %zu %zu %zu\\n", sizeof(union AnonUnion), '
        "offsetof(union AnonUnion, value), "
        "offsetof(union AnonUnion, byte), "
        "offsetof(union AnonUnion, overlay));\n"
        '  printf("%zu %zu %zu\\n", sizeof(struct NestedAnon), '
        "offsetof(struct NestedAnon, deep), "
        "offsetof(struct NestedAnon, trailing));\n"
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + [
        "-std=c11", "-pedantic-errors", str(c_layout_source), "-o",
        str(c_executable),
    ], cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory)

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        "Dim anonStruct As c2fb_AnonStruct\n"
        "Dim anonUnion As c2fb_AnonUnion\n"
        "Dim nestedAnon As c2fb_NestedAnon\n"
        'Print SizeOf(c2fb_AnonStruct); " "; '
        'CULngInt(@anonStruct.first)-CULngInt(@anonStruct); " "; '
        'CULngInt(@anonStruct.innerTail)-CULngInt(@anonStruct); " "; '
        'CULngInt(@anonStruct.trailing)-CULngInt(@anonStruct)\n'
        'Print SizeOf(c2fb_AnonUnion); " "; '
        'CULngInt(@anonUnion.value)-CULngInt(@anonUnion); " "; '
        'CULngInt(@anonUnion.byte)-CULngInt(@anonUnion); " "; '
        'CULngInt(@anonUnion.overlay)-CULngInt(@anonUnion)\n'
        'Print SizeOf(c2fb_NestedAnon); " "; '
        'CULngInt(@nestedAnon.deep)-CULngInt(@nestedAnon); " "; '
        'CULngInt(@nestedAnon.trailing)-CULngInt(@nestedAnon)\n'
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory)
    def parse_layout(text):
        return [
            tuple(int(value) for value in line.split())
            for line in text.splitlines()
        ]

    assert parse_layout(fb_layout) == parse_layout(c_layout), (
        f"Anonymous record layout differs: C={c_layout!r}, "
        f"FreeBASIC={fb_layout!r}"
    )


def check_generic_header_empty_anonymous_aggregates(converter, fbc, cc, work):
    # Empty nested GCC aggregates have no fields or storage; omit their wrappers
    # without changing the layout of surrounding anonymous struct and union members.
    source_directory = work / "generic-header-empty-anonymous-aggregates"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "union EmptyAnonymousNested {\n"
        "    int first;\n"
        "    int overlap;\n"
        "    struct {\n"
        "        int nested;\n"
        "        union {\n"
        "            int nestedValue;\n"
        "            int nestedAlternative;\n"
        "        };\n"
        "        int nestedTail;\n"
        "    };\n"
        "    int last;\n"
        "    struct { int namedNested; };\n"
        "    struct { union { struct { union { }; }; }; };\n"
        "};\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
    ], cwd=source_directory)
    assert "emitted 1 record layouts" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    generated = binding.read_text()
    assert "Type c2fb_EmptyAnonymousNested" in generated, generated
    assert "Union" in generated and "End Union" in generated, generated

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        "    printf(\"%zu %zu %zu %zu %zu %zu %zu %zu %zu\\n\", "
        "sizeof(union EmptyAnonymousNested),\n"
        "        offsetof(union EmptyAnonymousNested, first),\n"
        "        offsetof(union EmptyAnonymousNested, overlap),\n"
        "        offsetof(union EmptyAnonymousNested, nested),\n"
        "        offsetof(union EmptyAnonymousNested, nestedValue),\n"
        "        offsetof(union EmptyAnonymousNested, nestedAlternative),\n"
        "        offsetof(union EmptyAnonymousNested, nestedTail),\n"
        "        offsetof(union EmptyAnonymousNested, last),\n"
        "        offsetof(union EmptyAnonymousNested, namedNested));\n"
        "    return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + ["-std=gnu11", str(c_layout_source), "-o", str(c_executable)],
        cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory)

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        "Dim value As c2fb_EmptyAnonymousNested\n"
        'Print SizeOf(value); " "; '
        'CULngInt(@value.first)-CULngInt(@value); " "; '
        'CULngInt(@value.overlap)-CULngInt(@value); " "; '
        'CULngInt(@value.nested)-CULngInt(@value); " "; '
        'CULngInt(@value.nestedValue)-CULngInt(@value); " "; '
        'CULngInt(@value.nestedAlternative)-CULngInt(@value); " "; '
        'CULngInt(@value.nestedTail)-CULngInt(@value); " "; '
        'CULngInt(@value.last)-CULngInt(@value); " "; '
        'CULngInt(@value.namedNested)-CULngInt(@value)\n'
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory)
    assert tuple(int(value) for value in fb_layout.split()) == tuple(
        int(value) for value in c_layout.split()), (
            f"Empty anonymous aggregate layout differs: C={c_layout!r}, "
            f"FreeBASIC={fb_layout!r}"
        )


def check_generic_header_empty_named_records(converter, fbc, cc, work):
    # GCC empty tagged records have size zero. FreeBASIC's Any alias preserves
    # that size while keeping the C tag and typedef names available.
    source_directory = work / "generic-header-empty-named-records"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "struct EmptyTag { };\n"
        "typedef struct EmptyTag EmptyAlias;\n"
        "union EmptyUnion { };\n"
        "struct Parent { struct Nested { int value; }; };\n"
        "struct WrappedParent { union { struct WrappedNested { int value; }; }; };\n"
        "struct PackedParent { struct { int first; char last; } __attribute__((packed)); };\n"
        "extern struct EmptyTag emptyObject;\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
    ], cwd=source_directory)
    generated = binding.read_text()
    assert "zero-size record object has no FreeBASIC by-value storage" in generated, generated
    assert "Type c2fb_EmptyTag As Any" in generated, generated
    assert "Type c2fb_EmptyAlias As c2fb_EmptyTag" in generated, generated
    assert "Type c2fb_EmptyUnion As Any" in generated, generated
    assert "Type c2fb_Parent As Any" in generated, generated
    assert "Type c2fb_WrappedParent As Any" in generated, generated
    assert "Type c2fb_Nested" in generated and "value As Long" in generated, generated
    assert "Type c2fb_WrappedNested" in generated and "value As Long" in generated, generated
    assert "Type Field = 1" in generated, generated
    assert 'Extern c2fb_emptyObject Alias "emptyObject" As c2fb_EmptyTag' \
        not in generated, generated

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '    printf("%zu %zu %zu %zu %zu %zu %zu %zu %zu %zu\\n", sizeof(struct EmptyTag), '
        "sizeof(EmptyAlias), sizeof(union EmptyUnion), sizeof(struct Parent), "
        "sizeof(struct Nested), sizeof(struct WrappedParent), "
        "sizeof(struct WrappedNested), sizeof(struct PackedParent), "
        "offsetof(struct PackedParent, first), offsetof(struct PackedParent, last));\n"
        "    return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + ["-std=gnu11", str(c_layout_source), "-o", str(c_executable)],
        cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory).split()

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        "Dim emptyTag As c2fb_EmptyTag Ptr\n"
        "Dim emptyAlias As c2fb_EmptyAlias Ptr\n"
        "Dim emptyUnion As c2fb_EmptyUnion Ptr\n"
        "Dim parent As c2fb_Parent Ptr\n"
        "Dim nested As c2fb_Nested\n"
        "Dim wrappedParent As c2fb_WrappedParent Ptr\n"
        "Dim wrappedNested As c2fb_WrappedNested\n"
        "Dim packedParent As c2fb_PackedParent\n"
        'Print SizeOf(c2fb_EmptyTag); " "; SizeOf(c2fb_EmptyAlias); " "; '
        'SizeOf(c2fb_EmptyUnion); " "; SizeOf(c2fb_Parent); " "; '
        'SizeOf(c2fb_Nested); " "; SizeOf(c2fb_WrappedParent); " "; '
        'SizeOf(c2fb_WrappedNested); " "; SizeOf(c2fb_PackedParent); " "; '
        'CULngInt(@packedParent.first)-CULngInt(@packedParent); " "; '
        "CULngInt(@packedParent.last)-CULngInt(@packedParent)\n"
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory).split()
    assert fb_layout == c_layout, f"Empty/packed record layouts differ: C={c_layout}, FB={fb_layout}"


def check_generic_header_supports_longdouble_record_dependencies(
    converter, fbc, cc, work
):
    # Long-double by-value layouts must retain storage and alignment in parents.
    source_directory = work / "generic-header-longdouble-record-dependencies"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef struct C2fbUnsupportedLongDouble {\n"
        "    long double value;\n"
        "} C2fbUnsupportedLongDouble;\n"
        "typedef union C2fbDependentStorage {\n"
        "    C2fbUnsupportedLongDouble alignment;\n"
        "    unsigned char bytes[32];\n"
        "} C2fbDependentStorage;\n"
        "struct C2fbLongDoubleHolder {\n"
        "    char prefix;\n"
        "    C2fbUnsupportedLongDouble value;\n"
        "    char suffix;\n"
        "};\n"
        "typedef struct C2fbPointerToUnsupported {\n"
        "    C2fbUnsupportedLongDouble *value;\n"
        "} C2fbPointerToUnsupported;\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), "--exclude=*",
        *cc,
    ], cwd=source_directory)
    generated = binding.read_text()
    assert "unsupported record declaration/layout:" not in generated, generated
    assert "value As CLongDouble" in generated, generated
    assert "c2fbLongDoubleAlignment_" not in generated, generated
    assert "Type _c2fb_record_c2fb_C2fbUnsupportedLongDouble Field = 16" \
        in generated, generated
    assert "Union _c2fb_record_c2fb_C2fbDependentStorage" in generated, generated
    assert "alignment As c2fb_C2fbUnsupportedLongDouble" in generated, generated
    assert "bytes(0 To 31) As UByte" in generated, generated
    assert "Type c2fb_C2fbPointerToUnsupported" in generated, generated
    assert "value As c2fb_C2fbUnsupportedLongDouble Ptr" in generated, generated

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '  printf("%zu %zu\\n", sizeof(C2fbUnsupportedLongDouble), '
        "offsetof(C2fbUnsupportedLongDouble, value));\n"
        '  printf("%zu %zu %zu\\n", sizeof(C2fbDependentStorage), '
        "offsetof(C2fbDependentStorage, alignment), "
        "offsetof(C2fbDependentStorage, bytes));\n"
        '  printf("%zu %zu %zu\\n", sizeof(struct C2fbLongDoubleHolder), '
        "offsetof(struct C2fbLongDoubleHolder, value), "
        "offsetof(struct C2fbLongDoubleHolder, suffix));\n"
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + [str(c_layout_source), "-o", str(c_executable)],
        cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory).split()

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        "Dim unsupportedValue As c2fb_C2fbUnsupportedLongDouble\n"
        "Dim dependentStorage As c2fb_C2fbDependentStorage\n"
        "Dim longDoubleHolder As c2fb_C2fbLongDoubleHolder\n"
        'Print SizeOf(c2fb_C2fbUnsupportedLongDouble); " "; '
        'CULngInt(@unsupportedValue.value)-CULngInt(@unsupportedValue)\n'
        'Print SizeOf(c2fb_C2fbDependentStorage); " "; '
        'CULngInt(@dependentStorage.alignment)-CULngInt(@dependentStorage); " "; '
        'CULngInt(@dependentStorage.bytes(0))-CULngInt(@dependentStorage)\n'
        'Print SizeOf(c2fb_C2fbLongDoubleHolder); " "; '
        'CULngInt(@longDoubleHolder.value)-CULngInt(@longDoubleHolder); " "; '
        'CULngInt(@longDoubleHolder.suffix)-CULngInt(@longDoubleHolder)\n'
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory).split()
    assert fb_layout == c_layout, (
        f"Long-double record dependencies differ: C={c_layout}, "
        f"FreeBASIC={fb_layout}"
    )


def check_generic_header_longdouble_bindings(converter, fbc, cc, work):
    # Native C long-double objects and fixed C ABI declarations must use the
    # target-sized CRT type and remain callable from generated bindings.
    source_directory = work / "generic-header-longdouble-bindings"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "extern long double c2fb_longdouble_global;\n"
        "long double c2fb_longdouble_sum(long double lhs, long double rhs);\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
    ], cwd=source_directory)
    generated = binding.read_text()
    assert 'crt/longdouble.bi' in generated, generated
    assert 'As CLongDouble' in generated, generated
    assert 'Alias "c2fb_longdouble_global"' in generated, generated
    assert 'Alias "c2fb_longdouble_sum"' in generated, generated
    assert "unsupported declaration" not in generated, summary + generated

    c_source = source_directory / "probe.c"
    c_source.write_text(
        '#include "probe.h"\n'
        "long double c2fb_longdouble_global = 1.75L;\n"
        "long double c2fb_longdouble_sum(long double lhs, long double rhs) {\n"
        "    return lhs + rhs;\n"
        "}\n"
    )
    c_object = source_directory / "probe.o"
    run(cc + ["-Wall", "-Wextra", "-Werror", "-c", str(c_source),
              "-o", str(c_object)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        'Dim As CLongDouble leftValue = CLongDoubleFromStringValue( _\n'
        '    StrPtr(!"1.25"))\n'
        'Dim As CLongDouble rightValue = CLongDoubleFromStringValue( _\n'
        '    StrPtr(!"2.5"))\n'
        'If (c2fb_c2fb_longdouble_global = _\n'
        '    CLongDoubleFromStringValue(StrPtr(!"1.75"))) <> -1 Then End 1\n'
        'If (c2fb_c2fb_longdouble_sum(leftValue, rightValue) = _\n'
        '    CLongDoubleFromStringValue(StrPtr(!"3.75"))) <> -1 Then End 2\n'
    )
    for backend, flags in (
        ("default", []), ("gcc", ["-gen", "gcc"]),
        ("llvm", ["-gen", "llvm"]),
    ):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), str(c_object),
                           "-x", str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_int128_types(
    converter, fbc, cc, work, fbc_source_directory=None
):
    # Linux __u128 typedefs must retain 16-byte scalar layout and alignment.
    source_directory = work / "generic-header-int128-types"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef unsigned __int128 __u128 __attribute__((aligned(16)));\n"
        "typedef struct C2fbWideRecord {\n"
        "    unsigned char prefix;\n"
        "    __u128 unsignedValue;\n"
        "    __int128 signedValue;\n"
        "    unsigned char suffix;\n"
        "} C2fbWideRecord;\n"
        "extern C2fbWideRecord c2fbWideObject;\n"
        "extern __u128 c2fbWideFunction(__u128 value);\n"
        "extern __u128 *c2fbWidePointer;\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert "Type c2fb___u128 As UInteger<128>" in generated, generated
    assert "Type c2fb_C2fbWideRecord As _c2fb_record_c2fb_C2fbWideRecord" \
        in generated, generated
    assert "unsignedValue As c2fb___u128" in generated, generated
    assert "signedValue As Integer<128>" in generated, generated
    assert "Declare Function c2fb_c2fbWideFunction" in generated, generated
    assert "ByVal arg0 As c2fb___u128) As c2fb___u128" in generated, generated
    assert "Extern c2fb_c2fbWidePointer" in generated, generated

    c_layout = source_directory / "layout.c"
    c_layout.write_text(
        "#include <stddef.h>\n"
        '#include "probe.h"\n'
        "_Static_assert(sizeof(C2fbWideRecord) == 64, \"size\");\n"
        "_Static_assert(offsetof(C2fbWideRecord, unsignedValue) == 16, \"u128\");\n"
        "_Static_assert(offsetof(C2fbWideRecord, signedValue) == 32, \"i128\");\n"
        "_Static_assert(offsetof(C2fbWideRecord, suffix) == 48, \"tail\");\n"
    )
    run(cc + ["-std=gnu11", "-I", str(source_directory), "-c", str(c_layout),
              "-o", str(source_directory / "layout.o")])

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "If SizeOf(c2fb_C2fbWideRecord) <> 64 Then End 1\n"
        "Dim As c2fb_C2fbWideRecord layoutValue\n"
        "Dim As UByte Ptr baseAddress = @layoutValue\n"
        "If CULngInt(@layoutValue.unsignedValue) - CULngInt(baseAddress) <> 16 Then End 2\n"
        "If CULngInt(@layoutValue.signedValue) - CULngInt(baseAddress) <> 32 Then End 3\n"
        "If CULngInt(@layoutValue.suffix) - CULngInt(baseAddress) <> 48 Then End 4\n"
    )
    run(fbc + ["-w", "all", "-i", str(source_directory), "-c", str(wrapper),
               "-o", str(source_directory / "check.o")], cwd=source_directory)
    gas32_wrapper = source_directory / "check_gas32.bas"
    gas32_wrapper.write_text(
        '#include once "probe.bi"\n'
        "If SizeOf(c2fb_C2fbWideRecord) <> 64 Then End 1\n"
        "Dim As c2fb_C2fbWideRecord layoutValue\n"
    )
    gas32_assembly = source_directory / "check_gas32.asm"
    gas32_object = source_directory / "check_gas32.o"
    run(fbc + ["-target", "linux-x86", "-gen", "gas", "-w", "all", "-i",
               str(source_directory), "-r", str(gas32_wrapper), "-o",
               str(gas32_assembly)], cwd=source_directory)
    run([shutil.which("as") or "as", "--32", "-o", str(gas32_object),
         str(gas32_assembly)], cwd=source_directory)

    body_source = source_directory / "wide_body.c"
    body_source.write_text(
        "unsigned __int128 c2fbWideAdd(unsigned __int128 left, "
        "unsigned __int128 right) { return left + right; }\n"
        "__int128 c2fbWideIncrement(__int128 value) { return value + 1; }\n"
    )
    body_candidate = source_directory / "wide_body_candidates.bas"
    body_summary = run([
        converter, "translate-simple-generic-c", str(body_source),
        str(body_candidate), "cc",
    ])
    body_generated = body_candidate.read_text()
    assert "translated 2 simple functions; skipped 0" in body_summary, body_summary
    assert "UInteger<128>" in body_generated, body_generated
    assert "Integer<128>" in body_generated, body_generated
    run(fbc + ["-gen", "gcc", "-w", "all", "-c", str(body_candidate), "-o",
               str(source_directory / "wide_body.o")], cwd=source_directory)
    run(fbc + ["-gen", "gas64", "-w", "all", "-c", str(body_candidate), "-o",
               str(source_directory / "wide_body_gas64.o")], cwd=source_directory)
    gas32_body_assembly = source_directory / "wide_body_gas32.asm"
    gas32_body_object = source_directory / "wide_body_gas32.o"
    run(fbc + ["-target", "linux-x86", "-gen", "gas", "-w", "all", "-r",
               str(body_candidate), "-o", str(gas32_body_assembly)],
        cwd=source_directory)
    run([shutil.which("as") or "as", "--32", "-o", str(gas32_body_object),
         str(gas32_body_assembly)], cwd=source_directory)

    reference_source = source_directory / "wide_body_reference.c"
    reference_source.write_text(
        body_source.read_text().replace(
            "c2fbWideAdd", "c2fbReferenceWideAdd"
        ).replace(
            "c2fbWideIncrement", "c2fbReferenceWideIncrement"
        )
    )
    reference_object = source_directory / "wide_body_reference.o"
    run(cc + ["-std=gnu11", "-c", str(reference_source), "-o",
              str(reference_object)], cwd=source_directory)
    runtime_wrapper = source_directory / "wide_body_runtime.bas"
    runtime_wrapper.write_text(
        '#include once "wide_body_candidates.bas"\n'
        'Declare Function c2fbReferenceWideAdd CDecl Alias '
        '"c2fbReferenceWideAdd" (ByVal leftValue As UInteger<128>, '
        'ByVal rightValue As UInteger<128>) As UInteger<128>\n'
        'Declare Function c2fbReferenceWideIncrement CDecl Alias '
        '"c2fbReferenceWideIncrement" (ByVal value As Integer<128>) '
        'As Integer<128>\n'
        "Dim As UInteger<128> leftValue = 1\n"
        "leftValue = (leftValue Shl 100) + 17\n"
        "Dim As UInteger<128> rightValue = 1\n"
        "rightValue = (rightValue Shl 90) + 33\n"
        "If c2fbWideAdd(leftValue, rightValue) <> "
        "c2fbReferenceWideAdd(leftValue, rightValue) Then End 1\n"
        "Dim As UInteger<128> allBitsSet = -1\n"
        "If c2fbWideAdd(allBitsSet, 1) <> "
        "c2fbReferenceWideAdd(allBitsSet, 1) Then End 2\n"
        "Dim As Integer<128> negativeValue = 1\n"
        "negativeValue = -((negativeValue Shl 100) + 17)\n"
        "If c2fbWideIncrement(negativeValue) <> "
        "c2fbReferenceWideIncrement(negativeValue) Then End 3\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"wide-body-runtime-{backend}"
        run(fbc + flags + ["-w", "all", str(runtime_wrapper),
                           str(reference_object), "-x", str(executable)],
            cwd=source_directory)
        run([str(executable)], cwd=source_directory)

    arithmetic_source = source_directory / "wide_arithmetic_body.c"
    arithmetic_source.write_text(
        "typedef unsigned __int128 wide_uint;\n"
        "struct c2fb_wide_info { wide_uint lim; };\n"
        "wide_uint c2fbWideSeed(wide_uint value) {\n"
        "    return 0xf5397db1 >> (4 * ((value / 2) & 0x7));\n"
        "}\n"
        "void c2fbWideStore(struct c2fb_wide_info *info, unsigned divisor) {\n"
        "    wide_uint maximum = -1;\n"
        "    info->lim = maximum / divisor;\n"
        "}\n"
    )
    arithmetic_candidate = source_directory / "wide_arithmetic_candidates.bas"
    arithmetic_summary = run([
        converter, "translate-simple-generic-c", str(arithmetic_source),
        str(arithmetic_candidate), "cc", "--include-global-definitions",
    ])
    arithmetic_generated = arithmetic_candidate.read_text()
    assert "translated 2 simple functions; skipped 0" in arithmetic_summary, arithmetic_summary
    assert "UInteger<128>" in arithmetic_generated, arithmetic_generated
    record_match = re.search(
        r"^Private Type (c2fb_source_record_\d+)\b",
        arithmetic_generated, re.MULTILINE)
    assert record_match is not None, arithmetic_generated
    record_type = record_match.group(1)

    arithmetic_reference = source_directory / "wide_arithmetic_reference.c"
    arithmetic_reference.write_text(
        arithmetic_source.read_text()
        .replace("c2fbWideSeed", "c2fbReferenceWideSeed")
        .replace("c2fbWideStore", "c2fbReferenceWideStore")
    )
    arithmetic_reference_object = source_directory / "wide_arithmetic_reference.o"
    run(cc + ["-std=gnu11", "-c", str(arithmetic_reference), "-o",
              str(arithmetic_reference_object)], cwd=source_directory)
    arithmetic_runtime = source_directory / "wide_arithmetic_runtime.bas"
    arithmetic_runtime.write_text(
        '#include once "wide_arithmetic_candidates.bas"\n'
        'Declare Function c2fbReferenceWideSeed CDecl Alias '
        '"c2fbReferenceWideSeed" (ByVal value As UInteger<128>) '
        'As UInteger<128>\n'
        'Declare Sub c2fbReferenceWideStore CDecl Alias '
        '"c2fbReferenceWideStore" (ByVal info As ' + record_type +
        ' Ptr, ByVal divisor As c2fb_c_uint)\n'
        "Dim As UInteger<128> seedValue = 1\n"
        "seedValue = (seedValue Shl 100) + 1234567\n"
        "If c2fbWideSeed(seedValue) <> "
        "c2fbReferenceWideSeed(seedValue) Then End 1\n"
        "Dim divisor As c2fb_c_uint\n"
        "For divisor = 1 To 99\n"
        "    Dim actualInfo As " + record_type + "\n"
        "    Dim referenceInfo As " + record_type + "\n"
        "    c2fbWideStore(@actualInfo, divisor)\n"
        "    c2fbReferenceWideStore(@referenceInfo, divisor)\n"
        "    If actualInfo.lim <> referenceInfo.lim Then End 2\n"
        "Next\n"
        "End 0\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"wide-arithmetic-runtime-{backend}"
        run(fbc + flags + ["-w", "all", str(arithmetic_runtime),
                           str(arithmetic_reference_object), "-x", str(executable)],
            cwd=source_directory)
        run([str(executable)], cwd=source_directory)

    if fbc_source_directory is not None and sys.platform == "linux" and \
       platform.machine().lower() in ("x86_64", "amd64"):
        rtlib_math_directory = freebasic_source_root(
            fbc_source_directory
        ) / "rtlib" / "math"
        gas32_main = source_directory / "wide_body_gas32_main.c"
        gas32_main.write_text(
            "#include <stdint.h>\n"
            "#include <stdlib.h>\n"
            "typedef struct __attribute__((aligned(16))) C2fbWideValue {\n"
            "    uint64_t low;\n"
            "    uint64_t high;\n"
            "} C2fbWideValue;\n"
            "extern C2fbWideValue c2fbWideAdd(C2fbWideValue left, "
            "C2fbWideValue right);\n"
            "extern C2fbWideValue c2fbWideIncrement(C2fbWideValue value);\n"
            "void fb_End(int exit_code) { exit(exit_code); }\n"
            "int main(void) {\n"
            "    C2fbWideValue left = { UINT64_MAX - 15, UINT64_C(0x123456789abcdef0) };\n"
            "    C2fbWideValue right = { 48, UINT64_C(0x0fedcba987654321) };\n"
            "    C2fbWideValue result = c2fbWideAdd(left, right);\n"
            "    uint64_t expected_high = left.high + right.high + 1;\n"
            "    if (result.low != 32 || result.high != expected_high) return 1;\n"
            "    C2fbWideValue negative = { UINT64_MAX - 16, UINT64_MAX };\n"
            "    result = c2fbWideIncrement(negative);\n"
            "    if (result.low != UINT64_MAX - 15 || result.high != UINT64_MAX) return 2;\n"
            "    return 0;\n"
            "}\n"
        )
        gas32_runtime = source_directory / "wide-body-gas32-runtime"
        run(cc + ["-m32", "-no-pie", "-std=c99", "-Wall", "-Wextra", "-Werror",
                  str(gas32_body_object), str(gas32_main),
                  str(rtlib_math_directory / "int128.c"),
                  str(rtlib_math_directory / "longdouble_ops.c"),
                  "-lm", "-o", str(gas32_runtime)], cwd=source_directory)
        run([str(gas32_runtime)], cwd=source_directory)

        gcc_i386_body = source_directory / "wide_body_gcc_i386.c"
        run(fbc + ["-target", "linux", "-arch", "686", "-gen", "gcc",
                   "-w", "all", "-r", str(body_candidate), "-o",
                   str(gcc_i386_body)], cwd=source_directory)
        i386_c_compilers = [(Path(cc[0]).name, cc[0])]
        clang = shutil.which("clang")
        if clang is not None and Path(clang) != Path(cc[0]):
            i386_c_compilers.append(("clang", clang))
        for compiler_name, compiler in i386_c_compilers:
            c_backend_runtime = source_directory / f"wide-body-gcc-i386-{compiler_name}"
            run([compiler, "-m32", "-no-pie", "-std=c99", "-Wall", "-Wextra",
                 "-Werror=implicit-function-declaration", str(gcc_i386_body),
                 str(gas32_main),
                 str(rtlib_math_directory / "int128.c"),
                 str(rtlib_math_directory / "longdouble_ops.c"),
                 "-lm", "-o", str(c_backend_runtime)], cwd=source_directory)
            run([str(c_backend_runtime)], cwd=source_directory)


def check_generic_header_mixed_typedef_specifiers(converter, fbc, work):
    # Invalid C mixtures of a typedef name and scalar type words must be
    # reported, not emitted as malformed FreeBASIC declarations.
    source_directory = work / "generic-header-mixed-typedef-specifiers"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef int myint;\n"
        "static long myint longValue;\n"
        "static short myint shortValue;\n"
        "static signed myint signedValue;\n"
        "static unsigned myint unsignedValue;\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), "cc",
        "--include-static-objects", "--private-static-objects",
    ])
    generated = binding.read_text()
    assert "Type c2fb_myint As Long" in generated, generated
    for invalid_name in ("longValue", "shortValue", "signedValue", "unsignedValue"):
        assert f"Dim Shared c2fb_{invalid_name}" not in generated, generated
    assert "skipped 4 unsupported declarations or macro expressions" in summary, summary

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "probe.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check.o")], cwd=source_directory)


def check_generic_header_record_typedef_groups(converter, fbc, cc, work):
    # Split record typedef declarator groups without losing pointer or callback types.
    source_directory = work / "generic-header-record-typedef-groups"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef struct { int value; char tail; } "
        "Base, Copy, *BasePtr, **BasePtrPtr, (*BaseFactory)(void);\n"
        "typedef struct { int laterBase; } *FirstPtr, LaterBase;\n"
        "typedef struct Tagged { int tag; char tail; } "
        "TaggedAlias, TaggedCopy, *TaggedPtr, (*TaggedFactory)(void);\n"
        "typedef struct { int pointerTarget; } *AnonymousPtr;\n"
        "typedef struct { int callbackResult; } (*AnonymousFactory)(void);\n"
        "typedef struct NestedOuter {\n"
        "    struct NestedInner { short code; int value; } item;\n"
        "    unsigned char tag;\n"
        "} NestedOuter;\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
        "-std=c11", "-pedantic-errors",
    ])
    assert "emitted 7 record layouts" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    generated = binding.read_text()
    assert "Type c2fb_Copy As c2fb_Base" in generated, generated
    assert "Type c2fb_BasePtr As c2fb_Base Ptr" in generated, generated
    assert "Type c2fb_BasePtrPtr As c2fb_Base Ptr Ptr" in generated, generated
    assert "Type c2fb_FirstPtr As c2fb_LaterBase Ptr" in generated, generated
    assert "Type c2fb_TaggedCopy As c2fb_Tagged" in generated, generated
    assert "Type c2fb_TaggedPtr As c2fb_Tagged Ptr" in generated, generated
    assert "Type c2fb_NestedInner As _c2fb_record_c2fb_NestedInner" \
        in generated, generated
    assert "Type c2fb_NestedOuter As _c2fb_record_c2fb_NestedOuter" \
        in generated, generated
    assert "Type c2fb_BaseFactory As Function CDecl() As c2fb_Base" in generated
    assert "Type c2fb_TaggedFactory As Function CDecl() As c2fb_Tagged" in generated
    assert re.search(
        r"Type c2fb_AnonymousPtr As c2fb___c2fb_anonymous_record_\d+ Ptr$",
        generated, re.M,
    ), generated
    assert re.search(
        r"Type c2fb_AnonymousFactory As Function CDecl\(\) As "
        r"c2fb___c2fb_anonymous_record_\d+$",
        generated, re.M,
    ), generated
    assert generated.index("Type _c2fb_record_c2fb_Base") < generated.index(
        "Type c2fb_BaseFactory As Function")
    assert generated.index("Type _c2fb_record_c2fb_Tagged") < generated.index(
        "Type c2fb_TaggedFactory As Function")

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '  printf("%zu %zu %zu %zu %zu %zu\\n", sizeof(Base), '
        "offsetof(Base, value), offsetof(Base, tail), sizeof(Copy), "
        "offsetof(Copy, value), offsetof(Copy, tail));\n"
        '  printf("%zu %zu %zu %zu\\n", sizeof(LaterBase), '
        "offsetof(LaterBase, laterBase), sizeof(TaggedAlias), "
        "offsetof(TaggedAlias, tag));\n"
        '  printf("%zu %zu\\n", sizeof(TaggedCopy), '
        "offsetof(TaggedCopy, tail));\n"
        '  printf("%zu %zu %zu %zu %zu\\n", sizeof(NestedOuter), '
        "offsetof(NestedOuter, item), offsetof(NestedOuter, item.code), "
        "offsetof(NestedOuter, item.value), offsetof(NestedOuter, tag));\n"
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + [
        "-std=c11", "-pedantic-errors", str(c_layout_source), "-o",
        str(c_executable),
    ], cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory)

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        "Dim baseValue As c2fb_Base\n"
        "Dim copyValue As c2fb_Copy\n"
        "Dim laterBase As c2fb_LaterBase\n"
        "Dim taggedAlias As c2fb_TaggedAlias\n"
        "Dim taggedCopy As c2fb_TaggedCopy\n"
        "Dim basePtr As c2fb_BasePtr = @baseValue\n"
        "Dim basePtrPtr As c2fb_BasePtrPtr = @basePtr\n"
        "Dim firstPtr As c2fb_FirstPtr = @laterBase\n"
        "Dim taggedPtr As c2fb_TaggedPtr = @taggedAlias\n"
        "Dim baseFactory As c2fb_BaseFactory\n"
        "Dim taggedFactory As c2fb_TaggedFactory\n"
        "Dim anonymousPointer As c2fb_AnonymousPtr\n"
        "Dim anonymousFactory As c2fb_AnonymousFactory\n"
        "Dim nestedOuter As c2fb_NestedOuter\n"
        'Print SizeOf(c2fb_Base); " "; '
        'CULngInt(@baseValue.value)-CULngInt(@baseValue); " "; '
        'CULngInt(@baseValue.tail)-CULngInt(@baseValue); " "; '
        'SizeOf(c2fb_Copy); " "; '
        'CULngInt(@copyValue.value)-CULngInt(@copyValue); " "; '
        'CULngInt(@copyValue.tail)-CULngInt(@copyValue)\n'
        'Print SizeOf(c2fb_LaterBase); " "; '
        'CULngInt(@laterBase.laterBase)-CULngInt(@laterBase); " "; '
        'SizeOf(c2fb_TaggedAlias); " "; '
        'CULngInt(@taggedAlias.tag)-CULngInt(@taggedAlias)\n'
        'Print SizeOf(c2fb_TaggedCopy); " "; '
        'CULngInt(@taggedCopy.tail)-CULngInt(@taggedCopy)\n'
        'Print SizeOf(c2fb_NestedOuter); " "; '
        'CULngInt(@nestedOuter.item)-CULngInt(@nestedOuter); " "; '
        'CULngInt(@nestedOuter.item.code)-CULngInt(@nestedOuter); " "; '
        'CULngInt(@nestedOuter.item.value)-CULngInt(@nestedOuter); " "; '
        'CULngInt(@nestedOuter.tag)-CULngInt(@nestedOuter)\n'
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory)

    def parse_layout(text):
        return [
            tuple(int(value) for value in line.split())
            for line in text.splitlines()
        ]

    assert parse_layout(fb_layout) == parse_layout(c_layout), (
        f"Grouped record typedef layout differs: C={c_layout!r}, "
        f"FreeBASIC={fb_layout!r}"
    )

    removal_header = source_directory / "remove.h"
    removal_header.write_text(
        "typedef struct { int kept; } RemovedBase, KeptBase, *KeptPointer;\n"
    )
    removal_binding = source_directory / "remove.bi"
    run([
        converter, "generic-header", str(removal_header),
        str(removal_binding), *cc, "-remove1st", "RemovedBase",
    ])
    removal_output = removal_binding.read_text()
    assert "c2fb_RemovedBase" not in removal_output, removal_output
    assert "Type c2fb_KeptBase As _c2fb_record_c2fb_KeptBase" in removal_output, removal_output
    assert "Type c2fb_KeptPointer As c2fb_KeptBase Ptr" in removal_output, removal_output
    removal_wrapper = source_directory / "remove.bas"
    removal_wrapper.write_text(
        '#include once "remove.bi"\n'
        "Dim kept As c2fb_KeptBase\n"
        "Dim keptPointer As c2fb_KeptPointer = @kept\n"
    )
    run(fbc + ["-w", "all", "-c", str(removal_wrapper), "-o",
               str(source_directory / "remove.o")], cwd=source_directory)


def check_generic_header_multidimensional_arrays(converter, fbc, cc, work):
    # Array typedef dimensions compose with object and record-field dimensions.
    source_directory = work / "generic-header-multidimensional-arrays"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "enum { C2fbEnumArrayCount = 1u << 2 };\n"
        "typedef int EnumArray[C2fbEnumArrayCount];\n"
        "typedef struct EnumArrayRecord {\n"
        "    EnumArray viaTypedef;\n"
        "    int direct[C2fbEnumArrayCount];\n"
        "} EnumArrayRecord;\n"
        "typedef int Matrix[3][4];\n"
        "struct MatrixRecord { Matrix fromTypedef; int direct[3][4]; };\n"
        "static Matrix globalMatrices[2];\n"
        "typedef unsigned char Tile[2][5];\n"
        "static Tile tileBlocks[10][20];\n"
        "extern int declaredMatrices[2][3][4];\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
        "-std=c11", "-pedantic-errors",
    ])
    assert "emitted 2 record layouts" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    generated = binding.read_text()
    assert "viaTypedef(0 To 3) As Long" in generated, generated
    assert "direct(0 To 3) As Long" in generated, generated
    assert "fromTypedef(0 To 2, 0 To 3) As Long" in generated, generated
    assert "direct(0 To 2, 0 To 3) As Long" in generated, generated
    assert "Dim Shared c2fb_globalMatrices(0 To 1, 0 To 2, 0 To 3) As Long" in generated
    assert ("Dim Shared c2fb_tileBlocks(0 To 9, 0 To 19, 0 To 1, 0 To 4) "
            "As UByte") in generated
    assert ('Extern c2fb_declaredMatrices(0 To 1, 0 To 2, 0 To 3) '
            'Alias "declaredMatrices" As Long') in generated

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '  printf("%zu\\n", sizeof(struct EnumArrayRecord));\n'
        '  printf("%zu %zu %zu\\n", sizeof(struct MatrixRecord), '
        "offsetof(struct MatrixRecord, fromTypedef), "
        "offsetof(struct MatrixRecord, direct));\n"
        '  printf("%zu %zu\\n", sizeof(globalMatrices), '
        "sizeof(declaredMatrices));\n"
        '  printf("%zu\\n", sizeof(tileBlocks));\n'
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + [
        "-std=c11", "-pedantic-errors", str(c_layout_source), "-o",
        str(c_executable),
    ], cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory)

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        'Print SizeOf(c2fb_EnumArrayRecord)\n'
        "Dim recordValue As c2fb_MatrixRecord\n"
        'Print SizeOf(c2fb_MatrixRecord); " "; '
        'CULngInt(@recordValue.fromTypedef(0,0))-CULngInt(@recordValue); " "; '
        'CULngInt(@recordValue.direct(0,0))-CULngInt(@recordValue)\n'
        'Print SizeOf(c2fb_globalMatrices(0,0,0))*24; " "; '
        'SizeOf(c2fb_declaredMatrices(0,0,0))*24\n'
        'Print SizeOf(c2fb_tileBlocks(0,0,0,0))*2000\n'
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory)

    def parse_layout(text):
        return [
            tuple(int(value) for value in line.split())
            for line in text.splitlines()
        ]

    assert parse_layout(fb_layout) == parse_layout(c_layout), (
        f"Multidimensional array layout differs: C={c_layout!r}, "
        f"FreeBASIC={fb_layout!r}"
    )


def check_generic_header_typedef_array_union_layout(converter, fbc, cc, work):
    # Typedef array members retain their C extents inside records and unions.
    source_directory = work / "generic-header-typedef-array-union-layout"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef int IntTen[10];\n"
        "typedef unsigned char BytePair[2][5];\n"
        "struct ArrayRecord { IntTen values; int direct[10]; char marker; };\n"
        "union ArrayUnion {\n"
        "    IntTen values;\n"
        "    int direct[10];\n"
        "    struct { BytePair first; BytePair second; } nested;\n"
        "};\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
        "-std=c11", "-pedantic-errors",
    ])
    assert "emitted 3 record layouts" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    generated = binding.read_text()
    assert "values(0 To 9) As Long" in generated, generated
    assert "direct(0 To 9) As Long" in generated, generated
    assert "first(0 To 1, 0 To 4) As UByte" in generated, generated
    assert "second(0 To 1, 0 To 4) As UByte" in generated, generated

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '  printf("%zu %zu %zu %zu %zu %zu\\n", '
        "sizeof(struct ArrayRecord), "
        "offsetof(struct ArrayRecord, values), "
        "offsetof(struct ArrayRecord, values[9]), "
        "offsetof(struct ArrayRecord, direct), "
        "offsetof(struct ArrayRecord, direct[9]), "
        "offsetof(struct ArrayRecord, marker));\n"
        '  printf("%zu %zu %zu %zu\\n", sizeof(union ArrayUnion), '
        "offsetof(union ArrayUnion, values[9]), "
        "offsetof(union ArrayUnion, direct[9]), "
        "offsetof(union ArrayUnion, nested));\n"
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + [
        "-std=c11", "-pedantic-errors", str(c_layout_source), "-o",
        str(c_executable),
    ], cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory)

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        'Print SizeOf(c2fb_ArrayRecord); " "; '
        'OffsetOf(c2fb_ArrayRecord, values(0)); " "; '
        'OffsetOf(c2fb_ArrayRecord, values(9)); " "; '
        'OffsetOf(c2fb_ArrayRecord, direct(0)); " "; '
        'OffsetOf(c2fb_ArrayRecord, direct(9)); " "; '
        'OffsetOf(c2fb_ArrayRecord, marker)\n'
        'Print SizeOf(c2fb_ArrayUnion); " "; '
        'OffsetOf(c2fb_ArrayUnion, values(9)); " "; '
        'OffsetOf(c2fb_ArrayUnion, direct(9)); " "; '
        'OffsetOf(c2fb_ArrayUnion, nested)\n'
    )
    def parse_layout(text):
        return [
            tuple(int(value) for value in line.split())
            for line in text.splitlines()
        ]

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        fb_executable = source_directory / f"layout-fb-{backend}"
        run(fbc + flags + [
            "-w", "all", str(fb_layout_source), "-x", str(fb_executable),
        ], cwd=source_directory)
        fb_layout = run([str(fb_executable)], cwd=source_directory)
        assert parse_layout(fb_layout) == parse_layout(c_layout), (
            f"Typedef array record/union layout differs on {backend}: "
            f"C={c_layout!r}, FreeBASIC={fb_layout!r}"
        )


def check_generic_header_gnu_extension_typedef(converter, fbc, work):
    # GCC's __extension__ marker suppresses diagnostics but does not change a type.
    source_directory = work / "generic-header-gnu-extension-typedef"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "__extension__ typedef signed long long myint64;\n"
        "extern myint64 c2fbExtensionValue;\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert "Type c2fb_myint64 As LongInt" in generated, generated
    assert ('Extern c2fb_c2fbExtensionValue Alias "c2fbExtensionValue" '
            'As c2fb_myint64') in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "Dim localValue As c2fb_myint64 = 1234567890123LL\n"
        "If localValue <> 1234567890123LL Then End 1\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_gnu_signed_types(converter, fbc, cc, work):
    # Linux headers use GCC's reserved spellings even in strict C modes.
    # Check both ABI declarations and signed arithmetic in translated bodies.
    source_directory = work / "generic-gnu-signed-types"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef __signed__ char gnu_s8;\n"
        "typedef __signed short gnu_s16;\n"
        "typedef __signed__ int gnu_s32;\n"
        "typedef __signed long long gnu_s64;\n"
        "typedef __signed__ __int128 gnu_s128;\n"
        "struct SignedValues { gnu_s8 a; gnu_s16 b; gnu_s32 c; gnu_s64 d; };\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), *cc])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    for name, expected_type in (("s8", "Byte"), ("s16", "Short"),
                                ("s32", "Long"), ("s64", "LongInt"),
                                ("s128", "Integer<128>")):
        assert f"Type c2fb_gnu_{name} As {expected_type}" in generated, generated

    c_probe = source_directory / "layout.c"
    c_probe.write_text(
        '#include "probe.h"\n'
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        "int main(void) {\n"
        '  printf("%zu %zu %zu %zu %zu %zu %zu %zu %zu %zu\\n", '
        "sizeof(gnu_s8), sizeof(gnu_s16), sizeof(gnu_s32), sizeof(gnu_s64), "
        "sizeof(gnu_s128), sizeof(struct SignedValues), "
        "offsetof(struct SignedValues, a), offsetof(struct SignedValues, b), "
        "offsetof(struct SignedValues, c), offsetof(struct SignedValues, d));\n"
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + [str(c_probe), "-o", str(c_executable)], cwd=source_directory)
    expected_layout = run([str(c_executable)], cwd=source_directory).split()
    wrapper = source_directory / "layout.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "Dim value As c2fb_SignedValues\n"
        'Print SizeOf(c2fb_gnu_s8); " "; SizeOf(c2fb_gnu_s16); " "; '
        'SizeOf(c2fb_gnu_s32); " "; SizeOf(c2fb_gnu_s64); " "; '
        'SizeOf(c2fb_gnu_s128); " "; SizeOf(value); " "; '
        'CULngInt(@value.a)-CULngInt(@value); " "; '
        'CULngInt(@value.b)-CULngInt(@value); " "; '
        'CULngInt(@value.c)-CULngInt(@value); " "; '
        'CULngInt(@value.d)-CULngInt(@value)\n'
    )
    source = source_directory / "signed.c"
    source.write_text(
        "__signed__ long long signed_roundtrip(__signed long long value) {\n"
        "  __signed__ short adjustment = -7;\n"
        "  return (__signed__ long long)(value + adjustment);\n"
        "}\n"
    )
    candidate = source_directory / "signed.bas"
    summary = run([converter, "translate-simple-generic-c", str(source),
                   str(candidate), *cc])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    body_wrapper = source_directory / "body-check.bas"
    body_wrapper.write_text(
        '#include once "signed.bas"\n'
        "If signed_roundtrip(-1234567890123LL) <> -1234567890130LL Then End 1\n"
        "If signed_roundtrip(1234567890123LL) <> 1234567890116LL Then End 2\n"
    )
    for backend in ([], ["-gen", "gcc"]):
        executable = source_directory / "check"
        run(fbc + backend + ["-w", "all", str(wrapper), "-x", str(executable)],
            cwd=source_directory)
        assert run([str(executable)], cwd=source_directory).split() == expected_layout
        run(fbc + backend + ["-w", "all", str(body_wrapper), "-x", str(executable)],
            cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_body_global_definitions(converter, fbc, cc, work):
    # C object definitions retain their linker names and initial storage.
    source_directory = work / "generic-body-global-definitions"
    source_directory.mkdir()
    header = source_directory / "global-declarations.h"
    header.write_text(
        "extern int imported_by_reference;\n"
        "int header_tentative = 13;\n"
        "static int header_private = 5;\n"
    )
    source = source_directory / "globals.c"
    source.write_text(
        '#include "global-declarations.h"\n'
        "extern int exported_counter;\n"
        "int exported_counter = 7;\n"
        "const unsigned char exported_bytes[3] = {9, 17, 33};\n"
        "int add_to_globals(int amount) {\n"
        "  exported_counter += amount;\n"
        "  return imported_by_reference + exported_counter + "
        "header_tentative + header_private;\n"
        "}\n"
    )
    candidate = source_directory / "globals.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), *cc, "--include-global-definitions",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    for c_name in ("exported_counter", "exported_bytes", "header_tentative"):
        assert f"' c2fb global definition {c_name}=" in generated, generated
        assert f'Alias "{c_name}"' in generated, generated
    assert "Private Dim Shared" in generated and "header_private" in generated

    reference = source_directory / "reference.c"
    reference.write_text(
        "int imported_by_reference = 12;\n"
        "extern int exported_counter;\n"
        "extern const unsigned char exported_bytes[3];\n"
        "extern int header_tentative;\n"
        "int check_global_values(void) {\n"
        "  return exported_counter == 7 && imported_by_reference == 12 && "
        "header_tentative == 13 && exported_bytes[0] == 9 && "
        "exported_bytes[1] == 17 && exported_bytes[2] == 33;\n"
        "}\n"
        "int check_constant_globals(void) {\n"
        "  return imported_by_reference == 12 && header_tentative == 13 && "
        "exported_bytes[0] == 9 && exported_bytes[1] == 17 && "
        "exported_bytes[2] == 33;\n"
        "}\n"
        "void replace_exported_counter(int value) { exported_counter = value; }\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-Wall", "-Wextra", "-Werror", "-c", str(reference),
              "-o", str(reference_object)], cwd=source_directory)
    exported = run(["nm", "-g", "--defined-only", "--format=posix",
                    str(reference_object)], cwd=source_directory)
    assert "imported_by_reference" in exported
    assert "header_tentative" not in exported

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "globals.bas"\n'
        "Extern \"C\"\n"
        '    Declare Function check_global_values Cdecl Alias "check_global_values"() As Long\n'
        '    Declare Function check_constant_globals Cdecl Alias "check_constant_globals"() As Long\n'
        '    Declare Sub replace_exported_counter Cdecl Alias "replace_exported_counter"(ByVal value As Long)\n'
        "End Extern\n"
        "If check_global_values() = 0 Then End 1\n"
        "If add_to_globals(3) <> 40 Then End 2\n"
        "replace_exported_counter(41)\n"
        "If add_to_globals(1) <> 72 Then End 3\n"
        "If check_constant_globals() = 0 Then End 4\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + [str(wrapper), str(reference_object), "-x",
                           str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)
        symbols = run(["nm", "-g", "--defined-only", "--format=posix",
                       str(executable)], cwd=source_directory)
        for c_name in ("exported_counter", "exported_bytes", "header_tentative"):
            assert re.search(rf"^{re.escape(c_name)} [A-Z] ", symbols, re.M), symbols


def check_generic_body_global_callback_objects(converter, fbc, cc, work):
    # Initialized function-pointer objects are C data definitions with ABI-visible names.
    source_directory = work / "generic-body-global-callback-objects"
    source_directory.mkdir()
    source = source_directory / "callbacks.c"
    source.write_text(
        "#include <stddef.h>\n"
        "#include <string.h>\n"
        "void *(*c2fb_copy_callback)(void *, const void *, size_t) = memcpy;\n"
        "void *(*c2fb_set_callback)(void *, int, size_t) = memset;\n"
        "void *(*c2fb_null_copy_callback)(void *, const void *, size_t) = 0;\n"
        "int c2fb_callback_target(int value) { return value * 2 + 3; }\n"
        "int (*c2fb_direct_callback)(int) = c2fb_callback_target;\n"
        "int (*c2fb_null_callback)(int) = 0;\n"
        "typedef int (*c2fb_callback_alias)(int);\n"
        "c2fb_callback_alias c2fb_typedef_callback = c2fb_callback_target;\n"
    )
    probe = source_directory / "probe.c"
    probe.write_text(
        "#include <stddef.h>\n"
        "extern void *(*c2fb_copy_callback)(void *, const void *, size_t);\n"
        "extern void *(*c2fb_set_callback)(void *, int, size_t);\n"
        "extern void *(*c2fb_null_copy_callback)(void *, const void *, size_t);\n"
        "extern int (*c2fb_direct_callback)(int);\n"
        "extern int (*c2fb_null_callback)(int);\n"
        "typedef int (*c2fb_probe_callback)(int);\n"
        "extern c2fb_probe_callback c2fb_typedef_callback;\n"
        "int c2fb_probe_global_callback_objects(void) {\n"
        "    const unsigned char source[3] = { 11, 22, 33 };\n"
        "    unsigned char destination[3] = { 0, 0, 0 };\n"
        "    void *copy_result = c2fb_copy_callback(destination, source, 3);\n"
        "    void *set_result = c2fb_set_callback(destination + 1, 9, 2);\n"
        "    return copy_result == destination && set_result == destination + 1 &&\n"
        "           destination[0] == 11 && destination[1] == 9 &&\n"
        "           destination[2] == 9 && c2fb_null_copy_callback == 0 &&\n"
        "           c2fb_direct_callback != 0 && c2fb_null_callback == 0 &&\n"
        "           c2fb_direct_callback(4) == 11 &&\n"
        "           c2fb_typedef_callback(5) == 13;\n"
        "}\n"
    )
    candidate = source_directory / "callbacks.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), *cc, "--include-global-definitions",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    for name in (
        "c2fb_copy_callback", "c2fb_set_callback", "c2fb_null_copy_callback",
        "c2fb_direct_callback", "c2fb_null_callback", "c2fb_typedef_callback",
    ):
        assert f'Alias "{name}"' in generated, generated
    assert '#include once "crt/mem.bi"' in generated, generated
    assert "ProcPtr(memcpy)" in generated and "ProcPtr(memset)" in generated

    probe_object = source_directory / "probe.o"
    run(cc + ["-Wall", "-Wextra", "-Werror", "-c", str(probe),
              "-o", str(probe_object)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "callbacks.bas"\n'
        "Extern \"C\"\n"
        '    Declare Function c2fb_probe_global_callback_objects Cdecl Alias '
        '"c2fb_probe_global_callback_objects"() As Long\n'
        "End Extern\n"
        "If c2fb_probe_global_callback_objects() = 0 Then End 1\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), str(probe_object),
                           "-x", str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_source_unit_global_definitions_keep_static_storage_with_body(
    converter, fbc, cc, work
):
    # With global definitions enabled, the body module owns source static data.
    source_directory = work / "source-unit-global-definitions-static-storage"
    source_directory.mkdir()
    source = source_directory / "static-storage.c"
    source.write_text(
        "static int c2fb_private_values[3] = {4, 7, 11};\n"
        "int c2fbReadPrivateValue(int index) {\n"
        "    return c2fb_private_values[index];\n"
        "}\n"
    )
    candidate = source_directory / "static-storage_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    result = subprocess.run(
        [
            sys.executable, str(source_unit_tool), str(source), str(candidate),
            "--converter", converter, "--compiler", cc[0],
            "--body-option=--include-global-definitions",
        ],
        cwd=source_directory, capture_output=True, text=True, check=False,
    )
    assert result.returncode == 0, result.stdout + result.stderr
    type_context = candidate.with_name("static-storage_candidates_types.bi")
    type_context_text = type_context.read_text()
    generated = candidate.read_text()
    assert "c2fb_private_values" not in type_context_text, type_context_text
    assert "Private Dim Shared c2fb_global_c2fb_private_values(0 To 2)" \
        in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-shared", "-fPIC", str(source), "-o", str(reference_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbReadPrivateValue.argtypes = [ctypes.c_int]
    reference.c2fbReadPrivateValue.restype = ctypes.c_int
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate), "-x",
                           str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        converted.c2fbReadPrivateValue.argtypes = [ctypes.c_int]
        converted.c2fbReadPrivateValue.restype = ctypes.c_int
        for index, expected in enumerate((4, 7, 11)):
            assert reference.c2fbReadPrivateValue(index) == \
                converted.c2fbReadPrivateValue(index) == expected


def check_generic_body_parameter_matches_tag(converter, fbc, cc, work):
    # Tags occupy a separate C namespace. A parameter can have the same name
    # as its enum tag, as in Coreutils' enum backup_type backup_type.
    source_directory = work / "generic-body-parameter-matches-tag"
    source_directory.mkdir()
    source = source_directory / "probe.c"
    source.write_text(
        "enum backup_type { no_backup = -7, simple_backup = 0, numbered_backup = 12 };\n"
        "int same_tag(enum backup_type backup_type) {\n"
        "  return backup_type == no_backup ? -11 : backup_type + 7;\n"
        "}\n"
    )
    candidate = source_directory / "probe.bas"
    summary = run([converter, "translate-simple-generic-c", str(source),
                   str(candidate), *cc])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    reference = source_directory / "reference.c"
    reference.write_text(
        '#include "probe.c"\n'
        "#include <stdio.h>\n"
        "int main(void) {\n"
        "  int values[] = {-7, 0, 12};\n"
        "  for (int i = 0; i < 3; ++i)\n"
        '    printf("%d\\n", same_tag(values[i]));\n'
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "reference"
    run(cc + [str(reference), "-o", str(c_executable)], cwd=source_directory)
    expected = run([str(c_executable)], cwd=source_directory).split()
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bas"\n'
        "Print same_tag(-7)\n"
        "Print same_tag(0)\n"
        "Print same_tag(12)\n"
    )
    for backend in ([], ["-gen", "gcc"]):
        executable = source_directory / "check"
        run(fbc + backend + ["-w", "all", str(wrapper), "-x", str(executable)],
            cwd=source_directory)
        assert run([str(executable)], cwd=source_directory).split() == expected


def check_generic_header_record_trailing_declarators(converter, fbc, cc, work):
    # Declarations after a record body still enter object, callback, and prototype lowering.
    source_directory = work / "generic-header-record-trailing-declarators"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "struct PackedRecord { short a; int b; } "
        "__attribute__((packed)) packedInstance;\n"
        "struct CallbackRecord { int value; } "
        "__attribute__((stdcall)) (*callbackRecord)(void);\n"
        "struct ReturnRecord { int value; } "
        "__attribute__((stdcall)) returnRecord(void);\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
    ])
    assert "emitted 3 record layouts" in summary, summary
    assert "converted 1 function declarations and 2 external objects" in summary, summary
    generated = binding.read_text()
    assert "Type _c2fb_record_c2fb_PackedRecord Field = 1" in generated, generated
    assert ('Extern c2fb_packedInstance Alias "packedInstance" '
            'As c2fb_PackedRecord') in generated, generated
    assert ('Extern c2fb_callbackRecord_ Alias "callbackRecord" '
            'As Function StdCall() As c2fb_CallbackRecord') in generated, generated
    assert ('Declare Function c2fb_returnRecord_ StdCall Alias "returnRecord" '
            '() As c2fb_ReturnRecord') in generated, generated

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '  printf("%zu %zu %zu\\n", sizeof(struct PackedRecord), '
        "offsetof(struct PackedRecord, a), offsetof(struct PackedRecord, b));\n"
        '  printf("%zu %zu\\n", sizeof(struct CallbackRecord), '
        "offsetof(struct CallbackRecord, value));\n"
        '  printf("%zu %zu\\n", sizeof(struct ReturnRecord), '
        "offsetof(struct ReturnRecord, value));\n"
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + [str(c_layout_source), "-o", str(c_executable)],
        cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory)

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        "Dim packedValue As c2fb_PackedRecord\n"
        "Dim callbackValue As c2fb_CallbackRecord\n"
        "Dim returnValue As c2fb_ReturnRecord\n"
        'Print SizeOf(c2fb_PackedRecord); " "; '
        'CULngInt(@packedValue.a)-CULngInt(@packedValue); " "; '
        'CULngInt(@packedValue.b)-CULngInt(@packedValue)\n'
        'Print SizeOf(c2fb_CallbackRecord); " "; '
        'CULngInt(@callbackValue.value)-CULngInt(@callbackValue)\n'
        'Print SizeOf(c2fb_ReturnRecord); " "; '
        'CULngInt(@returnValue.value)-CULngInt(@returnValue)\n'
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory)

    def parse_layout(text):
        return [
            tuple(int(value) for value in line.split())
            for line in text.splitlines()
        ]

    assert parse_layout(fb_layout) == parse_layout(c_layout), (
        f"Record trailing declaration layout differs: C={c_layout!r}, "
        f"FreeBASIC={fb_layout!r}"
    )


def check_generic_header_aligned_record_types(converter, fbc, cc, work):
    # A one-member union can raise record alignment while preserving promoted fields.
    source_directory = work / "generic-header-aligned-record-types"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "struct __attribute__((aligned(2))) AlignedShort { char value; };\n"
        "struct __attribute__((aligned(4))) AlignedLong { char value; };\n"
        "struct __attribute__((aligned(8))) AlignedRecord { int value; };\n"
        "struct Holder { char prefix; struct AlignedRecord value; char suffix; };\n"
        "union __attribute__((aligned(8))) AlignedUnion { char byte; int word; };\n"
        "struct UnionHolder { char prefix; union AlignedUnion value; char suffix; };\n"
        "typedef int AlignedInt __attribute__((aligned(8)));\n"
        "struct AlignedIntHolder { char prefix; AlignedInt value; char suffix; };\n"
        "typedef struct TailRecord { int value; } "
        "TailRecordAlias __attribute__((aligned(8)));\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
        "-std=gnu11",
    ])
    assert "emitted 8 record layouts" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    generated = binding.read_text()
    assert "Union _c2fb_record_c2fb_AlignedRecord" in generated, generated
    assert "Union _c2fb_record_c2fb_AlignedUnion" in generated, generated
    assert "Type c2fb_AlignedInt As Long Field = 8" in generated, generated
    assert "c2fb typedef-alignment-not-represented: AlignedInt" not in generated, generated
    assert "Type c2fb_TailRecordAlias As c2fb_TailRecord" in generated, generated
    assert "Type c2fb_TailRecordAlias As c2fb_TailRecord Field = 8" in generated, generated
    assert "typedef-alignment-not-represented" not in generated, generated

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        '_Static_assert(sizeof(TailRecordAlias) == 4, "typedef size changed");\n'
        '_Static_assert(_Alignof(TailRecordAlias) == 8, "typedef alignment missing");\n'
        "int main(void) {\n"
        '  printf("%zu %zu\\n", sizeof(struct AlignedShort), '
        "offsetof(struct AlignedShort, value));\n"
        '  printf("%zu %zu\\n", sizeof(struct AlignedLong), '
        "offsetof(struct AlignedLong, value));\n"
        '  printf("%zu %zu %zu %zu\\n", sizeof(struct AlignedRecord), '
        "offsetof(struct AlignedRecord, value), sizeof(struct Holder), "
        "offsetof(struct Holder, suffix));\n"
        '  printf("%zu %zu %zu %zu\\n", sizeof(union AlignedUnion), '
        "offsetof(union AlignedUnion, word), sizeof(struct UnionHolder), "
        "offsetof(struct UnionHolder, suffix));\n"
        '  printf("%zu %zu %zu\\n", sizeof(struct AlignedIntHolder), '
        "offsetof(struct AlignedIntHolder, value), "
        "offsetof(struct AlignedIntHolder, suffix));\n"
        '  printf("%zu %zu %zu %zu\\n", sizeof(struct TailRecord), '
        "offsetof(struct TailRecord, value), sizeof(TailRecordAlias), "
        "offsetof(TailRecordAlias, value));\n"
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + [str(c_layout_source), "-o", str(c_executable)],
        cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory)

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        "Dim alignedShort As c2fb_AlignedShort\n"
        "Dim alignedLong As c2fb_AlignedLong\n"
        "Dim alignedRecord As c2fb_AlignedRecord\n"
        "Dim holder As c2fb_Holder\n"
        "Dim alignedUnion As c2fb_AlignedUnion\n"
        "Dim unionHolder As c2fb_UnionHolder\n"
        "Dim alignedIntHolder As c2fb_AlignedIntHolder\n"
        "Dim tailRecord As c2fb_TailRecord\n"
        "Dim tailAlias As c2fb_TailRecordAlias\n"
        'Print SizeOf(c2fb_AlignedShort); " "; '
        'CULngInt(@alignedShort.value)-CULngInt(@alignedShort)\n'
        'Print SizeOf(c2fb_AlignedLong); " "; '
        'CULngInt(@alignedLong.value)-CULngInt(@alignedLong)\n'
        'Print SizeOf(c2fb_AlignedRecord); " "; '
        'CULngInt(@alignedRecord.value)-CULngInt(@alignedRecord); " "; '
        'SizeOf(c2fb_Holder); " "; '
        'CULngInt(@holder.suffix)-CULngInt(@holder)\n'
        'Print SizeOf(c2fb_AlignedUnion); " "; '
        'CULngInt(@alignedUnion.word)-CULngInt(@alignedUnion); " "; '
        'SizeOf(c2fb_UnionHolder); " "; '
        'CULngInt(@unionHolder.suffix)-CULngInt(@unionHolder)\n'
        'Print SizeOf(c2fb_AlignedIntHolder); " "; '
        'CULngInt(@alignedIntHolder.value)-CULngInt(@alignedIntHolder); " "; '
        'CULngInt(@alignedIntHolder.suffix)-CULngInt(@alignedIntHolder)\n'
        'Print SizeOf(c2fb_TailRecord); " "; '
        'CULngInt(@tailRecord.value)-CULngInt(@tailRecord); " "; '
        'SizeOf(c2fb_TailRecordAlias); " "; '
        'CULngInt(@tailAlias.value)-CULngInt(@tailAlias)\n'
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory)

    def parse_layout(text):
        return [
            tuple(int(value) for value in line.split())
            for line in text.splitlines()
        ]

    assert parse_layout(fb_layout) == parse_layout(c_layout), (
        f"Aligned record layout differs: C={c_layout!r}, "
        f"FreeBASIC={fb_layout!r}"
    )


