def check_generic_header_inline_aggregate_declarator_groups(
    converter, fbc, cc, work
):
    # One inline record definition may declare several fields with distinct operators.
    source_directory = work / "generic-header-inline-aggregate-declarators"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "struct InlineMembers {\n"
        "    struct { int value; } first;\n"
        "    struct { int value; } second, third, fourth;\n"
        "    struct { int value; } *pointer;\n"
        "    struct { int value; } (*factory)(void);\n"
        "};\n"
        "struct ConstInline { struct { int value; } const first, second; };\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
        "-std=c11", "-pedantic-errors",
    ])
    assert "emitted 7 record layouts" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    generated = binding.read_text()
    for field_name in ("first", "second", "third", "fourth"):
        assert re.search(rf"^\s*{field_name} As c2fb__c2fb_inline_", generated, re.M), generated
    assert re.search(r"^\s*pointer As c2fb__c2fb_inline_\w+ Ptr$", generated, re.M)
    assert re.search(
        r"^\s*factory As Function CDecl\(\) As c2fb__c2fb_inline_\w+$",
        generated, re.M,
    ), generated
    assert re.search(
        r"^\s*first As Const c2fb__c2fb_inline_\w+$", generated, re.M
    ), generated
    assert re.search(
        r"^\s*second As Const c2fb__c2fb_inline_\w+$", generated, re.M
    ), generated

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stddef.h>\n"
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '  printf("%zu %zu %zu %zu %zu %zu %zu\\n", '
        "sizeof(struct InlineMembers), offsetof(struct InlineMembers, first), "
        "offsetof(struct InlineMembers, second), offsetof(struct InlineMembers, third), "
        "offsetof(struct InlineMembers, fourth), offsetof(struct InlineMembers, pointer), "
        "offsetof(struct InlineMembers, factory));\n"
        '  printf("%zu %zu %zu\\n", sizeof(struct ConstInline), '
        "offsetof(struct ConstInline, first), offsetof(struct ConstInline, second));\n"
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "layout-c"
    run(cc + [
        "-std=c11", "-pedantic-errors", str(c_layout_source), "-o",
        str(c_executable),
    ], cwd=source_directory)
    c_layout = run([str(c_executable)], cwd=source_directory)

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        "Dim value As c2fb_InlineMembers\n"
        "Dim constValue As c2fb_ConstInline\n"
        'Print SizeOf(c2fb_InlineMembers); " "; '
        'CULngInt(@value.first)-CULngInt(@value); " "; '
        'CULngInt(@value.second)-CULngInt(@value); " "; '
        'CULngInt(@value.third)-CULngInt(@value); " "; '
        'CULngInt(@value.fourth)-CULngInt(@value); " "; '
        'CULngInt(@value.pointer)-CULngInt(@value); " "; '
        'CULngInt(@value.factory)-CULngInt(@value)\n'
        'Print SizeOf(c2fb_ConstInline); " "; '
        'CULngInt(@constValue.first)-CULngInt(@constValue); " "; '
        'CULngInt(@constValue.second)-CULngInt(@constValue)\n'
    )
    fb_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_executable)], cwd=source_directory)

    def parse_layout(text):
        return [
            tuple(int(value) for value in line.split())
            for line in text.splitlines()
        ]

    assert parse_layout(fb_layout) == parse_layout(c_layout), (
        f"Inline aggregate field layout differs: C={c_layout!r}, "
        f"FreeBASIC={fb_layout!r}"
    )


def check_generic_header_anonymous_record_tails(converter, fbc, cc, work):
    # Anonymous record definitions can declare objects or function results in their tail.
    source_directory = work / "generic-header-anonymous-record-tails"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "struct { int value; } c2fbAnonymousReturn(void);\n"
        "union { int value; } c2fbAnonymousUnionReturn(void);\n"
        "enum { C2FB_ANON_ENUM_VALUE = 7 } c2fbAnonymousEnumReturn(void);\n"
        "static struct { int value; } c2fbAnonA, c2fbAnonB;\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), *cc,
        "-std=c11", "-pedantic-errors",
    ])
    assert "emitted 3 record layouts" in summary, summary
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    generated = binding.read_text()
    for name in (
        "c2fb_c2fbAnonymousReturn", "c2fb_c2fbAnonymousUnionReturn",
        "c2fb_c2fbAnonymousEnumReturn", "c2fb_C2FB_ANON_ENUM_VALUE",
        "Dim Shared c2fb_c2fbAnonA", "Dim Shared c2fb_c2fbAnonB",
    ):
        assert name in generated, generated
    for alias_name in (
        "c2fb_c2fbAnonymousReturn", "c2fb_c2fbAnonymousUnionReturn",
        "c2fb_c2fbAnonymousEnumReturn", "c2fb_c2fbAnonA",
        "c2fb_c2fbAnonB",
    ):
        assert re.search(
            rf"^Type {alias_name} As c2fb___c2fb_anonymous_", generated, re.M
        ), generated

    c_source = source_directory / "syntax.c"
    c_source.write_text('#include "probe.h"\nint main(void) { return 0; }\n')
    run(cc + ["-std=c11", "-pedantic-errors", "-fsyntax-only", str(c_source)],
        cwd=source_directory)

    c_layout_source = source_directory / "layout.c"
    c_layout_source.write_text(
        "#include <stdio.h>\n"
        '#include "probe.h"\n'
        "int main(void) {\n"
        '    printf("%zu %zu\\n", sizeof(__typeof__(c2fbAnonymousReturn())), '
        "__builtin_offsetof(__typeof__(c2fbAnonymousReturn()), value));\n"
        '    printf("%zu %zu\\n", sizeof(__typeof__(c2fbAnonymousUnionReturn())), '
        "__builtin_offsetof(__typeof__(c2fbAnonymousUnionReturn()), value));\n"
        '    printf("%zu\\n", sizeof(__typeof__(c2fbAnonymousEnumReturn())));\n'
        '    printf("%zu %zu %zu %zu\\n", sizeof(__typeof__(c2fbAnonA)), '
        "__builtin_offsetof(__typeof__(c2fbAnonA), value), "
        "sizeof(__typeof__(c2fbAnonB)), "
        "__builtin_offsetof(__typeof__(c2fbAnonB), value));\n"
        "    return 0;\n"
        "}\n"
    )
    c_layout_executable = source_directory / "layout-c"
    run(cc + [str(c_layout_source), "-o", str(c_layout_executable)],
        cwd=source_directory)
    c_layout = run([str(c_layout_executable)], cwd=source_directory)

    fb_source = source_directory / "check.bas"
    fb_source.write_text(
        '#include once "probe.bi"\n'
        "c2fb_c2fbAnonA.value = 11\n"
        "c2fb_c2fbAnonB.value = 13\n"
        "If c2fb_c2fbAnonA.value <> 11 Then End 1\n"
        "If c2fb_c2fbAnonB.value <> 13 Then End 2\n"
        "If c2fb_C2FB_ANON_ENUM_VALUE <> 7 Then End 3\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(fb_source), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)

    fb_layout_source = source_directory / "layout.bas"
    fb_layout_source.write_text(
        '#include once "probe.bi"\n'
        "Dim returned As c2fb_c2fbAnonymousReturn\n"
        "Dim unionReturned As c2fb_c2fbAnonymousUnionReturn\n"
        "Dim enumReturned As c2fb_c2fbAnonymousEnumReturn\n"
        "Dim anonymousA As c2fb_c2fbAnonA\n"
        "Dim anonymousB As c2fb_c2fbAnonB\n"
        'Print SizeOf(returned); " "; '
        'CULngInt(@returned.value)-CULngInt(@returned)\n'
        'Print SizeOf(unionReturned); " "; '
        'CULngInt(@unionReturned.value)-CULngInt(@unionReturned)\n'
        'Print SizeOf(enumReturned)\n'
        'Print SizeOf(anonymousA); " "; '
        'CULngInt(@anonymousA.value)-CULngInt(@anonymousA); " "; '
        'SizeOf(anonymousB); " "; '
        'CULngInt(@anonymousB.value)-CULngInt(@anonymousB)\n'
    )
    fb_layout_executable = source_directory / "layout-fb"
    run(fbc + ["-w", "all", str(fb_layout_source), "-x", str(fb_layout_executable)],
        cwd=source_directory)
    fb_layout = run([str(fb_layout_executable)], cwd=source_directory)
    def parse_layout(text):
        return [
            tuple(int(value) for value in line.split())
            for line in text.splitlines()
        ]

    assert parse_layout(fb_layout) == parse_layout(c_layout), (
        f"Anonymous use-site record layout differs: C={c_layout!r}, "
        f"FreeBASIC={fb_layout!r}"
    )


def check_generic_header_remove_include(converter, fbc, work):
    # Removing a mapped include must flatten its declarations into the current binding.
    source_directory = work / "generic-header-remove-include"
    source_directory.mkdir()
    (source_directory / "child_preserved.h").write_text(
        "typedef struct ChildPreserved { int value; } ChildPreserved;\n"
        "int c2fbChildPreserved(ChildPreserved *value);\n"
    )
    (source_directory / "child_flattened.h").write_text(
        "typedef struct ChildFlattened { int value; } ChildFlattened;\n"
        "int c2fbChildFlattened(ChildFlattened *value);\n"
    )
    root_header = source_directory / "root.h"
    root_header.write_text(
        '#include "child_preserved.h"\n'
        '#include "child_flattened.h"\n'
        "int c2fbRoot(ChildPreserved *preserved, ChildFlattened *flattened);\n"
    )
    (source_directory / "child_preserved.bi").write_text(
        "Type c2fb_ChildPreserved\n"
        "    value As Long\n"
        "End Type\n"
    )

    outputs = []
    for label, remove_options in (
        ("compat", ["-removeinclude", "child_flattened.h"]),
        ("long", ["--remove-include=child_flattened.h"]),
    ):
        output = source_directory / f"{label}.bi"
        run([
            converter, "generic-header", str(root_header), str(output), "cc",
            f"-I{source_directory}",
            "--preserve-include=child_preserved.h=child_preserved.bi",
            "--preserve-include=child_flattened.h=child_flattened.bi",
            *remove_options,
        ])
        generated = output.read_text()
        assert '#include once "child_preserved.bi"' in generated, generated
        assert '#include once "child_flattened.bi"' not in generated, generated
        assert "Type c2fb_ChildFlattened" in generated, generated
        assert "c2fb_c2fbChildFlattened" in generated, generated
        assert "' c2fb remove include matched: child_flattened.h" in generated
        outputs.append(output)

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "compat.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check.o")], cwd=source_directory)


def check_generic_header_preserve_missing_includes(converter, fbc, work):
    source_directory = work / "generic-header-preserve-missing-includes"
    source_directory.mkdir()
    header = source_directory / "missing.h"
    header.write_text(
        "#include <split/missing.h>\n"
        "extern int afterMissingInclude(void);\n"
    )
    binding = source_directory / "missing.bi"
    run([
        converter, "generic-header", str(header), str(binding),
        "--preserve-include=split/missing.h=split/missing.bi",
        "--preserve-missing-includes", "cc",
    ])
    generated = binding.read_text()
    assert '#include once "split/missing.bi"' in generated, generated
    assert "Declare Function c2fb_afterMissingInclude" in generated, generated
    assert "Exact mapped C includes may use empty preprocessing stubs" in generated
    assert not list(source_directory.glob(
        "missing.bi.c2fb-preprocessed-*.i.include-stubs"))

    split_directory = source_directory / "split"
    split_directory.mkdir()
    (split_directory / "missing.bi").write_text("' supplied by the caller\n")
    wrapper = source_directory / "check-missing.bi.bas"
    wrapper.write_text('#include once "missing.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check-missing.o")], cwd=source_directory)

    failing_header = source_directory / "failing.h"
    failing_header.write_text(
        "#include <split/failing.h>\n#error stop after staging the include\n"
    )
    failed_binding = source_directory / "failing.bi"
    failed_result = subprocess.run([
        converter, "generic-header", str(failing_header), str(failed_binding),
        "--preserve-include=split/failing.h=split/failing.bi",
        "--preserve-missing-includes", "cc",
    ], capture_output=True, text=True)
    assert failed_result.returncode != 0, failed_result.stdout
    assert not failed_binding.exists()
    assert not list(source_directory.glob(
        "failing.bi.c2fb-preprocessed-*.i.include-stubs"))

    real_header = source_directory / "real.h"
    real_header.write_text(
        "typedef struct RealType { int value; } RealType;\n"
        "#define REAL_HEADER_VALUE 9\n"
        "extern RealType *getRealType(void);\n"
    )
    (source_directory / "real.bi").write_text(
        "Type c2fb_RealType\n    value As Long\nEnd Type\n"
    )
    real_input = source_directory / "real-input.h"
    real_input.write_text(
        '#include "real.h"\n'
        "extern RealType *getRealType(void);\n"
    )
    real_binding = source_directory / "real-binding.bi"
    run([
        converter, "generic-header", str(real_input), str(real_binding),
        "--preserve-include=real.h=real.bi", "--preserve-missing-includes",
        "cc",
    ])
    real_generated = real_binding.read_text()
    assert '#include once "real.bi"' in real_generated, real_generated
    assert "Type c2fb_RealType" not in real_generated, real_generated
    assert "Const c2fb_REAL_HEADER_VALUE" not in real_generated, real_generated
    assert "Declare Function c2fb_getRealType" in real_generated, real_generated
    real_wrapper = source_directory / "check-real.bi.bas"
    real_wrapper.write_text('#include once "real-binding.bi"\n')
    run(fbc + ["-w", "all", "-c", str(real_wrapper), "-o",
               str(source_directory / "check-real.o")], cwd=source_directory)
    assert not list(source_directory.glob(
        "real-binding.bi.c2fb-preprocessed-*.i.include-stubs"))


def check_generic_header_empty_macros(converter, fbc, work):
    # Preserve ordinary empty macros, while fbfrog's reserved-define option
    # removes only empty reserved object-like forms.
    source_directory = work / "generic-header-empty-macros"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "#define EMPTY\n"
        "#define __EMPTY\n"
        "#define _Upper\n"
        "#define _lower\n"
        "#define EMPTY_CALL()\n"
        "#define __EMPTY_CALL()\n"
        "#define EMPTY_PARAM(value)\n"
    )

    for label, options in (("all", []), ("reserved-removed", ["-removeEmptyReservedDefines"])):
        binding = source_directory / f"{label}.bi"
        summary = run([
            converter, "generic-header", str(header), str(binding), "cc", *options,
        ])
        generated = binding.read_text()
        expected_count = 7 if label == "all" else 5
        assert f"{expected_count} empty macros" in summary, summary
        assert "#define c2fb_EMPTY\n" in generated
        assert re.search(r"^#define c2fb_EMPTY_CALL_?\(\)$", generated, re.M)
        assert re.search(r"^#define c2fb___EMPTY_CALL_?\(\)$", generated, re.M)
        assert "#define c2fb_EMPTY_PARAM(c2fb_macro_arg_0)\n" in generated
        assert "#define c2fb__lower\n" in generated
        if label == "all":
            assert "#define c2fb___EMPTY\n" in generated
            assert "#define c2fb__Upper\n" in generated
        else:
            assert "#define c2fb___EMPTY\n" not in generated
            assert "#define c2fb__Upper\n" not in generated

        wrapper = source_directory / f"check-{label}.bas"
        wrapper.write_text(f'#include once "{label}.bi"\n')
        run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
                   str(source_directory / f"check-{label}.o")], cwd=source_directory)


