def check_generic_header_msvc_integer_cast_macros(converter, fbc, work):
    # Translate MSVC fixed-width integer cast spellings using their C widths.
    source_directory = work / "generic-header-msvc-integer-cast-macros"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "#define I8 ((__int8)7)\n"
        "#define U8 ((unsigned __int8)7)\n"
        "#define I16 ((__int16)7)\n"
        "#define U16 ((unsigned __int16)7)\n"
        "#define I32 ((__int32)7)\n"
        "#define U32 ((unsigned __int32)7)\n"
        "#define I64 ((__int64)7)\n"
        "#define U64 ((unsigned __int64)7)\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    for name, target in (
        ("I8", "Byte"), ("U8", "UByte"),
        ("I16", "Short"), ("U16", "UShort"),
        ("I32", "Long"), ("U32", "ULong"),
        ("I64", "LongInt"), ("U64", "ULongInt"),
    ):
        assert f"Const c2fb_{name} = Cast({target}, 7)" in generated, generated

    wrapper = source_directory / "check.bas"
    checks = "".join(
        f"If c2fb_{name} <> 7 Then End {index}\n"
        for index, name in enumerate(
            ("I8", "U8", "I16", "U16", "I32", "U32", "I64", "U64"),
            1,
        )
    )
    wrapper.write_text(f'#include once "probe.bi"\n{checks}')
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_numeric_suffix_macros(converter, fbc, work):
    # Map C unsigned-long and floating suffixes to FreeBASIC's typed literals.
    source_directory = work / "generic-header-numeric-suffix-macros"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "#define DECIMAL_UL 1ul\n"
        "#define OCTAL_UL 01ul\n"
        "#define HEX_UL 0x1ul\n"
        "#define SINGLE_INT_SUFFIX 1f\n"
        "#define DOUBLE_INT_SUFFIX 1d\n"
        "#define MALFORMED_HEX_PREFIX 0x\n"
        "#define DOUBLE_SUFFIX 1.0d\n"
        "#define SINGLE_SUFFIX 1.0f\n"
        "#define INT8_SUFFIX 1i8\n"
        "#define INT16_SUFFIX 1i16\n"
        "#define INT32_SUFFIX 1i32\n"
        "#define INT64_SUFFIX 1i64\n"
        "#define UINT8_SUFFIX 1ui8\n"
        "#define UINT16_SUFFIX 1ui16\n"
        "#define UINT32_SUFFIX 1ui32\n"
        "#define UINT64_SUFFIX 1ui64\n"
        "#define BINARY_PREFIX 0b\n"
        "#define BINARY_ZERO 0b0\n"
        "#define BINARY_ONE 0b1\n"
        "#define BINARY_BITS 0b10100110\n"
        "#define BINARY_UPPER 0B0\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert "Const c2fb_DECIMAL_UL = Cast(CULong, 1)" in generated, generated
    assert "Const c2fb_OCTAL_UL = Cast(CULong, &O1)" in generated, generated
    assert "Const c2fb_HEX_UL = Cast(CULong, &H1)" in generated, generated
    assert "Const c2fb_SINGLE_INT_SUFFIX As Single = 1!" in generated, generated
    assert "Const c2fb_DOUBLE_INT_SUFFIX As Double = 1#" in generated, generated
    assert "Const c2fb_MALFORMED_HEX_PREFIX = &h" in generated, generated
    assert "Const c2fb_DOUBLE_SUFFIX As Double = 1.0#" in generated, generated
    assert "Const c2fb_SINGLE_SUFFIX As Single = 1.0!" in generated, generated
    for suffix_name in ("INT8", "INT16", "INT32", "UINT8", "UINT16", "UINT32"):
        assert f"Const c2fb_{suffix_name}_SUFFIX = 1" in generated, generated
    assert "Const c2fb_INT64_SUFFIX = 1ll" in generated, generated
    assert "Const c2fb_UINT64_SUFFIX = 1ull" in generated, generated
    assert "Const c2fb_BINARY_PREFIX = &b" in generated, generated
    assert "Const c2fb_BINARY_ZERO = &b0" in generated, generated
    assert "Const c2fb_BINARY_ONE = &b1" in generated, generated
    assert "Const c2fb_BINARY_BITS = &b10100110" in generated, generated
    assert "Const c2fb_BINARY_UPPER = &b0" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "If c2fb_DECIMAL_UL <> 1 Then End 1\n"
        "If c2fb_OCTAL_UL <> 1 Then End 2\n"
        "If c2fb_HEX_UL <> 1 Then End 3\n"
        "If c2fb_SINGLE_INT_SUFFIX <> 1.0 Then End 4\n"
        "If c2fb_DOUBLE_INT_SUFFIX <> 1.0 Then End 5\n"
        "If c2fb_DOUBLE_SUFFIX <> 1.0 Then End 6\n"
        "If c2fb_SINGLE_SUFFIX <> 1.0 Then End 7\n"
        "If c2fb_MALFORMED_HEX_PREFIX <> 0 Then End 8\n"
        "If c2fb_INT8_SUFFIX <> 1 Then End 9\n"
        "If c2fb_INT16_SUFFIX <> 1 Then End 10\n"
        "If c2fb_INT32_SUFFIX <> 1 Then End 11\n"
        "If c2fb_INT64_SUFFIX <> 1 Then End 12\n"
        "If c2fb_UINT8_SUFFIX <> 1 Then End 13\n"
        "If c2fb_UINT16_SUFFIX <> 1 Then End 14\n"
        "If c2fb_UINT32_SUFFIX <> 1 Then End 15\n"
        "If c2fb_UINT64_SUFFIX <> 1 Then End 16\n"
        "If c2fb_BINARY_ZERO <> 0 Then End 17\n"
        "If c2fb_BINARY_ONE <> 1 Then End 18\n"
        "If c2fb_BINARY_BITS <> &b10100110 Then End 19\n"
        "If c2fb_BINARY_UPPER <> 0 Then End 20\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


