def check_generic_header_redundant_callback_objects(converter, fbc, work):
    # Redundant C grouping must not hide pointer-to-function object declarators.
    source_directory = work / "generic-header-redundant-callback-objects"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "extern int (*callback)(int value);\n"
        "extern void (*callback_void)(void);\n"
        "extern int *(*callback_with_ptr_return)(int value);\n"
        "extern void (*callback_nested)(void (*inner)(int value));\n"
        "extern void (*callback0)(void);\n"
        "extern void ((*callback1))(void);\n"
        "extern void (((*callback2)))(void);\n"
        "extern void (* (callback3) )(void);\n"
        "extern void ((* (callback4) )) (void);\n"
        "extern void (((* (callback5) ))) (void);\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "10 external objects" in summary, summary
    assert 'Extern c2fb_callback Alias "callback" As Function CDecl(ByVal arg0 As Long) As Long' in generated
    assert 'Extern c2fb_callback_nested Alias "callback_nested" As Sub CDecl(ByVal arg0 As Sub CDecl(ByVal arg0 As Long))' in generated
    for callback_index in range(6):
        name = f"callback{callback_index}"
        assert f'Extern c2fb_{name} Alias "{name}" As Sub CDecl()' in generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "probe.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check.o")], cwd=source_directory)


def check_generic_header_function_pointer_type_macro(converter, fbc, work):
    # A function-pointer type macro is a declaration-like macro, not a value.
    source_directory = work / "generic-header-function-pointer-type-macro"
