    run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert re.search(
        r'Declare Sub c2fb_c2fbTakeVaList CDecl Alias "c2fbTakeVaList" '
        r'\(ByVal arg0 As Const ZString Ptr, ByVal arg1 As Cva_List\)',
        generated,
    ), generated
    wrapper = source_directory / "check-binding.bas"
    wrapper.write_text('#include once "probe.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check-binding.o")], cwd=source_directory)

    body_source = source_directory / "va-list-body.c"
