def check_generic_header_fbfrog_rename_and_reserved_define_options(
        converter, fbc, work):
    # Keep two fbfrog command spellings usable in existing binding scripts.
    source_directory = work / "generic-header-fbfrog-options"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "#define A 1\n"
        "#define __EMPTY\n"
        "#define _Upper 4\n"
        "#define _lower 2\n"
    )
    binding = source_directory / "probe.bi"
    run([
        converter, "generic-header", str(header), str(binding), "cc",
        "-rename_", "A", "-removeEmptyReservedDefines",
    ])
    generated = binding.read_text()
    constant_names = set(re.findall(r"^Const\s+(\w+)", generated, re.M))
    assert "A_" in constant_names, generated
    assert "c2fb___EMPTY" not in constant_names, generated
    assert "c2fb__Upper" in constant_names, generated
    assert "c2fb__lower" in constant_names, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "probe.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check.o")], cwd=source_directory)

    keyword_header = source_directory / "keyword_renames.h"
    keyword_header.write_text(
        "typedef signed char c2fbByteType;\n"
        "struct c2fbRecordTag { int value; };\n"
        "int c2fbKeywordProc(c2fbByteType value);\n"
        "extern int c2fbKeywordObject;\n"
        "#define c2fbKeywordMacro 3\n"
    )
    keyword_binding = source_directory / "keyword_renames.bi"
    run([
        converter, "generic-header", str(keyword_header),
        str(keyword_binding), "cc",
        "--rename-typedef=c2fbByteType=Byte",
        "--rename-tag=c2fbRecordTag=Type",
        "--rename-proc=c2fbKeywordProc=If",
        "--rename=c2fbKeywordObject=Get",
        "--rename-define=c2fbKeywordMacro=While",
    ])
    keyword_text = keyword_binding.read_text()
    for declaration in (
        "Type Byte_ As Byte",
        "Type Type_ As _c2fb_record_Type_",
        'Declare Function If_ CDecl Alias "c2fbKeywordProc"',
        'Extern Get_ Alias "c2fbKeywordObject" As Long',
        "Const While_ = 3",
    ):
        assert declaration in keyword_text, keyword_text
    keyword_wrapper = source_directory / "keyword_renames_check.bas"
    keyword_wrapper.write_text(
        '#include once "keyword_renames.bi"\n'
        "Dim value As Byte_ = 7\n"
        "Type KeywordUse\n"
        "    value As Byte_\n"
        "End Type\n"
    )
    run(fbc + ["-w", "all", "-c", str(keyword_wrapper), "-o",
               str(source_directory / "keyword_renames_check.o")],
        cwd=source_directory)


