def check_generic_header_ordinal_removals(converter, fbc, work):
    # Match fbfrog's occurrence semantics across function declarations and
    # preprocessor definitions while preserving earlier macro bodies on -remove2nd.
    source_directory = work / "generic-header-ordinal-removals"
    source_directory.mkdir()
    remove_first_header = source_directory / "remove_first.h"
    remove_first_header.write_text(
        "#define A(x) x\n"
        "#define A(x) x\n"
        "void f2(void);\n"
        "void f(void);\n"
        "int c2fbSwitch(void);\n"
        "double c2fbSwitch(void);\n"
        "#define f() f2()\n"
    )
    remove_first_binding = source_directory / "remove_first.bi"
    run([
        converter, "generic-header", str(remove_first_header),
        str(remove_first_binding), "cc", "-remove1st", "A", "--remove-first=f",
        "--remove-first=c2fbSwitch",
    ])
    first_output = remove_first_binding.read_text()
    assert "Declare Sub c2fb_f2" in first_output
    assert "Declare Sub c2fb_f CDecl" not in first_output
    assert "#define c2fb_A(" in first_output
    assert "#define c2fb_f()" in first_output
    switch_declarations = [
        line for line in first_output.splitlines()
        if "Declare Function c2fb_c2fbSwitch" in line
    ]
    assert len(switch_declarations) == 1, switch_declarations
    assert "As Double" in switch_declarations[0], switch_declarations

    remove_repeated_header = source_directory / "remove_repeated.h"
    remove_repeated_header.write_text(
        "#define A(x) 1\n"
        "#define A(x) 2\n"
        "#define B 1\n"
        "#define B 2\n"
        "#define B 3\n"
        "int c2fbSwitchBack(void);\n"
        "double c2fbSwitchBack(void);\n"
        "int c2fbBoth(void);\n"
        "double c2fbBoth(void);\n"
        "char c2fbBoth(void);\n"
    )
    remove_repeated_binding = source_directory / "remove_repeated.bi"
    run([
        converter, "generic-header", str(remove_repeated_header),
        str(remove_repeated_binding), "cc", "--remove-repeated=A", "-remove2nd", "B",
        "--remove-repeated=c2fbSwitchBack", "-remove1st", "c2fbBoth",
        "-remove2nd", "c2fbBoth",
    ])
    repeated_output = remove_repeated_binding.read_text()
    assert re.search(r"#define c2fb_A\([^\n]*\) 1", repeated_output)
    assert "Const c2fb_B = 1" in repeated_output
    assert "Const c2fb_B = 2" not in repeated_output
    assert "Const c2fb_B = 3" not in repeated_output
    back_declarations = [
        line for line in repeated_output.splitlines()
        if "Declare Function c2fb_c2fbSwitchBack" in line
    ]
    assert len(back_declarations) == 1, back_declarations
    assert "As Long" in back_declarations[0], back_declarations
    both_declarations = [
        line for line in repeated_output.splitlines()
        if "Declare Function c2fb_c2fbBoth" in line
    ]
    assert len(both_declarations) == 1, both_declarations
    assert "As Double" in both_declarations[0], both_declarations

    inline_occurrence_header = source_directory / "inline_occurrence.h"
    inline_occurrence_header.write_text(
        "inline int c2fbInlineOccurrence(int value);\n"
        "inline int c2fbInlineOccurrence(int value) { return value + 1; }\n"
    )
    inline_occurrence_binding = source_directory / "inline_occurrence.bi"
    run([
        converter, "generic-header", str(inline_occurrence_header),
        str(inline_occurrence_binding), "cc",
        "--remove-repeated=c2fbInlineOccurrence",
    ])
    inline_occurrence_output = inline_occurrence_binding.read_text()
    assert len([
        line for line in inline_occurrence_output.splitlines()
        if line.startswith("Declare Function c2fb_c2fbInlineOccurrence")
    ]) == 1, inline_occurrence_output
    assert "#define c2fb_c2fbInlineOccurrence(" not in inline_occurrence_output, \
        inline_occurrence_output
    inline_occurrence_wrapper = source_directory / "check-inline-occurrence.bas"
    inline_occurrence_wrapper.write_text(
        '#include once "inline_occurrence.bi"\n')
    run(fbc + ["-w", "all", "-c", str(inline_occurrence_wrapper), "-o",
               str(source_directory / "check-inline-occurrence.o")],
        cwd=source_directory)

    inline_first_binding = source_directory / "inline_first.bi"
    run([
        converter, "generic-header", str(inline_occurrence_header),
        str(inline_first_binding), "cc",
        "--remove-first=c2fbInlineOccurrence",
    ])
    inline_first_output = inline_first_binding.read_text()
    assert "Declare Function c2fb_c2fbInlineOccurrence" not in inline_first_output, \
        inline_first_output
    assert len([
        line for line in inline_first_output.splitlines()
        if line.startswith("#define c2fb_c2fbInlineOccurrence(")
    ]) == 1, inline_first_output
    inline_first_wrapper = source_directory / "check-inline-first.bas"
    inline_first_wrapper.write_text(
        '#include once "inline_first.bi"\n'
        "If c2fb_c2fbInlineOccurrence(4) <> 5 Then End 1\n")
    inline_first_executable = source_directory / "check-inline-first"
    run(fbc + ["-w", "all", str(inline_first_wrapper), "-x",
               str(inline_first_executable)], cwd=source_directory)
    run([str(inline_first_executable)], cwd=source_directory)

    for name in ("first", "repeated"):
        wrapper = source_directory / f"check-{name}.bas"
        binding_name = "remove_first.bi" if name == "first" else "remove_repeated.bi"
        wrapper.write_text(f'#include once "{binding_name}"\n')
        run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
                   str(source_directory / f"check-{name}.o")], cwd=source_directory)

    declarations_header = source_directory / "remove_declarations.h"
    declarations_header.write_text(
        "extern int c2fbObject;\n"
        "extern double c2fbObject;\n"
        "extern int c2fbFirstObject, c2fbSecondObject;\n"
        "typedef int c2fbType;\n"
        "typedef double c2fbType;\n"
        "typedef int c2fbFirstType, c2fbSecondType;\n"
        "typedef struct ProbeRecord { int value; } ProbeRecord;\n"
        "enum ProbeMode { PROBE_A = 1, PROBE_B, PROBE_C = PROBE_A + 4 };\n"
        "#define PROBE_A_PLUS (PROBE_A + 5)\n"
    )
    declarations_binding = source_directory / "remove_declarations.bi"
    run([
        converter, "generic-header", str(declarations_header),
        str(declarations_binding), "cc",
        "-remove1st", "c2fbObject", "-remove1st", "c2fbFirstObject",
        "-remove1st", "c2fbType", "-remove1st", "c2fbFirstType",
        "-remove1st", "ProbeRecord", "-remove1st", "PROBE_A",
    ])
    declarations_output = declarations_binding.read_text()
    assert 'Extern c2fb_c2fbObject Alias "c2fbObject" As Double' in declarations_output
    assert "c2fb_c2fbFirstObject" not in declarations_output
    assert "c2fb_c2fbSecondObject" in declarations_output
    assert "Type c2fb_c2fbType As Double" in declarations_output
    assert "c2fb_c2fbFirstType" not in declarations_output
    assert "c2fb_c2fbSecondType" in declarations_output
    assert "c2fb_ProbeRecord" not in declarations_output
    assert not re.search(r"^Const c2fb_PROBE_A As", declarations_output, re.M)
    assert "Const c2fb_PROBE_B As Long = 2" in declarations_output
    assert "Const c2fb_PROBE_C As Long = 5" in declarations_output
    assert re.search(r"^Const c2fb_PROBE_A_PLUS = 1\+\s*5$", declarations_output, re.M)
    declarations_wrapper = source_directory / "check-declarations.bas"
    declarations_wrapper.write_text('#include once "remove_declarations.bi"\n')
    run(fbc + ["-w", "all", "-c", str(declarations_wrapper), "-o",
               str(source_directory / "check-declarations.o")],
        cwd=source_directory)


def check_generic_body_profile_timings(converter, work):
    # Optional body-stage timings must not change generated candidates.
    source_directory = work / "generic-body-profile-timings"
    source_directory.mkdir()
    source = source_directory / "probe.c"
    source.write_text(
        "enum ProbeMode { PROBE_FIRST = 1, PROBE_SECOND = PROBE_FIRST + 1 };\n"
        "int c2fbProbe(int value) { return value + PROBE_SECOND; }\n"
    )
    candidate = source_directory / "probe_candidates.bas"
    normal_output = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc",
    ])
    generated = candidate.read_bytes()
    assert "generic-body stage timing:" not in normal_output, normal_output

    timed_output = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "--profile-timings", "cc",
    ])
    for stage in (
        "FreeBASIC project catalog",
        "C declaration scan",
        "initial enum indexing",
        "type alias and record indexing",
        "enum resolution after aliases",
        "procedure and object indexing",
        "enum resolution after object extents",
        "function scanning and lowering",
        "function c2fbProbe",
        "candidate dependency filtering",
        "candidate output",
    ):
        assert f"generic-body stage timing: {stage} completed in " in timed_output, timed_output
    assert candidate.read_bytes() == generated

    excluded_source = source_directory / "excluded.c"
    excluded_source.write_text(
        "int c2fbExcluded(int value) { return value + 3; }\n"
    )
    excluded_candidate = source_directory / "excluded_candidates.bas"
    excluded_output = run([
        converter, "translate-simple-generic-c", str(excluded_source),
        str(excluded_candidate), "--exclude-proc=c2fbExcluded",
        "--profile-timings", "cc",
    ])
    assert "generic-body stage timing: excluded function c2fbExcluded" \
        in excluded_output, excluded_output
    assert "generic-body stage timing: function c2fbExcluded" \
        not in excluded_output, excluded_output
    assert "excluded by --exclude-proc" in excluded_candidate.read_text()


def check_generic_body_enum_constants(converter, fbc, work):
    # Resolve known enum values, including unparenthesized shifts, in C bodies.
    source_directory = work / "generic-body-enum-constants"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef enum ProbeMode {\n"
        "    PROBE_ZERO = 0,\n"
        "    PROBE_FIRST,\n"
        "    PROBE_SHIFT = PROBE_FIRST + 4,\n"
        "    PROBE_AFTER,\n"
        "    PROBE_NEGATIVE = -2,\n"
        "    PROBE_AFTER_NEGATIVE,\n"
        "    PROBE_UNSUPPORTED = 1 << 3,\n"
        "} ProbeMode;\n"
    )
    source = source_directory / "probe.c"
    source.write_text(
        '#include "probe.h"\n'
        "int c2fbEnumArithmetic(int value) { return value + PROBE_SHIFT; }\n"
        "int c2fbEnumImplicit(void) { return PROBE_AFTER; }\n"
        "int c2fbEnumNegative(void) { return PROBE_NEGATIVE; }\n"
        "int c2fbEnumAfterNegative(void) { return PROBE_AFTER_NEGATIVE; }\n"
        "int c2fbEnumShadow(int PROBE_FIRST) { return PROBE_FIRST; }\n"
        "int c2fbEnumUnsupported(void) { return PROBE_UNSUPPORTED; }\n"
    )
    binding = source_directory / "probe.bi"
    run([converter, "generic-header", str(header), str(binding), "cc"])
    candidate = source_directory / "probe_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
        f"-I{source_directory}", f"--fb-source-directory={source_directory}",
    ])
    assert "translated 6 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "c2fbEnumUnsupported" in procedure_names(generated)

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        '#include once "probe_candidates.bas"\n'
        "If c2fbEnumArithmetic(3) <> 8 Then End 1\n"
        "If c2fbEnumImplicit() <> 6 Then End 2\n"
        "If c2fbEnumNegative() <> -2 Then End 3\n"
        "If c2fbEnumAfterNegative() <> -1 Then End 4\n"
        "If c2fbEnumShadow(37) <> 37 Then End 5\n"
        "If c2fbEnumUnsupported() <> 8 Then End 6\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_body_typeof_compound_literal_generic_selection(
    converter, fbc, cc, work
):
    # __typeof__ compound literals in a _Generic control need only their type.
    source_directory = work / "generic-body-typeof-compound-literal-generic"
    source_directory.mkdir()
    source = source_directory / "generic.c"
    source.write_text(
        "int c2fbGenericTypeofExpression(int value) {\n"
        "    return _Generic((__typeof__(value)){0},\n"
        "                    int: value + 3, default: -1);\n"
        "}\n"
        "int c2fbGenericTypeofTypeName(int value) {\n"
        "    return _Generic((__typeof__(unsigned long)){0},\n"
        "                    unsigned long: value + 9, default: -1);\n"
        "}\n"
    )
    candidate = source_directory / "generic_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        cc[0],
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=gnu11", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "generic_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x",
               str(converted_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for name in ("c2fbGenericTypeofExpression", "c2fbGenericTypeofTypeName"):
        reference_function = getattr(reference, name)
        converted_function = getattr(converted, name)
        for function in (reference_function, converted_function):
            function.argtypes = [ctypes.c_int]
            function.restype = ctypes.c_int
        for value in (-5, 0, 14):
            assert converted_function(value) == reference_function(value)


def check_generic_body_nested_bitfields(converter, fbc, work):
    # Generated FreeBASIC bindings represent C bitfields as named fields with
    # widths. Body conversion must find those nested fields for reads and writes.
    source_directory = work / "generic-body-nested-bitfields"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef struct ProbeHeader {\n"
        "    union {\n"
        "        struct {\n"
        "            unsigned short bpp:3;\n"
        "            unsigned short width:13;\n"
        "            unsigned short height;\n"
        "        } old;\n"
        "        unsigned int type;\n"
        "    };\n"
        "    unsigned int bpp;\n"
        "} ProbeHeader;\n"
    )
    source = source_directory / "probe.c"
    source.write_text(
        '#include "probe.h"\n'
        "void c2fbSetOldBpp(ProbeHeader *header, unsigned int value) {\n"
        "    header->old.bpp = value;\n"
        "}\n"
        "unsigned short c2fbReadOldBpp(ProbeHeader *header) {\n"
        "    return header->old.bpp;\n"
        "}\n"
        "void c2fbSetOldWidth(ProbeHeader *header, unsigned int value) {\n"
        "    header->old.width = value;\n"
        "}\n"
        "unsigned short c2fbReadOldWidth(ProbeHeader *header) {\n"
        "    return header->old.width;\n"
        "}\n"
        "unsigned short c2fbPostIncrementOldBpp(ProbeHeader *header) {\n"
        "    return header->old.bpp++;\n"
        "}\n"
    )
    binding = source_directory / "probe.bi"
    run([converter, "generic-header", str(header), str(binding), "cc"])
    candidate = source_directory / "probe_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
        f"-I{source_directory}", f"--fb-source-directory={source_directory}",
    ])
    assert "translated 5 simple functions; skipped 0" in summary, summary

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        '#include once "probe_candidates.bas"\n'
        "Dim header As c2fb_ProbeHeader\n"
        "c2fbSetOldBpp(@header, 15)\n"
        "If c2fbReadOldBpp(@header) <> 7 Then End 1\n"
        "c2fbSetOldWidth(@header, 65535)\n"
        "If c2fbReadOldWidth(@header) <> 8191 Then End 2\n"
        "If c2fbPostIncrementOldBpp(@header) <> 7 Then End 3\n"
        "If c2fbReadOldBpp(@header) <> 0 Then End 4\n"
        "If c2fbReadOldWidth(@header) <> 8191 Then End 5\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), "-x", str(executable)],
            cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_body_signed_bitfields(converter, fbc, work):
    # Narrow signed C bitfields need explicit sign extension in generated code;
    # FreeBASIC's named bitfield load exposes the stored low bits.
    source_directory = work / "generic-body-signed-bitfields"
    source_directory.mkdir()
    header = source_directory / "signed_bits.h"
    header.write_text(
        "typedef struct C2fbSignedBits {\n"
        "    signed int value : 5;\n"
        "    signed int fullWidth : 32;\n"
        "} C2fbSignedBits;\n"
    )
    source = source_directory / "signed_bits.c"
    source.write_text(
        '#include "signed_bits.h"\n'
        "int c2fbSignedSetRead(C2fbSignedBits *bits, int value) {\n"
        "    bits->value = value;\n"
        "    return bits->value;\n"
        "}\n"
        "int c2fbSignedRead(C2fbSignedBits *bits) {\n"
        "    return bits->value;\n"
        "}\n"
        "int c2fbSignedAdd(C2fbSignedBits *bits, int value) {\n"
        "    bits->value += value;\n"
        "    return bits->value;\n"
        "}\n"
        "int c2fbSignedFullWidth(C2fbSignedBits *bits, int value) {\n"
        "    bits->fullWidth = value;\n"
        "    return bits->fullWidth;\n"
        "}\n"
        "int c2fbSignedPostIncrement(C2fbSignedBits *bits) {\n"
        "    return bits->value++;\n"
        "}\n"
        "int c2fbSignedPreDecrement(C2fbSignedBits *bits) {\n"
        "    return --bits->value;\n"
        "}\n"
    )

    binding = source_directory / "signed_bits.bi"
    run([converter, "generic-header", str(header), str(binding), "cc"])
    candidate = source_directory / "signed_bits_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
        f"-I{source_directory}", f"--fb-source-directory={source_directory}",
    ])
    assert "translated 6 simple functions; skipped 0" in summary, summary

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "signed_bits.bi"\n'
        '#include once "signed_bits_candidates.bas"\n'
        "Dim bits As c2fb_C2fbSignedBits\n"
        "If c2fbSignedSetRead(@bits, 31) <> -1 Then End 1\n"
        "If c2fbSignedRead(@bits) <> -1 Then End 2\n"
        "If c2fbSignedSetRead(@bits, -17) <> 15 Then End 3\n"
        "If c2fbSignedSetRead(@bits, 14) <> 14 Then End 4\n"
        "If c2fbSignedAdd(@bits, 2) <> -16 Then End 5\n"
        "If c2fbSignedAdd(@bits, -2) <> 14 Then End 6\n"
        "If c2fbSignedFullWidth(@bits, -2147483648) <> -2147483648 Then End 7\n"
        "If c2fbSignedFullWidth(@bits, 2147483647) <> 2147483647 Then End 8\n"
        "If c2fbSignedFullWidth(@bits, -1) <> -1 Then End 9\n"
        "If c2fbSignedSetRead(@bits, 15) <> 15 Then End 10\n"
        "If c2fbSignedPostIncrement(@bits) <> 15 Then End 11\n"
        "If c2fbSignedRead(@bits) <> -16 Then End 12\n"
        "If c2fbSignedSetRead(@bits, -16) <> -16 Then End 13\n"
        "If c2fbSignedPreDecrement(@bits) <> 15 Then End 14\n"
        "If c2fbSignedRead(@bits) <> 15 Then End 15\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), "-x", str(executable)],
            cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_body_recursive_freebasic_bindings(converter, fbc, work):
    # Nested FreeBASIC interface paths can supply call signatures and includes.
    source_directory = work / "generic-body-recursive-bindings"
    source_directory.mkdir()
    bindings = source_directory / "bindings"
    nested_directory = bindings / "crt"
    nested_directory.mkdir(parents=True)
    generated_directory = bindings / "build"
    generated_directory.mkdir()
    (nested_directory / "widget.bi").write_text(
        "#ifndef C2FB_WIDGET_BI\n"
        "#define C2FB_WIDGET_BI\n"
        'Declare Function c2fbNestedDeclaration CDecl Alias "c2fbNestedDeclaration" '
        "(ByVal value As Long) As Long\n"
        "#endif\n"
    )
    (generated_directory / "generated.bi").write_text(
        'Declare Function c2fbBuildOnly CDecl Alias "c2fbBuildOnly" '
        "(ByVal value As Long) As Long\n"
    )
    source = source_directory / "caller.c"
    source.write_text(
        "int c2fbNestedDeclaration(int value);\n"
        "int c2fbBuildOnly(int value);\n"
        "int c2fbNestedCaller(int value) {\n"
        "    return c2fbNestedDeclaration(value) + c2fbBuildOnly(value);\n"
        "}\n"
    )

    flat_candidate = source_directory / "flat_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(flat_candidate), "cc", f"--fb-source-directory={bindings}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    flat_output = flat_candidate.read_text()
    assert '"crt/widget.bi"' not in flat_output
    assert 'Declare Function c2fb_external_c2fbNestedDeclaration' in flat_output

    recursive_candidate = source_directory / "recursive_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(recursive_candidate), "cc",
        f"--fb-source-directory={bindings}", "--fb-source-recursive",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    recursive_output = recursive_candidate.read_text()
    assert '#include once "crt/widget.bi"' in recursive_output
    assert '"build/generated.bi"' not in recursive_output
    assert 'Declare Function c2fbNestedDeclaration' not in recursive_output

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "recursive_candidates.bas"\n')
    run(fbc + ["-w", "all", "-i", str(bindings), "-c", str(wrapper)],
        cwd=source_directory)


def check_generic_body_header_function_definitions(converter, fbc, work):
    # A header supplied as the root can contribute ordinary function bodies,
    # not only inline helpers included from another C file.
    source_directory = work / "generic-body-header-functions"
    source_directory.mkdir()
    header = source_directory / "function_bodies.h"
    header.write_text(
        "void c2fbHeaderBodyEmpty(void) {}\n"
        "void c2fbHeaderBodyPrint(void) { int i = 1; printf(\"%i\\n\", i); }\n"
        "int c2fbHeaderBodyShift(int value) {\n"
        "    return value << 3 & 0xFF;\n"
        "    return 0;\n"
        "}\n"
        "void c2fbHeaderBodyReturn(void) { return; }\n"
    )
    candidate = source_directory / "header_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(header), str(candidate), "cc",
    ])
    assert "translated 4 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    for function_name in (
        "c2fbHeaderBodyEmpty", "c2fbHeaderBodyPrint",
        "c2fbHeaderBodyShift", "c2fbHeaderBodyReturn",
    ):
        assert function_name in generated, f"Header body {function_name} is missing"

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "crt/stdio.bi"\n'
        '#include once "header_candidates.bas"\n'
    )
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check.o")], cwd=source_directory)


def check_glibc_profile_file_offset_types(converter, fbc, work):
    # The Linux x86-64 profile must reuse FreeBASIC's CRT size and offset types.
    if platform.system() != "Linux" or platform.machine().lower() not in ("x86_64", "amd64"):
        return
    source_directory = work / "glibc-profile-types"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "#include <sys/types.h>\n"
        "#include <stdint.h>\n"
        "#include <pthread.h>\n"
        "typedef off_t fb_off_t;\n"
        "struct ProbeOffsets { ssize_t count; fb_off_t fileOffset; "
        "intptr_t signedPointer; uintptr_t unsignedPointer; "
        "pthread_t threadHandle; };\n"
    )
    binding = source_directory / "probe.bi"
    profile = Path(__file__).resolve().parents[1] / "profiles" / \
        "freebasic-linux-glibc-x86_64.rsp"
    run([
        converter, "generic-header", str(header), str(binding), "cc",
        f"@{profile}", "--emit-source=probe.h",
    ])
    generated = binding.read_text()
    assert "count As ssize_t" in generated
    assert "fileOffset As off_t" in generated
    assert "signedPointer As CLong" in generated
    assert "unsignedPointer As CULong" in generated
    assert "threadHandle As CULong" in generated
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "probe.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper)], cwd=source_directory)

    source = source_directory / "probe.c"
    source.write_text(
        '#include "probe.h"\n'
        "ssize_t c2fbProbeSsize(ssize_t value) { return value + 1; }\n"
        "fb_off_t c2fbProbeOffset(fb_off_t value) { return value + 1; }\n"
        "ssize_t c2fbSsizeAssignment(void) { ssize_t value; value = 1; return value; }\n"
        "intptr_t c2fbProbeIntPtr(void *value) { return (intptr_t)value; }\n"
        "uintptr_t c2fbProbeUIntPtr(void *value) { return (uintptr_t)value; }\n"
        "void *c2fbProbePointerFromUIntPtr(uintptr_t value) { return (void *)value; }\n"
        "pthread_t c2fbProbeThread(pthread_t value) { return value; }\n"
    )
    candidate = source_directory / "probe_candidates.bas"
    body_profile = Path(__file__).resolve().parents[1] / "profiles" / \
        "freebasic-linux-glibc-x86_64-body.rsp"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
        f"-I{source_directory}", f"--fb-source-directory={source_directory}",
        f"@{body_profile}",
    ])
    assert "translated 7 simple functions; skipped 0" in summary, summary
    generated_body = candidate.read_text()
    assert "Cast(c2fb_size_t, arg0)" in generated_body, generated_body
    assert "CPtr(Any Ptr, Cast(c2fb_size_t, arg0))" in generated_body, generated_body
    body_check = source_directory / "body_check.bas"
    body_check.write_text(
        '#include once "probe.bi"\n'
        '#include once "probe_candidates.bas"\n'
        "If c2fbProbeSsize(-2) <> -1 Then End 1\n"
        "If c2fbProbeOffset(8) <> 9 Then End 2\n"
        "If c2fbSsizeAssignment() <> 1 Then End 3\n"
        "If c2fbProbeIntPtr(CPtr(Any Ptr, 0)) <> 0 Then End 4\n"
        "If c2fbProbeUIntPtr(CPtr(Any Ptr, 0)) <> 0 Then End 5\n"
        "If c2fbProbeThread(Cast(c2fb_c_ulong, 37)) <> 37 Then End 6\n"
        "Dim pointerProbe As Long\n"
        "Dim pointerAddress As ULongInt = Cast(ULongInt, @pointerProbe)\n"
        "'' Require a high address so truncating it to Integer cannot pass.\n"
        "If pointerAddress <= &HFFFFFFFFULL Then End 7\n"
        "If Cast(ULongInt, c2fbProbeIntPtr(@pointerProbe)) <> pointerAddress Then End 8\n"
        "If Cast(ULongInt, c2fbProbeUIntPtr(@pointerProbe)) <> pointerAddress Then End 9\n"
        "If c2fbProbePointerFromUIntPtr(Cast(CULong, pointerAddress)) <> @pointerProbe Then End 10\n"
    )
    executable = source_directory / "body_check"
    run(fbc + ["-w", "all", str(body_check), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_body_included_inline_functions(converter, fbc, work):
    # Header inline bodies use the same statement translator as source bodies
    # when the caller opts into that header workflow.
    source_directory = work / "generic-body-header-inlines"
    source_directory.mkdir()
    header = source_directory / "inline.h"
    header.write_text(
        "static __inline__ int c2fbHeaderClamp(int value) {\n"
        "    if (value < 0) return -value;\n"
        "    return value + 3;\n"
        "}\n"
        "static __inline__ int c2fbWideNul(void) { return L'\\0'; }\n"
    )
    source = source_directory / "caller.c"
    source.write_text(
        '#include "inline.h"\n'
        "int c2fbInlineCaller(int value) {\n"
        "    return c2fbHeaderClamp(value);\n"
        "}\n"
    )
    candidate = source_directory / "caller_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
        f"-I{source_directory}", "--include-header-inline-bodies",
    ])
    assert "translated 3 simple functions; skipped 0" in summary, summary
    definitions = re.findall(
        r"^(?:Private )?(?:Function|Sub) (\w+)", candidate.read_text(), re.M)
    assert len(definitions) == 3, f"Expected both header inline bodies and caller: {definitions}"
    caller = next(name for name in definitions if "InlineCaller" in name)
    wide_nul = next(name for name in definitions if "WideNul" in name)

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "caller_candidates.bas"\n'
        f"If {caller}(-3) <> 3 Then End 1\n"
        f"If {caller}(4) <> 7 Then End 2\n"
        f"If {wide_nul}() <> 0 Then End 3\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_body_external_header_inline(converter, fbc, cc, work):
    # An excluded extern inline body still declares a callable C symbol.
    # This is how gnulib exposes streq while supplying its external definition
    # in a separate translation unit.
    source_directory = work / "generic-body-external-header-inline"
    source_directory.mkdir()
    header = source_directory / "inline.h"
    header.write_text(
        "extern __inline__ __attribute__((__gnu_inline__))\n"
        "int header_adjust(int value) { return value + 9; }\n"
    )
    source = source_directory / "caller.c"
    source.write_text(
        '#include "inline.h"\n'
        "int inline_caller(int value) { return header_adjust(value); }\n"
    )
    candidate = source_directory / "caller.bas"
    summary = run([converter, "translate-simple-generic-c", str(source),
                   str(candidate), *cc])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert not re.search(r"^(?:Private )?Function header_adjust\b", generated, re.M)
    implementation = source_directory / "implementation.c"
    implementation.write_text("int header_adjust(int value) { return value + 9; }\n")
    implementation_object = source_directory / "implementation.o"
    run(cc + ["-c", str(implementation), "-o", str(implementation_object)],
        cwd=source_directory)
    reference = source_directory / "reference.c"
    reference.write_text(
        "#include <stdio.h>\n"
        "extern int inline_caller(int);\n"
        "int main(void) {\n"
        '  printf("%d %d\\n", inline_caller(-27), inline_caller(35));\n'
        "  return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "reference"
    run(cc + ["-O0", str(source), str(reference), str(implementation_object),
              "-o", str(c_executable)], cwd=source_directory)
    expected = run([str(c_executable)], cwd=source_directory).split()
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "caller.bas"\n'
        'Print inline_caller(-27); " "; inline_caller(35)\n'
    )
    for backend in ([], ["-gen", "gcc"]):
        executable = source_directory / "check"
        run(fbc + backend + ["-w", "all", str(wrapper), str(implementation_object),
                             "-x", str(executable)], cwd=source_directory)
        assert run([str(executable)], cwd=source_directory).split() == expected


def check_generic_body_header_root(converter, fbc, work):
    # A header passed as the root input contributes its own function bodies.
    source_directory = work / "generic-body-header-root"
    source_directory.mkdir()
    header = source_directory / "standalone.h"
    header.write_text(
        "int c2fbHeaderRoot(int value) {\n"
        "    if (value > 0) return value + 2;\n"
        "    return -value;\n"
        "}\n"
        "int c2fbHeaderSum(int limit) {\n"
        "    int total = 0;\n"
        "    for (int index = 0; index < limit; ++index) total += index;\n"
        "    return total;\n"
        "}\n"
    )
    candidate = source_directory / "header_root_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(header),
        str(candidate), "cc",
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "Function c2fbHeaderRoot" in generated, generated
    assert "If (-Cast(c2fb_c_int" in generated, generated
    assert "Function c2fbHeaderSum" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "header_root_candidates.bas"\n'
        "If c2fbHeaderRoot(5) <> 7 Then End 1\n"
        "If c2fbHeaderRoot(-5) <> 5 Then End 2\n"
        "If c2fbHeaderSum(0) <> 0 Then End 3\n"
        "If c2fbHeaderSum(6) <> 15 Then End 4\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_forced_non_inline_function_macro(converter, fbc, work):
    # fbfrog's forcefunction2macro option also applies to ordinary definitions.
    source_directory = work / "generic-header-forced-non-inline-function-macro"
    source_directory.mkdir()
    header = source_directory / "forced.h"
    header.write_text(
        "int forcedSquare(int value) { return value * value; }\n"
    )
    for label, options in (
        ("long", ["--force-inline-macro=forcedSquare"]),
        ("fbfrog", ["-forcefunction2macro", "forcedSquare"]),
    ):
        binding = source_directory / f"{label}.bi"
        summary = run([
            converter, "generic-header", str(header), str(binding), "cc",
            *options,
        ])
        generated = binding.read_text()
        assert "1 function-like" in summary, summary
        assert (
            "#define c2fb_forcedSquare(c2fb_inline_arg_0) "
            "Cast(Long, (Cast(Long, Fix((c2fb_inline_arg_0))))*"
            "(Cast(Long, Fix((c2fb_inline_arg_0)))))"
        ) in generated, generated
        assert "c2fb force-inline-macro matched: forcedSquare" in generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "fbfrog.bi"\n'
        "If c2fb_forcedSquare(7) <> 49 Then End 1\n"
        "If c2fb_forcedSquare(7.8) <> 49 Then End 2\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_fbfrog_forced_parameter_usage(converter, fbc, work):
    # FBFrog's force option accepts unused, repeated, and lazy parameter uses.
    source_directory = work / "generic-header-fbfrog-forced-parameter-usage"
    source_directory.mkdir()
    header = source_directory / "forced-parameter-usage.h"
    header.write_text(
        "static inline int forcedUnused(int value) { return 17; }\n"
        "static inline int forcedRepeated(int value) { return value + value; }\n"
        "static inline int forcedLazy(int condition, int value) {\n"
        "    return condition && value;\n"
        "}\n"
        "static inline int forcedConditional(\n"
        "    int condition, int whenTrue, int whenFalse) {\n"
        "    return condition ? whenTrue : whenFalse;\n"
        "}\n"
    )

    safe_binding = source_directory / "safe.bi"
    run([converter, "generic-header", str(header), str(safe_binding), "cc"])
    assert "#define c2fb_forcedUnused(" not in safe_binding.read_text()
    assert "#define c2fb_forcedRepeated(" not in safe_binding.read_text()
    assert "#define c2fb_forcedLazy(" not in safe_binding.read_text()
    assert "#define c2fb_forcedConditional(" not in safe_binding.read_text()

    binding = source_directory / "forced.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), "cc",
        "-forcefunction2macro", "forcedUnused",
        "-forcefunction2macro", "forcedRepeated",
        "-forcefunction2macro", "forcedLazy",
        "-forcefunction2macro", "forcedConditional",
    ])
    generated = binding.read_text()
    assert "4 function-like" in summary, summary
    for name in (
        "forcedUnused", "forcedRepeated", "forcedLazy", "forcedConditional",
    ):
        assert f"#define c2fb_{name}(" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        "If c2fb_forcedUnused(22) <> 17 Then End 1\n"
        "If c2fb_forcedRepeated(5) <> 10 Then End 2\n"
        "If c2fb_forcedLazy(0, 9) <> 0 Then End 3\n"
        "If c2fb_forcedLazy(1, 9) = 0 Then End 4\n"
        "If c2fb_forcedConditional(0, 11, 19) <> 19 Then End 5\n"
        "If c2fb_forcedConditional(1, 11, 19) <> 11 Then End 6\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_floating_inline_function_macros(converter, fbc, cc, work):
    # Fbfrog lowers simple floating return functions to typed FreeBASIC macros.
    source_directory = work / "generic-header-floating-inline-macros"
    source_directory.mkdir()
    header = source_directory / "floating-inline.h"
    header.write_text(
        "double blend(double left, double right) {\n"
        "    return left * 1.5 + right;\n"
        "}\n"
        "static inline float scale(float value) {\n"
        "    return value * 0.25f;\n"
        "}\n"
        "double hex_offset(double value) {\n"
        "    return value + 0x1.8p0;\n"
        "}\n"
        "static inline float hex_scale(float value) {\n"
        "    return value + 0x1.8p0f;\n"
        "}\n"
        "int hex_integer_cast(double value) {\n"
        "    return (int)(value + 0x1.8p0);\n"
        "}\n"
        "double hex_long_double(double value) {\n"
        "    return value + 0x1.0000000000000008p0L;\n"
        "}\n"
    )
    binding = source_directory / "floating-inline.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "6 function-like" in summary, summary
    assert "#define c2fb_blend(" in generated, generated
    assert "Cast(Double," in generated, generated
    assert "#define c2fb_scale(" in generated, generated
    assert "Cast(Single," in generated, generated
    assert "#define c2fb_hex_offset(" in generated, generated
    assert "#define c2fb_hex_scale(" in generated, generated
    assert "#define c2fb_hex_integer_cast(" in generated, generated
    assert "#define c2fb_hex_long_double(" in generated, generated
    assert 'crt/longdouble.bi' in generated, generated
    assert "unsupported header function body" not in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "floating-inline.h"\n'
        "double c2fbReferenceBlend(double left, double right) {\n"
        "    return blend(left, right);\n"
        "}\n"
        "float c2fbReferenceScale(float value) {\n"
        "    return scale(value);\n"
        "}\n"
        "double c2fbReferenceHexOffset(double value) {\n"
        "    return hex_offset(value);\n"
        "}\n"
        "float c2fbReferenceHexScale(float value) {\n"
        "    return hex_scale(value);\n"
        "}\n"
        "int c2fbReferenceHexIntegerCast(double value) {\n"
        "    return hex_integer_cast(value);\n"
        "}\n"
        "double c2fbReferenceHexLongDouble(double value) {\n"
        "    return hex_long_double(value);\n"
        "}\n"
    )
    reference_library = source_directory / "reference.so"
    run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(reference_source),
              "-o", str(reference_library)])
    reference = ctypes.CDLL(str(reference_library))
    reference.c2fbReferenceBlend.argtypes = [ctypes.c_double, ctypes.c_double]
    reference.c2fbReferenceBlend.restype = ctypes.c_double
    reference.c2fbReferenceScale.argtypes = [ctypes.c_float]
    reference.c2fbReferenceScale.restype = ctypes.c_float
    reference.c2fbReferenceHexOffset.argtypes = [ctypes.c_double]
    reference.c2fbReferenceHexOffset.restype = ctypes.c_double
    reference.c2fbReferenceHexScale.argtypes = [ctypes.c_float]
    reference.c2fbReferenceHexScale.restype = ctypes.c_float
    reference.c2fbReferenceHexIntegerCast.argtypes = [ctypes.c_double]
    reference.c2fbReferenceHexIntegerCast.restype = ctypes.c_int
    reference.c2fbReferenceHexLongDouble.argtypes = [ctypes.c_double]
    reference.c2fbReferenceHexLongDouble.restype = ctypes.c_double

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        "Print c2fb_blend(1.25, 3.0)\n"
        "Print c2fb_blend(-2.5, 0.125)\n"
        "Print c2fb_scale(5.25)\n"
        "Print c2fb_scale(-2.0)\n"
        "Print c2fb_hex_offset(1.25)\n"
        "Print c2fb_hex_scale(2.0)\n"
        "Print c2fb_hex_integer_cast(1.25)\n"
        "Print c2fb_hex_long_double(1.0)\n"
    )
    expected_values = [
        reference.c2fbReferenceBlend(1.25, 3.0),
        reference.c2fbReferenceBlend(-2.5, 0.125),
        reference.c2fbReferenceScale(5.25),
        reference.c2fbReferenceScale(-2.0),
        reference.c2fbReferenceHexOffset(1.25),
        reference.c2fbReferenceHexScale(2.0),
        reference.c2fbReferenceHexIntegerCast(1.25),
        reference.c2fbReferenceHexLongDouble(1.0),
    ]
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), "-x", str(executable)],
            cwd=source_directory)
        actual_values = [
            float(line.strip())
            for line in run([str(executable)], cwd=source_directory).splitlines()
            if line.strip()
        ]
        assert len(actual_values) == len(expected_values), actual_values
        for expected, actual in zip(expected_values, actual_values):
            assert math.isclose(expected, actual, rel_tol=1e-6, abs_tol=1e-6), (
                backend, expected, actual
            )


def check_generic_header_pointer_inline_function_macros(converter, fbc, cc, work):
    # Pointer identity and null returns are safe when macro arguments are used once.
    source_directory = work / "generic-header-pointer-inline-macros"
    source_directory.mkdir()
    header = source_directory / "pointer-inline.h"
    header.write_text(
        "#include <stddef.h>\n"
        "static inline void *pointerIdentity(void *value) {\n"
        "    return value;\n"
        "}\n"
        "static inline unsigned char *bytePointerCast(void *value) {\n"
        "    return (unsigned char *)value;\n"
        "}\n"
        "static inline const char *stringPointerIdentity(const char *value) {\n"
        "    return value;\n"
        "}\n"
        'static inline const char *stringPointerLiteral(void) { return "literal"; }\n'
        "static inline void **pointerPointerIdentity(void **value) {\n"
        "    return value;\n"
        "}\n"
        "static inline void **pointerPointerAdvance(void **value, int offset) {\n"
        "    return value + offset;\n"
        "}\n"
        "static inline void *voidPointerAdvance(void *value, int offset) {\n"
        "    return value + offset;\n"
        "}\n"
        "static inline int *pointerAdvance(int *value, int offset) {\n"
        "    return value + offset;\n"
        "}\n"
        "static inline int *pointerNext(int *value) {\n"
        "    return value + 1;\n"
        "}\n"
        "static inline void *nullPointer(void) {\n"
        "    return NULL;\n"
        "}\n"
    )
    binding = source_directory / "pointer-inline.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    for function_name in (
        "pointerIdentity", "bytePointerCast", "stringPointerIdentity",
        "pointerPointerIdentity",
        "stringPointerLiteral", "pointerPointerAdvance", "voidPointerAdvance",
        "pointerAdvance", "pointerNext",
        "nullPointer",
    ):
        assert f"#define c2fb_{function_name}(" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "pointer-inline.h"\n'
        "void *c2fbReferencePointer(void *value) {\n"
        "    return pointerIdentity(value);\n"
        "}\n"
        "unsigned char *c2fbReferenceBytePointerCast(void *value) {\n"
        "    return bytePointerCast(value);\n"
        "}\n"
        "const char *c2fbReferenceStringPointer(const char *value) {\n"
        "    return stringPointerIdentity(value);\n"
        "}\n"
        "const char *c2fbReferenceStringLiteral(void) {\n"
        "    return stringPointerLiteral();\n"
        "}\n"
        "void **c2fbReferencePointerPointer(void **value) {\n"
        "    return pointerPointerIdentity(value);\n"
        "}\n"
        "void **c2fbReferencePointerPointerAdvance(void **value, int offset) {\n"
        "    return pointerPointerAdvance(value, offset);\n"
        "}\n"
        "void *c2fbReferenceVoidPointerAdvance(void *value, int offset) {\n"
        "    return voidPointerAdvance(value, offset);\n"
        "}\n"
        "int *c2fbReferencePointerAdvance(int *value, int offset) {\n"
        "    return pointerAdvance(value, offset);\n"
        "}\n"
        "int *c2fbReferencePointerNext(int *value) {\n"
        "    return pointerNext(value);\n"
        "}\n"
        "void *c2fbReferenceNullPointer(void) {\n"
        "    return nullPointer();\n"
        "}\n"
    )
    reference_library = source_directory / "reference.so"
    run(cc + ["-std=gnu99", "-O2", "-shared", "-fPIC", str(reference_source),
              "-o", str(reference_library)])
    reference = ctypes.CDLL(str(reference_library))
    reference.c2fbReferencePointer.argtypes = [ctypes.c_void_p]
    reference.c2fbReferencePointer.restype = ctypes.c_void_p
    reference.c2fbReferenceBytePointerCast.argtypes = [ctypes.c_void_p]
    reference.c2fbReferenceBytePointerCast.restype = ctypes.c_void_p
    reference.c2fbReferenceStringPointer.argtypes = [ctypes.c_void_p]
    reference.c2fbReferenceStringPointer.restype = ctypes.c_void_p
    reference.c2fbReferenceStringLiteral.argtypes = []
    reference.c2fbReferenceStringLiteral.restype = ctypes.c_void_p
    reference.c2fbReferencePointerPointer.argtypes = [ctypes.c_void_p]
    reference.c2fbReferencePointerPointer.restype = ctypes.c_void_p
    reference.c2fbReferencePointerPointerAdvance.argtypes = [
        ctypes.c_void_p, ctypes.c_int,
    ]
    reference.c2fbReferencePointerPointerAdvance.restype = ctypes.c_void_p
    reference.c2fbReferenceVoidPointerAdvance.argtypes = [
        ctypes.c_void_p, ctypes.c_int,
    ]
    reference.c2fbReferenceVoidPointerAdvance.restype = ctypes.c_void_p
    reference.c2fbReferencePointerAdvance.argtypes = [ctypes.c_void_p, ctypes.c_int]
    reference.c2fbReferencePointerAdvance.restype = ctypes.c_void_p
    reference.c2fbReferencePointerNext.argtypes = [ctypes.c_void_p]
    reference.c2fbReferencePointerNext.restype = ctypes.c_void_p
    reference.c2fbReferenceNullPointer.argtypes = []
    reference.c2fbReferenceNullPointer.restype = ctypes.c_void_p
    marker = ctypes.c_long(41)
    text = ctypes.create_string_buffer(b"pointer", 16)
    marker_pointer = ctypes.c_void_p(ctypes.addressof(marker))
    pointer_values = (ctypes.c_void_p * 3)(None, None, None)
    byte_values = ctypes.create_string_buffer(b"pointer", 16)
    integer_values = (ctypes.c_int * 4)(1, 2, 3, 4)
    assert reference.c2fbReferencePointer(ctypes.addressof(marker)) == \
        ctypes.addressof(marker)
    assert reference.c2fbReferenceBytePointerCast(ctypes.addressof(marker)) == \
        ctypes.addressof(marker)
    assert reference.c2fbReferenceStringPointer(ctypes.addressof(text)) == \
        ctypes.addressof(text)
    string_literal_pointer = reference.c2fbReferenceStringLiteral()
    assert string_literal_pointer is not None
    assert ctypes.string_at(string_literal_pointer) == b"literal"
    assert reference.c2fbReferencePointerPointer(
        ctypes.addressof(marker_pointer)
    ) == ctypes.addressof(marker_pointer)
    assert reference.c2fbReferencePointerPointerAdvance(
        ctypes.addressof(pointer_values), 1
    ) == ctypes.addressof(pointer_values) + ctypes.sizeof(ctypes.c_void_p)
    assert reference.c2fbReferenceVoidPointerAdvance(
        ctypes.addressof(byte_values), 3
    ) == ctypes.addressof(byte_values) + 3
    assert reference.c2fbReferencePointerAdvance(
        ctypes.addressof(integer_values), 2
    ) == ctypes.addressof(integer_values) + 2 * ctypes.sizeof(ctypes.c_int)
    assert reference.c2fbReferencePointerNext(ctypes.addressof(integer_values)) == \
        ctypes.addressof(integer_values) + ctypes.sizeof(ctypes.c_int)
    assert reference.c2fbReferenceNullPointer() is None

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        "Dim marker As Long = 41\n"
        "Dim markerPointer As Any Ptr = @marker\n"
        "If c2fb_pointerIdentity(markerPointer) <> markerPointer Then End 1\n"
        "Dim bytePointer As UByte Ptr = CPtr(UByte Ptr, markerPointer)\n"
        "If c2fb_bytePointerCast(markerPointer) <> bytePointer Then End 10\n"
        "Dim pointerPointer As Any Ptr Ptr = @markerPointer\n"
        "If c2fb_pointerPointerIdentity(pointerPointer) <> pointerPointer Then End 4\n"
        "Dim pointerValues(0 To 2) As Any Ptr\n"
        "If c2fb_pointerPointerAdvance(@pointerValues(0), 1) <> @pointerValues(1) Then End 6\n"
        "Dim byteValues(0 To 5) As UByte\n"
        "If c2fb_voidPointerAdvance(@byteValues(0), 3) <> @byteValues(3) Then End 11\n"
        "Dim integerValues(0 To 3) As Long\n"
        "If c2fb_pointerAdvance(@integerValues(0), 2) <> @integerValues(2) Then End 5\n"
        "If c2fb_pointerNext(@integerValues(0)) <> @integerValues(1) Then End 7\n"
        "Dim text As ZString * 16 = \"pointer\"\n"
        "Dim textPointer As Const Byte Ptr = CPtr(Const Byte Ptr, @text)\n"
        "If c2fb_stringPointerIdentity(textPointer) <> textPointer Then End 2\n"
        "Dim stringLiteralPointer As Const ZString Ptr = c2fb_stringPointerLiteral()\n"
        "If stringLiteralPointer = 0 Then End 8\n"
        "If *stringLiteralPointer <> \"literal\" Then End 9\n"
        "If c2fb_nullPointer() <> 0 Then End 3\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), "-x", str(executable)],
            cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_inline_function_call_macro(converter, fbc, cc, work):
    # Fbfrog converts a single-return wrapper call when its arguments stay single-use.
    source_directory = work / "generic-header-inline-function-call-macro"
    source_directory.mkdir()
    header = source_directory / "inline-call.h"
    header.write_text(
        "double c2fbHelper(double value);\n"
        "static inline double c2fbCallHelper(double value) {\n"
        "    return c2fbHelper(value);\n"
        "}\n"
    )
    binding = source_directory / "inline-call.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "1 function-like" in summary, summary
    assert "#define c2fb_c2fbCallHelper(" in generated, generated
    assert 'Alias "c2fbHelper"' in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "inline-call.h"\n'
        "double c2fbHelper(double value) { return value * 2.0 + 0.75; }\n"
        "double c2fbReferenceCall(double value) {\n"
        "    return c2fbCallHelper(value);\n"
        "}\n"
    )
    reference_library = source_directory / "reference.so"
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(reference_source),
              "-o", str(reference_library)])
    run(cc + ["-std=c99", "-O2", "-c", str(reference_source),
              "-o", str(reference_object)])
    reference = ctypes.CDLL(str(reference_library))
    reference.c2fbReferenceCall.argtypes = [ctypes.c_double]
    reference.c2fbReferenceCall.restype = ctypes.c_double

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        "Print c2fb_c2fbCallHelper(2.5)\n"
        "Print c2fb_c2fbCallHelper(-1.25)\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(reference_object), "-x",
               str(executable)], cwd=source_directory)
    actual_values = [
        float(line.strip())
        for line in run([str(executable)], cwd=source_directory).splitlines()
        if line.strip()
    ]
    expected_values = [
        reference.c2fbReferenceCall(2.5),
        reference.c2fbReferenceCall(-1.25),
    ]
    assert len(actual_values) == len(expected_values), actual_values
    for expected, actual in zip(expected_values, actual_values):
        assert math.isclose(expected, actual, rel_tol=1e-6, abs_tol=1e-6), (
            expected, actual
        )


def check_generic_header_inline_record_accessors(converter, fbc, cc, work):
    # Single-return field and indexed reads should keep working as typed macros.
    source_directory = work / "generic-header-inline-record-accessors"
    source_directory.mkdir()
    header = source_directory / "record-accessors.h"
    header.write_text(
        "struct Sample { int value; int values[3]; };\n"
        "static inline int readMember(const struct Sample *sample) {\n"
        "    return sample->value;\n"
        "}\n"
        "static inline int readNamedField(const struct Sample *value) {\n"
        "    return value->value;\n"
        "}\n"
        "static inline int readElement(const struct Sample *sample, int index) {\n"
        "    return sample->values[index];\n"
        "}\n"
    )
    binding = source_directory / "record-accessors.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "3 function-like" in summary, summary
    assert "Type c2fb_Sample" in generated, generated
    assert "#define c2fb_readMember(" in generated, generated
    assert "#define c2fb_readNamedField(" in generated, generated
    assert "#define c2fb_readElement(" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "record-accessors.h"\n'
        "int c2fbReferenceReadMember(const struct Sample *sample) {\n"
        "    return readMember(sample);\n"
        "}\n"
        "int c2fbReferenceReadNamedField(const struct Sample *value) {\n"
        "    return readNamedField(value);\n"
        "}\n"
        "int c2fbReferenceReadElement(const struct Sample *sample, int index) {\n"
        "    return readElement(sample, index);\n"
        "}\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-O2", "-c", str(reference_source),
              "-o", str(reference_object)])

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        'Declare Function c2fbReferenceReadMember CDecl '
        'Alias "c2fbReferenceReadMember" '
        '(ByRef sample As c2fb_Sample) As Long\n'
        'Declare Function c2fbReferenceReadElement CDecl '
        'Alias "c2fbReferenceReadElement" '
        '(ByRef sample As c2fb_Sample, ByVal index As Long) As Long\n'
        'Declare Function c2fbReferenceReadNamedField CDecl '
        'Alias "c2fbReferenceReadNamedField" '
        '(ByRef value As c2fb_Sample) As Long\n'
        "Dim sample As c2fb_Sample\n"
        "sample.value = 42\n"
        "sample.values(1) = 73\n"
        "If c2fb_readMember(@sample) <> "
        "c2fbReferenceReadMember(sample) Then End 1\n"
        "If c2fb_readNamedField(@sample) <> "
        "c2fbReferenceReadNamedField(sample) Then End 3\n"
        "If c2fb_readElement(@sample, 1) <> "
        "c2fbReferenceReadElement(sample, 1) Then End 2\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), str(reference_object),
                           "-x", str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_inline_pointer_dereferences(converter, fbc, cc, work):
    # A typed integer pointer can be dereferenced in a scalar return macro.
    source_directory = work / "generic-header-inline-pointer-dereferences"
    source_directory.mkdir()
    header = source_directory / "pointer-dereference.h"
    header.write_text(
        "static inline int readIntPointer(const int *value) {\n"
        "    return *value;\n"
        "}\n"
        "static inline int readDoublePointer(const int **value) {\n"
        "    return **value;\n"
        "}\n"
        "static inline const int *selectPointer(const int **value) {\n"
        "    return *value;\n"
        "}\n"
        "static inline int readAdjustedPointer(\n"
        "    const int *value, int adjustment) {\n"
        "    return *value + adjustment;\n"
        "}\n"
        "static inline int readPointerElement(\n"
        "    const int *values, int index) {\n"
        "    return values[index];\n"
        "}\n"
        "static inline int readOffsetPointer(\n"
        "    const int *values, int offset) {\n"
        "    return *(values + offset);\n"
        "}\n"
        "static inline int readShortPointer(const short *value) {\n"
        "    return *value;\n"
        "}\n"
        "static inline unsigned int readUnsignedPointer(\n"
        "    const unsigned int *value) {\n"
        "    return *value;\n"
        "}\n"
    )
    binding = source_directory / "pointer-dereference.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "8 function-like" in summary, summary
    for name in (
        "readIntPointer", "readDoublePointer", "selectPointer",
        "readAdjustedPointer", "readPointerElement", "readOffsetPointer",
        "readShortPointer", "readUnsignedPointer",
    ):
        assert f"#define c2fb_{name}(" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "pointer-dereference.h"\n'
        "int c2fbReferenceReadInt(int value) { return readIntPointer(&value); }\n"
        "int c2fbReferenceReadDoublePointer(int value) {\n"
        "    const int *pointer = &value;\n"
        "    return readDoublePointer(&pointer);\n"
        "}\n"
        "int c2fbReferenceReadSelectedPointer(int value) {\n"
        "    const int *pointer = &value;\n"
        "    return *selectPointer(&pointer);\n"
        "}\n"
        "int c2fbReferenceReadAdjusted(int value, double adjustment) {\n"
        "    return readAdjustedPointer(&value, adjustment);\n"
        "}\n"
        "int c2fbReferenceReadPointerElement(\n"
        "    const int *values, int index) {\n"
        "    return readPointerElement(values, index);\n"
        "}\n"
        "int c2fbReferenceReadOffsetPointer(\n"
        "    const int *values, int offset) {\n"
        "    return readOffsetPointer(values, offset);\n"
        "}\n"
        "int c2fbReferenceReadShort(int value) {\n"
        "    short narrowed = (short)value;\n"
        "    return readShortPointer(&narrowed);\n"
        "}\n"
        "unsigned int c2fbReferenceReadUnsigned(unsigned int value) {\n"
        "    return readUnsignedPointer(&value);\n"
        "}\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-O2", "-c", str(reference_source),
              "-o", str(reference_object)])

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        'Declare Function c2fbReferenceReadInt CDecl '
        'Alias "c2fbReferenceReadInt" (ByVal value As Long) As Long\n'
        'Declare Function c2fbReferenceReadDoublePointer CDecl '
        'Alias "c2fbReferenceReadDoublePointer" (ByVal value As Long) As Long\n'
        'Declare Function c2fbReferenceReadSelectedPointer CDecl '
        'Alias "c2fbReferenceReadSelectedPointer" (ByVal value As Long) As Long\n'
        'Declare Function c2fbReferenceReadAdjusted CDecl '
        'Alias "c2fbReferenceReadAdjusted" '
        '(ByVal value As Long, ByVal adjustment As Double) As Long\n'
        'Declare Function c2fbReferenceReadPointerElement CDecl '
        'Alias "c2fbReferenceReadPointerElement" '
        '(ByVal values As Long Ptr, ByVal index As Long) As Long\n'
        'Declare Function c2fbReferenceReadOffsetPointer CDecl '
        'Alias "c2fbReferenceReadOffsetPointer" '
        '(ByVal values As Long Ptr, ByVal offset As Long) As Long\n'
        'Declare Function c2fbReferenceReadShort CDecl '
        'Alias "c2fbReferenceReadShort" (ByVal value As Long) As Long\n'
        'Declare Function c2fbReferenceReadUnsigned CDecl '
        'Alias "c2fbReferenceReadUnsigned" (ByVal value As ULong) As ULong\n'
        "Dim integerValue As Long = -12345\n"
        "Dim constIntegerPointer As Const Long Ptr = @integerValue\n"
        "Dim constIntegerPointerPointer As Const Long Ptr Ptr = @constIntegerPointer\n"
        "If c2fb_readIntPointer(@integerValue) <> "
        "c2fbReferenceReadInt(integerValue) Then End 1\n"
        "If c2fb_readDoublePointer(constIntegerPointerPointer) <> "
        "c2fbReferenceReadDoublePointer(integerValue) Then End 5\n"
        "Dim selectedPointer As Const Long Ptr = "
        "c2fb_selectPointer(constIntegerPointerPointer)\n"
        "If selectedPointer = 0 OrElse *selectedPointer <> "
        "c2fbReferenceReadSelectedPointer(integerValue) Then End 6\n"
        "Dim integerPointer As Any Ptr = @integerValue\n"
        "If c2fb_readAdjustedPointer(integerPointer, 2.8) <> "
        "c2fbReferenceReadAdjusted(integerValue, 2.8) Then End 4\n"
        "Dim integerValues(0 To 2) As Long\n"
        "integerValues(1) = 789\n"
        "If c2fb_readPointerElement(@integerValues(0), 1) <> "
        "c2fbReferenceReadPointerElement(@integerValues(0), 1) Then End 7\n"
        "If c2fb_readOffsetPointer(@integerValues(1), -1) <> "
        "c2fbReferenceReadOffsetPointer(@integerValues(1), -1) Then End 8\n"
        "Dim shortValue As Short = -321\n"
        "If c2fb_readShortPointer(@shortValue) <> "
        "c2fbReferenceReadShort(shortValue) Then End 2\n"
        "Dim unsignedValue As ULong = &hF1234567\n"
        "If c2fb_readUnsignedPointer(@unsignedValue) <> "
        "c2fbReferenceReadUnsigned(unsignedValue) Then End 3\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), str(reference_object),
                           "-x", str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_integer_division_function_macros(converter, fbc, cc, work):
    # Integer division and remainder keep C truncation and parameter conversions.
    source_directory = work / "generic-header-integer-division-function-macros"
    source_directory.mkdir()
    header = source_directory / "integer-division.h"
    header.write_text(
        "static inline int divideInt(int dividend, int divisor) {\n"
        "    return dividend / divisor;\n"
        "}\n"
        "static inline int remainderInt(int dividend, int divisor) {\n"
        "    return dividend % divisor;\n"
        "}\n"
        "static inline unsigned int divideUnsigned(\n"
        "    unsigned int dividend, unsigned int divisor) {\n"
        "    return dividend / divisor;\n"
        "}\n"
        "static inline long long divideWide(long long dividend, long long divisor) {\n"
        "    return dividend / divisor;\n"
        "}\n"
        "static inline int divideDouble(double dividend, double divisor) {\n"
        "    return dividend / divisor;\n"
        "}\n"
        "static inline int returnDoubleAsInt(double value) {\n"
        "    return value;\n"
        "}\n"
        "static inline int explicitCast(double value) {\n"
        "    return (int)value;\n"
        "}\n"
        "static inline int addMixed(int whole, double fraction) {\n"
        "    return whole + fraction;\n"
        "}\n"
        "static inline double integerDivideThenPromote(\n"
        "    int dividend, int divisor) {\n"
        "    return dividend / divisor;\n"
        "}\n"
    )
    binding = source_directory / "integer-division.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "9 function-like" in summary, summary
    for name in (
        "divideInt", "remainderInt", "divideUnsigned", "divideWide",
        "divideDouble", "returnDoubleAsInt", "explicitCast", "addMixed",
        "integerDivideThenPromote",
    ):
        assert f"#define c2fb_{name}(" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "integer-division.h"\n'
        "int c2fbReferenceDivideInt(void) { return divideInt(-5.8, 2); }\n"
        "int c2fbReferenceRemainder(void) { return remainderInt(-7, 3); }\n"
        "unsigned int c2fbReferenceDivideUnsigned(void) {\n"
        "    return divideUnsigned(-1, 2);\n"
        "}\n"
        "long long c2fbReferenceDivideWide(void) {\n"
        "    return divideWide(-9223372036854775807LL, 3);\n"
        "}\n"
        "int c2fbReferenceDivideDouble(void) {\n"
        "    return divideDouble(-7.5, 3.0);\n"
        "}\n"
        "int c2fbReferenceReturnDoubleAsInt(void) {\n"
        "    return returnDoubleAsInt(-5.8);\n"
        "}\n"
        "int c2fbReferenceExplicitCast(void) { return explicitCast(-5.8); }\n"
        "int c2fbReferenceAddMixed(void) { return addMixed(2.8, 1.5); }\n"
        "double c2fbReferenceIntegerDivideThenPromote(void) {\n"
        "    return integerDivideThenPromote(-7, 3);\n"
        "}\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-O2", "-c", str(reference_source),
              "-o", str(reference_object)])

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        'Declare Function c2fbReferenceDivideInt CDecl '
        'Alias "c2fbReferenceDivideInt" () As Long\n'
        'Declare Function c2fbReferenceRemainder CDecl '
        'Alias "c2fbReferenceRemainder" () As Long\n'
        'Declare Function c2fbReferenceDivideUnsigned CDecl '
        'Alias "c2fbReferenceDivideUnsigned" () As ULong\n'
        'Declare Function c2fbReferenceDivideWide CDecl '
        'Alias "c2fbReferenceDivideWide" () As LongInt\n'
        'Declare Function c2fbReferenceDivideDouble CDecl '
        'Alias "c2fbReferenceDivideDouble" () As Long\n'
        'Declare Function c2fbReferenceReturnDoubleAsInt CDecl '
        'Alias "c2fbReferenceReturnDoubleAsInt" () As Long\n'
        'Declare Function c2fbReferenceExplicitCast CDecl '
        'Alias "c2fbReferenceExplicitCast" () As Long\n'
        'Declare Function c2fbReferenceAddMixed CDecl '
        'Alias "c2fbReferenceAddMixed" () As Long\n'
        'Declare Function c2fbReferenceIntegerDivideThenPromote CDecl '
        'Alias "c2fbReferenceIntegerDivideThenPromote" () As Double\n'
        "If c2fb_divideInt(-5.8, 2) <> c2fbReferenceDivideInt() Then End 1\n"
        "If c2fb_remainderInt(-7, 3) <> c2fbReferenceRemainder() Then End 2\n"
        "If c2fb_divideUnsigned(-1, 2) <> "
        "c2fbReferenceDivideUnsigned() Then End 3\n"
        "Dim wideDividend As LongInt = -9223372036854775807\n"
        "If c2fb_divideWide(wideDividend, 3) <> "
        "c2fbReferenceDivideWide() Then End 4\n"
        "If c2fb_divideDouble(-7.5, 3.0) <> "
        "c2fbReferenceDivideDouble() Then End 5\n"
        "If c2fb_returnDoubleAsInt(-5.8) <> "
        "c2fbReferenceReturnDoubleAsInt() Then End 6\n"
        "If c2fb_explicitCast(-5.8) <> "
        "c2fbReferenceExplicitCast() Then End 9\n"
        "If c2fb_addMixed(2.8, 1.5) <> "
        "c2fbReferenceAddMixed() Then End 7\n"
        "If c2fb_integerDivideThenPromote(-7, 3) <> "
        "c2fbReferenceIntegerDivideThenPromote() Then End 8\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), str(reference_object),
                           "-x", str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_dynamic_integer_division_macros(converter, fbc, cc, work):
    # Untyped C operands dispatch to integer or floating semantics at the call site.
    source_directory = work / "generic-header-dynamic-integer-division-macros"
    source_directory.mkdir()
    header = source_directory / "division-macros.h"
    header.write_text(
        "#define C2FB_DIVIDE(left, right) ((left) / (right))\n"
        "#define C2FB_REMAINDER(left, right) ((left) % (right))\n"
        "#define C2FB_DIVIDE_SUM(left, middle, right) "
        "(((left) + (middle)) / (right))\n"
        "#define C2FB_CAST_DIVIDE(left, right) "
        "(((int)(left)) / (right))\n"
    )

    default_binding = source_directory / "default.bi"
    default_summary = run([
        converter, "generic-header", str(header), str(default_binding), "cc",
    ])
    default_output = default_binding.read_text()
    assert "4 unsupported declarations or macro expressions" in default_summary, default_summary
    assert "unsupported function-like macro: #define C2FB_DIVIDE" in default_output, default_output
    assert "c2fbInternalCOperator_" not in default_output, default_output

    binding = source_directory / "division-macros.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), "cc",
        "--dynamic-macro-division=C2FB_*DIV*",
        "--dynamic-macro-division=C2FB_REMAINDER",
    ])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    for name in (
        "C2FB_DIVIDE", "C2FB_REMAINDER", "C2FB_DIVIDE_SUM",
        "C2FB_CAST_DIVIDE",
    ):
        assert f"#define c2fb_{name}(" in generated, generated
    assert "c2fbInternalCOperator_" in generated, generated
    assert "unsupported function-like macro: #define C2FB_DIVIDE" not in generated, generated
    assert "c2fb dynamic macro division matched: C2FB_*DIV*" in generated, generated
    assert "c2fb dynamic macro division matched: C2FB_REMAINDER" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "division-macros.h"\n'
        "static int cLeftCalls, cRightCalls;\n"
        "static double cLeftValue(void) { cLeftCalls++; return -7.5; }\n"
        "static double cRightValue(void) { cRightCalls++; return 2.0; }\n"
        "int c2fbReferenceDivideInt(void) { return C2FB_DIVIDE(-7, 2); }\n"
        "double c2fbReferenceDivideDouble(void) {\n"
        "    return C2FB_DIVIDE(-7.5, 2.0);\n"
        "}\n"
        "unsigned int c2fbReferenceDivideMixed(void) {\n"
        "    return C2FB_DIVIDE((int)-1, (unsigned int)2);\n"
        "}\n"
        "int c2fbReferenceRemainder(void) { return C2FB_REMAINDER(-7, 3); }\n"
        "int c2fbReferencePrecedence(void) {\n"
        "    return C2FB_DIVIDE_SUM(7, 5, 2);\n"
        "}\n"
        "int c2fbReferenceCast(void) { return C2FB_CAST_DIVIDE(-5.8, 2); }\n"
        "int c2fbReferenceSideEffects(int *left, int *right) {\n"
        "    cLeftCalls = 0; cRightCalls = 0;\n"
        "    int value = (int)(C2FB_DIVIDE(cLeftValue(), cRightValue()) * 100.0);\n"
        "    *left = cLeftCalls; *right = cRightCalls;\n"
        "    return value;\n"
        "}\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-O2", "-c", str(reference_source),
              "-o", str(reference_object)])

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        'Declare Function c2fbReferenceDivideInt CDecl Alias '
        '"c2fbReferenceDivideInt" () As Long\n'
        'Declare Function c2fbReferenceDivideDouble CDecl Alias '
        '"c2fbReferenceDivideDouble" () As Double\n'
        'Declare Function c2fbReferenceDivideMixed CDecl Alias '
        '"c2fbReferenceDivideMixed" () As ULong\n'
        'Declare Function c2fbReferenceRemainder CDecl Alias '
        '"c2fbReferenceRemainder" () As Long\n'
        'Declare Function c2fbReferencePrecedence CDecl Alias '
        '"c2fbReferencePrecedence" () As Long\n'
        'Declare Function c2fbReferenceCast CDecl Alias '
        '"c2fbReferenceCast" () As Long\n'
        'Declare Function c2fbReferenceSideEffects CDecl Alias '
        '"c2fbReferenceSideEffects" (ByVal left As Long Ptr, '
        'ByVal right As Long Ptr) As Long\n'
        "If c2fb_C2FB_DIVIDE(-7, 2) <> c2fbReferenceDivideInt() Then End 1\n"
        "If c2fb_C2FB_DIVIDE(-7.5, 2.0) <> "
        "c2fbReferenceDivideDouble() Then End 2\n"
        "If c2fb_C2FB_DIVIDE(Cast(Long, -1), Cast(ULong, 2)) <> "
        "c2fbReferenceDivideMixed() Then End 3\n"
        "If c2fb_C2FB_REMAINDER(-7, 3) <> c2fbReferenceRemainder() Then End 4\n"
        "If c2fb_C2FB_DIVIDE_SUM(7, 5, 2) <> "
        "c2fbReferencePrecedence() Then End 5\n"
        "If c2fb_C2FB_CAST_DIVIDE(-5.8, 2) <> c2fbReferenceCast() Then End 6\n"
        "Dim Shared leftCalls As Long, rightCalls As Long\n"
        "Function leftValue() As Double\n"
        "    leftCalls += 1\n"
        "    Return -7.5\n"
        "End Function\n"
        "Function rightValue() As Double\n"
        "    rightCalls += 1\n"
        "    Return 2.0\n"
        "End Function\n"
        "Dim cLeft As Long, cRight As Long\n"
        "leftCalls = 0\n"
        "rightCalls = 0\n"
        "Dim fbValue As Long = Fix(c2fb_C2FB_DIVIDE("
        "leftValue(), rightValue()) * 100.0)\n"
        "Dim cValue As Long = c2fbReferenceSideEffects(@cLeft, @cRight)\n"
        "If fbValue <> cValue Then End 7\n"
        "If leftCalls <> 1 OrElse rightCalls <> 1 OrElse "
        "cLeft <> 1 OrElse cRight <> 1 Then End 8\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), str(reference_object),
                           "-x", str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)

    assumed_binding = source_directory / "integer-assumption.bi"
    assumed_summary = run([
        converter, "generic-header", str(header), str(assumed_binding), "cc",
        "--assume-integer-macro=C2FB_DIVIDE",
        "--assume-integer-macro=C2FB_REMAINDER",
    ])
    assumed = assumed_binding.read_text()
    assert "2 unsupported declarations or macro expressions" in assumed_summary, assumed_summary
    assert "(c2fb_macro_arg_0) \\ (c2fb_macro_arg_1)" in assumed, assumed
    assert "(c2fb_macro_arg_0) Mod (c2fb_macro_arg_1)" in assumed, assumed
    assert "c2fb assume-integer-macro matched: C2FB_DIVIDE" in assumed, assumed
    assert "c2fb assume-integer-macro matched: C2FB_REMAINDER" in assumed, assumed
    const_wrapper = source_directory / "check-constants.bas"
    const_wrapper.write_text(
        f'#include once "{assumed_binding.resolve()}"\n'
        "Const quotient As Long = c2fb_C2FB_DIVIDE(7, 2)\n"
        "Const remainder As Long = c2fb_C2FB_REMAINDER(-7, 2)\n"
        "If quotient <> 3 Then End 1\n"
        "If remainder <> -1 Then End 2\n"
    )
    const_executable = source_directory / "check-constants"
    run(fbc + ["-w", "all", str(const_wrapper), "-x", str(const_executable)],
        cwd=source_directory)
    run([str(const_executable)], cwd=source_directory)


def check_generic_header_inline_boolean_integer_macros(converter, fbc, cc, work):
    # C comparisons and logical operators must normalize to C's 0-or-1 result.
    source_directory = work / "generic-header-inline-boolean-integer-macros"
    source_directory.mkdir()
    header = source_directory / "boolean-integer.h"
    header.write_text(
        "static inline int lessThan(int left, int right) {\n"
        "    return left < right;\n"
        "}\n"
        "static inline int equalTo(int left, int right) {\n"
        "    return left == right;\n"
        "}\n"
        "static inline int logicalNot(int value) {\n"
        "    return !value;\n"
        "}\n"
        "static inline int bitwiseNot(int value) {\n"
        "    return ~value;\n"
        "}\n"
    )
    binding = source_directory / "boolean-integer.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "4 function-like" in summary, summary
    for name in ("lessThan", "equalTo", "logicalNot", "bitwiseNot"):
        assert f"#define c2fb_{name}(" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "boolean-integer.h"\n'
        "int c2fbReferenceLessThan(int left, int right) {\n"
        "    return lessThan(left, right);\n"
        "}\n"
        "int c2fbReferenceLessThanFromDouble(double left, double right) {\n"
        "    return lessThan(left, right);\n"
        "}\n"
        "int c2fbReferenceEqualTo(int left, int right) {\n"
        "    return equalTo(left, right);\n"
        "}\n"
        "int c2fbReferenceLogicalNot(int value) { return logicalNot(value); }\n"
        "int c2fbReferenceBitwiseNot(int value) { return bitwiseNot(value); }\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-O2", "-c", str(reference_source),
              "-o", str(reference_object)])

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        'Declare Function c2fbReferenceLessThan CDecl Alias '
        '"c2fbReferenceLessThan" (ByVal left As Long, ByVal right As Long) As Long\n'
        'Declare Function c2fbReferenceLessThanFromDouble CDecl Alias '
        '"c2fbReferenceLessThanFromDouble" '
        '(ByVal left As Double, ByVal right As Double) As Long\n'
        'Declare Function c2fbReferenceEqualTo CDecl Alias '
        '"c2fbReferenceEqualTo" (ByVal left As Long, ByVal right As Long) As Long\n'
        'Declare Function c2fbReferenceLogicalNot CDecl Alias '
        '"c2fbReferenceLogicalNot" (ByVal value As Long) As Long\n'
        'Declare Function c2fbReferenceBitwiseNot CDecl Alias '
        '"c2fbReferenceBitwiseNot" (ByVal value As Long) As Long\n'
        "If c2fb_lessThan(-3, 2) <> c2fbReferenceLessThan(-3, 2) Then End 1\n"
        "If c2fb_lessThan(2, -3) <> c2fbReferenceLessThan(2, -3) Then End 2\n"
        "If c2fb_lessThan(2.1, 2.5) <> "
        "c2fbReferenceLessThanFromDouble(2.1, 2.5) Then End 8\n"
        "If c2fb_equalTo(9, 9) <> c2fbReferenceEqualTo(9, 9) Then End 3\n"
        "If c2fb_equalTo(9, 8) <> c2fbReferenceEqualTo(9, 8) Then End 4\n"
        "If c2fb_logicalNot(0) <> c2fbReferenceLogicalNot(0) Then End 5\n"
        "If c2fb_logicalNot(-1) <> c2fbReferenceLogicalNot(-1) Then End 6\n"
        "If c2fb_bitwiseNot(&h1234567) <> "
        "c2fbReferenceBitwiseNot(&h1234567) Then End 7\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), str(reference_object),
                           "-x", str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_inline_parameter_increment_macros(
    converter, fbc, cc, work
):
    # Incrementing a by-value C parameter must not mutate the macro caller.
    source_directory = work / "generic-header-inline-parameter-increment-macros"
    source_directory.mkdir()
    header = source_directory / "parameter-increment.h"
    header.write_text(
        "static inline int prefixIncrement(int value) { return ++value; }\n"
        "static inline int postfixIncrement(int value) { return value++; }\n"
        "static inline int prefixDecrement(int value) { return --value; }\n"
        "static inline int postfixDecrement(int value) { return value--; }\n"
        "static inline int prefixFloatIncrement(double value) { return ++value; }\n"
        "static inline int postfixFloatIncrement(double value) { return value++; }\n"
        "static inline const int *prefixPointerIncrement(const int *value) {\n"
        "    return ++value;\n"
        "}\n"
        "static inline const int *postfixPointerIncrement(const int *value) {\n"
        "    return value++;\n"
        "}\n"
    )
    binding = source_directory / "parameter-increment.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "8 function-like" in summary, summary
    for name in (
        "prefixIncrement", "postfixIncrement", "prefixDecrement",
        "postfixDecrement", "prefixFloatIncrement", "postfixFloatIncrement",
        "prefixPointerIncrement", "postfixPointerIncrement",
    ):
        assert f"#define c2fb_{name}(" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "parameter-increment.h"\n'
        "int c2fbReferencePrefixIncrement(double value) {\n"
        "    return prefixIncrement(value);\n"
        "}\n"
        "int c2fbReferencePostfixIncrement(double value) {\n"
        "    return postfixIncrement(value);\n"
        "}\n"
        "int c2fbReferencePrefixDecrement(double value) {\n"
        "    return prefixDecrement(value);\n"
        "}\n"
        "int c2fbReferencePostfixDecrement(double value) {\n"
        "    return postfixDecrement(value);\n"
        "}\n"
        "int c2fbReferencePrefixFloatIncrement(double value) {\n"
        "    return prefixFloatIncrement(value);\n"
        "}\n"
        "int c2fbReferencePostfixFloatIncrement(double value) {\n"
        "    return postfixFloatIncrement(value);\n"
        "}\n"
        "const int *c2fbReferencePrefixPointerIncrement(const int *value) {\n"
        "    return prefixPointerIncrement(value);\n"
        "}\n"
        "const int *c2fbReferencePostfixPointerIncrement(const int *value) {\n"
        "    return postfixPointerIncrement(value);\n"
        "}\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-O2", "-c", str(reference_source),
              "-o", str(reference_object)])

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        'Declare Function c2fbReferencePrefixIncrement CDecl Alias '
        '"c2fbReferencePrefixIncrement" (ByVal value As Double) As Long\n'
        'Declare Function c2fbReferencePostfixIncrement CDecl Alias '
        '"c2fbReferencePostfixIncrement" (ByVal value As Double) As Long\n'
        'Declare Function c2fbReferencePrefixDecrement CDecl Alias '
        '"c2fbReferencePrefixDecrement" (ByVal value As Double) As Long\n'
        'Declare Function c2fbReferencePostfixDecrement CDecl Alias '
        '"c2fbReferencePostfixDecrement" (ByVal value As Double) As Long\n'
        'Declare Function c2fbReferencePrefixFloatIncrement CDecl Alias '
        '"c2fbReferencePrefixFloatIncrement" (ByVal value As Double) As Long\n'
        'Declare Function c2fbReferencePostfixFloatIncrement CDecl Alias '
        '"c2fbReferencePostfixFloatIncrement" (ByVal value As Double) As Long\n'
        'Declare Function c2fbReferencePrefixPointerIncrement CDecl Alias '
        '"c2fbReferencePrefixPointerIncrement" '
        '(ByVal value As Const Long Ptr) As Const Long Ptr\n'
        'Declare Function c2fbReferencePostfixPointerIncrement CDecl Alias '
        '"c2fbReferencePostfixPointerIncrement" '
        '(ByVal value As Const Long Ptr) As Const Long Ptr\n'
        "If c2fb_prefixIncrement(-5.8) <> "
        "c2fbReferencePrefixIncrement(-5.8) Then End 1\n"
        "If c2fb_postfixIncrement(-5.8) <> "
        "c2fbReferencePostfixIncrement(-5.8) Then End 2\n"
        "If c2fb_prefixDecrement(-5.8) <> "
        "c2fbReferencePrefixDecrement(-5.8) Then End 3\n"
        "If c2fb_postfixDecrement(-5.8) <> "
        "c2fbReferencePostfixDecrement(-5.8) Then End 4\n"
        "If c2fb_prefixFloatIncrement(-5.8) <> "
        "c2fbReferencePrefixFloatIncrement(-5.8) Then End 5\n"
        "If c2fb_postfixFloatIncrement(-5.8) <> "
        "c2fbReferencePostfixFloatIncrement(-5.8) Then End 6\n"
        "Dim values(0 To 2) As Long\n"
        "If c2fb_prefixPointerIncrement(@values(0)) <> "
        "c2fbReferencePrefixPointerIncrement(@values(0)) Then End 7\n"
        "If c2fb_postfixPointerIncrement(@values(0)) <> "
        "c2fbReferencePostfixPointerIncrement(@values(0)) Then End 8\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), str(reference_object),
                           "-x", str(executable)], cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_callback_return_function_macros(converter, fbc, cc, work):
    # Simple callback returns and invocations use the emitted callback type.
    source_directory = work / "generic-header-callback-return-function-macros"
    source_directory.mkdir()
    header = source_directory / "callback-return.h"
    header.write_text(
        "typedef int (*Callback)(int value);\n"
        "int target(int value);\n"
        "static inline Callback returnCallback(Callback callback) {\n"
        "    return callback;\n"
        "}\n"
        "static inline Callback returnTarget(void) {\n"
        "    return target;\n"
        "}\n"
        "static inline int invokeCallback(Callback callback, int value) {\n"
        "    return callback(value);\n"
        "}\n"
        "static inline Callback chooseCallback(\n"
        "    int condition, Callback whenTrue, Callback whenFalse) {\n"
        "    return condition ? whenTrue : whenFalse;\n"
        "}\n"
    )
    binding = source_directory / "callback-return.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), "cc",
        "-forcefunction2macro", "chooseCallback",
    ])
    generated = binding.read_text()
    assert "4 function-like" in summary, summary
    assert "Type c2fb_Callback As Function CDecl" in generated, generated
    assert "#define c2fb_returnCallback(" in generated, generated
    assert "#define c2fb_returnTarget()" in generated, generated
    assert "#define c2fb_invokeCallback(" in generated, generated
    assert "#define c2fb_chooseCallback(" in generated, generated
    assert "ProcPtr(c2fb_target)" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "callback-return.h"\n'
        "static int c2fbReferenceCallback(int value) {\n"
        "    return value * 3 + 1;\n"
        "}\n"
        "static int c2fbReferenceFirst(int value) { return value - 2; }\n"
        "static int c2fbReferenceSecond(int value) { return value * 4; }\n"
        "int c2fbReferenceCallbackResult(void) {\n"
        "    Callback callback = returnCallback(c2fbReferenceCallback);\n"
        "    return callback(5);\n"
        "}\n"
        "int c2fbReferenceTargetResult(void) {\n"
        "    Callback callback = returnTarget();\n"
        "    return callback(5);\n"
        "}\n"
        "int c2fbReferenceInvokeCallbackResult(void) {\n"
        "    return invokeCallback(c2fbReferenceCallback, 5);\n"
        "}\n"
        "int c2fbReferenceChooseFalseResult(void) {\n"
        "    Callback callback = chooseCallback(0, c2fbReferenceFirst,\n"
        "                                         c2fbReferenceSecond);\n"
        "    return callback(5);\n"
        "}\n"
        "int c2fbReferenceChooseTrueResult(void) {\n"
        "    Callback callback = chooseCallback(1, c2fbReferenceFirst,\n"
        "                                         c2fbReferenceSecond);\n"
        "    return callback(5);\n"
        "}\n"
        "int target(int value) { return value * 2 + 2; }\n"
    )
    reference_library = source_directory / "reference.so"
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(reference_source),
              "-o", str(reference_library)])
    run(cc + ["-std=c99", "-O2", "-c", str(reference_source),
              "-o", str(reference_object)])
    reference = ctypes.CDLL(str(reference_library))
    reference.c2fbReferenceCallbackResult.argtypes = []
    reference.c2fbReferenceCallbackResult.restype = ctypes.c_int
    reference.c2fbReferenceTargetResult.argtypes = []
    reference.c2fbReferenceTargetResult.restype = ctypes.c_int
    reference.c2fbReferenceInvokeCallbackResult.argtypes = []
    reference.c2fbReferenceInvokeCallbackResult.restype = ctypes.c_int
    reference.c2fbReferenceChooseFalseResult.argtypes = []
    reference.c2fbReferenceChooseFalseResult.restype = ctypes.c_int
    reference.c2fbReferenceChooseTrueResult.argtypes = []
    reference.c2fbReferenceChooseTrueResult.restype = ctypes.c_int
    assert reference.c2fbReferenceCallbackResult() == 16
    assert reference.c2fbReferenceTargetResult() == 12
    assert reference.c2fbReferenceInvokeCallbackResult() == 16
    assert reference.c2fbReferenceChooseFalseResult() == 20
    assert reference.c2fbReferenceChooseTrueResult() == 3

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        'Declare Function c2fbReferenceInvokeCallbackResult CDecl '
        'Alias "c2fbReferenceInvokeCallbackResult" () As Long\n'
        'Declare Function c2fbReferenceChooseFalseResult CDecl '
        'Alias "c2fbReferenceChooseFalseResult" () As Long\n'
        'Declare Function c2fbReferenceChooseTrueResult CDecl '
        'Alias "c2fbReferenceChooseTrueResult" () As Long\n'
        "Function callbackImpl CDecl(ByVal value As Long) As Long\n"
        "    Return value * 3 + 1\n"
        "End Function\n"
        "Function firstCallback CDecl(ByVal value As Long) As Long\n"
        "    Return value - 2\n"
        "End Function\n"
        "Function secondCallback CDecl(ByVal value As Long) As Long\n"
        "    Return value * 4\n"
        "End Function\n"
        "Dim callback As c2fb_Callback = ProcPtr(callbackImpl)\n"
        "Dim returnedCallback As c2fb_Callback = c2fb_returnCallback(callback)\n"
        "If returnedCallback(5) <> 16 Then End 1\n"
        "If c2fb_invokeCallback(callback, 5) <> "
        "c2fbReferenceInvokeCallbackResult() Then End 3\n"
        "Dim firstCallbackPointer As c2fb_Callback = ProcPtr(firstCallback)\n"
        "Dim secondCallbackPointer As c2fb_Callback = ProcPtr(secondCallback)\n"
        "Dim chosenFalse As c2fb_Callback = c2fb_chooseCallback("
        "0, firstCallbackPointer, secondCallbackPointer)\n"
        "If chosenFalse(5) <> c2fbReferenceChooseFalseResult() Then End 4\n"
        "Dim chosenTrue As c2fb_Callback = c2fb_chooseCallback("
        "1, firstCallbackPointer, secondCallbackPointer)\n"
        "If chosenTrue(5) <> c2fbReferenceChooseTrueResult() Then End 5\n"
        "Dim returnedTarget As c2fb_Callback = c2fb_returnTarget()\n"
        "If returnedTarget(5) <> 12 Then End 6\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(reference_object), "-x",
               str(executable)], cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_body_generic_selections(converter, fbc, work):
    # Generic selection resolves known C types and emits only the chosen arm.
    source_directory = work / "generic-body-generic-selections"
    source_directory.mkdir()
    source = source_directory / "generic.c"
    source.write_text(
        "static int c2fbGenericPointer(const unsigned int *source, int *counter) {\n"
        "    return _Generic((0 ? source : (void *)1),\n"
        "        const void *: source[0],\n"
        "        default: (*counter)++);\n"
        "}\n"
        "static int c2fbGenericDefault(int value) {\n"
        "    return _Generic(value, unsigned int: value + 3, default: value - 2);\n"
        "}\n"
    )
    candidate = source_directory / "generic_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "generic_candidates.bas"\n'
        "Dim sourceValue As ULong = 42\n"
        "Dim counter As Long = 7\n"
        "If c2fbGenericPointer(@sourceValue, @counter) <> 42 Then End 1\n"
        "If counter <> 7 Then End 2\n"
        "If c2fbGenericDefault(5) <> 3 Then End 3\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)

    # glibc exposes wcsstr as a C23 type-generic macro on current compilers.
    if platform.system() != "Linux" or platform.machine().lower() not in ("x86_64", "amd64"):
        return
    wcsstr_source = source_directory / "wcsstr.c"
    wcsstr_source.write_text(
        "#include <wchar.h>\n"
        "static __inline__ wchar_t *c2fbGenericWcsstr(\n"
        "    const wchar_t *text, const wchar_t *pattern) {\n"
        "    return (wchar_t *)wcsstr(text, pattern);\n"
        "}\n"
    )
    wcsstr_candidate = source_directory / "wcsstr_candidates.bas"
    body_profile = Path(__file__).resolve().parents[1] / "profiles" / \
        "freebasic-linux-glibc-x86_64-body.rsp"
    summary = run([
        converter, "translate-simple-generic-c", str(wcsstr_source),
        str(wcsstr_candidate), "cc", f"@{body_profile}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    wcsstr_wrapper = source_directory / "wcsstr_check.bas"
    wcsstr_wrapper.write_text(
        '#include once "wcsstr_candidates.bas"\n'
        "Dim text(0 To 3) As Long = { 97, 98, 99, 0 }\n"
        "Dim pattern(0 To 1) As Long = { 98, 0 }\n"
        "If c2fbGenericWcsstr(@text(0), @pattern(0)) <> @text(1) Then End 4\n"
    )
    wcsstr_executable = source_directory / "wcsstr_check"
    run(fbc + ["-w", "all", str(wcsstr_wrapper), "-x", str(wcsstr_executable)],
        cwd=source_directory)
    run([str(wcsstr_executable)], cwd=source_directory)


def check_generic_body_switch_block_generic_default(converter, fbc, cc, work):
    # A _Generic default association inside a switch block is not a case label.
    source_directory = work / "generic-body-switch-block-generic-default"
    source_directory.mkdir()
    source = source_directory / "switch_generic_default.c"
    source.write_text(
        "#include <stddef.h>\n"
        "struct SwitchRecord { const char *pattern; };\n"
        "int c2fbSwitchBlockGenericDefault(int value, int choose_return,\n"
        "    int flags, const char *text, const char *text_end) {\n"
        "    switch (value) {\n"
        "    case '*':\n"
        "        if (choose_return == 0) {\n"
        "            int result = (flags & 1) == 0 ? 0 : 1;\n"
        "            if (flags & 1) {\n"
        "                /* default: this comment is not a switch label. */\n"
        "                if (flags & 8)\n"
        "                    result = 0;\n"
        "                else {\n"
        "                    if (_Generic(0 ? (text) : (void *) 1,\n"
        "                                 const void *: text == text_end,\n"
        "                                 default: text == NULL))\n"
        "                        result = 0;\n"
        "                }\n"
        "            }\n"
        "            return result;\n"
        "        } else {\n"
        "            const char *endp;\n"
        "            struct SwitchRecord end;\n"
        "            end.pattern = NULL;\n"
        "            endp = text;\n"
        "            if (endp == NULL)\n"
        "                endp = text_end;\n"
        "        }\n"
        "        return 2;\n"
        "    default:\n"
        "        return 0;\n"
        "    }\n"
        "}\n"
    )
    candidate = source_directory / "switch_generic_default_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), *cc,
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c11", "-O2", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)])
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbSwitchBlockGenericDefault.argtypes = [
        ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_void_p,
        ctypes.c_void_p,
    ]
    reference.c2fbSwitchBlockGenericDefault.restype = ctypes.c_int

    buffer = ctypes.create_string_buffer(b"switch")
    text = ctypes.addressof(buffer)
    text_end = text + len(b"switch")
    cases = [
        (ord("*"), 0, 0, text, text_end),
        (ord("*"), 0, 1, text, text_end),
        (ord("*"), 0, 1, text_end, text_end),
        (ord("*"), 0, 9, text, text_end),
        (ord("*"), 1, 1, text, text_end),
        (ord("x"), 0, 1, text, text_end),
    ]
    expected = [reference.c2fbSwitchBlockGenericDefault(*case) for case in cases]

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"]),
                           ("llvm", ["-gen", "llvm"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate), "-x",
                           str(converted_path)])
        converted = ctypes.CDLL(str(converted_path))
        converted.c2fbSwitchBlockGenericDefault.argtypes = \
            reference.c2fbSwitchBlockGenericDefault.argtypes
        converted.c2fbSwitchBlockGenericDefault.restype = ctypes.c_int
        actual = [converted.c2fbSwitchBlockGenericDefault(*case)
                  for case in cases]
        assert actual == expected, (backend, expected, actual)


def check_generic_body_glibc_open64_alias(converter, fbc, work):
    if platform.system() != "Linux" or platform.machine().lower() not in (
        "x86_64", "amd64",
    ):
        return
    source_directory = work / "generic-body-glibc-open64-alias"
    source_directory.mkdir()

    definition_source = source_directory / "asm_definition.c"
    definition_source.write_text(
        'int c2fbAliasDefinition(int value) '
        '__asm__("c2fb_alias_definition");\n'
        "int c2fbAliasDefinition(int value) { return value + 1; }\n"
    )
    definition_candidate = source_directory / "asm_definition_candidates.bas"
    definition_summary = run([
        converter, "translate-simple-generic-c", str(definition_source),
        str(definition_candidate), "cc",
    ])
    assert "translated 1 simple functions; skipped 0" \
        in definition_summary, definition_summary
    definition_text = definition_candidate.read_text()
    assert (
        'Function c2fbAliasDefinition CDecl '
        'Alias "c2fb_alias_definition"' in definition_text
    ), definition_text
    definition_wrapper = source_directory / "asm_definition_check.bas"
    definition_wrapper.write_text(
        '#include once "asm_definition_candidates.bas"\n'
        "If c2fbAliasDefinition(4) <> 5 Then End 1\n"
    )
    definition_executable = source_directory / "asm_definition_check"
    run(fbc + ["-w", "all", str(definition_wrapper), "-x",
               str(definition_executable)], cwd=source_directory)
    run([str(definition_executable)], cwd=source_directory)

    source = source_directory / "open64.c"
    source.write_text(
        "#define _FILE_OFFSET_BITS 64\n"
        "#include <fcntl.h>\n"
        "#include <unistd.h>\n"
        "int c2fbOpen64Probe(const char *path) {\n"
        "    int fd = open(path, O_RDONLY | O_NONBLOCK);\n"
        "    if (fd < 0) return fd;\n"
        "    return close(fd);\n"
        "}\n"
    )
    candidate = source_directory / "open64_candidates.bas"
    body_profile = Path(__file__).resolve().parents[1] / "profiles" / \
        "freebasic-linux-glibc-x86_64-body.rsp"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc", f"@{body_profile}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert 'Declare Function c2fb_external_open CDecl Alias "open64"' \
        in generated, generated

    probe_file = source_directory / "probe.txt"
    probe_file.write_bytes(b"c2fb open alias probe\n")
    wrapper = source_directory / "open64_check.bas"
    wrapper.write_text(
        '#include once "open64_candidates.bas"\n'
        f'Dim path As String = "{probe_file}"\n'
        "If c2fbOpen64Probe(StrPtr(path)) <> 0 Then End 1\n"
    )
    executable = source_directory / "open64_check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


