def check_generic_body_static_local_pointers(converter, fbc, cc, work):
    # Local static object pointers preserve their C storage and initializer lifetime.
    source_directory = work / "generic-body-static-local-pointers"
    source_directory.mkdir()
    source = source_directory / "static_pointers.c"
    source.write_text(
        "typedef int C2fbUnaryCallback(int value);\n"
        "static int c2fbStaticPointerTarget = 31;\n"
        "static int c2fbStaticCallbackPlus(int value) { return value + 3; }\n"
        "static int c2fbStaticCallbackTimes(int value) { return value * 2; }\n"
        "int c2fbStaticPointerState(int delta) {\n"
        "    static int *pointer = 0U;\n"
        "    if (pointer == 0) pointer = &c2fbStaticPointerTarget;\n"
        "    *pointer += delta;\n"
        "    return *pointer;\n"
        "}\n"
        "int c2fbStaticPointerAddress(void) {\n"
        "    static const int *pointer = &c2fbStaticPointerTarget;\n"
        "    return *pointer;\n"
        "}\n"
        "int c2fbStaticPointerString(void) {\n"
        "    static const char *pointer = \"C2FB\";\n"
        "    return pointer[1];\n"
        "}\n"
        "int c2fbStaticCallbackTypedef(int value) {\n"
        "    static C2fbUnaryCallback *callback = c2fbStaticCallbackPlus;\n"
        "    return callback(value);\n"
        "}\n"
        "int c2fbStaticCallbackInline(int value) {\n"
        "    static int (*callback)(int) = &c2fbStaticCallbackTimes;\n"
        "    return callback(value);\n"
        "}\n"
        "int c2fbStaticCallbackZeroIsNull(void) {\n"
        "    static int (*callback)(int);\n"
        "    return callback == 0;\n"
        "}\n"
    )
    candidate = source_directory / "static_pointer_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
    ])
    assert "translated 8 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert generated.count("C static scalar storage") >= 4, generated
    assert generated.count("C static callback storage") == 2, generated

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        reference_path = source_directory / f"reference-{backend}.so"
        run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(source),
                  "-o", str(reference_path)])
        reference = ctypes.CDLL(str(reference_path))
        output = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate), "-x", str(output)])
        converted = ctypes.CDLL(str(output))
        for library in (reference, converted):
            library.c2fbStaticPointerState.argtypes = [ctypes.c_int]
            library.c2fbStaticPointerState.restype = ctypes.c_int
            library.c2fbStaticPointerAddress.argtypes = []
            library.c2fbStaticPointerAddress.restype = ctypes.c_int
            library.c2fbStaticPointerString.argtypes = []
            library.c2fbStaticPointerString.restype = ctypes.c_int
            library.c2fbStaticCallbackTypedef.argtypes = [ctypes.c_int]
            library.c2fbStaticCallbackTypedef.restype = ctypes.c_int
            library.c2fbStaticCallbackInline.argtypes = [ctypes.c_int]
            library.c2fbStaticCallbackInline.restype = ctypes.c_int
            library.c2fbStaticCallbackZeroIsNull.argtypes = []
            library.c2fbStaticCallbackZeroIsNull.restype = ctypes.c_int
        assert reference.c2fbStaticPointerAddress() == \
            converted.c2fbStaticPointerAddress() == 31
        for delta in (5, -2, 19, -37, 0):
            assert reference.c2fbStaticPointerState(delta) == \
                converted.c2fbStaticPointerState(delta)
            assert reference.c2fbStaticPointerAddress() == \
                converted.c2fbStaticPointerAddress()
        assert reference.c2fbStaticPointerString() == \
            converted.c2fbStaticPointerString() == ord("2")
        for value in (-5, 0, 1, 42):
            assert reference.c2fbStaticCallbackTypedef(value) == \
                converted.c2fbStaticCallbackTypedef(value) == value + 3
            assert reference.c2fbStaticCallbackInline(value) == \
                converted.c2fbStaticCallbackInline(value) == value * 2
        assert reference.c2fbStaticCallbackZeroIsNull() == \
            converted.c2fbStaticCallbackZeroIsNull() == 1


def check_generic_body_automatic_callback_initializer(converter, fbc, cc, work):
    # An automatic callback initializer reads a typed field at its C declaration site.
    source_directory = work / "generic-body-automatic-callback-initializer"
    source_directory.mkdir()
    source = source_directory / "callback_initializer.c"
    source.write_text(
        "typedef struct C2fbFile C2fbFile;\n"
        "typedef struct C2fbFileMethods {\n"
        "    int (*xSectorSize)(C2fbFile *);\n"
        "} C2fbFileMethods;\n"
        "struct C2fbFile {\n"
        "    const C2fbFileMethods *pMethods;\n"
        "    int value;\n"
        "};\n"
        "int c2fbAutomaticCallbackInitializer("
        "C2fbFile *file, int useCallback) {\n"
        "    if (!useCallback) return -1;\n"
        "    int (*xSectorSize)(C2fbFile *) = file->pMethods->xSectorSize;\n"
        "    return xSectorSize(file);\n"
        "}\n"
    )
    candidate = source_directory / "callback_initializer_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source), "-o", str(reference_path)])
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x", str(converted_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))

    class C2fbFile(ctypes.Structure):
        pass

    callback_type = ctypes.CFUNCTYPE(ctypes.c_int, ctypes.POINTER(C2fbFile))

    class C2fbFileMethods(ctypes.Structure):
        _fields_ = [("xSectorSize", callback_type)]

    C2fbFile._fields_ = [
        ("pMethods", ctypes.POINTER(C2fbFileMethods)),
        ("value", ctypes.c_int),
    ]
    for library in (reference, converted):
        function = library.c2fbAutomaticCallbackInitializer
        function.argtypes = [ctypes.POINTER(C2fbFile), ctypes.c_int]
        function.restype = ctypes.c_int

    callback = callback_type(lambda file_pointer: file_pointer.contents.value * 3 + 5)
    methods = C2fbFileMethods(callback)
    for value in (-9, 0, 17, 1024):
        file = C2fbFile(ctypes.pointer(methods), value)
        expected = reference.c2fbAutomaticCallbackInitializer(
            ctypes.byref(file), 1)
        actual = converted.c2fbAutomaticCallbackInitializer(
            ctypes.byref(file), 1)
        assert expected == actual == value * 3 + 5, (
            f"callback initializer for {value}: C={expected}, FreeBASIC={actual}"
        )

    absent_methods = C2fbFile(None, 0)
    assert reference.c2fbAutomaticCallbackInitializer(
        ctypes.byref(absent_methods), 0) == -1
    assert converted.c2fbAutomaticCallbackInitializer(
        ctypes.byref(absent_methods), 0) == -1


def check_generic_body_callback_conditional_initializer(converter, fbc, cc, work):
    # C conditional operators retain callback types across initialization and assignment.
    source_directory = work / "generic-body-callback-conditional-initializer"
    source_directory.mkdir()
    source = source_directory / "callback_conditional.c"
    source.write_text(
        "#include <stddef.h>\n"
        "static void c2fbDefaultDtor(void *object) { (void)object; }\n"
        "static int c2fbCallbackOne(void) { return 11; }\n"
        "static int c2fbCallbackTwo(void) { return 22; }\n"
        "static int c2fbCallbackThree(void) { return 33; }\n"
        "int c2fbConditionalCallbackInitializer(int useDefault) {\n"
        "    void (*dtorMult)(void *) = "
        "(useDefault ? &c2fbDefaultDtor : NULL);\n"
        "    return dtorMult != NULL;\n"
        "}\n"
        "int c2fbNestedCallbackConditional(int first, int second) {\n"
        "    int (*callback)(void);\n"
        "    callback = first ? c2fbCallbackOne : "
        "second ? c2fbCallbackTwo : c2fbCallbackThree;\n"
        "    return callback();\n"
        "}\n"
    )
    candidate = source_directory / "callback_conditional_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 6 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source), "-o", str(reference_path)])
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x", str(converted_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        function = library.c2fbConditionalCallbackInitializer
        function.argtypes = [ctypes.c_int]
        function.restype = ctypes.c_int
        for use_default in (0, 1):
            assert function(use_default) == use_default, (
                f"conditional callback result for {use_default}"
            )
        nested = library.c2fbNestedCallbackConditional
        nested.argtypes = [ctypes.c_int, ctypes.c_int]
        nested.restype = ctypes.c_int
        for first, second, expected in ((1, 0, 11), (0, 1, 22), (0, 0, 33)):
            assert nested(first, second) == expected, (
                f"nested callback selection for {first}, {second}"
            )


def check_generic_body_sizeof_self_reference_initializer(converter, fbc, cc, work):
    # C exposes the new local name inside sizeof in its own initializer.
    source_directory = work / "generic-body-sizeof-self-reference-initializer"
    source_directory.mkdir()
    source = source_directory / "sizeof_initializer.c"
    source.write_text(
        "typedef struct C2fbReferenceString { int referenceCount; } "
        "C2fbReferenceString;\n"
        "static C2fbReferenceString c2fbReferenceStorage;\n"
        "static void *c2fbAllocateReference(unsigned long bytes) {\n"
        "    if (bytes != sizeof(C2fbReferenceString)) return 0;\n"
        "    return &c2fbReferenceStorage;\n"
        "}\n"
        "int c2fbSelfSizeofPointerInitializer(void) {\n"
        "    C2fbReferenceString *p = c2fbAllocateReference(sizeof(*p));\n"
        "    if (p == 0) return 0;\n"
        "    p->referenceCount = 57;\n"
        "    return p->referenceCount;\n"
        "}\n"
    )
    candidate = source_directory / "sizeof_initializer_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source), "-o", str(reference_path)])
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x", str(converted_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    assert reference.c2fbSelfSizeofPointerInitializer() == 57
    assert converted.c2fbSelfSizeofPointerInitializer() == 57


def check_generic_body_mapped_record_sizeof(converter, fbc, cc, work):
    # Explicit type maps must retain the record layout for sizeof(T) and sizeof(*p).
    source_directory = work / "generic-body-mapped-record-sizeof"
    source_directory.mkdir()
    (source_directory / "sqlite3_probe_types.bi").write_text(
        "Type ProbeReader\n"
        "    nSegment As Long\n"
        "    aDoclist As Any Ptr\n"
        "End Type\n"
        "Type ProbeFilter\n"
        "    zTerm As Const ZString Ptr\n"
        "    nTerm As Long\n"
        "    iCol As Long\n"
        "    flags As Long\n"
        "End Type\n"
    )
    source = source_directory / "mapped_sizeof.c"
    source.write_text(
        "#include <string.h>\n"
        "typedef struct Fts3MultiSegReader { int nSegment; char *aDoclist; } Fts3MultiSegReader;\n"
        "typedef struct Fts3SegFilter { const char *zTerm; int nTerm, iCol, flags; } Fts3SegFilter;\n"
        "unsigned long long c2fbMappedRecordSizeSum(Fts3MultiSegReader *cursor, Fts3SegFilter *filter) {\n"
        "    return sizeof(*cursor) + sizeof(*filter);\n"
        "}\n"
        "unsigned long long c2fbMappedRecordSizeType(void) { return sizeof(Fts3SegFilter); }\n"
        "void c2fbMappedRecordClear(Fts3SegFilter *filter) { memset(filter, 0, sizeof(Fts3SegFilter)); }\n"
        "int c2fbMappedRecordRead(const Fts3SegFilter *filter) { return filter->nTerm + filter->flags; }\n"
    )
    candidate = source_directory / "mapped_sizeof_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        *cc, f"--fb-source-directory={source_directory}",
        "--type-map=Fts3MultiSegReader=ProbeReader",
        "--type-map=Fts3SegFilter=ProbeFilter",
    ])
    assert "translated 4 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert 'SizeOf(ProbeReader)' in generated, generated
    assert 'SizeOf(ProbeFilter)' in generated, generated
    assert 'c2fb_crt_memset' in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source), "-o", str(reference_path)])
    reference = ctypes.CDLL(str(reference_path))

    class CReader(ctypes.Structure):
        _fields_ = [("nSegment", ctypes.c_int), ("aDoclist", ctypes.c_void_p)]

    class CFilter(ctypes.Structure):
        _fields_ = [
            ("zTerm", ctypes.c_void_p), ("nTerm", ctypes.c_int),
            ("iCol", ctypes.c_int), ("flags", ctypes.c_int),
        ]

    reference_size_sum = reference.c2fbMappedRecordSizeSum
    reference_size_sum.argtypes = [ctypes.POINTER(CReader), ctypes.POINTER(CFilter)]
    reference_size_sum.restype = ctypes.c_ulonglong
    reference_size_type = reference.c2fbMappedRecordSizeType
    reference_size_type.argtypes = []
    reference_size_type.restype = ctypes.c_ulonglong
    reference_clear = reference.c2fbMappedRecordClear
    reference_clear.argtypes = [ctypes.POINTER(CFilter)]
    reference_read = reference.c2fbMappedRecordRead
    reference_read.argtypes = [ctypes.POINTER(CFilter)]
    reference_read.restype = ctypes.c_int

    reader = CReader(3, ctypes.c_void_p(0x1234))
    filter_value = CFilter(ctypes.c_void_p(0x5678), 11, 4, 7)
    expected_size_sum = ctypes.sizeof(CReader) + ctypes.sizeof(CFilter)
    assert reference_size_sum(ctypes.byref(reader), ctypes.byref(filter_value)) == expected_size_sum
    assert reference_size_type() == ctypes.sizeof(CFilter)
    assert reference_read(ctypes.byref(filter_value)) == 18

    for backend, backend_flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + backend_flags + [
            "-w", "all", "-i", str(source_directory), "-dll", str(candidate),
            "-x", str(converted_path),
        ], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        converted_size_sum = converted.c2fbMappedRecordSizeSum
        converted_size_sum.argtypes = reference_size_sum.argtypes
        converted_size_sum.restype = ctypes.c_ulonglong
        converted_size_type = converted.c2fbMappedRecordSizeType
        converted_size_type.argtypes = []
        converted_size_type.restype = ctypes.c_ulonglong
        converted_clear = converted.c2fbMappedRecordClear
        converted_clear.argtypes = [ctypes.POINTER(CFilter)]
        converted_read = converted.c2fbMappedRecordRead
        converted_read.argtypes = [ctypes.POINTER(CFilter)]
        converted_read.restype = ctypes.c_int

        assert converted_size_sum(ctypes.byref(reader), ctypes.byref(filter_value)) == expected_size_sum
        assert converted_size_type() == ctypes.sizeof(CFilter)
        current_filter = CFilter(ctypes.c_void_p(0x5678), 11, 4, 7)
        converted_clear(ctypes.byref(current_filter))
        assert (current_filter.zTerm, current_filter.nTerm, current_filter.iCol, current_filter.flags) == (None, 0, 0, 0)
        assert converted_read(ctypes.byref(current_filter)) == 0


