    generated = candidate.read_text()
    assert "Function c2fbGccDiagnosticPragma" in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=gnu11", "-O2", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)])
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbGccDiagnosticPragma.argtypes = [ctypes.c_int]
    reference.c2fbGccDiagnosticPragma.restype = ctypes.c_int

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate),
                           "-x", str(converted_path)])
        converted = ctypes.CDLL(str(converted_path))
        converted.c2fbGccDiagnosticPragma.argtypes = [ctypes.c_int]
        converted.c2fbGccDiagnosticPragma.restype = ctypes.c_int
        for value in (-7, 0, 19):
            assert reference.c2fbGccDiagnosticPragma(value) == \
                converted.c2fbGccDiagnosticPragma(value) == value + 7


