def check_generic_body_const_multidimensional_array_initializers(
    converter, fbc, cc, work,
):
    source_directory = work / "generic-body-const-multidimensional-array-initializers"
    source_directory.mkdir()
    source = source_directory / "array_initializers.c"
    source.write_text(
        "int c2fbConstMatrixValue(void) {\n"
        "    const int items[1][1] = {{17}};\n"
        "    return items[0][0];\n"
        "}\n"
        "int c2fbMixedMatrixValue(void) {\n"
        "    int items[2][2] = {{1}, 2, 3};\n"
        "    return items[0][0] * 1000 + items[0][1] * 100\n"
        "         + items[1][0] * 10 + items[1][1];\n"
        "}\n"
        "int c2fbGroupedPrefixMatrixValue(void) {\n"
        "    int items[2][3] = {{1, 2}, 3, 4, 5};\n"
        "    return items[0][0] * 100000 + items[0][1] * 10000\n"
        "         + items[0][2] * 1000 + items[1][0] * 100\n"
        "         + items[1][1] * 10 + items[1][2];\n"
        "}\n"
        "int c2fbScalarThenBracedScalarValue(void) {\n"
        "    int items[2][2] = {1, {2}, 3};\n"
        "    return items[0][0] * 1000 + items[0][1] * 100\n"
        "         + items[1][0] * 10 + items[1][1];\n"
        "}\n"
        "int c2fbScalarThenBracedRowValue(void) {\n"
        "    int items[2][2] = {1, 2, {3}};\n"
        "    return items[0][0] * 1000 + items[0][1] * 100\n"
        "         + items[1][0] * 10 + items[1][1];\n"
        "}\n"
        "int c2fbRankThreeBracedSubarrayValue(void) {\n"
        "    int items[2][2][2] = {1, 2, {3, 4}, 5};\n"
        "    return items[0][0][0] * 10000000 + items[0][0][1] * 1000000\n"
        "         + items[0][1][0] * 100000 + items[0][1][1] * 10000\n"
        "         + items[1][0][0] * 1000 + items[1][0][1] * 100\n"
        "         + items[1][1][0] * 10 + items[1][1][1];\n"
        "}\n"
        "struct c2fbRecordMatrixElement { int value; int tag; };\n"
        "int c2fbRecordMatrixInitializerValue(void) {\n"
        "    struct c2fbRecordMatrixElement items[2][2] = {\n"
        "        {{1, 10}, {2, 20}}, {{3, 30}, {4, 40}}\n"
        "    };\n"
        "    return items[0][0].value + items[0][0].tag * 10\n"
        "         + items[0][1].value * 100 + items[0][1].tag * 1000\n"
        "         + items[1][0].value * 10000 + items[1][0].tag * 100000\n"
        "         + items[1][1].value * 1000000\n"
        "         + items[1][1].tag * 10000000;\n"
        "}\n"
        "int c2fbConstVectorExtent(int count) {\n"
        "    const int items[count];\n"
        "    return (int)(sizeof(items) / sizeof(items[0]));\n"
        "}\n"
        "int c2fbConstMatrixExtent(int rows, int columns) {\n"
        "    const int items[rows][columns];\n"
        "    return (int)(sizeof(items) / sizeof(items[0])) * 100\n"
        "         + (int)(sizeof(items[0]) / sizeof(items[0][0]));\n"
        "}\n"
        "int c2fbConstFixedMatrixExtent(void) {\n"
        "    const int items[2][3];\n"
        "    return (int)(sizeof(items) / sizeof(items[0])) * 10\n"
        "         + (int)(sizeof(items[0]) / sizeof(items[0][0]));\n"
        "}\n"
    )
    candidate = source_directory / "array_initializers_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), *cc,
    ])
    assert "translated 10 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + [
        "-std=c99", "-O2", "-shared", "-fPIC", str(source),
        "-o", str(reference_path),
    ])
    reference = ctypes.CDLL(str(reference_path))
    function_names = (
        "c2fbConstMatrixValue",
        "c2fbMixedMatrixValue",
        "c2fbGroupedPrefixMatrixValue",
        "c2fbScalarThenBracedScalarValue",
        "c2fbScalarThenBracedRowValue",
        "c2fbRankThreeBracedSubarrayValue",
        "c2fbRecordMatrixInitializerValue",
    )
    expected_values = (17, 1023, 120345, 1230, 1230, 12345000, 407050301)
    for backend, backend_flags in (
        ("native", []), ("gcc", ["-gen", "gcc"]),
    ):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + backend_flags + [
            "-w", "all", "-dll", str(candidate), "-x", str(converted_path),
        ])
        converted = ctypes.CDLL(str(converted_path))
        for name, expected in zip(function_names, expected_values):
            c_function = getattr(reference, name)
            fb_function = getattr(converted, name)
            c_function.argtypes = []
            c_function.restype = ctypes.c_int
            fb_function.argtypes = []
            fb_function.restype = ctypes.c_int
            c_value = c_function()
            fb_value = fb_function()
            assert c_value == fb_value == expected, (
                f"{backend} array initializer mismatch for {name}: "
                f"C={c_value}, FreeBASIC={fb_value}, expected={expected}"
            )

        for name, arguments, expected in (
            ("c2fbConstVectorExtent", (1,), 1),
            ("c2fbConstVectorExtent", (7,), 7),
            ("c2fbConstVectorExtent", (31,), 31),
            ("c2fbConstMatrixExtent", (1, 1), 101),
            ("c2fbConstMatrixExtent", (2, 3), 203),
            ("c2fbConstMatrixExtent", (5, 7), 507),
            ("c2fbConstFixedMatrixExtent", (), 23),
        ):
            c_function = getattr(reference, name)
            fb_function = getattr(converted, name)
            argument_types = [ctypes.c_int] * len(arguments)
            for function in (c_function, fb_function):
                function.argtypes = argument_types
                function.restype = ctypes.c_int
            assert c_function(*arguments) == fb_function(*arguments) == expected, (
                f"{backend} const VLA extent mismatch for {name}{arguments}"
            )

    const_vla_write_source = source_directory / "const_vla_write.c"
    const_vla_write_source.write_text(
        "int c2fbConstVlaWrite(int count) {\n"
        "    const int items[count];\n"
        "    items[0] = 1;\n"
        "    return 0;\n"
        "}\n"
    )
    const_vla_write_candidate = source_directory / "const_vla_write_candidates.bas"
    const_vla_write_summary = run([
        converter, "translate-simple-generic-c", str(const_vla_write_source),
        str(const_vla_write_candidate), *cc,
    ])
    assert "translated 0 simple functions; skipped 1" in const_vla_write_summary, \
        const_vla_write_summary
    const_vla_write_generated = const_vla_write_candidate.read_text()
    assert "Function c2fbConstVlaWrite" not in const_vla_write_generated, \
        const_vla_write_generated
    assert "c2fb skipped c2fbConstVlaWrite:" in const_vla_write_generated, \
        const_vla_write_generated

    const_write_source = source_directory / "const_matrix_write.c"
    const_write_source.write_text(
        "int c2fbConstMatrixWrite(void) {\n"
        "    const int items[1][1] = {{17}};\n"
        "    return items[0][0] = 18;\n"
        "}\n"
    )
    const_write_candidate = source_directory / "const_matrix_write_candidates.bas"
    const_write_summary = run([
        converter, "translate-simple-generic-c", str(const_write_source),
        str(const_write_candidate), *cc,
    ])
    assert "translated 0 simple functions; skipped 1" in const_write_summary, \
        const_write_summary
    const_write_generated = const_write_candidate.read_text()
    assert "Function c2fbConstMatrixWrite" not in const_write_generated, \
        const_write_generated
    assert "c2fb skipped c2fbConstMatrixWrite:" in const_write_generated, \
        const_write_generated


def check_generic_body_gnu_statement_expression_result_capture(converter, fbc, work):
    # typeof's captured expression is unevaluated and its initializer runs once.
    source_directory = work / "generic-body-gnu-statement-expression-result"
    source_directory.mkdir()
    source = source_directory / "statement_expression.c"
    source.write_text(
        "int c2fbGnuStatementExpressionAdvance(int *value, int delta) {\n"
        "    *value += delta;\n"
        "    return *value;\n"
        "}\n"
        "int c2fbGnuStatementExpressionResult(int input) {\n"
        "    int running = 0;\n"
        "    return __extension__ ({\n"
        "        __typeof__(c2fbGnuStatementExpressionAdvance(&running, input))\n"
        "            captured = c2fbGnuStatementExpressionAdvance(&running, input);\n"
        "        captured;\n"
        "    }) * 10 + running;\n"
        "}\n"
    )
    candidate = source_directory / "statement_expression_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc",
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "statement_expression_candidates.bas"\n'
        'If c2fbGnuStatementExpressionResult(3) <> 33 Then End 1\n'
        'If c2fbGnuStatementExpressionResult(-4) <> -44 Then End 2\n'
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), "-x", str(executable)],
            cwd=source_directory)
        run([str(executable)], cwd=source_directory)


