        '    If fb_sfxResolveChannel(-1) <> 0 Then Return 14\n'
        '    fb_sfxChannelCmdTestClearContext()\n'
        '    If fb_sfxChannelCmdGet() <> 0 Then Return 15\n'
        '    If fb_sfxResolveChannel(-1) <> 0 Then Return 16\n'
