def check_freebasic_sfx_capture_read(fbc, cc, source_root, work):
    test_directory = work / "fbc-source-sfx-capture-read"
    test_directory.mkdir()
    support_source = test_directory / "support.c"
    support_source.write_text(
        '#include "fb_sfx_internal.h"\n'
        'static FB_SFXCTX test_context;\n'
        'static int null_driver_tag;\n'
        'static int real_driver_tag;\n'
        'FB_SFXCTX *__fb_sfx = &test_context;\n'
        'static int null_driver_selected;\n'
        'static int driver_access_count;\n'
        'static int null_driver_check_count;\n'
        'static int capture_read_count;\n'
        'static int platform_read_count;\n'
        'static int capture_result;\n'
        'static int platform_result;\n'
        'static int last_frame_count;\n'
        'const FB_SFX_DRIVER *fb_sfxDeviceDriver(void) {\n'
        '    ++driver_access_count;\n'
        '    return null_driver_selected\n'
        '        ? (const FB_SFX_DRIVER *)&null_driver_tag\n'
        '        : (const FB_SFX_DRIVER *)&real_driver_tag;\n'
        '}\n'
        'int fb_sfxDriverIsNull(const FB_SFX_DRIVER *driver) {\n'
        '    ++null_driver_check_count;\n'
        '    return driver == (const FB_SFX_DRIVER *)&null_driver_tag;\n'
        '}\n'
        'int fb_sfxCaptureRead(float *buffer, int frames) {\n'
        '    ++capture_read_count;\n'
        '    last_frame_count = frames;\n'
        '    if (buffer && frames > 0)\n'
        '        buffer[0] = 3.5f;\n'
        '    return capture_result;\n'
        '}\n'
        'int fb_sfxPlatformCaptureRead(float *buffer, int frames) {\n'
        '    ++platform_read_count;\n'
        '    last_frame_count = frames;\n'
        '    if (buffer && frames > 0)\n'
        '        buffer[0] = 4.5f;\n'
        '    return platform_result;\n'
        '}\n'
        'void fb_sfxCaptureReadTestSetContext(int is_present) {\n'
        '    __fb_sfx = is_present ? &test_context : 0;\n'
        '}\n'
        'void fb_sfxCaptureReadTestSetDriver(int is_null) {\n'
        '    null_driver_selected = is_null;\n'
        '}\n'
        'void fb_sfxCaptureReadTestSetResults(int platform, int capture) {\n'
        '    platform_result = platform;\n'
        '    capture_result = capture;\n'
        '}\n'
        'int fb_sfxCaptureReadTestDriverAccessCount(void) {\n'
        '    return driver_access_count;\n'
        '}\n'
        'int fb_sfxCaptureReadTestNullDriverCheckCount(void) {\n'
        '    return null_driver_check_count;\n'
        '}\n'
        'int fb_sfxCaptureReadTestCaptureReadCount(void) {\n'
        '    return capture_read_count;\n'
        '}\n'
        'int fb_sfxCaptureReadTestPlatformReadCount(void) {\n'
        '    return platform_read_count;\n'
        '}\n'
        'int fb_sfxCaptureReadTestLastFrameCount(void) {\n'
        '    return last_frame_count;\n'
        '}\n'
    )
    support_object = test_directory / "support.o"
    run(cc + [
        "-std=c99", "-Wall", "-Wextra", "-Werror", "-c",
        f"-I{source_root / 'rtlib'}", f"-I{source_root / 'sfxlib'}",
        str(support_source), "-o", str(support_object),
    ], cwd=test_directory)

    test_source = test_directory / "capture_read_test.bas"
    test_source.write_text(
        'Declare Sub fb_sfxCaptureReadTestSetContext CDecl Alias "fb_sfxCaptureReadTestSetContext" (ByVal isPresent As Long)\n'
        'Declare Sub fb_sfxCaptureReadTestSetDriver CDecl Alias "fb_sfxCaptureReadTestSetDriver" (ByVal isNull As Long)\n'
        'Declare Sub fb_sfxCaptureReadTestSetResults CDecl Alias "fb_sfxCaptureReadTestSetResults" (ByVal platformResult As Long, ByVal captureResult As Long)\n'
        'Declare Function fb_sfxCaptureReadTestDriverAccessCount CDecl Alias "fb_sfxCaptureReadTestDriverAccessCount" () As Long\n'
        'Declare Function fb_sfxCaptureReadTestNullDriverCheckCount CDecl Alias "fb_sfxCaptureReadTestNullDriverCheckCount" () As Long\n'
        'Declare Function fb_sfxCaptureReadTestCaptureReadCount CDecl Alias "fb_sfxCaptureReadTestCaptureReadCount" () As Long\n'
        'Declare Function fb_sfxCaptureReadTestPlatformReadCount CDecl Alias "fb_sfxCaptureReadTestPlatformReadCount" () As Long\n'
        'Declare Function fb_sfxCaptureReadTestLastFrameCount CDecl Alias "fb_sfxCaptureReadTestLastFrameCount" () As Long\n'
        'Declare Function captureReadSamplesTest CDecl Alias "fb_sfxCaptureReadSamples" (ByVal samples As Single Ptr, ByVal frames As Long) As Long\n'
        'Declare Function captureProbeTest CDecl Alias "fb_sfxCaptureProbe" () As Long\n'
        'Function main() As Integer\n'
        '    Dim samples(0 To 63) As Single\n'
        '    fb_sfxCaptureReadTestSetResults(0, 13)\n'
        '    fb_sfxCaptureReadTestSetDriver(1)\n'
        '    If captureReadSamplesTest(0, 4) <> -1 Then Return 1\n'
        '    If captureReadSamplesTest(@samples(0), 0) <> -1 Then Return 2\n'
        '    If fb_sfxCaptureReadTestDriverAccessCount() <> 0 Then Return 3\n'
        '    If captureReadSamplesTest(@samples(0), 5) <> 13 Then Return 4\n'
        '    If fb_sfxCaptureReadTestCaptureReadCount() <> 1 Then Return 5\n'
        '    If fb_sfxCaptureReadTestPlatformReadCount() <> 0 Then Return 6\n'
        '    If fb_sfxCaptureReadTestLastFrameCount() <> 5 Then Return 7\n'
        '    If samples(0) <> 3.5f Then Return 8\n'
        '    fb_sfxCaptureReadTestSetDriver(0)\n'
        '    fb_sfxCaptureReadTestSetResults(-7, 14)\n'
        '    If captureReadSamplesTest(@samples(0), 7) <> -7 Then Return 9\n'
        '    If fb_sfxCaptureReadTestCaptureReadCount() <> 1 Then Return 10\n'
        '    If fb_sfxCaptureReadTestPlatformReadCount() <> 1 Then Return 11\n'
        '    fb_sfxCaptureReadTestSetResults(0, 15)\n'
        '    If captureReadSamplesTest(@samples(0), 8) <> 15 Then Return 12\n'
        '    If fb_sfxCaptureReadTestCaptureReadCount() <> 2 Then Return 13\n'
        '    If fb_sfxCaptureReadTestPlatformReadCount() <> 2 Then Return 14\n'
        '    If samples(0) <> 3.5f Then Return 15\n'
        '    fb_sfxCaptureReadTestSetContext(0)\n'
        '    fb_sfxCaptureReadTestSetResults(0, 16)\n'
        '    If captureReadSamplesTest(@samples(0), 11) <> 16 Then Return 16\n'
        '    If fb_sfxCaptureReadTestDriverAccessCount() <> 3 Then Return 17\n'
        '    If fb_sfxCaptureReadTestNullDriverCheckCount() <> 3 Then Return 18\n'
        '    fb_sfxCaptureReadTestSetContext(1)\n'
        '    fb_sfxCaptureReadTestSetDriver(1)\n'
        '    fb_sfxCaptureReadTestSetResults(0, 32)\n'
        '    If captureProbeTest() <> 32 Then Return 19\n'
        '    If fb_sfxCaptureReadTestLastFrameCount() <> 32 Then Return 20\n'
        '    Return 0\n'
        'End Function\n'
        'End main()\n'
    )
    executable = test_directory / "capture_read_test"
    run(fbc + [
        "-mt", "-w", "all", str(test_source),
        str(source_root / "sfxlib/sfx_capture_read.bas"),
        str(support_object), "-x", str(executable),
    ], cwd=test_directory)
    run([str(executable)], cwd=test_directory)


