        source_root / "rtlib/str_instrrevany.c",
        source_root / "rtlib/str_replace.c",
        source_root / "rtlib/str_vb_private.h",
        source_root / "sfxlib/fb_sfx_c_prefix.bi",
        source_root / "sfxlib/fb_sfx_internal.h",
        source_root / "sfxlib/sfx_capture_save.c",
        source_root / "sfxlib/sfx_capture_cmd.bas",
        source_root / "sfxlib/sfx_capture_read.bas",
        source_root / "sfxlib/sfx_device_cmd.bas",
        source_root / "sfxlib/sfx_music_cmd.bas",
