    missing_sources = [str(path) for path in expected_sources if not path.is_file()]
    assert not missing_sources, "FreeBASIC source tree is missing: " + ", ".join(missing_sources)

    header_profile = profile_directory / "freebasic-linux-glibc-x86_64.rsp"
    body_profile = profile_directory / "freebasic-linux-glibc-x86_64-body.rsp"
