    check_freebasic_gfx3_data(converter, fbc, cc, source_root, work)

    gfx_work = work / "fbc-source-gfx-rtlib"
    gfx_work.mkdir()
    gfx_binding = gfx_work / "fb_gfx.bi"
    # FB_GFX embeds FB_DROP_STATE, so the shared type catalog needs its header.
    gfx_source_patterns = (
        "gfxlib2/fb_gfx.h", "rtlib/fb_gfx_private.h", "rtlib/fb.h",
        "rtlib/fb_string.h", "rtlib/fb_array.h", "rtlib/fb_event.h",
        "rtlib/fb_drop.h", "rtlib/fb_hook.h", "rtlib/fb_thread.h", "rtlib/fb_file.h",
        "rtlib/fb_unicode.h",
    )
