    # their own external call declarations for independent object compilation.
    gfx_header_command = [
        converter, "generic-header",
        str(freebasic_source_file(source_root, "gfxlib2/fb_gfx.h")),
        str(gfx_binding), *cc,
        f"-I{source_root / 'rtlib'}", f"-I{source_root / 'gfxlib2'}",
        "-DFB_NO_GFXLIB", f"@{header_profile}", "--exclude=*",
    ]
    gfx_header_command.extend(
        f"--emit-source={pattern}" for pattern in gfx_source_patterns)
    run(gfx_header_command)
    assert "Type c2fb_FBARRAY" in gfx_binding.read_text(), "GFX binding omitted the runtime array descriptor"

    # gfx_core depends on FB_GFXCTX field layouts from the FreeBASIC binding.
