        support_object = work / "support.o"
        cc = shlex.split(args.cc)
        run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(fixtures / "expressions.c"),
                  str(fixtures / "support.c"), "-lm", "-o", str(reference_path)])
        run(cc + ["-std=c99", "-O2", "-fPIC", "-c", str(fixtures / "support.c"),
                  "-o", str(support_object)])
        reference = ctypes.CDLL(str(reference_path))
        for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
            converted_path = work / f"converted-{backend}.so"
            run(shlex.split(args.fbc) + flags + ["-w", "all", "-d", "SQLITE_THREADSAFE=1",
                "-i", str(body_catalog), "-dll", str(generated), str(support_object),
                "-x", str(converted_path)])
            converted = ctypes.CDLL(str(converted_path))
            checks = check_behavior(reference, converted)
            print(f"{backend}: {checks} C/FreeBASIC behavior comparisons passed")
        check_layout_members(converter, fixtures, body_catalog, work, shlex.split(args.fbc), cc)
        print(f"{len(expected)} candidates accepted; {len(expected_rejections)} unsupported functions rejected")


